BOOLEAN_PAGINATION_HEAD = r"""
<script>
(() => {
  if (window.__artistEloPaginationFixInstalled) return;
  window.__artistEloPaginationFixInstalled = true;

  const componentInput = (id) => {
    const root = document.getElementById(id);
    if (!root) return null;
    return root.matches?.('input,textarea,select')
      ? root
      : root.querySelector('input, textarea, select');
  };
  const componentButton = (id) => {
    const root = document.getElementById(id);
    if (!root) return null;
    return root.matches?.('button') ? root : root.querySelector('button');
  };
  const setNativeValue = (input, value) => {
    if (!input) return false;
    const prototype = input.tagName === 'TEXTAREA'
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
    const descriptor = Object.getOwnPropertyDescriptor(prototype, 'value');
    if (descriptor?.set) descriptor.set.call(input, String(value));
    else input.value = String(value);
    input.dispatchEvent(new Event('input', {bubbles: true}));
    input.dispatchEvent(new Event('change', {bubbles: true}));
    return true;
  };

  const bindings = [
    ['artist-row-limit', 'artist-page', 'artist-refresh-btn'],
    ['combination-row-limit', 'combination-page', 'combination-refresh-btn'],
    ['gallery-row-limit', 'gallery-page', 'gallery-refresh-btn'],
    ['favorites-row-limit', 'favorites-page', 'favorites-refresh-btn'],
  ];

  const install = () => {
    let installedAny = false;
    for (const [limitId, pageId, refreshId] of bindings) {
      const input = componentInput(limitId);
      if (!input || input.dataset.rowLimitFixBound === '1') continue;
      input.dataset.rowLimitFixBound = '1';
      input.addEventListener('change', () => {
        // Resetting first avoids landing on a now-invalid page when the page size changes.
        setNativeValue(componentInput(pageId), 1);
        window.setTimeout(() => componentButton(refreshId)?.click(), 90);
      });
      installedAny = true;
    }
    return installedAny;
  };

  install();
  const observer = new MutationObserver(() => install());
  observer.observe(document.documentElement, {subtree: true, childList: true});
})();
</script>
"""

