def _resolve_program_resource(configured_path: Path) -> Path:
    configured = Path(configured_path)
    candidates = [
        configured,
        PROGRAM_DIR / configured.name,
        PROGRAM_DIR / "resources" / configured.name,
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate.resolve()
    return configured

