def _sampler_runtime_value(sampler_id: Any):
    '''Map a persisted sampler ID to the installed SDK enum when possible.'''
    normalized = normalize_sampler(sampler_id, DEFAULT_SAMPLER_ID)
    for member in getattr(Sampler, "__members__", {}).values():
        if enum_value(member).casefold() == normalized:
            return member
    return normalized


def _scheduler_runtime_value(scheduler_id: Any):
    '''Map a persisted scheduler ID to the installed SDK enum when available.'''
    normalized = str(scheduler_id or "default").strip().casefold()
    if normalized == "default" or NoiseSchedule is None:
        return None
    for member in getattr(NoiseSchedule, "__members__", {}).values():
        if enum_value(member).casefold() == normalized:
            return member
    return normalized

