# Gradio 6 renders the mounted app's head payload as inert HTML, so scripts placed
# only in `head=` are not a reliable way to control component visibility. This code
# is attached to the credential HTML component through `js_on_load`, which Gradio
# executes as a real component lifecycle hook. The field remains visible if this
# enhancement fails; server-side request checks remain the security boundary.
SECURE_SETUP_COMPONENT_JS = r"""
(async () => {
  const root = document.documentElement;
  const host = String(location.hostname || '').toLowerCase();
  const obviousLoopback = host === '127.0.0.1' || host === 'localhost' || host === '::1' || host === '[::1]';
  const apply = (local) => {
    root.classList.remove('artist-elo-local-secret', 'artist-elo-remote-secret');
    root.classList.add(local ? 'artist-elo-local-secret' : 'artist-elo-remote-secret');
  };
  if (obviousLoopback) apply(true);
  try {
    const response = await fetch('/api/local-secret-access', {cache: 'no-store', credentials: 'same-origin'});
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    apply(Boolean(data && data.local));
  } catch (_) {
    if (!obviousLoopback) root.classList.remove('artist-elo-remote-secret');
  }
})();
"""

