# PERMANENT_GLOBAL_DUEL_DIAGNOSTICS_V1
# Full diagnostics are globally disabled by default and add only one cheap boolean
# branch to duel callbacks while off. When enabled in Storage / Settings, server-side
# callbacks are profiled, browser click-to-render transitions are captured, logs rotate
# automatically, and a redacted ZIP can be exported for remote diagnosis.
DIAGNOSTICS_DIR = DATA_LAYOUT.path("diagnostics_dir")
DIAGNOSTICS_EXPORT_DIR = DIAGNOSTICS_DIR / "exports"
DIAGNOSTICS_SERVER_LOG = DIAGNOSTICS_DIR / "duel_server_trace.jsonl"
DIAGNOSTICS_BROWSER_LOG = DIAGNOSTICS_DIR / "duel_browser_trace.jsonl"
DIAGNOSTICS_SETTING_KEY = "full_diagnostics_enabled"
DIAGNOSTICS_MAX_LOG_BYTES = 12 * 1024 * 1024
DIAGNOSTICS_ROTATED_LOGS = 3
DIAGNOSTICS_SLOW_CALLBACK_MS = 900.0
DIAGNOSTICS_PROFILE_LINES = 70


def _diag_safe_json_value(value: Any, depth: int = 0) -> Any:
    """Convert arbitrary state to small JSON-safe diagnostic summaries."""
    if depth > 3:
        return f"<{type(value).__name__}>"
    if value is None or isinstance(value, (bool, int, float, str)):
        text = value
        if isinstance(text, str) and len(text) > 500:
            return text[:500] + "…"
        return text
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, dict):
        items = list(value.items())[:30]
        return {
            str(key)[:100]: _diag_safe_json_value(child, depth + 1)
            for key, child in items
        }
    if isinstance(value, (list, tuple, set, frozenset, deque)):
        items = list(value)
        return {
            "type": type(value).__name__,
            "length": len(items),
            "sample": [_diag_safe_json_value(item, depth + 1) for item in items[:8]],
        }
    try:
        length = len(value)
    except Exception:
        length = None
    return {
        "type": type(value).__name__,
        "length": length,
        "repr": repr(value)[:300],
    }


def _diag_redact_text(text: str) -> str:
    """Remove common API-token and secret assignments from exported source/config."""
    value = str(text or "")
    patterns = [
        (r"(?i)(EMBEDDED_NOVELAI_API_KEY\s*=\s*)['\"][^'\"]*['\"]", r"\1'<REDACTED>'"),
        (r"(?i)((?:api[_-]?key|token|secret|password)\s*[=:]\s*)['\"][^'\"]*['\"]", r"\1'<REDACTED>'"),
        (r"pst-[A-Za-z0-9_-]{20,}", "pst-<REDACTED>"),
        (r"sk-[A-Za-z0-9_-]{20,}", "sk-<REDACTED>"),
        (r"(?i)(Bearer\s+)[A-Za-z0-9._~+/-]{16,}", r"\1<REDACTED>"),
    ]
    for pattern, replacement in patterns:
        value = re.sub(pattern, replacement, value)
    return value


def _diag_file_info(path_value: Any) -> dict:
    try:
        path = Path(path_value)
        result = {
            "path": str(path),
            "exists": path.exists(),
            "is_file": path.is_file() if path.exists() else False,
            "is_dir": path.is_dir() if path.exists() else False,
        }
        if path.exists():
            stat = path.stat()
            result.update({
                "size_bytes": int(stat.st_size),
                "modified_epoch": float(stat.st_mtime),
            })
        return result
    except Exception as exc:
        return {"path": str(path_value), "error": repr(exc)}


def _diag_process_snapshot() -> dict:
    result = {
        "epoch": time.time(),
        "perf_counter": time.perf_counter(),
        "pid": os.getpid(),
        "thread_count": len(threading.enumerate()),
        "threads": [
            {"name": thread.name, "ident": thread.ident, "daemon": thread.daemon, "alive": thread.is_alive()}
            for thread in threading.enumerate()
        ],
    }
    try:
        import psutil
        process = psutil.Process(os.getpid())
        memory = process.memory_info()
        result.update({
            "rss_bytes": int(memory.rss),
            "vms_bytes": int(memory.vms),
            "cpu_percent": float(process.cpu_percent(interval=None)),
            "open_files": len(process.open_files()),
            "num_handles": int(process.num_handles()) if hasattr(process, "num_handles") else None,
        })
    except Exception as exc:
        result["psutil_unavailable"] = repr(exc)
    return result


def _diag_thread_dump() -> str:
    lines = [f"Thread dump generated {time.strftime('%Y-%m-%d %H:%M:%S')}"]
    frames = sys._current_frames()
    for thread in threading.enumerate():
        lines.append("\n" + "=" * 88)
        lines.append(
            f"Thread name={thread.name!r} ident={thread.ident} daemon={thread.daemon} alive={thread.is_alive()}"
        )
        frame = frames.get(thread.ident)
        if frame is None:
            lines.append("<no Python frame available>")
        else:
            lines.extend(traceback.format_stack(frame))
    return "\n".join(lines)


def _diag_owner_snapshot(owner: Any) -> dict:
    """Collect small, generic state summaries without serializing the full ranker."""
    if owner is None:
        return {}
    result = {"owner_type": type(owner).__name__}
    preferred = [
        "current_comparison", "comparison_buffer", "buffer", "history",
        "generation_paused", "generation_in_progress", "generated_count",
        "storage_settings", "active_pool", "favorites", "save_status",
        "pending_save", "pending_saves", "save_queue", "matchmaking_mode",
    ]
    for name in preferred:
        if hasattr(owner, name):
            try:
                result[name] = _diag_safe_json_value(getattr(owner, name))
            except Exception as exc:
                result[name] = {"error": repr(exc)}
    # Include lengths/status for additional likely performance-relevant fields.
    for name in sorted(getattr(owner, "__dict__", {}).keys()):
        lowered = name.casefold()
        if name in result or not any(token in lowered for token in ("buffer", "queue", "save", "thread", "cache")):
            continue
        try:
            result[name] = _diag_safe_json_value(getattr(owner, name))
        except Exception:
            pass
        if len(result) >= 28:
            break
    return result


class _ArtistRankerDiagnostics:
    def __init__(self):
        self._lock = threading.RLock()
        self.enabled = self._load_enabled()
        self.session_id = time.strftime("%Y%m%d_%H%M%S") + f"_{os.getpid()}"
        self.sequence = 0
        self.last_record: dict = {}
        self.last_export: Optional[Path] = None

    def _load_enabled(self) -> bool:
        try:
            if STORAGE_SETTINGS_FILE.exists():
                data = json.loads(STORAGE_SETTINGS_FILE.read_text(encoding="utf-8"))
                return bool(data.get(DIAGNOSTICS_SETTING_KEY, False)) if isinstance(data, dict) else False
        except Exception:
            pass
        return False

    def _persist_enabled(self) -> None:
        try:
            data = {}
            if STORAGE_SETTINGS_FILE.exists():
                loaded = json.loads(STORAGE_SETTINGS_FILE.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    data = loaded
            data[DIAGNOSTICS_SETTING_KEY] = bool(self.enabled)
            temporary = STORAGE_SETTINGS_FILE.with_suffix(STORAGE_SETTINGS_FILE.suffix + ".diagnostics.tmp")
            temporary.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
            temporary.replace(STORAGE_SETTINGS_FILE)
        except Exception as exc:
            print(f"Diagnostics warning: could not persist toggle: {exc}")

    def set_enabled(self, value: Any) -> bool:
        with self._lock:
            self.enabled = bool(value)
            self._persist_enabled()
            if self.enabled:
                self.write("diagnostics_enabled", {"message": "Full diagnostics enabled"}, force=True)
            return self.enabled

    def _rotate(self, path: Path) -> None:
        try:
            if not path.exists() or path.stat().st_size < DIAGNOSTICS_MAX_LOG_BYTES:
                return
            oldest = path.with_name(path.name + f".{DIAGNOSTICS_ROTATED_LOGS}")
            oldest.unlink(missing_ok=True)
            for index in range(DIAGNOSTICS_ROTATED_LOGS - 1, 0, -1):
                source = path.with_name(path.name + f".{index}")
                destination = path.with_name(path.name + f".{index + 1}")
                if source.exists():
                    source.replace(destination)
            path.replace(path.with_name(path.name + ".1"))
        except Exception as exc:
            print(f"Diagnostics warning: log rotation failed: {exc}")

    def write(self, event: str, payload: Any, *, browser: bool = False, force: bool = False) -> None:
        if not self.enabled and not force:
            return
        with self._lock:
            self.sequence += 1
            record = {
                "schema": 1,
                "session_id": self.session_id,
                "sequence": self.sequence,
                "event": str(event),
                "epoch": time.time(),
                "iso_time": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                "thread": threading.current_thread().name,
                "payload": _diag_safe_json_value(payload),
            }
            if str(event) == "duel_callback" and isinstance(payload, dict):
                profile_text = payload.get("cprofile")
                if isinstance(profile_text, str):
                    record["payload"]["cprofile"] = profile_text[:250000]
                phase_timings = payload.get("phase_timings")
                if phase_timings is not None:
                    record["payload"]["phase_timings"] = phase_timings
            path = DIAGNOSTICS_BROWSER_LOG if browser else DIAGNOSTICS_SERVER_LOG
            try:
                DIAGNOSTICS_DIR.mkdir(parents=True, exist_ok=True)
                self._rotate(path)
                with path.open("a", encoding="utf-8") as handle:
                    handle.write(json.dumps(record, ensure_ascii=False, default=str) + "\n")
                self.last_record = record
            except Exception as exc:
                print(f"Diagnostics warning: could not append log: {exc}")

    def browser_event(self, payload_text: Any) -> str:
        if not self.enabled:
            return "Diagnostics are disabled."
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {"raw": str(payload_text or "")[:2000], "parse_error": True}
        self.write("browser_transition", payload, browser=True)
        return f"Browser trace received at {time.strftime('%H:%M:%S')}."

    def status_markdown(self) -> str:
        state = "**ON**" if self.enabled else "**OFF**"
        server_size = DIAGNOSTICS_SERVER_LOG.stat().st_size if DIAGNOSTICS_SERVER_LOG.exists() else 0
        browser_size = DIAGNOSTICS_BROWSER_LOG.stat().st_size if DIAGNOSTICS_BROWSER_LOG.exists() else 0
        return (
            f"Full diagnostics: {state}  \n"
            f"Session: `{self.session_id}`  \n"
            f"Server log: `{DIAGNOSTICS_SERVER_LOG}` ({server_size:,} bytes)  \n"
            f"Browser log: `{DIAGNOSTICS_BROWSER_LOG}` ({browser_size:,} bytes)"
        )

    def latest_json(self) -> str:
        if not self.last_record:
            return "No diagnostic event has been recorded in this process."
        return json.dumps(self.last_record, ensure_ascii=False, indent=2, default=str)

    def clear(self) -> str:
        with self._lock:
            for base in (DIAGNOSTICS_SERVER_LOG, DIAGNOSTICS_BROWSER_LOG):
                base.unlink(missing_ok=True)
                for index in range(1, DIAGNOSTICS_ROTATED_LOGS + 2):
                    base.with_name(base.name + f".{index}").unlink(missing_ok=True)
            self.last_record = {}
        return "Diagnostic logs cleared."

    def export_bundle(self, owner: Any = None) -> Path:
        with self._lock:
            DIAGNOSTICS_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
            stamp = time.strftime("%Y%m%d_%H%M%S")
            destination = DIAGNOSTICS_EXPORT_DIR / f"artist_ranker_diagnostics_{stamp}.zip"
            script_path = Path(__file__).resolve()
            config_path = SCRIPT_DIR / "config.py"
            source_paths = [script_path, config_path, PROGRAM_DIR / "ranker_data_layout.py"]
            known_paths = {
                name: globals().get(name)
                for name in (
                    "ARTIST_TAGS_FILE", "DATA_MANIFEST_FILE", "ELO_RATINGS_FILE", "COMPARISON_HISTORY_FILE",
                    "BUFFER_STATE_FILE", "COMBINATION_RATINGS_FILE", "MATCHMAKING_STATE_FILE",
                    "FAVORITES_FILE", "CLASSIFICATION_TAGS_FILE", "ENTITY_NOTES_FILE",
                    "TOP_SEARCH_RATINGS_FILE", "ARTIST_PORTRAITS_FILE", "STORAGE_SETTINGS_FILE",
                )
                if globals().get(name) is not None
            }
            summary = {
                "schema": 1,
                "created": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                "enabled": self.enabled,
                "session_id": self.session_id,
                "process": _diag_process_snapshot(),
                "owner": _diag_owner_snapshot(owner),
                "data_layout": DATA_LAYOUT.status_dict(),
                "files": {key: _diag_file_info(value) for key, value in known_paths.items()},
                "log_files": {
                    "server": _diag_file_info(DIAGNOSTICS_SERVER_LOG),
                    "browser": _diag_file_info(DIAGNOSTICS_BROWSER_LOG),
                },
            }
            environment_lines = [
                f"Python: {sys.version}",
                f"Executable: {sys.executable}",
                f"Platform: {platform.platform()}",
                f"Working directory: {Path.cwd()}",
                f"Script directory: {SCRIPT_DIR}",
            ]
            try:
                environment_lines.append(f"Gradio: {getattr(gr, '__version__', 'unknown')}")
            except Exception:
                pass
            try:
                import importlib.metadata as metadata
                packages = sorted(
                    f"{dist.metadata.get('Name', 'unknown')}=={dist.version}"
                    for dist in metadata.distributions()
                    if dist.metadata.get("Name")
                )
                environment_lines.append("\nInstalled packages:\n" + "\n".join(packages))
            except Exception as exc:
                environment_lines.append(f"Package listing failed: {exc!r}")

            readme = (
                "NovelAI Artist Ranker diagnostic bundle\n"
                "========================================\n"
                "Upload this ZIP to ChatGPT together with a short description of when the delay occurred.\n"
                "It contains bounded server/browser timing logs, cProfile summaries, process/thread state,\n"
                "file metadata, environment information, and redacted source snapshots. API-looking secrets\n"
                "are removed from the source snapshots. Ranking data and generated images are not included.\n"
            )

            with zipfile.ZipFile(destination, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("README.txt", readme)
                archive.writestr("summary.json", json.dumps(summary, ensure_ascii=False, indent=2, default=str))
                archive.writestr("thread_stacks.txt", _diag_thread_dump())
                archive.writestr("environment.txt", "\n".join(environment_lines))
                for log_path in (DIAGNOSTICS_SERVER_LOG, DIAGNOSTICS_BROWSER_LOG):
                    if log_path.exists():
                        archive.write(log_path, arcname=f"logs/{log_path.name}")
                    for index in range(1, DIAGNOSTICS_ROTATED_LOGS + 2):
                        rotated = log_path.with_name(log_path.name + f".{index}")
                        if rotated.exists():
                            archive.write(rotated, arcname=f"logs/{rotated.name}")
                for optional_name in ("boot_diagnostics.log", "boot_diagnostics.json"):
                    optional_path = SCRIPT_DIR / optional_name
                    if optional_path.exists():
                        archive.write(optional_path, arcname=f"logs/{optional_name}")
                for path in source_paths:
                    if path.exists() and path.is_file():
                        try:
                            redacted = _diag_redact_text(path.read_text(encoding="utf-8", errors="replace"))
                            archive.writestr(f"source_redacted/{path.name}", redacted)
                        except Exception as exc:
                            archive.writestr(f"source_redacted/{path.name}.error.txt", repr(exc))
            self.last_export = destination
            self.write("diagnostic_bundle_exported", {"path": str(destination)}, force=True)
            return destination


GLOBAL_DUEL_DIAGNOSTICS = _ArtistRankerDiagnostics()


_DIAGNOSTIC_TRACE_LOCAL = threading.local()


class _DuelPhaseTrace:
    def __init__(self, action: str):
        self.action = str(action)
        self.started = time.perf_counter()
        self.previous = self.started
        self.marks: List[dict] = []

    def mark(self, name: str, **details: Any) -> None:
        now = time.perf_counter()
        self.marks.append({
            "name": str(name),
            "delta_ms": round((now - self.previous) * 1000.0, 3),
            "elapsed_ms": round((now - self.started) * 1000.0, 3),
            **_diag_safe_json_value(details),
        })
        self.previous = now

    def summary(self) -> dict:
        return {
            "action": self.action,
            "total_ms": round((time.perf_counter() - self.started) * 1000.0, 3),
            "marks": list(self.marks),
        }


def _current_duel_trace() -> Optional[_DuelPhaseTrace]:
    return getattr(_DIAGNOSTIC_TRACE_LOCAL, "current", None)


def _diagnostic_callback(action: str, callback: Any, owner: Any = None):
    """Wrap a Gradio action; profiling is completely bypassed while disabled."""
    @functools.wraps(callback)
    def wrapped(*args, **kwargs):
        if not GLOBAL_DUEL_DIAGNOSTICS.enabled:
            return callback(*args, **kwargs)

        started_perf = time.perf_counter()
        started_epoch = time.time()
        GLOBAL_DUEL_DIAGNOSTICS.write(
            "duel_callback_received",
            {
                "action": action,
                "started_epoch": started_epoch,
                "started_perf": started_perf,
                "thread": threading.current_thread().name,
                "owner": _diag_owner_snapshot(owner),
            },
        )
        before_process = _diag_process_snapshot()
        before_owner = _diag_owner_snapshot(owner)
        profiler = cProfile.Profile()
        trace = _DuelPhaseTrace(action)
        _DIAGNOSTIC_TRACE_LOCAL.current = trace
        success = False
        error_text = None
        result_summary = None
        try:
            profiler.enable()
            result = callback(*args, **kwargs)
            success = True
            result_summary = _diag_safe_json_value(result)
            return result
        except Exception:
            error_text = traceback.format_exc()
            raise
        finally:
            try:
                profiler.disable()
            except Exception:
                pass
            duration_ms = (time.perf_counter() - started_perf) * 1000.0
            stream = io.StringIO()
            try:
                stats = pstats.Stats(profiler, stream=stream).strip_dirs()
                stats.sort_stats("cumulative").print_stats(DIAGNOSTICS_PROFILE_LINES)
                stream.write("\n\n--- Sorted by internal time ---\n")
                stats.sort_stats("tottime").print_stats(DIAGNOSTICS_PROFILE_LINES)
            except Exception as exc:
                stream.write(f"Could not render cProfile statistics: {exc!r}")
            payload = {
                "action": action,
                "started_epoch": started_epoch,
                "duration_ms": round(duration_ms, 3),
                "success": success,
                "error": error_text,
                "args": _diag_safe_json_value(args),
                "kwargs": _diag_safe_json_value(kwargs),
                "result": result_summary,
                "process_before": before_process,
                "process_after": _diag_process_snapshot(),
                "owner_before": before_owner,
                "owner_after": _diag_owner_snapshot(owner),
                "cprofile": stream.getvalue(),
                "phase_timings": trace.summary(),
            }
            try:
                delattr(_DIAGNOSTIC_TRACE_LOCAL, "current")
            except Exception:
                pass
            if duration_ms >= DIAGNOSTICS_SLOW_CALLBACK_MS:
                payload["slow_callback_thread_dump"] = _diag_thread_dump()
            GLOBAL_DUEL_DIAGNOSTICS.write("duel_callback", payload)
    return wrapped


DIAGNOSTICS_HEAD = '\n<style>\n.diagnostics-hidden-bridge { display: none !important; }\n</style>\n<script>\n(() => {\n  if (window.__artistRankerInputDiagnosticsV1710) return;\n  window.__artistRankerInputDiagnosticsV1710 = true;\n\n  const root = document.documentElement;\n  const sessionId = `${Date.now()}-${Math.random().toString(36).slice(2)}`;\n  let sequence = 0, actionCounter = 0, currentAction = null, queue = [], flushTimer = 0;\n  let lastRootClasses = root.className, lastImages = \'\', lastStatus = \'\', lastResult = \'\', lastToken = \'\';\n  const component=id=>document.getElementById(id);\n  const inputOf=id=>{const node=component(id);return node?(node.matches?.(\'input,textarea,select\')?node:node.querySelector(\'input,textarea,select\')):null;};\n  const buttonOf=id=>{const node=component(id);return node?(node.matches?.(\'button\')?node:node.querySelector(\'button\')):null;};\n  const enabled=()=>Boolean(inputOf(\'full-diagnostics-enabled\')?.checked);\n  const nowPerf=()=>Math.round(performance.now()*1000)/1000;\n  const imageSignature=()=>[\'compare-image-a\',\'compare-image-b\'].map(id=>{const image=component(id)?.querySelector(\'img\');return image?.currentSrc||image?.src||\'\';}).join(\'|\');\n  const normalizeResultText=value=>String(value||\'\')\n    .replace(/^\\s*\\d+(?:\\.\\d+)?s\\b\\s*/,\'\')\n    .replace(/\\s+/g,\' \')\n    .trim();\n  const stateSnapshot=()=>({\n    root_classes:root.className,\n    active_element:document.activeElement?.id||document.activeElement?.tagName||\'\',\n    visibility:document.visibilityState,\n    image_signature:imageSignature(),\n    transition_token:String(inputOf(\'qol-transition-token\')?.value||\'\'),\n    status:String(component(\'status-message\')?.textContent||\'\').trim().slice(0,500),\n    result:normalizeResultText(component(\'duel-result-banner\')?.textContent).slice(0,500),\n  });\n  const actionFromRootId=id=>({\'pick-a-btn\':\'pick_a\',\'pick-b-btn\':\'pick_b\',\'tie-btn\':\'tie\',\'both-bad-btn\':\'both_bad\',\'invalid-btn\':\'invalid\',\'skip-btn\':\'skip\',\'undo-btn\':\'undo\',\'redo-btn\':\'redo\',\'compare-image-a\':\'pick_a\',\'compare-image-b\':\'pick_b\'})[String(id||\'\')]||\'\';\n  const actionTarget=event=>{const path=event?.composedPath?.()||[];const node=path.find(item=>actionFromRootId(item?.id))||event?.target?.closest?.(\'#pick-a-btn,#pick-b-btn,#tie-btn,#both-bad-btn,#invalid-btn,#skip-btn,#undo-btn,#redo-btn,#compare-image-a,#compare-image-b\');const rootId=node?.id||node?.closest?.(\'[id]\')?.id||\'\';return{action:actionFromRootId(rootId),rootId};};\n  const actionFromKey=event=>{const codeKey=({Digit1:\'1\',Numpad1:\'1\',Digit2:\'2\',Numpad2:\'2\',Digit0:\'0\',Numpad0:\'0\',KeyT:\'t\',KeyB:\'b\',KeyI:\'i\',KeyS:\'s\'})[event.code];const key=codeKey||String(event.key||\'\').toLowerCase();const rootId=({\'1\':\'pick-a-btn\',\'2\':\'pick-b-btn\',\'t\':\'tie-btn\',\'b\':\'both-bad-btn\',\'i\':\'invalid-btn\',\'s\':\'skip-btn\',\'0\':\'undo-btn\'})[key]||\'\';return{action:actionFromRootId(rootId),rootId,key};};\n  const enqueue=(eventName,details={})=>{\n    if(!enabled())return;\n    queue.push({schema:5,event:eventName,session_id:sessionId,sequence:++sequence,client_epoch:Date.now()/1000,client_perf_ms:nowPerf(),action_id:details.action_id||currentAction?.id||\'\',action:details.action||currentAction?.action||\'\',source:details.source||currentAction?.source||\'\',elapsed_from_input_ms:currentAction?Math.round((performance.now()-currentAction.startedPerf)*1000)/1000:null,...details,snapshot:stateSnapshot()});\n    if(queue.length>=20)flush();else if(!flushTimer)flushTimer=setTimeout(flush,70);\n  };\n  const flush=()=>{clearTimeout(flushTimer);flushTimer=0;if(!queue.length)return;const events=queue.splice(0,50);fetch(\'/api/diagnostics/browser-events\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({events}),cache:\'no-store\',keepalive:true}).catch(()=>{});if(queue.length)flushTimer=setTimeout(flush,70);};\n  const beginAction=(action,source,details={})=>{\n    if(!enabled()||!action)return;\n    const previous=currentAction?.id||\'\';\n    currentAction={id:`${sessionId}-${++actionCounter}`,action,source,startedPerf:performance.now(),startedEpoch:Date.now()/1000};\n    enqueue(\'physical_input\',{...details,previous_action_id:previous});\n    const expected=currentAction.id;\n    setTimeout(()=>{if(currentAction?.id===expected){enqueue(\'input_timeout_30s\');currentAction=null;flush();}},30000);\n  };\n  const waitForPaint=(eventName,actionId,clearAfter=false)=>{\n    const started=performance.now();\n    const wait=attempt=>{\n      if(attempt>360)return;\n      const nodes=[\'compare-image-a\',\'compare-image-b\'].map(id=>component(id)?.querySelector(\'img\')).filter(Boolean);\n      if(nodes.length===2&&nodes.every(image=>image.complete&&image.naturalWidth>0)){\n        requestAnimationFrame(()=>requestAnimationFrame(()=>{\n          enqueue(eventName,{action_id:actionId||\'\',paint_wait_ms:Math.round((performance.now()-started)*1000)/1000});\n          if(clearAfter&&currentAction?.id===actionId){currentAction=null;flush();}\n        }));return;\n      }\n      setTimeout(()=>wait(attempt+1),16);\n    };wait(0);\n  };\n\n  document.addEventListener(\'pointerdown\',event=>{const hit=actionTarget(event);if(!hit.action)return;beginAction(hit.action,event.pointerType||\'pointer\',{root_id:hit.rootId,pointer_phase:\'down\',pointer_button:event.button,pointer_x:event.clientX,pointer_y:event.clientY,trusted:event.isTrusted});},true);\n  document.addEventListener(\'pointerup\',event=>{const hit=actionTarget(event);if(hit.action)enqueue(\'pointer_up\',{root_id:hit.rootId,pointer_button:event.button,trusted:event.isTrusted,default_prevented:event.defaultPrevented});},true);\n  document.addEventListener(\'keydown\',event=>{if(event.target?.matches?.(\'input,textarea,select,[contenteditable="true"]\')||event.isComposing)return;const hit=actionFromKey(event);if(!hit.action)return;beginAction(hit.action,\'keyboard\',{root_id:hit.rootId,key:event.key,code:event.code,repeat:event.repeat,trusted:event.isTrusted,default_prevented:event.defaultPrevented});},true);\n  document.addEventListener(\'click\',event=>{const hit=actionTarget(event);if(!hit.action)return;if(!currentAction)beginAction(hit.action,event.isTrusted?\'click\':\'programmatic-click\',{root_id:hit.rootId});enqueue(\'click_capture\',{root_id:hit.rootId,trusted:event.isTrusted,default_prevented:event.defaultPrevented,button_disabled:Boolean(buttonOf(hit.rootId)?.disabled),aria_disabled:buttonOf(hit.rootId)?.getAttribute(\'aria-disabled\')||\'\'});queueMicrotask(()=>enqueue(\'click_after_capture_dispatch\',{root_id:hit.rootId,default_prevented:event.defaultPrevented}));},true);\n  document.addEventListener(\'click\',event=>{const hit=actionTarget(event);if(hit.action)enqueue(\'click_bubble_reached\',{root_id:hit.rootId,trusted:event.isTrusted,default_prevented:event.defaultPrevented});},false);\n  window.addEventListener(\'artist-elo-queue-shortcut\',event=>enqueue(\'shortcut_queue_event\',{root_id:String(event.detail?.rootId||\'\')}));\n  window.addEventListener(\'artist-elo-transition-event\',event=>{const detail={...(event.detail||{})};const name=String(detail.event||\'unknown\');delete detail.event;enqueue(`transition_${name}`,detail);});\n\n  const mutationObserver=new MutationObserver(()=>{\n    if(!enabled())return;\n    if(root.className!==lastRootClasses){lastRootClasses=root.className;enqueue(\'processing_classes_changed\');}\n    const images=imageSignature();\n    if(images!==lastImages){const previous=lastImages;lastImages=images;const actionId=currentAction?.id||\'\';enqueue(\'image_sources_changed\',{previous_image_signature:previous});waitForPaint(\'images_loaded_and_painted\',actionId,false);}\n    const token=String(inputOf(\'qol-transition-token\')?.value||\'\');\n    if(token!==lastToken){const previous=lastToken;lastToken=token;const actionId=currentAction?.id||\'\';enqueue(\'transition_token_changed\',{previous_token:previous,new_token:token});if(actionId)waitForPaint(\'authoritative_images_painted\',actionId,true);}\n    const status=String(component(\'status-message\')?.textContent||\'\').trim();if(status!==lastStatus){const previous=lastStatus;lastStatus=status;enqueue(\'status_changed\',{previous_status:previous.slice(0,500),new_status:status.slice(0,500)});}\n    const result=normalizeResultText(component(\'duel-result-banner\')?.textContent);if(result!==lastResult){const previous=lastResult;lastResult=result;enqueue(\'result_changed\',{previous_result:previous.slice(0,500),new_result:result.slice(0,500)});}\n  });\n\n  const installPerformanceObservers=()=>{\n    try{\n      if(PerformanceObserver.supportedEntryTypes?.includes(\'longtask\'))new PerformanceObserver(list=>{if(!enabled())return;for(const entry of list.getEntries())enqueue(\'browser_long_task\',{start_ms:Math.round(entry.startTime*1000)/1000,duration_ms:Math.round(entry.duration*1000)/1000});}).observe({type:\'longtask\',buffered:true});\n    }catch(_){}\n    try{\n      if(PerformanceObserver.supportedEntryTypes?.includes(\'resource\'))new PerformanceObserver(list=>{if(!enabled())return;for(const entry of list.getEntries()){let path=\'\';try{path=new URL(entry.name,location.href).pathname;}catch(_){}if(path===\'/api/duel/state\'||path.includes(\'/ranker/gradio_api/run/predict\'))enqueue(\'relevant_network_request\',{path,duration_ms:Math.round(entry.duration*1000)/1000,start_ms:Math.round(entry.startTime*1000)/1000,transfer_size:entry.transferSize||0});}}).observe({type:\'resource\',buffered:true});\n    }catch(_){}\n    let expected=performance.now()+250;\n    setInterval(()=>{const now=performance.now(),lag=now-expected;expected=now+250;if(enabled()&&document.visibilityState===\'visible\'&&lag>150)enqueue(\'event_loop_stall\',{lag_ms:Math.round(lag*1000)/1000});},250);\n  };\n  const start=()=>{\n    lastRootClasses=root.className;lastImages=imageSignature();lastToken=String(inputOf(\'qol-transition-token\')?.value||\'\');lastStatus=String(component(\'status-message\')?.textContent||\'\').trim();lastResult=normalizeResultText(component(\'duel-result-banner\')?.textContent);\n    mutationObserver.observe(document.documentElement,{attributes:true,attributeFilter:[\'class\']});\n    mutationObserver.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:[\'src\',\'class\',\'value\'],characterData:true});\n    installPerformanceObservers();document.addEventListener(\'visibilitychange\',()=>enqueue(\'visibility_changed\'));window.addEventListener(\'focus\',()=>enqueue(\'window_focus\'));window.addEventListener(\'blur\',()=>enqueue(\'window_blur\'));window.addEventListener(\'pagehide\',flush);\n  };\n  if(document.readyState===\'loading\')document.addEventListener(\'DOMContentLoaded\',start,{once:true});else start();\n})();\n</script>\n'

# Matchmaking strategy. Coverage is the safe default: broad discovery continues
# through 80% observed coverage, then smoothly tapers toward Top-100/Top-50
# selection. Selection mode is a persisted manual override that immediately uses
# the selection-heavy endpoint while retaining a small discovery/screening budget.
