def gallery_thumbnail_path(original_path: str, force_full_resolution: bool = False) -> Optional[str]:
    """Return a cached lightweight gallery preview, or the original on fallback."""
    path = Path(str(original_path or ""))
    if not path.exists() or not path.is_file():
        return None
    if force_full_resolution or PILImage is None:
        return str(path)
    try:
        stat = path.stat()
        fingerprint = hashlib.sha1(
            f"{path.resolve()}|{stat.st_mtime_ns}|{stat.st_size}".encode("utf-8")
        ).hexdigest()[:24]
        THUMBNAIL_DIR.mkdir(parents=True, exist_ok=True)
        thumb = THUMBNAIL_DIR / f"gallery_thumb_{fingerprint}.jpg"
        if thumb.exists():
            return str(thumb)
        with PILImage.open(path) as image:
            image = image.convert("RGB")
            image.thumbnail((720, 720))
            image.save(thumb, "JPEG", quality=86, optimize=True)
        return str(thumb)
    except Exception as e:
        print(f"Warning: Could not create gallery thumbnail for {path}: {e}")
        return str(path)


def gallery_record_preview(record: dict, side: str, force_full_resolution: bool = False) -> Optional[str]:
    """Return a historical original or its retained thumbnail after cleanup."""
    normalized_side = "b" if str(side or "A").strip().upper() == "B" else "a"
    original = Path(str(record.get(f"image_{normalized_side}_path", "") or ""))
    if force_full_resolution:
        return str(original) if original.is_file() else None
    thumbnail = Path(str(record.get(f"image_{normalized_side}_thumbnail_path", "") or ""))
    if thumbnail.is_file():
        return str(thumbnail)
    return gallery_thumbnail_path(str(original), False)


def gallery_record_preview_exists(record: dict, side: str) -> bool:
    """Check Gallery availability without creating thumbnails or opening images.

    The Gallery list can contain thousands of duels. Its index must stay metadata-only;
    thumbnail generation is deferred until a specific duel is opened.
    """
    normalized_side = "b" if str(side or "A").strip().upper() == "B" else "a"
    original = Path(str(record.get(f"image_{normalized_side}_path", "") or ""))
    if original.is_file():
        return True
    thumbnail = Path(str(record.get(f"image_{normalized_side}_thumbnail_path", "") or ""))
    return thumbnail.is_file()


def gallery_record_retention_status(record: dict) -> str:
    """Summarize whether full-resolution historical originals remain retained."""
    statuses: List[str] = []
    for side in ("a", "b"):
        original = Path(str(record.get(f"image_{side}_path", "") or ""))
        if original.is_file():
            statuses.append("original")
            continue
        status = str(record.get(f"image_{side}_retention_status", "") or "").strip().casefold()
        thumbnail = Path(str(record.get(f"image_{side}_thumbnail_path", "") or ""))
        if status == "quarantined":
            statuses.append("recovery")
        elif thumbnail.is_file():
            statuses.append("thumbnail")
        else:
            statuses.append("missing")
    if statuses == ["original", "original"]:
        return "Both full-resolution originals are retained."
    if "recovery" in statuses:
        return "One or both originals are in the recovery quarantine; retained thumbnails remain available when configured."
    if all(value in {"original", "thumbnail"} for value in statuses):
        return "One or both full-resolution originals were removed by retention cleanup; gallery thumbnails remain available."
    return "One or both historical image files are unavailable."


# --------------------------------------------------------------------------------
# Phase 2 scoring helpers
# --------------------------------------------------------------------------------

def clamp(value: float, minimum: float, maximum: float) -> float:
    return max(minimum, min(maximum, value))


def confidence_info(comparisons: int) -> Tuple[str, float]:
    """Return a human-readable confidence label and a 0-1 confidence factor."""
    comparisons = max(0, int(comparisons))
    if comparisons <= 2:
        return "Provisional", comparisons / 10.0
    if comparisons <= 5:
        return "Low", 0.30 + (comparisons - 3) * 0.10
    if comparisons <= 11:
        return "Medium", 0.55 + (comparisons - 6) * 0.05
    if comparisons <= 24:
        return "High", 0.82 + (comparisons - 12) * 0.01
    return "Very high", 1.0


def weighted_result_weight(opponent_rating: float, opponent_comparisons: int) -> float:
    """
    Weight a result by opponent strength and confidence.

    A 1500-rated fully established opponent has weight 1.0. Strong opponents
    count more, weak opponents count less, and provisional opponents are
    discounted until there is enough evidence that their rating is meaningful.
    """
    strength = clamp(1.0 + (float(opponent_rating) - DEFAULT_ELO) / 500.0, 0.50, 1.75)
    _, confidence = confidence_info(opponent_comparisons)
    confidence_weight = 0.50 + 0.50 * confidence
    return strength * confidence_weight


def confidence_adjusted_weighted_win_rate(
    weighted_wins: float,
    weighted_total: float,
    own_comparisons: int,
) -> Tuple[float, float]:
    """
    Return (displayed weighted WR, raw opponent-weighted WR).

    Results are first weighted by opponent strength/confidence. The resulting
    rate is then shrunk toward 50% while the artist or combination has only a
    small sample. As more valid duels accumulate, the displayed score places
    progressively more weight on the observed results, reaching full weight at
    the Very-high confidence threshold.

    Neutral overlap appearances (the same artist on both sides) are excluded
    before this function is called and therefore do not increase the sample.
    """
    if weighted_total <= 0 or own_comparisons <= 0:
        return 0.0, 0.0
    raw_rate = clamp(float(weighted_wins) / float(weighted_total) * 100.0, 0.0, 100.0)
    _, own_confidence = confidence_info(int(own_comparisons))
    adjusted_rate = 50.0 + (raw_rate - 50.0) * own_confidence
    return clamp(adjusted_rate, 0.0, 100.0), raw_rate


# --------------------------------------------------------------------------------
# ELO Rating System
# --------------------------------------------------------------------------------

@dataclass
class ELOSystem:
    """Manages overall and solo/duo/trio ELO ratings for artists."""
    ratings: dict = field(default_factory=dict)
    comparison_count: int = 0
    artist_comparisons: dict = field(default_factory=dict)
    ratings_by_size: dict = field(default_factory=lambda: {"solo": {}, "duo": {}, "trio": {}})
    artist_comparisons_by_size: dict = field(
        default_factory=lambda: {"solo": {}, "duo": {}, "trio": {}}
    )

    SIZE_KEYS = ("solo", "duo", "trio")

    @staticmethod
    def size_key(group_size: int) -> str:
        return {1: "solo", 2: "duo"}.get(group_size, "trio")

    @classmethod
    def load(cls, filepath: Path) -> "ELOSystem":
        """Load ratings while remaining compatible with older rating files."""
        if not filepath.exists():
            return cls()
        with open(filepath, "r", encoding="utf-8") as f:
            data = json.load(f)
        system = cls()
        system.ratings = data.get("ratings", {})
        system.comparison_count = data.get("comparison_count", 0)
        system.artist_comparisons = data.get("artist_comparisons", {})
        loaded_ratings_by_size = data.get("ratings_by_size", {})
        loaded_counts_by_size = data.get("artist_comparisons_by_size", {})
        system.ratings_by_size = {
            key: dict(loaded_ratings_by_size.get(key, {})) for key in cls.SIZE_KEYS
        }
        system.artist_comparisons_by_size = {
            key: dict(loaded_counts_by_size.get(key, {})) for key in cls.SIZE_KEYS
        }
        return system

    def save(self, filepath: Path):
        """Save overall and category ratings in one backward-compatible JSON file."""
        filepath.parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, "w", encoding="utf-8") as f:
            json.dump({
                "ratings": self.ratings,
                "comparison_count": self.comparison_count,
                "artist_comparisons": self.artist_comparisons,
                "ratings_by_size": self.ratings_by_size,
                "artist_comparisons_by_size": self.artist_comparisons_by_size,
            }, f, indent=2, ensure_ascii=False)

    def get_rating(self, artist: str) -> float:
        return self.ratings.get(artist, DEFAULT_ELO)

    def get_size_rating(self, artist: str, size_key: str) -> float:
        return self.ratings_by_size.get(size_key, {}).get(artist, DEFAULT_ELO)

    def get_artist_comparison_count(self, artist: str) -> int:
        return self.artist_comparisons.get(artist, 0)

    def get_size_comparison_count(self, artist: str, size_key: str) -> int:
        return self.artist_comparisons_by_size.get(size_key, {}).get(artist, 0)

    def get_combined_rating(self, artists: List[str]) -> float:
        if not artists:
            return DEFAULT_ELO
        return sum(self.get_rating(a) for a in artists) / len(artists)

    def calculate_expected_score(self, rating_a: float, rating_b: float) -> float:
        return 1 / (1 + 10 ** ((rating_b - rating_a) / 400))

    def _calculate_changes(
        self,
        winners: List[str],
        losers: List[str],
        winner_rating_getter,
        loser_rating_getter,
    ) -> Tuple[List[Tuple[str, float]], List[Tuple[str, float]]]:
        """Calculate zero-sum individual changes for two artist groups."""
        overlap = set(winners) & set(losers)
        actual_winners = [a for a in winners if a not in overlap]
        actual_losers = [a for a in losers if a not in overlap]
        if not actual_winners or not actual_losers:
            return [], []

        winner_team_avg = sum(winner_rating_getter(a) for a in winners) / len(winners)
        loser_team_avg = sum(loser_rating_getter(a) for a in losers) / len(losers)

        winner_changes = []
        for artist in actual_winners:
            current = winner_rating_getter(artist)
            expected = self.calculate_expected_score(current, loser_team_avg)
            winner_changes.append((artist, K_FACTOR * (1 - expected)))

        loser_changes = []
        for artist in actual_losers:
            current = loser_rating_getter(artist)
            expected = self.calculate_expected_score(current, winner_team_avg)
            # Preserve the original project's individual-loss weighting, then
            # rescale all loser changes so the duel remains zero-sum.
            loser_changes.append((artist, K_FACTOR * (0 - (1 - expected))))

        total_gain = sum(change for _, change in winner_changes)
        total_loss = sum(change for _, change in loser_changes)
        scale_factor = (-total_gain / total_loss) if total_loss else 1.0
        loser_changes = [(artist, change * scale_factor) for artist, change in loser_changes]
        return winner_changes, loser_changes

    def _update_size_ratings(self, winners: List[str], losers: List[str]) -> Dict[str, float]:
        winner_key = self.size_key(len(winners))
        loser_key = self.size_key(len(losers))
        winner_map = self.ratings_by_size[winner_key]
        loser_map = self.ratings_by_size[loser_key]
        winner_counts = self.artist_comparisons_by_size[winner_key]
        loser_counts = self.artist_comparisons_by_size[loser_key]

        winner_changes, loser_changes = self._calculate_changes(
            winners,
            losers,
            lambda artist: winner_map.get(artist, DEFAULT_ELO),
            lambda artist: loser_map.get(artist, DEFAULT_ELO),
        )
        changes: Dict[str, float] = {}
        for artist, change in winner_changes:
            winner_map[artist] = winner_map.get(artist, DEFAULT_ELO) + change
            winner_counts[artist] = winner_counts.get(artist, 0) + 1
            changes[f"{winner_key}:{artist}"] = change
        for artist, change in loser_changes:
            loser_map[artist] = loser_map.get(artist, DEFAULT_ELO) + change
            loser_counts[artist] = loser_counts.get(artist, 0) + 1
            changes[f"{loser_key}:{artist}"] = change
        return changes

    def update_ratings(self, winners: List[str], losers: List[str]) -> dict:
        """Update overall ELO plus the size category each side participated in."""
        overlap = set(winners) & set(losers)
        if overlap:
            print(f"Overlap detected (neutral): {overlap}")

        winner_changes, loser_changes = self._calculate_changes(
            winners,
            losers,
            self.get_rating,
            self.get_rating,
        )
        overall_changes: Dict[str, float] = {}
        for artist, change in winner_changes:
            self.ratings[artist] = self.get_rating(artist) + change
            self.artist_comparisons[artist] = self.artist_comparisons.get(artist, 0) + 1
            overall_changes[artist] = change
        for artist, change in loser_changes:
            self.ratings[artist] = self.get_rating(artist) + change
            self.artist_comparisons[artist] = self.artist_comparisons.get(artist, 0) + 1
            overall_changes[artist] = change

        size_changes = self._update_size_ratings(winners, losers)
        self.comparison_count += 1
        return {"overall": overall_changes, "size": size_changes}

    def _update_size_tie_ratings(self, artists_a: List[str], artists_b: List[str]) -> Dict[str, float]:
        key_a = self.size_key(len(artists_a))
        key_b = self.size_key(len(artists_b))
        map_a = self.ratings_by_size[key_a]
        map_b = self.ratings_by_size[key_b]
        counts_a = self.artist_comparisons_by_size[key_a]
        counts_b = self.artist_comparisons_by_size[key_b]
        overlap = set(artists_a) & set(artists_b)
        active_a = [artist for artist in artists_a if artist not in overlap]
        active_b = [artist for artist in artists_b if artist not in overlap]
        if not active_a or not active_b:
            return {}
        avg_a = sum(map_a.get(a, DEFAULT_ELO) for a in artists_a) / len(artists_a)
        avg_b = sum(map_b.get(a, DEFAULT_ELO) for a in artists_b) / len(artists_b)
        expected_a = self.calculate_expected_score(avg_a, avg_b)
        team_change = K_FACTOR * (0.5 - expected_a)
        changes: Dict[str, float] = {}
        for artist in active_a:
            delta = team_change / max(1, len(active_a))
            map_a[artist] = map_a.get(artist, DEFAULT_ELO) + delta
            counts_a[artist] = counts_a.get(artist, 0) + 1
            changes[f"{key_a}:{artist}"] = delta
        for artist in active_b:
            delta = -team_change / max(1, len(active_b))
            map_b[artist] = map_b.get(artist, DEFAULT_ELO) + delta
            counts_b[artist] = counts_b.get(artist, 0) + 1
            changes[f"{key_b}:{artist}"] = delta
        return changes

    def update_tie_ratings(self, artists_a: List[str], artists_b: List[str]) -> dict:
        """Update legacy ELO for a tie while keeping the duel zero-sum."""
        overlap = set(artists_a) & set(artists_b)
        active_a = [artist for artist in artists_a if artist not in overlap]
        active_b = [artist for artist in artists_b if artist not in overlap]
        if not active_a or not active_b:
            return {"overall": {}, "size": {}}
        avg_a = sum(self.get_rating(a) for a in artists_a) / len(artists_a)
        avg_b = sum(self.get_rating(a) for a in artists_b) / len(artists_b)
        expected_a = self.calculate_expected_score(avg_a, avg_b)
        team_change = K_FACTOR * (0.5 - expected_a)
        changes: Dict[str, float] = {}
        for artist in active_a:
            delta = team_change / max(1, len(active_a))
            self.ratings[artist] = self.get_rating(artist) + delta
            self.artist_comparisons[artist] = self.artist_comparisons.get(artist, 0) + 1
            changes[artist] = delta
        for artist in active_b:
            delta = -team_change / max(1, len(active_b))
            self.ratings[artist] = self.get_rating(artist) + delta
            self.artist_comparisons[artist] = self.artist_comparisons.get(artist, 0) + 1
            changes[artist] = delta
        size_changes = self._update_size_tie_ratings(artists_a, artists_b)
        self.comparison_count += 1
        return {"overall": changes, "size": size_changes}

    def has_size_rating_data(self) -> bool:
        return any(self.ratings_by_size[key] for key in self.SIZE_KEYS)

    def rebuild_size_ratings_from_history(self, records: List[dict]):
        """Backfill solo/duo/trio ratings by replaying rated and tied history."""
        self.ratings_by_size = {key: {} for key in self.SIZE_KEYS}
        self.artist_comparisons_by_size = {key: {} for key in self.SIZE_KEYS}
        for record in records:
            artists_a = list(record.get("artists_a", []))
            artists_b = list(record.get("artists_b", []))
            winner = str(record.get("winner", "") or "").upper()
            if not artists_a or not artists_b or winner not in ("A", "B", "TIE"):
                continue
            if winner == "TIE":
                self._update_size_tie_ratings(artists_a, artists_b)
            else:
                winners = artists_a if winner == "A" else artists_b
                losers = artists_b if winner == "A" else artists_a
                self._update_size_ratings(winners, losers)

    def snapshot_size_state(self, artists: List[str]) -> dict:
        unique = list(dict.fromkeys(artists))
        return {
            "ratings": {
                key: {artist: self.ratings_by_size[key].get(artist) for artist in unique}
                for key in self.SIZE_KEYS
            },
            "comparisons": {
                key: {artist: self.artist_comparisons_by_size[key].get(artist) for artist in unique}
                for key in self.SIZE_KEYS
            },
        }

    def restore_size_state(self, snapshot: dict):
        for key in self.SIZE_KEYS:
            for artist, value in snapshot.get("ratings", {}).get(key, {}).items():
                if value is None:
                    self.ratings_by_size[key].pop(artist, None)
                else:
                    self.ratings_by_size[key][artist] = value
            for artist, value in snapshot.get("comparisons", {}).get(key, {}).items():
                if value is None:
                    self.artist_comparisons_by_size[key].pop(artist, None)
                else:
                    self.artist_comparisons_by_size[key][artist] = value

    def get_top_artists(self, n: int = 50) -> List[Tuple[str, float, int]]:
        sorted_artists = sorted(self.ratings.items(), key=lambda x: x[1], reverse=True)[:n]
        return [
            (artist, rating, self.get_artist_comparison_count(artist))
            for artist, rating in sorted_artists
        ]

    def get_bottom_artists(self, n: int = 20) -> List[Tuple[str, float]]:
        return sorted(self.ratings.items(), key=lambda x: x[1])[:n]


@dataclass
class CombinationELOSystem:
    """Tracks each exact solo/duo/trio artist combination as one ELO competitor."""
    entries: dict = field(default_factory=dict)

    @staticmethod
    def normalize_artists(artists: List[str]) -> List[str]:
        return sorted(dict.fromkeys(artists), key=str.casefold)

    @classmethod
    def combination_id(cls, artists: List[str]) -> str:
        return " || ".join(cls.normalize_artists(artists))

    @classmethod
    def load(cls, filepath: Path) -> "CombinationELOSystem":
        if not filepath.exists():
            return cls()
        try:
            with open(filepath, "r", encoding="utf-8") as f:
                data = json.load(f)
            return cls(entries=dict(data.get("entries", {})))
        except Exception as e:
            print(f"Warning: Could not load combination ratings: {e}")
            return cls()

    def save(self, filepath: Path):
        filepath.parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, "w", encoding="utf-8") as f:
            json.dump({"entries": self.entries}, f, indent=2, ensure_ascii=False)

    def _ensure_entry(self, artists: List[str]) -> Tuple[str, dict]:
        normalized = self.normalize_artists(artists)
        combo_id = self.combination_id(normalized)
        entry = self.entries.setdefault(combo_id, {
            "artists": normalized,
            "rating": DEFAULT_ELO,
            "comparisons": 0,
            "wins": 0,
            "losses": 0,
        })
        entry.setdefault("artists", normalized)
        entry.setdefault("rating", DEFAULT_ELO)
        entry.setdefault("comparisons", 0)
        entry.setdefault("wins", 0)
        entry.setdefault("losses", 0)
        entry.setdefault("ties", 0)
        entry.setdefault("both_bad", 0)
        return combo_id, entry

    def update_ratings(self, winners: List[str], losers: List[str]) -> Dict[str, float]:
        winner_id, winner_entry = self._ensure_entry(winners)
        loser_id, loser_entry = self._ensure_entry(losers)
        if winner_id == loser_id:
            return {winner_id: 0.0}

        winner_rating = float(winner_entry["rating"])
        loser_rating = float(loser_entry["rating"])
        expected_winner = 1 / (1 + 10 ** ((loser_rating - winner_rating) / 400))
        winner_change = K_FACTOR * (1 - expected_winner)
        loser_change = -winner_change

        winner_entry["rating"] = winner_rating + winner_change
        loser_entry["rating"] = loser_rating + loser_change
        winner_entry["comparisons"] += 1
        loser_entry["comparisons"] += 1
        winner_entry["wins"] += 1
        loser_entry["losses"] += 1
        return {winner_id: winner_change, loser_id: loser_change}

    def update_tie_ratings(self, artists_a: List[str], artists_b: List[str]) -> Dict[str, float]:
        combo_a, entry_a = self._ensure_entry(artists_a)
        combo_b, entry_b = self._ensure_entry(artists_b)
        if combo_a == combo_b:
            return {combo_a: 0.0}
        rating_a = float(entry_a["rating"])
        rating_b = float(entry_b["rating"])
        expected_a = 1 / (1 + 10 ** ((rating_b - rating_a) / 400))
        change_a = K_FACTOR * (0.5 - expected_a)
        entry_a["rating"] = rating_a + change_a
        entry_b["rating"] = rating_b - change_a
        for entry in (entry_a, entry_b):
            entry["comparisons"] = int(entry.get("comparisons", 0)) + 1
            entry["ties"] = int(entry.get("ties", 0)) + 1
        return {combo_a: change_a, combo_b: -change_a}

    def snapshot(self, combinations: List[List[str]]) -> dict:
        snapshot = {}
        for artists in combinations:
            combo_id = self.combination_id(artists)
            snapshot[combo_id] = deepcopy(self.entries.get(combo_id))
        return snapshot

    def restore(self, snapshot: dict):
        for combo_id, entry in snapshot.items():
            if entry is None:
                self.entries.pop(combo_id, None)
            else:
                self.entries[combo_id] = deepcopy(entry)

    def rebuild_from_history(self, records: List[dict]):
        """Replay exact-combination ratings, including ties and excluding invalid duels."""
        self.entries = {}
        for record in records:
            artists_a = list(record.get("artists_a", []))
            artists_b = list(record.get("artists_b", []))
            winner = str(record.get("winner", "") or "").upper()
            if not artists_a or not artists_b or winner not in ("A", "B", "TIE"):
                continue
            if winner == "TIE":
                self.update_tie_ratings(artists_a, artists_b)
            else:
                winners = artists_a if winner == "A" else artists_b
                losers = artists_b if winner == "A" else artists_a
                self.update_ratings(winners, losers)

    def get_rating(self, artists: List[str]) -> float:
        combo_id = self.combination_id(artists)
        return float(self.entries.get(combo_id, {}).get("rating", DEFAULT_ELO))

    def get_comparison_count(self, artists: List[str]) -> int:
        combo_id = self.combination_id(artists)
        return int(self.entries.get(combo_id, {}).get("comparisons", 0))

    def get_top(self, n: int = 30) -> List[dict]:
        return sorted(
            self.entries.values(),
            key=lambda entry: float(entry.get("rating", DEFAULT_ELO)),
            reverse=True,
        )[:n]


# --------------------------------------------------------------------------------
# Bayesian Top-K ranking core
# --------------------------------------------------------------------------------

PRIOR_MU = 1500.0
PRIOR_SIGMA = 350.0
MIN_SIGMA = 55.0
MAX_SIGMA = PRIOR_SIGMA
SYNERGY_PRIOR_SIGMA = 180.0
MIN_SYNERGY_SIGMA = 45.0
LOGISTIC_SCALE = 180.0
TOP_K = 50
TEAM_SIZE_FRACTIONS: Dict[int, float] = {1: 0.68, 2: 0.26, 3: 0.06}
# Fresh discovery is forced solo, but contributes only half a duel to the
# global team-size quota. This prevents early Opening/Recovery/Screening work
# from being pushed overwhelmingly into duo/trio while retaining meaningful
# multi-artist evidence.
FRESH_DISCOVERY_QUOTA_WEIGHT = max(
    0.0, min(1.0, float(FRESH_DISCOVERY_QUOTA_WEIGHT))
)
EVIDENCE_WEIGHTS: Dict[int, float] = {1: 1.0, 2: 0.60, 3: 0.35}
# A generated or queued duel is provisional evidence for matchmaking. Until it
# is voted, scheduling the same artist again cannot use an updated posterior and
# creates low-information duplicate bursts. One pending appearance per artist is
# therefore the hard cap; recent generated appearances also receive a short
# cooldown before they may be scheduled again.
MAX_BUFFERED_APPEARANCES_PER_ARTIST = 1
ARTIST_GENERATION_COOLDOWN_MATCHES = 12
MODEL_VERSION = 9


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def logistic(value: float) -> float:
    if value >= 0:
        z = math.exp(-value)
        return 1.0 / (1.0 + z)
    z = math.exp(value)
    return z / (1.0 + z)


def atomic_write_json(path: Path, data: Any) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    with temp.open("w", encoding="utf-8") as handle:
        json.dump(data, handle, ensure_ascii=False, indent=2)
    temp.replace(path)


def normalized_combo_id(artists: Sequence[str]) -> str:
    return " || ".join(sorted(str(a) for a in artists))


def deterministic_synergy(artists: Sequence[str], seed: int, amplitude: float) -> float:
    """Deterministic hidden synergy used by the simulator, not by live ranking."""
    key = f"{seed}|{'|'.join(sorted(str(a) for a in artists))}"
    rng = random.Random(key)
    return rng.gauss(0.0, amplitude)


@dataclass
class BayesianTopKRatingSystem:
    """Bayesian Bradley–Terry ranking with separate exact-team synergy and reliability.

    Online diagonal updates make votes immediately visible. Periodic deterministic
    global MAP refits remove chronology dependence and recalibrate uncertainty.
    """

    artists: Dict[str, dict] = field(default_factory=dict)
    synergies: Dict[str, dict] = field(default_factory=dict)
    evidence: List[dict] = field(default_factory=list)
    comparison_count: int = 0
    version: int = MODEL_VERSION
    refit_interval: int = 500
    _last_refit_evidence: int = 0
    _last_refit_error: str = ""
    _revision: int = 0
    _rank_cache: Dict[Tuple[float, str], Tuple[int, List[str]]] = field(default_factory=dict, repr=False)
    _fast_rank_cache: Dict[str, Any] = field(default_factory=dict, repr=False)
    _lock: threading.RLock = field(default_factory=threading.RLock, repr=False, compare=False)

    @classmethod
    def load(cls, filepath: Path, refit_interval: int = 500) -> "BayesianTopKRatingSystem":
        path = Path(filepath)
        if not path.exists():
            return cls(refit_interval=refit_interval)
        try:
            with path.open("r", encoding="utf-8") as handle:
                raw = json.load(handle)
            if int(raw.get("version", 0) or 0) < MODEL_VERSION:
                # Legacy competitive state must be backed up/reset, not silently imported.
                model = cls(refit_interval=refit_interval)
                model._last_refit_error = "legacy_competitive_data"
                return model
            return cls(
                artists=dict(raw.get("artists", {})),
                synergies=dict(raw.get("synergies", {})),
                evidence=list(raw.get("evidence", [])),
                comparison_count=int(raw.get("comparison_count", 0) or 0),
                version=int(raw.get("version", MODEL_VERSION) or MODEL_VERSION),
                refit_interval=int(raw.get("refit_interval", refit_interval) or refit_interval),
                _last_refit_evidence=int(raw.get("last_refit_evidence", 0) or 0),
                _last_refit_error=str(raw.get("last_refit_error", "") or ""),
            )
        except Exception as exc:
            model = cls(refit_interval=refit_interval)
            model._last_refit_error = f"load_failed: {exc}"
            return model

    def snapshot(self) -> dict:
        with self._lock:
            return {
                "version": MODEL_VERSION,
                "comparison_count": int(self.comparison_count),
                "refit_interval": int(self.refit_interval),
                "last_refit_evidence": int(self._last_refit_evidence),
                "last_refit_error": self._last_refit_error,
                "artists": deepcopy(self.artists),
                "synergies": deepcopy(self.synergies),
                "evidence": deepcopy(self.evidence),
            }

    def save(self, filepath: Path) -> None:
        atomic_write_json(Path(filepath), self.snapshot())

    @property
    def ranking_revision(self) -> int:
        return self._revision

    def invalidate_ranking_cache(self) -> None:
        self._revision += 1
        self._rank_cache.clear()
        self._fast_rank_cache.clear()

    @staticmethod
    def combo_id(artists: Iterable[str]) -> str:
        return normalized_combo_id(list(artists))

    @staticmethod
    def _default_artist_entry() -> dict:
        return {
            "mu": PRIOR_MU,
            "sigma": PRIOR_SIGMA,
            "comparisons": 0,
            "wins": 0,
            "losses": 0,
            "ties": 0,
            "both_bad": 0,
            "solo_comparisons": 0,
            "duo_comparisons": 0,
            "trio_comparisons": 0,
            "last_comparison_index": 0,
            "first_outcome": "",
            "bad_alpha": 1.0,
            "bad_beta": 9.0,
            "posterior_top50_probability": None,
            "posterior_probability_duel": -1,
        }

    def _ensure_artist(self, artist: str) -> dict:
        artist = str(artist)
        entry = self.artists.setdefault(artist, self._default_artist_entry())
        defaults = self._default_artist_entry()
        for key, value in defaults.items():
            entry.setdefault(key, deepcopy(value))
        return entry

    def _ensure_synergy(self, artists: Sequence[str]) -> Tuple[str, Optional[dict]]:
        if len(artists) <= 1:
            return "", None
        key = self.combo_id(artists)
        entry = self.synergies.setdefault(key, {
            "mu": 0.0,
            "sigma": SYNERGY_PRIOR_SIGMA,
            "comparisons": 0,
            "size": len(artists),
        })
        return key, entry

    def get_entry(self, artist: str) -> dict:
        return deepcopy(self.artists.get(str(artist), self._default_artist_entry()))

    def get_mu(self, artist: str) -> float:
        return float(self.artists.get(str(artist), {}).get("mu", PRIOR_MU))

    def get_sigma(self, artist: str) -> float:
        return float(self.artists.get(str(artist), {}).get("sigma", PRIOR_SIGMA))

    def get_comparison_count(self, artist: str) -> int:
        return int(self.artists.get(str(artist), {}).get("comparisons", 0) or 0)

    def effective_evidence(self, artist: str) -> float:
        entry = self.artists.get(str(artist), {})
        return (
            float(entry.get("solo_comparisons", 0) or 0) * EVIDENCE_WEIGHTS[1]
            + float(entry.get("duo_comparisons", 0) or 0) * EVIDENCE_WEIGHTS[2]
            + float(entry.get("trio_comparisons", 0) or 0) * EVIDENCE_WEIGHTS[3]
        )

    def conservative_score(self, artist: str) -> float:
        # Confidence-adjusted official score. This is an 80% one-sided lower
        # credible bound; raw mean and uncertainty remain visible separately.
        return self.get_mu(artist) - 1.28 * self.get_sigma(artist)

    def potential_score(self, artist: str) -> float:
        return self.get_mu(artist) + 1.28 * self.get_sigma(artist)

    def stage(self, artist: str) -> str:
        evidence = self.effective_evidence(artist)
        if evidence <= 0:
            return "Unseen"
        if evidence < 2:
            return "Opening"
        if evidence < 4:
            return "Screening"
        if evidence < 8:
            return "Qualification"
        return "Established"

    def bad_probability(self, artist: str) -> float:
        entry = self.artists.get(str(artist), {})
        alpha = float(entry.get("bad_alpha", 1.0) or 1.0)
        beta = float(entry.get("bad_beta", 9.0) or 9.0)
        return alpha / max(1e-9, alpha + beta)

    def team_strength(self, artists: Sequence[str]) -> float:
        members = [str(a) for a in artists]
        if not members:
            return PRIOR_MU
        base = sum(self.get_mu(a) for a in members) / len(members)
        if len(members) > 1:
            base += float(self.synergies.get(self.combo_id(members), {}).get("mu", 0.0))
        return base

    def team_conservative_score(self, artists: Sequence[str]) -> float:
        members = [str(a) for a in artists]
        if not members:
            return PRIOR_MU - 1.64 * PRIOR_SIGMA
        mean = sum(self.get_mu(a) for a in members) / len(members)
        variance = sum(self.get_sigma(a) ** 2 for a in members) / (len(members) ** 2)
        if len(members) > 1:
            synergy = self.synergies.get(self.combo_id(members), {})
            mean += float(synergy.get("mu", 0.0))
            variance += float(synergy.get("sigma", SYNERGY_PRIOR_SIGMA)) ** 2
        return mean - 1.64 * math.sqrt(max(1.0, variance))

    def ranked_artists(self, minimum_comparisons: float = 0, score_type: str = "mean") -> List[str]:
        key = (float(minimum_comparisons), str(score_type))
        cached = self._rank_cache.get(key)
        if cached and cached[0] == self._revision:
            return list(cached[1])
        candidates = [
            a for a in self.artists
            if self.effective_evidence(a) > 0.0
            and self.effective_evidence(a) >= float(minimum_comparisons)
        ]
        if score_type == "conservative":
            candidates.sort(key=lambda a: (self.conservative_score(a), self.get_mu(a), a), reverse=True)
        elif score_type == "potential":
            candidates.sort(key=lambda a: (self.potential_score(a), self.get_mu(a), a), reverse=True)
        else:
            candidates.sort(key=lambda a: (self.get_mu(a), -self.get_sigma(a), a), reverse=True)
        self._rank_cache[key] = (self._revision, list(candidates))
        return candidates

    # PERMANENT_DUEL_SPEED_AND_DIAGNOSTICS_V1
    def fast_rank_summary(self) -> dict:
        """Return exact Top-50/Top-100 heads without sorting the full 17k ladder.

        The tuple keys exactly match ranked_artists(), so membership and tie-breaking
        are unchanged. A bounded heap makes the per-vote work O(N log 100) rather
        than performing two O(N log N) global sorts.
        """
        cached = self._fast_rank_cache.get("summary")
        if cached and int(cached.get("revision", -1)) == self._revision:
            return cached

        mean_heap: List[Tuple[float, float, str]] = []
        conservative_heap: List[Tuple[float, float, str]] = []
        for artist, entry in self.artists.items():
            evidence = (
                float(entry.get("solo_comparisons", 0) or 0) * EVIDENCE_WEIGHTS[1]
                + float(entry.get("duo_comparisons", 0) or 0) * EVIDENCE_WEIGHTS[2]
                + float(entry.get("trio_comparisons", 0) or 0) * EVIDENCE_WEIGHTS[3]
            )
            if evidence <= 0.0:
                continue
            mu = float(entry.get("mu", PRIOR_MU))
            sigma = float(entry.get("sigma", PRIOR_SIGMA))
            mean_key = (mu, -sigma, str(artist))
            if len(mean_heap) < 100:
                heapq.heappush(mean_heap, mean_key)
            elif mean_key > mean_heap[0]:
                heapq.heapreplace(mean_heap, mean_key)

            if evidence >= 1.0:
                conservative_key = (mu - 1.28 * sigma, mu, str(artist))
                if len(conservative_heap) < TOP_TARGET_RANK:
                    heapq.heappush(conservative_heap, conservative_key)
                elif conservative_key > conservative_heap[0]:
                    heapq.heapreplace(conservative_heap, conservative_key)

        mean_top100 = [item[2] for item in sorted(mean_heap, reverse=True)]
        conservative_top50 = [item[2] for item in sorted(conservative_heap, reverse=True)]
        summary = {
            "revision": self._revision,
            "mean_top100": mean_top100,
            "conservative_top50_min1": conservative_top50,
        }
        self._fast_rank_cache["summary"] = summary
        return summary

    def cutoff_score(self, target_rank: int = TOP_K) -> float:
        rank = int(target_rank)
        if 1 <= rank <= 100:
            ranked = self.fast_rank_summary()["mean_top100"]
        else:
            ranked = self.ranked_artists(0.0, "mean")
        if len(ranked) < rank:
            return PRIOR_MU
        return self.get_mu(ranked[rank - 1])

    def cutoff_sigma(self, target_rank: int = TOP_K) -> float:
        rank = int(target_rank)
        if 1 <= rank <= 100:
            ranked = self.fast_rank_summary()["mean_top100"]
        else:
            ranked = self.ranked_artists(0.0, "mean")
        if len(ranked) < rank:
            return PRIOR_SIGMA
        return self.get_sigma(ranked[rank - 1])

    def probability_above(self, artist: str, cutoff: float, cutoff_sigma: float = 0.0) -> float:
        mean = self.get_mu(artist) - float(cutoff)
        sd = math.sqrt(max(1.0, self.get_sigma(artist) ** 2 + float(cutoff_sigma) ** 2))
        z = mean / sd
        return clamp(0.5 * (1.0 + math.erf(z / math.sqrt(2.0))), 0.0, 1.0)

    def top_k_probability(self, artist: str, target_rank: int = TOP_K) -> float:
        fallback = self.probability_above(artist, self.cutoff_score(target_rank), self.cutoff_sigma(target_rank))
        if int(target_rank) != TOP_K:
            return fallback
        entry = self.artists.get(str(artist), {})
        cached = entry.get("posterior_top50_probability")
        cached_duel = int(entry.get("posterior_probability_duel", -1) or -1)
        if cached is None or cached_duel < 0:
            return fallback
        age = max(0, self.comparison_count - cached_duel)
        coherent_weight = clamp(1.0 - age / max(1.0, float(self.refit_interval)), 0.0, 1.0)
        return clamp(coherent_weight * float(cached) + (1.0 - coherent_weight) * fallback, 0.0, 1.0)

    def elite_artists(self, limit: int = 20) -> List[str]:
        established = [a for a in self.ranked_artists(8.0, "mean")]
        return established[: max(0, int(limit))]

    def is_promising_under_tested(self, artist: str, cutoff: Optional[float] = None) -> bool:
        evidence = self.effective_evidence(artist)
        if evidence <= 0 or evidence >= 8:
            return False
        cutoff = self.cutoff_score() if cutoff is None else float(cutoff)
        return self.potential_score(artist) >= cutoff - 80.0

    def is_confidently_below_cutoff(self, artist: str, cutoff: Optional[float] = None) -> bool:
        if self.effective_evidence(artist) < 8:
            return False
        cutoff = self.cutoff_score() if cutoff is None else float(cutoff)
        return self.potential_score(artist) < cutoff - 120.0 and self.top_k_probability(artist) < 0.08

    def retest_priority(self, artist: str, cutoff: Optional[float] = None) -> float:
        cutoff = self.cutoff_score() if cutoff is None else float(cutoff)
        evidence = self.effective_evidence(artist)
        stale = max(0, self.comparison_count - int(self.artists.get(str(artist), {}).get("last_comparison_index", 0) or 0))
        return (
            (self.potential_score(artist) - cutoff) / 180.0
            + self.get_sigma(artist) / PRIOR_SIGMA
            + min(1.0, stale / 800.0)
            - min(1.5, evidence / 16.0)
        )

    def snapshot_entities(self, artists: Iterable[str], combinations: Iterable[Sequence[str]]) -> dict:
        artist_names = list(dict.fromkeys(str(a) for a in artists))
        combo_keys = [self.combo_id(c) for c in combinations if len(c) > 1]
        return {
            "comparison_count": self.comparison_count,
            "evidence_length": len(self.evidence),
            "last_refit_evidence": self._last_refit_evidence,
            "artists": {a: deepcopy(self.artists.get(a)) for a in artist_names},
            "synergies": {k: deepcopy(self.synergies.get(k)) for k in combo_keys},
        }

    def restore_entities(self, snapshot: dict) -> None:
        with self._lock:
            for artist, entry in snapshot.get("artists", {}).items():
                if entry is None:
                    self.artists.pop(artist, None)
                else:
                    self.artists[artist] = deepcopy(entry)
            for key, entry in snapshot.get("synergies", {}).items():
                if entry is None:
                    self.synergies.pop(key, None)
                else:
                    self.synergies[key] = deepcopy(entry)
            evidence_length = int(snapshot.get("evidence_length", len(self.evidence)) or 0)
            if evidence_length < len(self.evidence):
                del self.evidence[evidence_length:]
            self.comparison_count = int(snapshot.get("comparison_count", self.comparison_count) or 0)
            self._last_refit_evidence = min(int(snapshot.get("last_refit_evidence", self._last_refit_evidence) or 0), len(self.evidence))
            self.invalidate_ranking_cache()

    def _online_relative_update(self, artists_a: Sequence[str], artists_b: Sequence[str], y: float, size: int) -> Tuple[float, Dict[str, float]]:
        members_a = [str(a) for a in artists_a]
        members_b = [str(a) for a in artists_b]
        strength_a = self.team_strength(members_a)
        strength_b = self.team_strength(members_b)
        expected_a = logistic((strength_a - strength_b) / LOGISTIC_SCALE)
        error = float(y) - expected_a
        changes: Dict[str, float] = {}
        # Diagonal assumed-density update. Team averaging naturally reduces each
        # member's individual information in duo/trio outcomes.
        for sign, members in ((1.0, members_a), (-1.0, members_b)):
            n = max(1, len(members))
            derivative = sign / (LOGISTIC_SCALE * n)
            for artist in members:
                entry = self._ensure_artist(artist)
                variance = float(entry["sigma"]) ** 2
                fisher = expected_a * (1.0 - expected_a) * derivative * derivative
                posterior_variance = 1.0 / (1.0 / max(1.0, variance) + fisher)
                delta = posterior_variance * derivative * error
                # A mild damping guard prevents one result from producing implausible jumps.
                delta = clamp(delta, -120.0, 120.0)
                entry["mu"] = float(entry["mu"]) + delta
                entry["sigma"] = clamp(math.sqrt(posterior_variance), MIN_SIGMA, MAX_SIGMA)
                changes[artist] = changes.get(artist, 0.0) + delta
        for sign, members in ((1.0, members_a), (-1.0, members_b)):
            if len(members) <= 1:
                continue
            _, synergy = self._ensure_synergy(members)
            assert synergy is not None
            derivative = sign / LOGISTIC_SCALE
            variance = float(synergy["sigma"]) ** 2
            fisher = expected_a * (1.0 - expected_a) * derivative * derivative
            posterior_variance = 1.0 / (1.0 / max(1.0, variance) + fisher)
            delta = clamp(posterior_variance * derivative * error, -100.0, 100.0)
            synergy["mu"] = float(synergy["mu"]) + delta
            synergy["sigma"] = clamp(math.sqrt(posterior_variance), MIN_SYNERGY_SIGMA, SYNERGY_PRIOR_SIGMA)
        return expected_a, changes

    def update_result(self, artists_a: List[str], artists_b: List[str], outcome: str) -> dict:
        members_a = [str(a) for a in artists_a]
        members_b = [str(a) for a in artists_b]
        if not members_a or not members_b or len(members_a) != len(members_b):
            raise ValueError("Both sides must contain the same nonzero number of artists")
        size = len(members_a)
        if size not in (1, 2, 3):
            raise ValueError("Only solo, duo, and trio comparisons are supported")
        outcome = str(outcome or "").upper()
        if outcome not in ("A", "B", "TIE", "BOTH_BAD"):
            raise ValueError(f"Unsupported outcome: {outcome}")
        with self._lock:
            self.comparison_count += 1
            before = {a: self.get_mu(a) for a in dict.fromkeys(members_a + members_b)}
            for artist in dict.fromkeys(members_a + members_b):
                entry = self._ensure_artist(artist)
                entry["comparisons"] = int(entry.get("comparisons", 0) or 0) + 1
                entry[{1: "solo_comparisons", 2: "duo_comparisons", 3: "trio_comparisons"}[size]] += 1
                entry["last_comparison_index"] = int(self.comparison_count)
                if not entry.get("first_outcome"):
                    if outcome == "A":
                        entry["first_outcome"] = "WIN" if artist in members_a else "LOSS"
                    elif outcome == "B":
                        entry["first_outcome"] = "LOSS" if artist in members_a else "WIN"
                    else:
                        entry["first_outcome"] = outcome
            expected_a = logistic((self.team_strength(members_a) - self.team_strength(members_b)) / LOGISTIC_SCALE)
            if outcome == "BOTH_BAD":
                for artist in dict.fromkeys(members_a + members_b):
                    entry = self._ensure_artist(artist)
                    entry["both_bad"] += 1
                    entry["bad_alpha"] = float(entry.get("bad_alpha", 1.0)) + 1.0
                # Reliability observation only: no relative skill evidence.
            else:
                y = 1.0 if outcome == "A" else 0.0 if outcome == "B" else 0.5
                expected_a, _ = self._online_relative_update(members_a, members_b, y, size)
                self.evidence.append({"a": members_a, "b": members_b, "y": y, "size": size})
                for artist in dict.fromkeys(members_a + members_b):
                    self._ensure_artist(artist)["bad_beta"] = float(self._ensure_artist(artist).get("bad_beta", 9.0)) + 1.0
                if outcome == "A":
                    for artist in members_a: self._ensure_artist(artist)["wins"] += 1
                    for artist in members_b: self._ensure_artist(artist)["losses"] += 1
                elif outcome == "B":
                    for artist in members_b: self._ensure_artist(artist)["wins"] += 1
                    for artist in members_a: self._ensure_artist(artist)["losses"] += 1
                else:
                    for artist in dict.fromkeys(members_a + members_b): self._ensure_artist(artist)["ties"] += 1
                for members in (members_a, members_b):
                    if len(members) > 1:
                        _, synergy = self._ensure_synergy(members)
                        assert synergy is not None
                        synergy["comparisons"] = int(synergy.get("comparisons", 0) or 0) + 1
            self.invalidate_ranking_cache()
            changes = {a: self.get_mu(a) - before[a] for a in before}
            return {
                "artist_changes": changes,
                "expected_a": expected_a,
                "outcome": outcome,
                "relative_evidence_added": outcome != "BOTH_BAD",
            }

    @staticmethod
    def record_has_effective_evidence(record: dict) -> bool:
        return str(record.get("winner", "") or "").upper() in ("A", "B", "TIE") or bool(record.get("both_bad", False))

    def rebuild_from_history(self, records: List[dict]) -> int:
        with self._lock:
            self.artists.clear()
            self.synergies.clear()
            self.evidence.clear()
            self.comparison_count = 0
            self._last_refit_evidence = 0
            count = 0
            for record in records:
                a = list(record.get("artists_a", []))
                b = list(record.get("artists_b", []))
                winner = "BOTH_BAD" if bool(record.get("both_bad", False)) else str(record.get("winner", "") or "").upper()
                if a and b and winner in ("A", "B", "TIE", "BOTH_BAD"):
                    self.update_result(a, b, winner)
                    count += 1
            if self.evidence:
                self.refit_global(max_iterations=35)
            return count

    def is_refit_due(self) -> bool:
        return len(self.evidence) - self._last_refit_evidence >= max(50, int(self.refit_interval))

    def _refresh_posterior_top50_probabilities_locked(self, samples: int = 256) -> None:
        names = list(self.artists)
        if not names:
            return
        if len(names) <= TOP_K:
            for artist in names:
                self.artists[artist]["posterior_top50_probability"] = 1.0
                self.artists[artist]["posterior_probability_duel"] = self.comparison_count
            return
        mus = np.asarray([self.get_mu(a) for a in names], dtype=np.float64)
        sigmas = np.asarray([self.get_sigma(a) for a in names], dtype=np.float64)
        seed = (self.comparison_count * 1000003 + len(names) * 9176 + MODEL_VERSION) & 0xFFFFFFFF
        rng = np.random.default_rng(seed)
        draws = rng.normal(mus, sigmas, size=(max(64, int(samples)), len(names)))
        indices = np.argpartition(draws, -TOP_K, axis=1)[:, -TOP_K:]
        counts = np.bincount(indices.reshape(-1), minlength=len(names)).astype(np.float64)
        probabilities = counts / draws.shape[0]
        for artist, probability in zip(names, probabilities):
            entry = self.artists[artist]
            entry["posterior_top50_probability"] = float(probability)
            entry["posterior_probability_duel"] = self.comparison_count

    def refit_global(self, max_iterations: int = 35) -> dict:
        """Deterministic vectorized diagonal-Newton MAP refit over all relative evidence."""
        with self._lock:
            if not self.evidence:
                self._last_refit_evidence = 0
                return {"success": True, "iterations": 0, "evidence": 0}
            names = sorted({a for row in self.evidence for side in (row["a"], row["b"]) for a in side})
            index = {a: i for i, a in enumerate(names)}
            combo_names = sorted({self.combo_id(side) for row in self.evidence for side in (row["a"], row["b"]) if len(side) > 1})
            combo_index = {c: i for i, c in enumerate(combo_names)}
            mu = np.full(len(names), PRIOR_MU, dtype=np.float64)
            combo_mu = np.zeros(len(combo_names), dtype=np.float64)
            rows_a: List[np.ndarray] = []
            rows_b: List[np.ndarray] = []
            combos_a: List[int] = []
            combos_b: List[int] = []
            y = np.empty(len(self.evidence), dtype=np.float64)
            for r, row in enumerate(self.evidence):
                rows_a.append(np.asarray([index[a] for a in row["a"]], dtype=np.int32))
                rows_b.append(np.asarray([index[a] for a in row["b"]], dtype=np.int32))
                combos_a.append(combo_index.get(self.combo_id(row["a"]), -1) if len(row["a"]) > 1 else -1)
                combos_b.append(combo_index.get(self.combo_id(row["b"]), -1) if len(row["b"]) > 1 else -1)
                y[r] = float(row["y"])
            prior_precision = 1.0 / (PRIOR_SIGMA ** 2)
            combo_prior_precision = 1.0 / (SYNERGY_PRIOR_SIGMA ** 2)
            last_max_delta = 0.0
            for iteration in range(max(1, int(max_iterations))):
                grad = -(mu - PRIOR_MU) * prior_precision
                info = np.full(len(names), prior_precision, dtype=np.float64)
                cgrad = -combo_mu * combo_prior_precision
                cinfo = np.full(len(combo_names), combo_prior_precision, dtype=np.float64)
                for r, (ia, ib) in enumerate(zip(rows_a, rows_b)):
                    sa = float(mu[ia].mean()) + (combo_mu[combos_a[r]] if combos_a[r] >= 0 else 0.0)
                    sb = float(mu[ib].mean()) + (combo_mu[combos_b[r]] if combos_b[r] >= 0 else 0.0)
                    p = logistic((sa - sb) / LOGISTIC_SCALE)
                    err = y[r] - p
                    fisher = p * (1.0 - p)
                    da = 1.0 / (LOGISTIC_SCALE * len(ia))
                    db = -1.0 / (LOGISTIC_SCALE * len(ib))
                    np.add.at(grad, ia, err * da)
                    np.add.at(grad, ib, err * db)
                    np.add.at(info, ia, fisher * da * da)
                    np.add.at(info, ib, fisher * db * db)
                    if combos_a[r] >= 0:
                        cgrad[combos_a[r]] += err / LOGISTIC_SCALE
                        cinfo[combos_a[r]] += fisher / (LOGISTIC_SCALE ** 2)
                    if combos_b[r] >= 0:
                        cgrad[combos_b[r]] -= err / LOGISTIC_SCALE
                        cinfo[combos_b[r]] += fisher / (LOGISTIC_SCALE ** 2)
                delta = np.clip(grad / np.maximum(info, 1e-12), -90.0, 90.0) * 0.45
                cdelta = np.clip(cgrad / np.maximum(cinfo, 1e-12), -70.0, 70.0) * 0.45 if len(combo_mu) else np.empty(0)
                mu += delta
                if len(combo_mu): combo_mu += cdelta
                # Translation is unidentifiable; center against the prior.
                mu += PRIOR_MU - float(mu.mean())
                last_max_delta = max(float(np.max(np.abs(delta))), float(np.max(np.abs(cdelta))) if len(cdelta) else 0.0)
                if last_max_delta < 0.02:
                    break
            # Final diagonal information for posterior sigmas.
            info = np.full(len(names), prior_precision, dtype=np.float64)
            cinfo = np.full(len(combo_names), combo_prior_precision, dtype=np.float64)
            for r, (ia, ib) in enumerate(zip(rows_a, rows_b)):
                sa = float(mu[ia].mean()) + (combo_mu[combos_a[r]] if combos_a[r] >= 0 else 0.0)
                sb = float(mu[ib].mean()) + (combo_mu[combos_b[r]] if combos_b[r] >= 0 else 0.0)
                p = logistic((sa - sb) / LOGISTIC_SCALE)
                fisher = p * (1.0 - p)
                da = 1.0 / (LOGISTIC_SCALE * len(ia)); db = -1.0 / (LOGISTIC_SCALE * len(ib))
                np.add.at(info, ia, fisher * da * da); np.add.at(info, ib, fisher * db * db)
                if combos_a[r] >= 0: cinfo[combos_a[r]] += fisher / (LOGISTIC_SCALE ** 2)
                if combos_b[r] >= 0: cinfo[combos_b[r]] += fisher / (LOGISTIC_SCALE ** 2)
            sigmas = np.clip(np.sqrt(1.0 / np.maximum(info, 1e-12)), MIN_SIGMA, MAX_SIGMA)
            combo_sigmas = np.clip(np.sqrt(1.0 / np.maximum(cinfo, 1e-12)), MIN_SYNERGY_SIGMA, SYNERGY_PRIOR_SIGMA) if len(cinfo) else np.empty(0)
            for artist, value, sigma in zip(names, mu, sigmas):
                entry = self._ensure_artist(artist)
                entry["mu"] = float(value)
                entry["sigma"] = float(sigma)
            for key, value, sigma in zip(combo_names, combo_mu, combo_sigmas):
                entry = self.synergies.setdefault(key, {"comparisons": 0, "size": key.count(" || ") + 1})
                entry["mu"] = float(value)
                entry["sigma"] = float(sigma)
            self._last_refit_evidence = len(self.evidence)
            self._last_refit_error = ""
            self.invalidate_ranking_cache()
            self._refresh_posterior_top50_probabilities_locked()
            return {
                "success": True,
                "iterations": iteration + 1,
                "evidence": len(self.evidence),
                "artists": len(names),
                "synergies": len(combo_names),
                "max_delta": last_max_delta,
            }


@dataclass
class InformationMatchmakingState:
    recent_matchups: List[str] = field(default_factory=list)
    recent_combinations: List[str] = field(default_factory=list)
    recent_artists: List[str] = field(default_factory=list)
    reason_counts: Dict[str, int] = field(default_factory=dict)
    opponent_graph: Dict[str, List[str]] = field(default_factory=dict)
    last_seen: Dict[str, int] = field(default_factory=dict)
    team_size_counts: Dict[int, int] = field(default_factory=lambda: {1: 0, 2: 0, 3: 0})
    completed_duels: int = 0

    @staticmethod
    def matchup_key(artists_a: Sequence[str], artists_b: Sequence[str]) -> str:
        left = normalized_combo_id(artists_a)
        right = normalized_combo_id(artists_b)
        return " VS ".join(sorted((left, right)))

    @classmethod
    def load(cls, filepath: Path) -> "InformationMatchmakingState":
        path = Path(filepath)
        if not path.exists(): return cls()
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
            return cls(
                recent_matchups=list(raw.get("recent_matchups", []))[-1200:],
                recent_combinations=list(raw.get("recent_combinations", []))[-2400:],
                recent_artists=list(raw.get("recent_artists", []))[-4000:],
                reason_counts={str(k): int(v) for k, v in raw.get("reason_counts", {}).items()},
                opponent_graph={str(k): list(v) for k, v in raw.get("opponent_graph", {}).items()},
                last_seen={str(k): int(v) for k, v in raw.get("last_seen", {}).items()},
                team_size_counts={int(k): int(v) for k, v in raw.get("team_size_counts", {1:0,2:0,3:0}).items()},
                completed_duels=int(raw.get("completed_duels", 0) or 0),
            )
        except Exception:
            return cls()

    def save(self, filepath: Path) -> None:
        atomic_write_json(Path(filepath), {
            "version": MODEL_VERSION,
            "recent_matchups": self.recent_matchups[-1200:],
            "recent_combinations": self.recent_combinations[-2400:],
            "recent_artists": self.recent_artists[-4000:],
            "reason_counts": self.reason_counts,
            "opponent_graph": self.opponent_graph,
            "last_seen": self.last_seen,
            "team_size_counts": {str(k): int(v) for k, v in self.team_size_counts.items()},
            "completed_duels": self.completed_duels,
        })

    def bootstrap_from_history(self, records: List[dict]) -> None:
        for record in records[-1200:]:
            a = list(record.get("artists_a", [])); b = list(record.get("artists_b", []))
            if a and b:
                self.record_matchup(a, b, str(record.get("matchmaking_reason", "Historical")))

    def record_matchup(self, artists_a: Sequence[str], artists_b: Sequence[str], reason: str) -> None:
        self.completed_duels += 1
        key = self.matchup_key(artists_a, artists_b)
        self.recent_matchups.append(key); del self.recent_matchups[:-1200]
        for team in (artists_a, artists_b):
            if len(team) > 1:
                self.recent_combinations.append(normalized_combo_id(team))
        del self.recent_combinations[:-2400]
        participants = list(dict.fromkeys([str(x) for x in list(artists_a) + list(artists_b)]))
        self.recent_artists.extend(participants); del self.recent_artists[:-4000]
        self.reason_counts[str(reason)] = int(self.reason_counts.get(str(reason), 0)) + 1
        self.team_size_counts[len(artists_a)] = int(self.team_size_counts.get(len(artists_a), 0)) + 1
        for artist in participants:
            self.last_seen[artist] = self.completed_duels
        for a in artists_a:
            graph = set(self.opponent_graph.get(str(a), []))
            graph.update(str(b) for b in artists_b)
            self.opponent_graph[str(a)] = sorted(graph)
        for b in artists_b:
            graph = set(self.opponent_graph.get(str(b), []))
            graph.update(str(a) for a in artists_a)
            self.opponent_graph[str(b)] = sorted(graph)

    def repetition_penalty(self, artists_a: Sequence[str], artists_b: Sequence[str]) -> float:
        key = self.matchup_key(artists_a, artists_b)
        exact = self.recent_matchups.count(key)
        combos = sum(self.recent_combinations.count(normalized_combo_id(team)) for team in (artists_a, artists_b) if len(team) > 1)
        recent = Counter(self.recent_artists[-800:])
        exposure = sum(recent[str(a)] for a in set(list(artists_a) + list(artists_b)))
        return exact * 1000.0 + combos * 18.0 + exposure * 0.35

    def unique_opponents(self, artist: str) -> int:
        return len(self.opponent_graph.get(str(artist), []))


class InformationDrivenScheduler:
    CATEGORY_LABELS = {
        "fresh": "Fresh discovery",
        "opening": "Opening follow-up",
        "recovery": "Early-loss recovery",
        "screening": "Screening completion",
        "qualification": "Qualification completion",
        "boundary": "Top-100 / Top-50 boundary",
        "upside": "High-upside retest",
        "stale": "Stale recall",
        "bridge": "Bridge calibration",
        "elite": "Elite verification",
        "exploration": "Broad exploration",
    }

    def __init__(
        self,
        artists: Sequence[str],
        ratings: BayesianTopKRatingSystem,
        state: Optional[InformationMatchmakingState] = None,
        rng: Optional[random.Random] = None,
        working_pool_size: int = 150,
        generation_mode: str = MATCHMAKING_MODE_COVERAGE,
    ):
        self.artists = [str(a) for a in artists]
        self.artist_set = set(self.artists)
        self.ratings = ratings
        for _artist in self.artists:
            self.ratings._ensure_artist(_artist)
        self.state = state or InformationMatchmakingState()
        self.rng = rng or random.Random()
        self.generation_mode = self.normalize_generation_mode(generation_mode)
        self.working_pool_size = int(working_pool_size)
        self.working_pool: List[str] = []
        self._candidate_cache_duel = -10**9
        self._candidate_cache_revision = -1
        self._coverage_cache_revision = -1
        self._coverage_cache_artist_count = -1
        self._coverage_cache_value = 0.0
        self._candidate_lists: Dict[str, List[str]] = {}
        self._mu_sorted: List[str] = []
        self._mu_values: List[float] = []
        self._queued_artists: Counter = Counter()
        self._queued_matchups: Counter = Counter()
        self._queued_combinations: Counter = Counter()
        self._queued_sizes: Counter = Counter()
        self._queued_fresh_count: int = 0
        self._queued_degree: Counter = Counter()
        self.refresh_global_cache(force=True)

    def snapshot_runtime_state(self) -> dict:
        return {
            "working_pool": list(self.working_pool),
            "candidate_cache_duel": self._candidate_cache_duel,
            "state": deepcopy(self.state),
        }

    def restore_runtime_state(self, snapshot: Optional[dict], refresh: bool = True) -> None:
        if not snapshot: return
        self.working_pool = [a for a in snapshot.get("working_pool", []) if a in self.artist_set][:self.working_pool_size]
        state = snapshot.get("state")
        if isinstance(state, InformationMatchmakingState):
            self.state = deepcopy(state)
        if refresh:
            self.refresh_global_cache(force=True)
        else:
            # Undo must return the previous duel immediately. The next background
            # refill rebuilds candidates before generating another matchup.
            self._candidate_cache_duel = -10**9
            self._candidate_cache_revision = -1

    @staticmethod
    def normalize_generation_mode(value: Any) -> str:
        mode = str(value or "").strip().lower()
        return (
            MATCHMAKING_MODE_SELECTION
            if mode == MATCHMAKING_MODE_SELECTION
            else MATCHMAKING_MODE_COVERAGE
        )

    def set_generation_mode(self, value: Any) -> str:
        mode = self.normalize_generation_mode(value)
        if mode != self.generation_mode:
            self.generation_mode = mode
            self._candidate_cache_duel = -10**9
            self._candidate_cache_revision = -1
            self.refresh_global_cache(force=True)
        return self.generation_mode

    def coverage_ratio(self) -> float:
        revision = int(self.ratings.ranking_revision)
        artist_count = len(self.artists)
        if (
            self._coverage_cache_revision == revision
            and self._coverage_cache_artist_count == artist_count
        ):
            return self._coverage_cache_value
        value = sum(
            self.ratings.get_comparison_count(artist) > 0
            for artist in self.artists
        ) / max(1, artist_count)
        self._coverage_cache_revision = revision
        self._coverage_cache_artist_count = artist_count
        self._coverage_cache_value = value
        return value

    def coverage_active(self) -> bool:
        return (
            self.generation_mode == MATCHMAKING_MODE_COVERAGE
            and self.coverage_ratio() < AUTO_SELECTION_TAPER_START
        )

    @staticmethod
    def _normalize_weights(values: Dict[str, float]) -> Dict[str, float]:
        total = sum(max(0.0, float(value)) for value in values.values())
        if total <= 0.0:
            return {key: 0.0 for key in values}
        return {key: max(0.0, float(value)) / total for key, value in values.items()}

    def _production_category_weights(self, coverage: Optional[float] = None) -> Dict[str, float]:
        coverage = self.coverage_ratio() if coverage is None else clamp(float(coverage), 0.0, 1.0)
        if coverage < 0.90:
            progress = clamp(coverage / 0.90, 0.0, 1.0)
            start = {"fresh":.58,"opening":.16,"recovery":.115,"screening":.07,"qualification":.02,"boundary":.008,"upside":.015,"stale":.004,"bridge":.025,"elite":.0015,"exploration":.0015}
            end = {"fresh":.34,"opening":.15,"recovery":.15,"screening":.13,"qualification":.07,"boundary":.05,"upside":.05,"stale":.02,"bridge":.035,"elite":.004,"exploration":.001}
        else:
            progress = clamp((coverage - 0.90) / 0.10, 0.0, 1.0)
            start = {"fresh":.10,"opening":.145,"recovery":.115,"screening":.145,"qualification":.13,"boundary":.14,"upside":.08,"stale":.045,"bridge":.055,"elite":.025,"exploration":.005}
            end = {"fresh":.015,"opening":.08,"recovery":.075,"screening":.10,"qualification":.17,"boundary":.235,"upside":.12,"stale":.08,"bridge":.075,"elite":.045,"exploration":.005}
        values = {key: start[key] + (end[key] - start[key]) * progress for key in start}
        return self._normalize_weights(values)

    def selection_taper_progress(self) -> float:
        if self.generation_mode == MATCHMAKING_MODE_SELECTION:
            return 1.0
        coverage = self.coverage_ratio()
        return clamp(
            (coverage - AUTO_SELECTION_TAPER_START)
            / max(1e-9, 1.0 - AUTO_SELECTION_TAPER_START),
            0.0,
            1.0,
        )

    def selection_focus_active(self) -> bool:
        return self.selection_taper_progress() > 0.0

    def _category_weights(self) -> Dict[str, float]:
        if self.generation_mode == MATCHMAKING_MODE_SELECTION:
            return self._normalize_weights(dict(FINAL_SELECTION_WEIGHTS))

        coverage = self.coverage_ratio()
        if coverage <= AUTO_SELECTION_TAPER_START:
            return self._production_category_weights(coverage)

        start_weights = self._production_category_weights(AUTO_SELECTION_TAPER_START)
        progress = self.selection_taper_progress()
        values = {
            key: start_weights[key]
            + (FINAL_SELECTION_WEIGHTS[key] - start_weights[key]) * progress
            for key in start_weights
        }
        return self._normalize_weights(values)

    def _artist_matches_category(self, artist: str, category: str) -> bool:
        """Revalidate cached category membership against the live posterior.

        Candidate lists are intentionally rebuilt in batches, but a vote can move
        an artist from Fresh to Opening (or between later stages) immediately.
        Rechecking the small candidate head prevents stale labels between full
        cache rebuilds.
        """
        artist = str(artist)
        count = self.ratings.get_comparison_count(artist)
        evidence = self.ratings.effective_evidence(artist)
        first_outcome = str(self.ratings.artists.get(artist, {}).get("first_outcome", "") or "")
        if category == "fresh":
            return count == 0
        if category == "opening":
            return 0.0 < evidence < 2.0
        if category == "recovery":
            return 0.0 < evidence < 4.0 and first_outcome == "LOSS"
        if category == "screening":
            return 2.0 <= evidence < 4.0
        if category == "qualification":
            return 4.0 <= evidence < 8.0
        if category == "boundary":
            return evidence >= 4.0
        if category == "upside":
            return 0.0 < evidence < 16.0
        if category == "stale":
            return evidence >= 2.0
        if category == "bridge":
            return count > 0
        if category == "elite":
            return evidence >= 8.0
        if category == "exploration":
            return count > 0
        return False

    def _artist_on_generation_cooldown(self, artist: str) -> bool:
        last_seen = self.state.last_seen.get(str(artist))
        if last_seen is None:
            return False
        return (
            int(self.state.completed_duels) - int(last_seen)
            < ARTIST_GENERATION_COOLDOWN_MATCHES
        )

    def _artist_available(
        self,
        artist: str,
        excluded: Optional[Set[str]] = None,
        *,
        require_seen: Optional[bool] = None,
        honor_cooldown: bool = True,
    ) -> bool:
        artist = str(artist)
        if excluded and artist in excluded:
            return False
        if self._queued_artists[artist] >= MAX_BUFFERED_APPEARANCES_PER_ARTIST:
            return False
        count = self.ratings.get_comparison_count(artist)
        if require_seen is True and count <= 0:
            return False
        if require_seen is False and count > 0:
            return False
        if honor_cooldown and self._artist_on_generation_cooldown(artist):
            return False
        return True

    def _category_candidates(
        self,
        category: str,
        excluded: Optional[Set[str]] = None,
        limit: Optional[int] = None,
    ) -> List[str]:
        """Return a live-valid candidate head without rescanning the whole database."""
        excluded = set(excluded or set())
        require_seen = False if category == "fresh" else True
        results: List[str] = []
        for artist in self._candidate_lists.get(category, []):
            if not self._artist_matches_category(artist, category):
                continue
            if not self._artist_available(
                artist, excluded, require_seen=require_seen, honor_cooldown=True
            ):
                continue
            results.append(artist)
            if limit is not None and len(results) >= max(1, int(limit)):
                break
        return results

    def refresh_global_cache(self, force: bool = False) -> None:
        duel = self.state.completed_duels
        if not force and duel - self._candidate_cache_duel < 25:
            return
        cutoff = self.ratings.cutoff_score()
        now = self.ratings.comparison_count
        recent = Counter(self.state.recent_artists[-1000:])
        lists: Dict[str, List[Tuple[float, str]]] = defaultdict(list)
        for artist in self.artists:
            evidence = self.ratings.effective_evidence(artist)
            count = self.ratings.get_comparison_count(artist)
            mu = self.ratings.get_mu(artist); sigma = self.ratings.get_sigma(artist)
            potential = self.ratings.potential_score(artist)
            ptop = self.ratings.top_k_probability(artist)
            stale = max(0, now - int(self.ratings.artists.get(artist, {}).get("last_comparison_index", 0) or 0))
            exposure_penalty = recent[artist] * .12 + self._queued_artists[artist] * .8
            if count == 0:
                lists["fresh"].append((self.rng.random() - exposure_penalty, artist))
            if 0 < evidence < 2:
                opening_score = 3.2 * max(0.0, 2.0 - evidence) + 1.8 * min(2.0, stale / 320.0) + 0.65 * (sigma / PRIOR_SIGMA) + 0.55 * ((potential-cutoff)/300.0) - exposure_penalty
                lists["opening"].append((opening_score, artist))
            if 0 < evidence < 4 and self.ratings.artists.get(artist, {}).get("first_outcome") == "LOSS":
                recovery_score = (
                    3.0 * max(0.0, 4.0 - evidence)
                    + 0.70 * (sigma / PRIOR_SIGMA)
                    + 0.65 * ((potential - cutoff) / 300.0)
                    + 2.1 * min(2.5, stale / 300.0)
                    - exposure_penalty
                )
                lists["recovery"].append((recovery_score, artist))
            if 2 <= evidence < 4:
                lists["screening"].append((1.6*(potential-cutoff)/300.0 + sigma/PRIOR_SIGMA + min(1.0,stale/500.0) - exposure_penalty, artist))
            if 4 <= evidence < 8:
                lists["qualification"].append((1.8*(potential-cutoff)/300.0 + .8*sigma/PRIOR_SIGMA + min(1.0,stale/650.0) - exposure_penalty, artist))
            if evidence >= 4:
                ambiguity = ptop * (1.0 - ptop)
                lists["boundary"].append((5.0*ambiguity + .5*sigma/PRIOR_SIGMA + min(.8,stale/800.0) - exposure_penalty, artist))
            if evidence > 0 and evidence < 16:
                lists["upside"].append((2.0*(potential-cutoff)/300.0 + sigma/PRIOR_SIGMA + min(1.0,stale/600.0) - .04*evidence - exposure_penalty, artist))
            if evidence >= 2:
                lists["stale"].append((min(3.0, stale/400.0) + .5*sigma/PRIOR_SIGMA + .3*ptop - exposure_penalty, artist))
            if count > 0:
                degree = self.state.unique_opponents(artist)
                lists["bridge"].append((2.5/(1+degree) + min(1.0,stale/700.0) + .4*sigma/PRIOR_SIGMA - exposure_penalty, artist))
            if evidence >= 8:
                lists["elite"].append((mu + .25*sigma - exposure_penalty*50.0, artist))
            if count > 0:
                lists["exploration"].append((self.rng.random() + .3*sigma/PRIOR_SIGMA - exposure_penalty, artist))
        self._candidate_lists = {k: [a for _, a in sorted(v, reverse=True)] for k, v in lists.items()}

        # Once the automatic 80% taper begins—or immediately in manual Selection
        # mode—rank boundary candidates against both the Top-100 and Top-50 cuts.
        # This preserves the broad production candidate construction beforehand.
        if self.selection_focus_active():
            cutoff50 = self.ratings.cutoff_score(50)
            cutoff100 = self.ratings.cutoff_score(100)
            selection_boundary: List[Tuple[float, str]] = []
            for artist in self.artists:
                evidence = self.ratings.effective_evidence(artist)
                if evidence < 4.0:
                    continue
                p50 = self.ratings.top_k_probability(artist, 50)
                p100 = self.ratings.top_k_probability(artist, 100)
                sigma = self.ratings.get_sigma(artist)
                mu = self.ratings.get_mu(artist)
                stale = max(
                    0,
                    now - int(
                        self.ratings.artists.get(artist, {}).get(
                            "last_comparison_index", 0
                        )
                        or 0
                    ),
                )
                exposure_penalty = (
                    recent[artist] * 0.12 + self._queued_artists[artist] * 0.8
                )
                ambiguity50 = p50 * (1.0 - p50)
                ambiguity100 = p100 * (1.0 - p100)
                scale = max(80.0, sigma)
                proximity50 = math.exp(-abs(mu - cutoff50) / scale)
                proximity100 = math.exp(-abs(mu - cutoff100) / scale)
                score = (
                    3.4 * ambiguity50
                    + 2.6 * ambiguity100
                    + 0.55 * proximity50
                    + 0.45 * proximity100
                    + 0.45 * (sigma / PRIOR_SIGMA)
                    + min(0.8, stale / 800.0)
                    - exposure_penalty
                )
                selection_boundary.append((score, artist))
            self._candidate_lists["boundary"] = [
                artist for _, artist in sorted(selection_boundary, reverse=True)
            ]

        self._mu_sorted = sorted(self.artists, key=lambda a: (self.ratings.get_mu(a), a))
        self._mu_values = [self.ratings.get_mu(a) for a in self._mu_sorted]
        self._candidate_cache_duel = duel
        self._candidate_cache_revision = self.ratings.ranking_revision
        # Working set is a cache of presently useful artists, never an eligibility gate.
        pool: List[str] = []
        for category in ("boundary","qualification","screening","recovery","opening","upside","elite","fresh","stale","bridge"):
            quota = {"boundary":30,"qualification":22,"screening":22,"recovery":14,"opening":18,"upside":14,"elite":15,"fresh":10,"stale":8,"bridge":8}[category]
            for artist in self._candidate_lists.get(category, [])[:quota*3]:
                if artist not in pool:
                    pool.append(artist)
                    if len(pool) >= self.working_pool_size: break
            if len(pool) >= self.working_pool_size: break
        if len(pool) < self.working_pool_size:
            for artist in self.artists:
                if artist not in pool:
                    pool.append(artist)
                    if len(pool) >= self.working_pool_size: break
        self.working_pool = pool[:self.working_pool_size]

    def _choose_category(self) -> str:
        weights = self._category_weights()
        available = {
            category: weight
            for category, weight in weights.items()
            if self._category_candidates(category, limit=1)
        }
        if not available:
            return ""
        total = sum(available.values())
        pick = self.rng.random() * total
        cumulative = 0.0
        for category, weight in available.items():
            cumulative += weight
            if pick <= cumulative:
                return category
        return next(reversed(available))

    def _choose_team_size(self) -> int:
        """Choose a non-fresh team size from the half-weight Fresh quota ledger."""
        raw_completed = {
            size: float(self.state.team_size_counts.get(size, 0))
            for size in TEAM_SIZE_FRACTIONS
        }
        raw_queued = {
            size: float(self._queued_sizes.get(size, 0))
            for size in TEAM_SIZE_FRACTIONS
        }
        fresh_label = self.CATEGORY_LABELS["fresh"]
        completed_fresh = min(
            raw_completed[1],
            float(self.state.reason_counts.get(fresh_label, 0)),
        )
        queued_fresh = min(raw_queued[1], float(self._queued_fresh_count))
        discount = 1.0 - FRESH_DISCOVERY_QUOTA_WEIGHT
        effective_completed = dict(raw_completed)
        effective_queued = dict(raw_queued)
        effective_completed[1] -= completed_fresh * discount
        effective_queued[1] -= queued_fresh * discount
        total_after = (
            sum(effective_completed.values())
            + sum(effective_queued.values())
            + 1.0
        )
        deficits = {
            size: TEAM_SIZE_FRACTIONS[size] * total_after
            - effective_completed[size]
            - effective_queued[size]
            for size in TEAM_SIZE_FRACTIONS
        }
        best = max(deficits.values())
        choices = [
            size for size, value in deficits.items()
            if abs(value - best) < 1e-9
        ]
        return self.rng.choice(choices)

    def _candidate_pick(self, category: str, excluded: Set[str]) -> Optional[str]:
        broad = category in {
            "fresh", "opening", "recovery", "screening",
            "qualification", "stale", "bridge",
        }
        head_size = 240 if broad else 60
        candidates = self._category_candidates(category, excluded, limit=head_size)
        if not candidates:
            return None
        # Stage-completion queues deliberately sample a broad head so candidates
        # cannot disappear forever below a narrow top-N sampling horizon.
        decay = 70.0 if broad else 16.0
        head = candidates
        weights = [math.exp(-index / decay) for index in range(len(head))]
        return self.rng.choices(head, weights=weights, k=1)[0]

    def _near_mu_candidates(self, target_mu: float, excluded: Set[str], limit: int = 180) -> List[str]:
        if not self._mu_sorted:
            return []
        position = bisect.bisect_left(self._mu_values, target_mu)
        lower = max(0, position - limit)
        upper = min(len(self._mu_sorted), position + limit)
        return [artist for artist in self._mu_sorted[lower:upper] if artist not in excluded]

    def _build_team(
        self,
        anchor: str,
        size: int,
        excluded: Set[str],
        prefer_unseen: bool = False,
        require_connected: bool = False,
        category: Optional[str] = None,
    ) -> List[str]:
        team = [anchor]
        excluded = set(excluded) | {anchor}
        stage_categories = {"opening", "recovery", "screening", "qualification"}
        recent = Counter(self.state.recent_artists[-500:])
        while len(team) < size:
            if prefer_unseen:
                pool = self._category_candidates("fresh", excluded, limit=800)
            elif category in stage_categories:
                pool = self._category_candidates(str(category), excluded, limit=800)
                target = self.ratings.get_mu(anchor)
                pool.sort(
                    key=lambda artist: (
                        recent[artist],
                        abs(self.ratings.get_mu(artist) - target),
                        self.rng.random(),
                    )
                )
            else:
                target = self.ratings.get_mu(anchor)
                pool = [
                    artist
                    for artist in self._near_mu_candidates(target, excluded, 180)
                    if self._artist_available(
                        artist, excluded, require_seen=True, honor_cooldown=True
                    )
                ]
                if require_connected:
                    connected = [
                        artist for artist in pool
                        if self.state.unique_opponents(artist) > 0
                        or self.ratings.get_comparison_count(artist) > 1
                    ]
                    if connected:
                        pool = connected
                pool.sort(
                    key=lambda artist: (
                        recent[artist],
                        abs(self.ratings.get_mu(artist) - target),
                        self.rng.random(),
                    )
                )
            if not pool:
                pool = [
                    artist
                    for artist in self.artists
                    if self._artist_available(
                        artist, excluded,
                        require_seen=(not prefer_unseen),
                        honor_cooldown=True,
                    )
                ]
            if not pool:
                break
            chosen = self.rng.choice(pool[: min(60, len(pool))]) if prefer_unseen else pool[0]
            team.append(chosen)
            excluded.add(chosen)
        return team

    def _opponent_anchor(
        self, anchor_team: Sequence[str], category: str, excluded: Set[str]
    ) -> Optional[str]:
        target = self.ratings.team_strength(anchor_team)
        candidates = [
            artist
            for artist in self._near_mu_candidates(target, excluded, 260)
            if self._artist_available(
                artist, excluded, require_seen=True, honor_cooldown=True
            )
        ]
        if not candidates:
            candidates = [
                artist
                for artist in self.artists
                if self._artist_available(
                    artist, excluded, require_seen=True, honor_cooldown=True
                )
            ]
        if not candidates:
            return None
        recent = Counter(self.state.recent_artists[-800:])

        def score(artist: str) -> float:
            probability = logistic((target - self.ratings.get_mu(artist)) / LOGISTIC_SCALE)
            information = probability * (1.0 - probability)
            degree = self.state.unique_opponents(artist)
            hub_bonus = 0.08 * math.log1p(degree)
            repeat = recent[artist]
            return 5.0 * information + hub_bonus - 0.28 * repeat + self.rng.random() * 0.03

        return max(candidates[:500], key=score)

    def set_buffer_reservations(self, buffer: Sequence[Any]) -> None:
        self._queued_artists = Counter()
        self._queued_matchups = Counter()
        self._queued_combinations = Counter()
        self._queued_sizes = Counter()
        self._queued_fresh_count = 0
        self._queued_degree = Counter()
        for item in buffer or []:
            matchmaking_reason = ""
            if isinstance(item, dict):
                artists_a = list(item.get("artists_a", []) or [])
                artists_b = list(item.get("artists_b", []) or [])
                matchmaking_reason = str(
                    item.get("matchmaking_reason", item.get("reason", "")) or ""
                )
            elif isinstance(item, (tuple, list)) and len(item) >= 2:
                artists_a = list(item[0] or [])
                artists_b = list(item[1] or [])
                if len(item) >= 3:
                    matchmaking_reason = str(item[2] or "")
            else:
                artists_a = list(getattr(item, "artists_a", []) or [])
                artists_b = list(getattr(item, "artists_b", []) or [])
                matchmaking_reason = str(
                    getattr(item, "matchmaking_reason", "") or ""
                )
            self._queued_artists.update(artists_a + artists_b)
            self._queued_matchups[self.state.matchup_key(artists_a, artists_b)] += 1
            for left in artists_a:
                self._queued_degree[left] += len(artists_b)
            for right in artists_b:
                self._queued_degree[right] += len(artists_a)
            if len(artists_a) in TEAM_SIZE_FRACTIONS:
                self._queued_sizes[len(artists_a)] += 1
            if (
                len(artists_a) == 1
                and matchmaking_reason == self.CATEGORY_LABELS["fresh"]
            ):
                self._queued_fresh_count += 1
            for team in (artists_a, artists_b):
                if len(team) > 1:
                    self._queued_combinations[normalized_combo_id(team)] += 1

    def _select_fresh_discovery(
        self,
    ) -> Optional[Tuple[List[str], List[str], str, str, float]]:
        """Reserve two globally unseen, unbuffered artists for one solo opening."""
        candidates = self._category_candidates("fresh", limit=800)
        if len(candidates) < 2:
            return None
        head = candidates[: min(800, len(candidates))]
        recent_matchups = set(self.state.recent_matchups[-300:])
        for _ in range(min(120, len(head) * 2)):
            artist_a = self.rng.choice(head)
            opponent_pool = [artist for artist in head if artist != artist_a]
            if not opponent_pool:
                return None
            artist_b = self.rng.choice(opponent_pool)
            team_a = [artist_a]
            team_b = [artist_b]
            key = self.state.matchup_key(team_a, team_b)
            if self._queued_matchups[key] or key in recent_matchups:
                continue
            detail = (
                "Fresh discovery; two globally unseen, unbuffered artists; "
                "solo opening test with provisional buffer reservation"
            )
            return team_a, team_b, self.CATEGORY_LABELS["fresh"], detail, 25.0
        return None

    def select_matchup(
        self, buffer: Optional[Sequence[Any]] = None, *args: Any, **kwargs: Any
    ) -> Tuple[List[str], List[str], str, str, float]:
        self.set_buffer_reservations(buffer or [])
        self.refresh_global_cache()
        for _ in range(120):
            category = self._choose_category()
            if not category:
                break
            if category == "fresh":
                fresh_match = self._select_fresh_discovery()
                if fresh_match is not None:
                    return fresh_match
                continue

            size = self._choose_team_size()
            anchor = self._candidate_pick(category, set())
            if anchor is None:
                continue
            team_a = self._build_team(anchor, size, set(), category=category)
            if len(team_a) != size:
                continue
            opponent = self._opponent_anchor(team_a, category, set(team_a))
            if opponent is None:
                continue
            team_b = self._build_team(
                opponent, size, set(team_a), require_connected=False, category=None
            )
            if len(team_b) != size or set(team_a) & set(team_b):
                continue
            participants = team_a + team_b
            if any(self._queued_artists[artist] for artist in participants):
                continue
            key = self.state.matchup_key(team_a, team_b)
            if self._queued_matchups[key] or key in self.state.recent_matchups[-300:]:
                continue
            expected = logistic(
                (self.ratings.team_strength(team_a) - self.ratings.team_strength(team_b))
                / LOGISTIC_SCALE
            )
            information = expected * (1.0 - expected)
            penalty = self.state.repetition_penalty(team_a, team_b)
            score = information * 100.0 - penalty
            label = self.CATEGORY_LABELS.get(category, category)
            detail = (
                f"{label}; predicted A win {expected * 100:.1f}%; "
                "global information scheduling; all participants unbuffered"
            )
            return team_a, team_b, label, detail, score

        # Fallback preserves the same hard invariants: no queued participant and
        # no unseen artist outside a solo Fresh discovery opening.
        fresh_match = self._select_fresh_discovery()
        if fresh_match is not None:
            return fresh_match
        available_seen = [
            artist
            for artist in self.artists
            if self._artist_available(
                artist, set(), require_seen=True, honor_cooldown=False
            )
        ]
        self.rng.shuffle(available_seen)
        for size in (self._choose_team_size(), 1, 2, 3):
            if len(available_seen) >= size * 2:
                team_a = available_seen[:size]
                team_b = available_seen[size:size * 2]
                return (
                    team_a, team_b, "Bridge calibration",
                    "Fallback bridge using unbuffered evaluated artists", 0.0,
                )
        raise RuntimeError(
            "Could not select a non-duplicated matchup: fewer than two eligible artists are available."
        )

    def record_completed(self, artists_a: Sequence[str], artists_b: Sequence[str], reason: str) -> None:
        self.state.record_matchup(artists_a,artists_b,reason)
        # Cache refresh cadence is independent of rating revision, avoiding vote-path scans.
        if self.state.completed_duels-self._candidate_cache_duel>=25:
            self.refresh_global_cache(force=True)

    # Compatibility helpers used by the monolithic application.
    def combination_strength(self, artists: List[str]) -> float:
        return self.ratings.team_strength(artists)

    def artist_status(self, artist: str) -> str:
        if artist in self.working_pool:return "Scheduled working set"
        stale=max(0,self.ratings.comparison_count-int(self.ratings.artists.get(str(artist),{}).get("last_comparison_index",0) or 0))
        if self.ratings.get_comparison_count(artist)==0:return "Unseen"
        if stale>800:return "High-priority recall"
        if stale>250:return "Dormant"
        return "Cooling down"

    def scheduling_priority(self, artist: str) -> float:
        self.refresh_global_cache()
        for category in ("recovery","boundary","qualification","screening","opening","upside","stale","bridge","elite","fresh"):
            try:
                position=self._candidate_lists.get(category,[]).index(str(artist))
                return max(0.0,10.0-position/50.0)
            except ValueError:pass
        return 0.0


class TopSearchRatingSystem(BayesianTopKRatingSystem):
    """Official Bayesian individual ranking used by the application."""
    pass

class MatchmakingState(InformationMatchmakingState):
    """Persistent global information-scheduling memory."""
    pass


class Matchmaker:
    """Compatibility wrapper around the global information-driven scheduler."""

    def __init__(self, artist_manager, elo_system, combination_elo, top_search, state):
        self.artist_manager = artist_manager
        self.elo_system = elo_system
        self.combination_elo = combination_elo
        self.top_search = top_search
        self.state = state
        self.scheduler = InformationDrivenScheduler(
            artist_manager.artists,
            top_search,
            state,
            random.Random(random.randint(0, MAX_NOVELAI_SEED)),
            ACTIVE_POOL_SIZE,
        )
        active_pool = getattr(artist_manager, "active_pool", None)
        if active_pool is not None:
            self.scheduler.working_pool = list(active_pool.pool)[:ACTIVE_POOL_SIZE] or list(self.scheduler.working_pool)
            active_pool.attach_scheduler(self.scheduler)

    @property
    def pool(self) -> List[str]:
        return list(self.scheduler.working_pool)

    def combination_strength(self, artists: List[str]) -> float:
        return self.top_search.team_strength(artists)

    def select_matchup(self, reserved_duels=None, buffer_target_size=BUFFER_TARGET_SIZE):
        _ = buffer_target_size
        result = self.scheduler.select_matchup(reserved_duels or [])
        active_pool = getattr(self.artist_manager, "active_pool", None)
        if active_pool is not None:
            active_pool._pool = list(self.scheduler.working_pool)
        return result


