# Active Pool System
# --------------------------------------------------------------------------------

class ActivePool:
    """A temporary 150-person working cache, never a competitive eligibility gate."""

    def __init__(self, all_artists, elo_system, top_search, classifications=None,
                 pool_size=ACTIVE_POOL_SIZE, pool_file=None, suppress_persistence=False):
        self.all_artists = list(dict.fromkeys(str(a) for a in all_artists))
        self.all_artist_set = set(self.all_artists)
        self.elo_system = elo_system
        self.top_search = top_search
        self.classifications = classifications
        self.pool_size = int(pool_size)
        self.pool_file = Path(pool_file or ACTIVE_POOL_FILE)
        self._pool: List[str] = []
        self.scheduler: Optional[InformationDrivenScheduler] = None
        self.suppress_persistence = bool(suppress_persistence)
        self.result_sequence = 0
        self.fresh_followup_deadlines: Dict[str, int] = {}
        if not self.suppress_persistence:
            self.load()
        if not self._pool:
            ranked = self.top_search.ranked_artists(0.0, "potential")
            self._pool = (ranked + [a for a in self.all_artists if a not in set(ranked)])[:self.pool_size]
        self._pool = list(dict.fromkeys(a for a in self._pool if a in self.all_artist_set))[:self.pool_size]
        if not self.suppress_persistence:
            self.save()

    @property
    def pool(self) -> List[str]:
        if self.scheduler is not None:
            return self.scheduler.working_pool
        return self._pool

    @pool.setter
    def pool(self, value: Iterable[str]) -> None:
        self._pool = list(dict.fromkeys(str(a) for a in value if str(a) in self.all_artist_set))[:self.pool_size]
        if self.scheduler is not None:
            self.scheduler.working_pool = list(self._pool)

    @property
    def elite_reservoir(self) -> List[str]:
        return self.top_search.elite_artists(20)

    def attach_scheduler(self, scheduler: InformationDrivenScheduler) -> None:
        self.scheduler = scheduler
        if self._pool:
            scheduler.working_pool = list(self._pool)[:self.pool_size]
        self._pool = list(scheduler.working_pool)

    def load(self) -> None:
        if not self.pool_file.exists():
            return
        try:
            raw = json.loads(self.pool_file.read_text(encoding="utf-8"))
            values = raw.get("working_pool", raw.get("pool", [])) if isinstance(raw, dict) else raw
            self._pool = [str(a) for a in values if str(a) in self.all_artist_set][:self.pool_size]
        except Exception as exc:
            print(f"Warning: Could not load working set: {exc}")
            self._pool = []

    def save(self) -> None:
        if self.suppress_persistence:
            return
        values = list(self.pool)[:self.pool_size]
        atomic_write_json(self.pool_file, {
            "version": MODEL_VERSION,
            "semantics": "temporary_working_set",
            "working_pool": values,
        })

    def seen_artist_count(self) -> int:
        return sum(self.top_search.get_comparison_count(a) > 0 for a in self.all_artists)

    def unseen_artist_count(self) -> int:
        return max(0, len(self.all_artists) - self.seen_artist_count())

    def coverage_mode_active(self) -> bool:
        return self.seen_artist_count() / max(1, len(self.all_artists)) < 0.90

    def coverage_reserve_target(self) -> int:
        return 0

    def coverage_reserve_count(self) -> int:
        return sum(self.top_search.get_comparison_count(a) == 0 for a in self.pool)

    def synchronize_coverage_reserve(self, max_releases=None):
        _ = max_releases
        if self.scheduler is not None:
            self.scheduler.refresh_global_cache(force=True)
            self._pool = list(self.scheduler.working_pool)
        return [], []

    def snapshot_runtime_state(self) -> dict:
        return {
            "working_pool": list(self.pool),
            "scheduler": self.scheduler.snapshot_runtime_state() if self.scheduler else None,
            "result_sequence": int(self.result_sequence),
            "fresh_followup_deadlines": dict(self.fresh_followup_deadlines),
        }

    def restore_runtime_state(self, state: Optional[dict], refresh: bool = True) -> None:
        if not state:
            return
        self._pool = [a for a in state.get("working_pool", []) if a in self.all_artist_set][:self.pool_size]
        self.result_sequence = int(state.get("result_sequence", self.result_sequence) or 0)
        self.fresh_followup_deadlines = {str(k): int(v) for k, v in state.get("fresh_followup_deadlines", {}).items()}
        if self.scheduler is not None:
            self.scheduler.restore_runtime_state(state.get("scheduler"), refresh=refresh)
            if self._pool:
                self.scheduler.working_pool = list(self._pool)

    def _has_fresh_followup_grace(self, artist: str) -> bool:
        return False

    def process_result(self, artists_a: List[str], artists_b: List[str]):
        self.result_sequence += 1
        # Ratings and global scheduling priority change; leaving the working set
        # never means competitive removal, so there are no rotation events.
        _ = artists_a, artists_b
        return [], []

    def restore_artists(self, artists: List[str]) -> None:
        _ = artists

    def remove_artists(self, artists: List[str]) -> None:
        _ = artists

    def get_selection_weight(self, artist: str) -> float:
        return self.scheduler.scheduling_priority(artist) if self.scheduler else 1.0

    def select_artist(self) -> str:
        source = self.pool or self.all_artists
        return random.choice(source) if source else ""

    def select_combination(self, min_artists=1, max_artists=3) -> List[str]:
        source = self.pool or self.all_artists
        if not source:
            return []
        size = random.randint(int(min_artists), int(max_artists))
        return random.sample(source, min(size, len(source)))

    def get_pool_stats(self) -> dict:
        stages = Counter(self.top_search.stage(a) for a in self.pool)
        statuses = Counter(
            self.scheduler.artist_status(a) if self.scheduler else "Scheduled working set"
            for a in self.pool
        )
        return {
            "size": len(self.pool),
            "target_size": self.pool_size,
            "overflow": max(0, len(self.pool)-self.pool_size),
            "followup_grace": 0,
            "elite": sum(a in set(self.elite_reservoir) for a in self.pool),
            "screening": stages.get("Opening",0)+stages.get("Screening",0),
            "qualification": stages.get("Qualification",0),
            "contenders": stages.get("Established",0),
            "proven": stages.get("Established",0),
            "at_risk": [],
            "at_risk_count": 0,
            "total_artists": len(self.all_artists),
            "top50_cutoff": self.top_search.cutoff_score(),
            "coverage_mode": self.coverage_mode_active(),
            "seen_artists": self.seen_artist_count(),
            "unseen_artists": self.unseen_artist_count(),
            # Valid completed evaluations only: A/B, Tie, and Both bad.
            # Generated, queued, skipped, and Invalid duels are excluded.
            "completed_duels": int(self.top_search.comparison_count),
            "coverage_reserve": self.coverage_reserve_count(),
            "coverage_reserve_target": 0,
            "working_set_semantics": True,
            "dormant": statuses.get("Dormant",0),
            "high_priority_recall": statuses.get("High-priority recall",0),
        }


class ArtistTagManager:
    """Manages loading and selecting artist tags."""

    def __init__(self, tags_file: Path, elo_system: ELOSystem = None):
        self.tags_file = tags_file
        self.artists: List[str] = []
        self.elo_system = elo_system
        self.active_pool: Optional[ActivePool] = None
        self.load_artists()

    def load_artists(self):
        """Load artist tags from file."""
        if self.tags_file.exists():
            with open(self.tags_file, "r", encoding="utf-8") as f:
                self.artists = [line.strip() for line in f if line.strip()]
            print(f"Loaded {len(self.artists)} artist tags")
        else:
            print(f"Warning: Artist tags file not found: {self.tags_file}")
            self.artists = []

    def initialize_pool(
        self,
        elo_system: ELOSystem,
        top_search: TopSearchRatingSystem,
        classifications: Optional[ClassificationStore] = None,
        suppress_persistence: bool = False,
    ):
        """Initialize the temporary Bayesian working set."""
        self.elo_system = elo_system
        self.active_pool = ActivePool(
            self.artists,
            elo_system,
            top_search,
            classifications,
            suppress_persistence=suppress_persistence,
        )

    def get_random_combination(self, min_artists: int = 1, max_artists: int = 3) -> List[str]:
        """Get a random combination of 1-3 artists, using active pool if available."""
        if self.active_pool:
            return self.active_pool.select_combination(min_artists, max_artists)

        # Fallback to pure random if no pool
        if not self.artists:
            return []
        num_artists = random.randint(min_artists, max_artists)
        return random.sample(self.artists, min(num_artists, len(self.artists)))

    def process_result(self, artists_a: List[str], artists_b: List[str]) -> Tuple[List[dict], List[dict]]:
        """Process one rated evaluation through the staged active pool."""
        if self.active_pool:
            return self.active_pool.process_result(artists_a, artists_b)
        return [], []

    def restore_artists(self, artists: List[str]):
        """Restore artists to the pool (for undo)."""
        if self.active_pool:
            self.active_pool.restore_artists(artists)

    def remove_artists(self, artists: List[str]):
        """Remove artists from the pool (for undo of rotated-in artists)."""
        if self.active_pool:
            self.active_pool.remove_artists(artists)

    def synchronize_coverage_reserve(self, max_releases: Optional[int] = None) -> Tuple[List[dict], List[dict]]:
        """Synchronize the active pool's coverage-first unseen reserve."""
        if self.active_pool:
            return self.active_pool.synchronize_coverage_reserve(max_releases)
        return [], []

    def get_pool_stats(self) -> dict:
        """Get active pool statistics."""
        if self.active_pool:
            return self.active_pool.get_pool_stats()
        return {"size": 0, "total_artists": len(self.artists)}

    def format_artist_tags(self, artists: List[str]) -> str:
        """Format artist list as comma-separated artist tags."""
        return ", ".join(f"artist: {artist}" for artist in artists)


# --------------------------------------------------------------------------------
# Prompt Processing
# --------------------------------------------------------------------------------

def is_artist_tag(segment: str) -> bool:
    """
    Check if a segment is an artist tag.
    Handles: artist: name, artist:name, [artist: name], {artist: name:1.5}, etc.
    """
    stripped = segment.strip().lower()
    # Remove surrounding brackets
    stripped_no_brackets = stripped.strip("[]{}()")

    # Check for artist: or artist (space) patterns
    if stripped_no_brackets.startswith("artist:") or stripped_no_brackets.startswith("artist "):
        return True
    # Check for artist: anywhere (handles weighted like "artist:name:1.5")
    if "artist:" in stripped_no_brackets:
        return True
    # Check for "artist name" pattern at start
    if re.match(r"^\s*artist\s+\w", stripped_no_brackets):
        return True
    return False


def remove_artist_tags_with_position(prompt: str) -> tuple:
    """
    Remove existing artist tags from a prompt and return position of first one found.
    Returns: (cleaned_prompt, first_artist_index or -1 if none found)

    Handles:
    - artist: name, artist:name
    - [artist: name], {artist: name}, (artist: name)
    - artist:name:1.5 (weighted tags)
    """
    segments = prompt.split(",")
    filtered_segments = []
    first_artist_idx = -1

    for segment in segments:
        if is_artist_tag(segment):
            if first_artist_idx == -1:
                first_artist_idx = len(filtered_segments)  # Position in filtered list
            continue
        filtered_segments.append(segment)

    return ",".join(filtered_segments), first_artist_idx


def remove_artist_tags(prompt: str) -> str:
    """Remove all artist tags from prompt, return cleaned prompt."""
    cleaned, _ = remove_artist_tags_with_position(prompt)
    return cleaned


def insert_artist_tags(prompt: str, artist_tags: str) -> str:
    """
    Insert artist tags into the prompt.
    If {artist_placeholder} exists, replace it.
    Otherwise, insert at position of first existing artist tag, or at end.
    """
    if "{artist_placeholder}" in prompt:
        return prompt.replace("{artist_placeholder}", artist_tags)

    # Remove any existing artist tags and get position of first one
    clean_prompt, first_artist_idx = remove_artist_tags_with_position(prompt)
    segments = clean_prompt.split(",")

    # If there was an existing artist tag, insert at that position
    if first_artist_idx >= 0 and first_artist_idx <= len(segments):
        segments.insert(first_artist_idx, f" {artist_tags}")
        return ",".join(segments)

    # No existing artist tags - always append at end
    return clean_prompt + ", " + artist_tags


# --------------------------------------------------------------------------------
# Gradio Temp Cleanup
# --------------------------------------------------------------------------------

def _is_our_gradio_temp_entry(path: Path) -> bool:
    """Return True if a Gradio temp entry contains comparison images from this app."""
    try:
        if path.is_file():
            return bool(
                re.fullmatch(r"compare_\d+_\d+_[ab]\.png", path.name)
                or re.fullmatch(r"gallery_thumb_[0-9a-f]+\.jpg", path.name)
            )

        if not path.is_dir():
            return False

        for candidate in path.rglob("*"):
            if candidate.is_file() and (
                re.fullmatch(r"compare_\d+_\d+_[ab]\.png", candidate.name)
                or re.fullmatch(r"gallery_thumb_[0-9a-f]+\.jpg", candidate.name)
            ):
                return True
    except (OSError, PermissionError):
        return False

    return False


def _entry_size_bytes(path: Path) -> int:
    """Best-effort recursive size calculation for cleanup logging."""
    try:
        if path.is_file():
            return path.stat().st_size
        return sum(
            p.stat().st_size
            for p in path.rglob("*")
            if p.is_file()
        )
    except (OSError, PermissionError):
        return 0


def cleanup_old_gradio_temp_entries(max_entries: int = GRADIO_CLEANUP_OLDEST_ENTRIES) -> Tuple[int, int]:
    """
    Delete the oldest Gradio temp entries belonging to this app.

    This deliberately ignores unrelated Gradio temp files from other applications.
    Returns: (entries_deleted, bytes_freed)
    """
    if max_entries <= 0 or not GRADIO_TEMP_DIR.exists():
        return 0, 0

    candidates = []
    try:
        for entry in GRADIO_TEMP_DIR.iterdir():
            if _is_our_gradio_temp_entry(entry):
                try:
                    modified_time = entry.stat().st_mtime
                except (OSError, PermissionError):
                    continue
                candidates.append((modified_time, entry))
    except (OSError, PermissionError) as e:
        print(f"Could not scan Gradio temp directory {GRADIO_TEMP_DIR}: {e}")
        return 0, 0

    candidates.sort(key=lambda item: item[0])
    deleted = 0
    bytes_freed = 0

    for _, entry in candidates[:max_entries]:
        size = _entry_size_bytes(entry)
        try:
            if entry.is_dir():
                shutil.rmtree(entry)
            else:
                entry.unlink()
            deleted += 1
            bytes_freed += size
        except (OSError, PermissionError) as e:
            print(f"Could not delete Gradio temp entry {entry}: {e}")

    if deleted:
        freed_mb = bytes_freed / (1024 * 1024)
        print(
            f"Gradio temp cleanup: deleted {deleted} oldest app entries "
            f"from {GRADIO_TEMP_DIR} and freed about {freed_mb:.1f} MB."
        )
    else:
        print(f"Gradio temp cleanup: no old app entries found in {GRADIO_TEMP_DIR}.")

    return deleted, bytes_freed


def note_successful_image_and_maybe_cleanup() -> None:
    """Run cleanup after the currently configured number of successful images."""
    global _successful_images_since_cleanup

    should_cleanup = False
    with _gradio_cleanup_lock:
        _successful_images_since_cleanup += 1
        if _successful_images_since_cleanup >= _runtime_cleanup_every_images:
            _successful_images_since_cleanup = 0
            should_cleanup = True

    if should_cleanup:
        cleanup_old_gradio_temp_entries(_runtime_cleanup_oldest_entries)


# --------------------------------------------------------------------------------
# Image Generation
# --------------------------------------------------------------------------------

def strip_standalone_nsfw_tag(prompt: Optional[str]) -> str:
    """Remove only comma-delimited standalone NSFW tags, including common weighting wrappers."""
    cleaned_parts: List[str] = []
    matching_wrappers = {"{": "}", "[": "]", "(": ")"}
    weight_prefix = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)::\s*", re.IGNORECASE)

    for raw_part in str(prompt or "").split(","):
        original = raw_part.strip()
        if not original:
            continue

        normalized = original
        for _ in range(8):
            changed = False
            normalized = normalized.strip()

            if normalized.endswith("::"):
                normalized = normalized[:-2].strip()
                changed = True

            without_weight = weight_prefix.sub("", normalized, count=1)
            if without_weight != normalized:
                normalized = without_weight.strip()
                changed = True

            if (
                len(normalized) >= 2
                and normalized[0] in matching_wrappers
                and normalized[-1] == matching_wrappers[normalized[0]]
            ):
                normalized = normalized[1:-1].strip()
                changed = True

            if not changed:
                break

        if normalized.casefold() == "nsfw":
            continue
        cleaned_parts.append(original)

    return ", ".join(cleaned_parts)


def remove_nsfw_from_generated_request(gen: GenerateImageInfer) -> None:
    """Keep the flat and V4 structured negative captions synchronized after preset expansion."""
    parameters = getattr(gen, "parameters", None)
    if parameters is None:
        return

    parameters.negative_prompt = strip_standalone_nsfw_tag(
        getattr(parameters, "negative_prompt", "")
    )

    v4_negative = getattr(parameters, "v4_negative_prompt", None)
    caption = getattr(v4_negative, "caption", None)
    if caption is None:
        return

    caption.base_caption = strip_standalone_nsfw_tag(
        getattr(caption, "base_caption", "")
    )
    for char_caption in getattr(caption, "char_captions", []) or []:
        char_caption.char_caption = strip_standalone_nsfw_tag(
            getattr(char_caption, "char_caption", "")
        )


async def generate_image(
    session: ApiCredential,
    prompt: str,
    output_path: Path,
    negative_prompt: str = None,
    quality_toggle: bool = True,
    uc_preset: int = 0,
    seed: Optional[int] = None,
    timing_callback: Any = None,
    *,
    width: int = IMG_WIDTH,
    height: int = IMG_HEIGHT,
    steps: int = STEPS,
    sampler: Any = DEFAULT_SAMPLER_ID,
    scheduler: str = "default",
    decrisp_mode: bool = False,
    variety_boost: bool = False,
) -> bool:
    """Generate a single image and save it, optionally reporting exact request timing."""
    timing_started_epoch = time.time()
    timing_started_perf = time.perf_counter()
    timing_success = False
    try:
        # Map UC preset index to enum (-1 = None/disabled)
        uc_preset_map = {
            -1: None,  # Disabled
            0: UCPreset.TYPE0,
            1: UCPreset.TYPE1,
            2: UCPreset.TYPE2,
            3: UCPreset.TYPE3,
        }
        normalized_sampler = normalize_sampler(sampler, DEFAULT_SAMPLER_ID)
        normalized_scheduler = normalize_scheduler(scheduler, normalized_sampler)
        gen = GenerateImageInfer.build_generate(
            prompt=prompt,
            width=int(width),
            height=int(height),
            model=MODEL,
            steps=int(steps),
            seed=seed,
            sampler=_sampler_runtime_value(normalized_sampler),
            negative_prompt=NEGATIVE_PROMPT if negative_prompt is None else negative_prompt,
            ucPreset=uc_preset_map.get(uc_preset, UCPreset.TYPE0),
            qualityToggle=quality_toggle,
            decrisp_mode=bool(decrisp_mode),
            variety_boost=bool(variety_boost),
        )
        runtime_scheduler = _scheduler_runtime_value(normalized_scheduler)
        if runtime_scheduler is not None and getattr(gen, "parameters", None) is not None:
            # build_generate does not expose noise_schedule, but the SDK parameter
            # model does. Set the already-validated Phase 3 scheduler explicitly.
            gen.parameters.noise_schedule = runtime_scheduler

        # The SDK expands the selected UC preset while constructing the request.
        # Sanitize afterward so standalone NSFW is absent from both serialized fields.
        remove_nsfw_from_generated_request(gen)

        resp = await gen.request(session=session)
        resp: ImageGenerateResp

        _, file_bytes = resp.files[0]

        output_path.parent.mkdir(parents=True, exist_ok=True)
        with open(output_path, "wb") as f:
            f.write(file_bytes)

        note_successful_image_and_maybe_cleanup()
        timing_success = True
        return True
    except Exception as e:
        print(f"Error generating image: {e}")
        return False
    finally:
        if timing_callback is not None:
            try:
                timing_callback(
                    timing_started_epoch,
                    time.perf_counter() - timing_started_perf,
                    timing_success,
                )
            except Exception as timing_exc:
                print(f"Warning: Could not capture image-generation timing: {timing_exc}")


