@dataclass
class ComparisonRecord:
    """Record of a single comparison, including reproducibility metadata."""
    timestamp: float
    artists_a: List[str]
    artists_b: List[str]
    winner: str
    image_a_path: str
    image_b_path: str
    duel_id: str = ""
    seed: int = 0
    rotation_preset: Optional[str] = None
    prompt_a: str = ""
    prompt_b: str = ""
    negative_prompt: str = ""
    quality_toggle: bool = True
    uc_preset: int = 0
    generation_config: Dict[str, Any] = field(default_factory=dict)
    matchmaking_reason: str = "Historical / unknown"
    matchmaking_details: str = ""
    matchmaking_score: float = 0.0
    result_weight_a: float = 0.0
    result_weight_b: float = 0.0
    legacy_rating_changes: Dict[str, float] = field(default_factory=dict)
    top_search_rating_changes: Dict[str, float] = field(default_factory=dict)
    combination_rating_changes: Dict[str, float] = field(default_factory=dict)
    top_search_expected_a: float = 0.5
    both_bad: bool = False


class ComparisonHistory:
    """Manages comparison history."""

    def __init__(self, filepath: Path):
        self.filepath = filepath
        self.records: List[dict] = []
        self.load()

    def load(self):
        """Load history from file."""
        if self.filepath.exists():
            with open(self.filepath, "r", encoding="utf-8") as f:
                self.records = json.load(f)

    def save(self):
        """Save history to file."""
        with open(self.filepath, "w", encoding="utf-8") as f:
            json.dump(self.records, f, indent=2)

    def add_record(self, record: ComparisonRecord, save_immediately: bool = True):
        """Add a comparison record, optionally deferring the full-history JSON rewrite."""
        self.records.append({
            "timestamp": record.timestamp,
            "artists_a": record.artists_a,
            "artists_b": record.artists_b,
            "winner": record.winner,
            "image_a_path": record.image_a_path,
            "image_b_path": record.image_b_path,
            "duel_id": record.duel_id,
            "seed": record.seed,
            "rotation_preset": record.rotation_preset,
            "prompt_a": record.prompt_a,
            "prompt_b": record.prompt_b,
            "negative_prompt": record.negative_prompt,
            "quality_toggle": record.quality_toggle,
            "uc_preset": record.uc_preset,
            "generation_config": deepcopy(record.generation_config),
            "matchmaking_reason": record.matchmaking_reason,
            "matchmaking_details": record.matchmaking_details,
            "matchmaking_score": record.matchmaking_score,
            "result_weight_a": record.result_weight_a,
            "result_weight_b": record.result_weight_b,
            "legacy_rating_changes": dict(record.legacy_rating_changes),
            "top_search_rating_changes": dict(record.top_search_rating_changes),
            "combination_rating_changes": dict(record.combination_rating_changes),
            "top_search_expected_a": float(record.top_search_expected_a),
            "both_bad": bool(record.both_bad),
        })
        if save_immediately:
            self.save()

    def get_artist_stats(
        self,
        elo_system: Optional[ELOSystem] = None,
        combination_elo: Optional[CombinationELOSystem] = None,
    ) -> dict:
        """
        Calculate ordinary and confidence-adjusted weighted artist win rates.

        If an artist appears on both sides of the same duel, that appearance is
        neutral: it contributes neither a win nor a loss and is excluded from
        the artist's duel count and every win-rate denominator.
        """
        stats: Dict[str, dict] = {}

        def ensure_artist(artist: str):
            if artist not in stats:
                stats[artist] = {
                    "rounds": 0, "wins": 0, "ties": 0,
                    "weighted_total": 0.0, "weighted_wins": 0.0,
                    "solo": {"rounds": 0, "wins": 0, "ties": 0, "weighted_total": 0.0, "weighted_wins": 0.0},
                    "duo": {"rounds": 0, "wins": 0, "ties": 0, "weighted_total": 0.0, "weighted_wins": 0.0},
                    "trio": {"rounds": 0, "wins": 0, "ties": 0, "weighted_total": 0.0, "weighted_wins": 0.0},
                }

        def opponent_weight(opponents: List[str]) -> float:
            if combination_elo is not None:
                rating = combination_elo.get_rating(opponents)
                comparisons = combination_elo.get_comparison_count(opponents)
            elif elo_system is not None and opponents:
                rating = sum(elo_system.get_rating(a) for a in opponents) / len(opponents)
                comparisons = int(sum(elo_system.get_artist_comparison_count(a) for a in opponents) / len(opponents))
            else:
                rating = DEFAULT_ELO
                comparisons = 0
            return weighted_result_weight(rating, comparisons)

        for record in self.records:
            artists_a = list(dict.fromkeys(record.get("artists_a", [])))
            artists_b = list(dict.fromkeys(record.get("artists_b", [])))
            winner = record.get("winner", "")
            if not artists_a or not artists_b or winner not in ("A", "B", "TIE"):
                continue

            # Case-insensitive overlap handling prevents a shared artist from
            # being counted once as a win and once as a loss.
            overlap_keys = {str(a).strip().casefold() for a in artists_a} & {
                str(b).strip().casefold() for b in artists_b
            }

            stored_weight_a = float(record.get("result_weight_a", 0.0) or 0.0)
            stored_weight_b = float(record.get("result_weight_b", 0.0) or 0.0)
            weight_a = stored_weight_a if stored_weight_a > 0 else opponent_weight(artists_b)
            weight_b = stored_weight_b if stored_weight_b > 0 else opponent_weight(artists_a)

            for side_artists, side_won, side_tied, weight in (
                (artists_a, winner == "A", winner == "TIE", weight_a),
                (artists_b, winner == "B", winner == "TIE", weight_b),
            ):
                size_key = ELOSystem.size_key(len(side_artists))
                for artist in side_artists:
                    if str(artist).strip().casefold() in overlap_keys:
                        continue
                    ensure_artist(artist)
                    artist_stats = stats[artist]
                    artist_stats["rounds"] += 1
                    artist_stats["weighted_total"] += weight
                    artist_stats[size_key]["rounds"] += 1
                    artist_stats[size_key]["weighted_total"] += weight
                    if side_tied:
                        artist_stats["ties"] += 1
                        artist_stats["weighted_wins"] += weight * 0.5
                        artist_stats[size_key]["ties"] += 1
                        artist_stats[size_key]["weighted_wins"] += weight * 0.5
                    elif side_won:
                        artist_stats["wins"] += 1
                        artist_stats["weighted_wins"] += weight
                        artist_stats[size_key]["wins"] += 1
                        artist_stats[size_key]["weighted_wins"] += weight

        for artist_stats in stats.values():
            adjusted, raw = confidence_adjusted_weighted_win_rate(
                artist_stats["weighted_wins"],
                artist_stats["weighted_total"],
                artist_stats["rounds"],
            )
            artist_stats["weighted_win_rate"] = adjusted
            artist_stats["raw_weighted_win_rate"] = raw
            for key in ELOSystem.SIZE_KEYS:
                category = artist_stats[key]
                adjusted, raw = confidence_adjusted_weighted_win_rate(
                    category["weighted_wins"],
                    category["weighted_total"],
                    category["rounds"],
                )
                category["weighted_win_rate"] = adjusted
                category["raw_weighted_win_rate"] = raw
        return stats

    def get_combination_stats(self, combination_elo: CombinationELOSystem) -> dict:
        """Calculate confidence-adjusted weighted win rate for exact combinations."""
        stats: Dict[str, dict] = {}
        for record in self.records:
            artists_a = list(record.get("artists_a", []))
            artists_b = list(record.get("artists_b", []))
            winner = record.get("winner", "")
            if not artists_a or not artists_b or winner not in ("A", "B", "TIE"):
                continue
            combo_a = combination_elo.combination_id(artists_a)
            combo_b = combination_elo.combination_id(artists_b)

            # The identical exact combination on both sides is neutral. This
            # mirrors CombinationELOSystem.update_ratings(), which also makes no
            # rating or comparison-count change for such a duel.
            if combo_a == combo_b:
                continue

            for side_label, combo_id, artists, opponents, won in (
                ("A", combo_a, artists_a, artists_b, winner == "A"),
                ("B", combo_b, artists_b, artists_a, winner == "B"),
            ):
                entry = stats.setdefault(combo_id, {
                    "artists": CombinationELOSystem.normalize_artists(artists),
                    "rounds": 0,
                    "wins": 0,
                    "ties": 0,
                    "weighted_total": 0.0,
                    "weighted_wins": 0.0,
                })
                stored_weight = float(
                    record.get("result_weight_a" if side_label == "A" else "result_weight_b", 0.0) or 0.0
                )
                weight = stored_weight if stored_weight > 0 else weighted_result_weight(
                    combination_elo.get_rating(opponents),
                    combination_elo.get_comparison_count(opponents),
                )
                entry["rounds"] += 1
                entry["weighted_total"] += weight
                if winner == "TIE":
                    entry["ties"] += 1
                    entry["weighted_wins"] += weight * 0.5
                elif won:
                    entry["wins"] += 1
                    entry["weighted_wins"] += weight

        for entry in stats.values():
            adjusted, raw = confidence_adjusted_weighted_win_rate(
                entry["weighted_wins"],
                entry["weighted_total"],
                entry["rounds"],
            )
            entry["weighted_win_rate"] = adjusted
            entry["raw_weighted_win_rate"] = raw
        return stats


