@dataclass
class ComparisonItem:
    """A generated duel ready for comparison and restart-safe persistence."""
    image_a_path: str
    image_b_path: str
    artists_a: List[str]
    artists_b: List[str]
    duel_id: str = ""
    seed: int = 0
    rotation_preset: Optional[str] = None
    prompt_a: str = ""
    prompt_b: str = ""
    negative_prompt: str = ""
    quality_toggle: bool = True
    uc_preset: int = 0
    generation_config: Dict[str, Any] = field(default_factory=dict)
    matchmaking_reason: str = "Historical / unknown"
    matchmaking_details: str = ""
    matchmaking_score: float = 0.0
    created_at: float = field(default_factory=time.time)

    def to_dict(self) -> dict:
        return {
            "image_a_path": self.image_a_path,
            "image_b_path": self.image_b_path,
            "artists_a": self.artists_a,
            "artists_b": self.artists_b,
            "duel_id": self.duel_id,
            "seed": self.seed,
            "rotation_preset": self.rotation_preset,
            "prompt_a": self.prompt_a,
            "prompt_b": self.prompt_b,
            "negative_prompt": self.negative_prompt,
            "quality_toggle": self.quality_toggle,
            "uc_preset": self.uc_preset,
            "generation_config": deepcopy(self.generation_config),
            "matchmaking_reason": self.matchmaking_reason,
            "matchmaking_details": self.matchmaking_details,
            "matchmaking_score": self.matchmaking_score,
            "created_at": self.created_at,
        }

    @classmethod
    def from_dict(cls, data: dict) -> Optional["ComparisonItem"]:
        try:
            item = cls(
                image_a_path=str(data.get("image_a_path", "")),
                image_b_path=str(data.get("image_b_path", "")),
                artists_a=list(data.get("artists_a", [])),
                artists_b=list(data.get("artists_b", [])),
                duel_id=str(data.get("duel_id", "") or ""),
                seed=int(data.get("seed", 0) or 0),
                rotation_preset=data.get("rotation_preset"),
                prompt_a=str(data.get("prompt_a", "") or ""),
                prompt_b=str(data.get("prompt_b", "") or ""),
                negative_prompt=str(data.get("negative_prompt", "") or ""),
                quality_toggle=bool(data.get("quality_toggle", True)),
                uc_preset=int(data.get("uc_preset", 0) or 0),
                generation_config=deepcopy(data.get("generation_config", {})) if isinstance(data.get("generation_config", {}), dict) else {},
                matchmaking_reason=str(data.get("matchmaking_reason", "Historical / unknown") or "Historical / unknown"),
                matchmaking_details=str(data.get("matchmaking_details", "") or ""),
                matchmaking_score=float(data.get("matchmaking_score", 0.0) or 0.0),
                created_at=float(data.get("created_at", time.time()) or time.time()),
            )
        except (TypeError, ValueError):
            return None
        if not item.artists_a or not item.artists_b:
            return None
        if not Path(item.image_a_path).exists() or not Path(item.image_b_path).exists():
            return None
        if not item.duel_id:
            payload = {
                "image_a_path": item.image_a_path,
                "image_b_path": item.image_b_path,
                "artists_a": item.artists_a,
                "artists_b": item.artists_b,
                "seed": item.seed,
            }
            item.duel_id = hashlib.sha1(
                json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
            ).hexdigest()[:20]
        return item


@dataclass
class UndoState:
    """State needed to undo the last comparison across all Phase 1 rating systems."""
    winners: List[str]
    losers: List[str]
    old_ratings: dict
    old_comparisons: dict
    old_size_state: dict
    old_combination_entries: dict
    old_top_search_state: dict
    old_pool_state: dict
    rotated_out: List[str]
    rotated_in: List[str]
    rotation_event_ids: List[str] = field(default_factory=list)
    selected_comparison: Optional[ComparisonItem] = None


def humanize_elapsed(seconds: Any) -> str:
    """Return a compact, stable elapsed-time label for UI tooltips."""
    try:
        value = max(0, int(float(seconds or 0)))
    except (TypeError, ValueError):
        value = 0
    if value < 60:
        return f"{value}s"
    minutes = value // 60
    if minutes < 60:
        return f"{minutes}m"
    hours = minutes // 60
    if hours < 48:
        return f"{hours}h"
    days = hours // 24
    if days < 60:
        return f"{days}d"
    months = days // 30
    if months < 24:
        return f"{months}mo"
    return f"{days // 365}y"


class ArtistELORanker:
    """Main application class."""

    def __init__(self):
        self.state_lock = threading.RLock()
        self.history = ComparisonHistory(COMPARISON_HISTORY_FILE)

        # Detect the previous competitive generation before *any* backfill or
        # persistence. Old data remains byte-stable until the mandatory backup
        # and explicit competitive reset succeed.
        top_file_version = 0
        if TOP_SEARCH_RATINGS_FILE.exists():
            try:
                raw_top = json.loads(TOP_SEARCH_RATINGS_FILE.read_text(encoding="utf-8"))
                top_file_version = int(raw_top.get("version", 0) or 0) if isinstance(raw_top, dict) else 0
            except Exception:
                top_file_version = 0
        self.legacy_competitive_guard = bool(self.history.records and top_file_version < MODEL_VERSION)
        self.legacy_guard_message = (
            "Legacy competitive data detected. Generation is paused until Storage → "
            "Reset competitive data creates a safety backup and starts the Bayesian ranking from zero."
            if self.legacy_competitive_guard else ""
        )

        if self.legacy_competitive_guard:
            self.elo_system = ELOSystem()
            self.combination_elo = CombinationELOSystem()
            self.top_search = TopSearchRatingSystem(refit_interval=500)
        else:
            self.elo_system = ELOSystem.load(ELO_RATINGS_FILE)
            if self.history.records and not self.elo_system.has_size_rating_data():
                print("Backfilling solo/duo/trio artist ratings from comparison history...")
                self.elo_system.rebuild_size_ratings_from_history(self.history.records)
                self.elo_system.save(ELO_RATINGS_FILE)

            self.combination_elo = CombinationELOSystem.load(COMBINATION_RATINGS_FILE)
            if self.history.records and not self.combination_elo.entries:
                print("Backfilling combination ratings from comparison history...")
                self.combination_elo.rebuild_from_history(self.history.records)
                self.combination_elo.save(COMBINATION_RATINGS_FILE)

            self.top_search = TopSearchRatingSystem.load(TOP_SEARCH_RATINGS_FILE)
            valid_top_history = sum(
                1 for record in self.history.records
                if TopSearchRatingSystem.record_has_effective_evidence(record)
            )
            if self.history.records and (
                self.top_search.version < MODEL_VERSION
                or self.top_search.comparison_count != valid_top_history
            ):
                print("Rebuilding Bayesian top-search ratings from current-generation history...")
                replayed = self.top_search.rebuild_from_history(self.history.records)
                self.top_search.save(TOP_SEARCH_RATINGS_FILE)
                print(f"Replayed {replayed:,} rated/tied duels into the Bayesian model.")

            if self.history.records:
                backfilled = self._backfill_history_rating_changes_if_needed()
                if backfilled:
                    print(f"Backfilled per-duel rating changes for {backfilled:,} historical duels.")

        # Convenience metadata is always loaded and is intentionally preserved
        # by the competitive reset.
        self.favorites = FavoritesStore(FAVORITES_FILE)
        self.classifications = ClassificationStore(CLASSIFICATION_TAGS_FILE)
        self.entity_notes = EntityNotesStore(ENTITY_NOTES_FILE)
        self.artist_portraits = ArtistPortraitStore(ARTIST_PORTRAITS_FILE, ARTIST_PORTRAITS_DIR)

        self.top50_tracking = (
            {"version": 3, "tracking_started_duel": 0, "entered_duel": {}, "current": [],
             "baseline_members": [], "last_updated_duel": 0}
            if self.legacy_competitive_guard else self._load_top50_tracking()
        )

        self.artist_manager = ArtistTagManager(ARTIST_TAGS_FILE)
        self._seed_new_list_artist_tags()
        self.artist_manager.initialize_pool(
            self.elo_system,
            self.top_search,
            self.classifications,
            suppress_persistence=self.legacy_competitive_guard,
        )
        if not self.legacy_competitive_guard:
            self._refresh_top50_tracking(initial=True)
            self.classifications.save()

        if self.legacy_competitive_guard:
            self.matchmaking_state = MatchmakingState()
        else:
            self.matchmaking_state = MatchmakingState.load(MATCHMAKING_STATE_FILE)
            if self.history.records and self.matchmaking_state.completed_duels == 0:
                self.matchmaking_state.bootstrap_from_history(self.history.records)
                self.matchmaking_state.save(MATCHMAKING_STATE_FILE)
        self.matchmaker = Matchmaker(
            self.artist_manager,
            self.elo_system,
            self.combination_elo,
            self.top_search,
            self.matchmaking_state,
        )
        self.session: Optional[ApiCredential] = None
        self.api_key_configured: bool = novelai_key_is_configured()

        # Phase 3 generation profiles. Existing saved prompts are migrated in-place
        # as Prompt-only profiles without changing their positive/negative text.
        self._saved_prompts_migrated = False
        self.saved_prompts: Dict[str, Dict[str, Any]] = self._load_saved_prompts()
        if self._saved_prompts_migrated:
            self._save_saved_prompts()

        # Phase 4 persistent storage settings.
        self.storage_settings = normalize_retention_settings(load_storage_settings())
        cleanup_every, cleanup_oldest = configure_gradio_cleanup(
            self.storage_settings.get("cleanup_every_images", GRADIO_CLEANUP_EVERY_IMAGES),
            self.storage_settings.get("cleanup_oldest_entries", GRADIO_CLEANUP_OLDEST_ENTRIES),
        )
        self.storage_settings["cleanup_every_images"] = cleanup_every
        self.storage_settings["cleanup_oldest_entries"] = cleanup_oldest
        matchmaking_mode = InformationDrivenScheduler.normalize_generation_mode(
            self.storage_settings.get("matchmaking_mode", MATCHMAKING_MODE_COVERAGE)
        )
        self.storage_settings["matchmaking_mode"] = matchmaking_mode
        self.storage_settings.setdefault("first_run_complete", False)
        self.storage_settings.setdefault("image_retention_policy", "keep_all")
        self.matchmaker.scheduler.set_generation_mode(matchmaking_mode)
        self.storage_settings["appearance_theme"] = normalize_theme_name(
            self.storage_settings.get("appearance_theme")
        )
        for key, fallback in NORMALIZED_CUSTOM_THEME_DEFAULTS.items():
            self.storage_settings[f"custom_theme_{key}"] = normalize_hex_color(
                self.storage_settings.get(f"custom_theme_{key}"), fallback
            )
        save_storage_settings(self.storage_settings)
        self.transfer_recovery = TransferRecoveryManager(PROGRAM_DIR, DATA_LAYOUT, SHAREABLE_EDITION_VERSION)
        self.generation_timing_stats = GenerationTimingStats(GENERATION_TIMING_STATS_FILE)

        # Current/queued comparison state
        self.current_comparison: Optional[ComparisonItem] = None
        self.comparison_queue: Deque[ComparisonItem] = deque()
        self.current_prompt: str = DEFAULT_PROMPT

        # Undo state
        self.last_undo_state: Optional[UndoState] = None

        # Recent auditable pool changes. Each dict includes direction, reason,
        # uncertainty scores, cutoff probability, and whether an entry is a retest.
        self.rotation_log: List[dict] = []

        # Rolling buffer / background refill state
        self.target_buffer_size = BUFFER_TARGET_SIZE
        self.refill_thread: Optional[threading.Thread] = None
        self.refill_in_progress: bool = False
        self.bayesian_refit_thread: Optional[threading.Thread] = None
        self.bayesian_refit_generation: int = 0
        # Transient by design: a reboot always resumes generation. When toggled
        # while a duel is generating, image A and image B finish as one atomic duel,
        # then the refill worker exits before starting another pair.
        self.generation_paused: bool = bool(self.legacy_competitive_guard)
        self.buffer_generation_token: int = 0
        self.last_generation_error: str = ""

        # Current generation settings for future buffer refills
        self.generation_settings = normalize_generation_settings(
            {
                **DEFAULT_GENERATION_PROFILE_SETTINGS,
                "base_prompt": self._normalize_base_prompt(DEFAULT_PROMPT),
                "negative_prompt": None,
            },
            DEFAULT_GENERATION_PROFILE_SETTINGS,
        )
        self.generation_settings["base_prompt"] = self._normalize_base_prompt(DEFAULT_PROMPT)
        self.generation_settings["negative_prompt"] = None

        # UI text state so polling doesn't clear messages
        self.ui_result_msg: str = ""
        self.ui_details_msg: str = ""

        # Phase 3 browser indexes are expensive to build from the complete history.
        # Cache them and only rebuild after the number of rated comparisons changes.
        self.browser_cache_lock = threading.RLock()
        self.browser_cache_stamp: Optional[Tuple[int, int, int, int, int]] = None
        self.artist_browser_records_cache: List[dict] = []
        self.combination_browser_records_cache: List[dict] = []

        # Phase 4 lazy indexes and short-lived disk-usage caches.
        self.gallery_cache_lock = threading.RLock()
        self.gallery_cache_condition = threading.Condition(self.gallery_cache_lock)
        self.gallery_cache_stamp: Optional[Tuple[int, int]] = None
        self.gallery_cache_building_stamp: Optional[Tuple[int, int]] = None
        self.gallery_records_cache: List[dict] = []
        self.storage_cache_lock = threading.RLock()
        self.storage_cache_time: float = 0.0
        self.storage_cache_markdown: str = ""
        self.last_orphan_scan: List[str] = []
        self.last_retention_plan: Optional[RetentionPlan] = None
        self.retention_cleanup_lock = threading.Lock()
        self.retention_worker_stop = threading.Event()
        self.retention_manager = RetentionManager(
            RETENTION_QUARANTINE_DIR, RETENTION_STATE_FILE
        )

        # Ensure output directory exists, then restore any ready duels from disk.
        COMPARISON_IMAGES_DIR.mkdir(parents=True, exist_ok=True)
        THUMBNAIL_DIR.mkdir(parents=True, exist_ok=True)
        if not self.legacy_competitive_guard:
            self._load_buffer_state()

        # Existing buffered duels are registered only for the current Bayesian generation.
        # Register them once so the refill worker does not immediately create duplicates.
        buffered_items = ([self.current_comparison] if self.current_comparison else []) + list(self.comparison_queue)
        if not self.legacy_competitive_guard:
            for item in buffered_items:
                matchup_key = self.matchmaking_state.matchup_key(item.artists_a, item.artists_b)
                if matchup_key not in self.matchmaking_state.recent_matchups:
                    self.matchmaking_state.record_matchup(
                        item.artists_a,
                        item.artists_b,
                        item.matchmaking_reason or "Restored buffer",
                    )
            self.matchmaking_state.save(MATCHMAKING_STATE_FILE)

        # Lightweight application-health state for the save/error indicators.
        self.last_error_details: str = ""
        self.last_persistence_requested_at: float = 0.0
        self.last_persistence_started_at: float = 0.0
        self.last_persistence_completed_at: float = time.time()
        self.last_persistence_error: str = ""

        # Coalesce vote-time disk writes in a background worker. Ratings/history
        # are updated in memory immediately, while JSON persistence happens shortly
        # afterward so the next buffered duel can be displayed without waiting for
        # several full-file rewrites. A final synchronous flush is registered for exit.
        # Scheduling and actual filesystem I/O use separate locks. The scheduler
        # lock is held only for tiny set updates; slow JSON writes never block a vote.
        self.persistence_write_lock = threading.Lock()
        self.persistence_io_lock = threading.Lock()
        self.persistence_event = threading.Event()
        self.persistence_shutdown = threading.Event()
        self.pending_backup_counts: Set[int] = set()
        self.pending_persistence_sections: Set[str] = set()
        self.persistence_thread = threading.Thread(
            target=self._persistence_worker_loop,
            daemon=True,
            name="artist-elo-persistence-worker",
        )
        self.persistence_thread.start()
        self.retention_thread = threading.Thread(
            target=self._retention_worker_loop,
            daemon=True,
            name="artist-elo-retention-worker",
        )
        self.retention_thread.start()
        atexit.register(self._stop_retention_worker)
        atexit.register(self._flush_persistence_on_exit)

    # -------------------------------------------------------------------------
    # Helpers / state management
    # -------------------------------------------------------------------------

    def _load_top50_tracking(self) -> dict:
        """Load current Top-50 streaks measured in completed system duels.

        Version 3 replaces wall-clock timestamps with the global history index. Older
        timestamp files cannot be converted accurately, so current members begin an
        explicitly approximate baseline at the duel count present during migration.
        """
        total_duels = len(self.history.records)
        if TOP50_ENTRY_FILE.exists():
            try:
                with open(TOP50_ENTRY_FILE, "r", encoding="utf-8") as handle:
                    raw = json.load(handle)
                if isinstance(raw, dict) and int(raw.get("version", 0) or 0) >= 3:
                    raw.setdefault("entered_duel", {})
                    raw.setdefault("current", [])
                    raw.setdefault("tracking_started_duel", total_duels)
                    raw.setdefault("baseline_members", [])
                    raw.setdefault("last_updated_duel", total_duels)
                    return raw
                if isinstance(raw, dict):
                    current = [str(value) for value in raw.get("current", [])]
                    return {
                        "version": 3,
                        "tracking_started_duel": total_duels,
                        "entered_duel": {artist: total_duels for artist in current},
                        "current": current,
                        "baseline_members": current,
                        "last_updated_duel": total_duels,
                        "migrated_from_time_tracking": True,
                    }
            except Exception as exc:
                print(f"Warning: Could not load Top-50 entry tracking: {exc}")
        return {
            "version": 3,
            "tracking_started_duel": total_duels,
            "entered_duel": {},
            "current": [],
            "baseline_members": [],
            "last_updated_duel": total_duels,
        }

    def _refresh_top50_tracking(self, initial: bool = False) -> None:
        """Track the current Top-50 streak using completed system-duel numbers."""
        total_duels = len(self.history.records)
        current = [str(value) for value in self.top_search.fast_rank_summary()["conservative_top50_min1"]]
        current_set = set(current)
        previous = {str(value) for value in self.top50_tracking.get("current", [])}
        entered = {
            str(key): max(0, int(value or 0))
            for key, value in dict(self.top50_tracking.get("entered_duel", {}) or {}).items()
        }
        baseline_members = {str(value) for value in self.top50_tracking.get("baseline_members", [])}
        first_baseline = bool(initial and not previous)

        if first_baseline:
            baseline_members = set(current)
            entered = {artist: total_duels for artist in current}
        else:
            for artist in current:
                if artist not in previous or artist not in entered:
                    entered[artist] = total_duels
                    baseline_members.discard(artist)
            for artist in list(entered):
                if artist not in current_set:
                    entered.pop(artist, None)
                    baseline_members.discard(artist)

        self.top50_tracking.update({
            "version": 3,
            "current": current,
            "entered_duel": entered,
            "baseline_members": sorted(baseline_members),
            "last_updated_duel": total_duels,
        })
        if first_baseline:
            self.top50_tracking["tracking_started_duel"] = total_duels
        if initial:
            try:
                atomic_write_json(TOP50_ENTRY_FILE, self.top50_tracking)
            except Exception as exc:
                print(f"Warning: Could not initialize Top-50 duel tracking: {exc}")

    def _top50_entry_info(self, artist: str) -> Tuple[int, str, bool]:
        entered_duel = int(
            dict(self.top50_tracking.get("entered_duel", {}) or {}).get(str(artist), 0) or 0
        )
        if entered_duel < 0 or str(artist) not in {
            str(value) for value in self.top50_tracking.get("current", [])
        }:
            return 0, "", False
        total_duels = len(self.history.records)
        streak_duels = max(0, total_duels - entered_duel)
        approximate = str(artist) in {
            str(value) for value in self.top50_tracking.get("baseline_members", [])
        }
        share = (streak_duels / total_duels * 100.0) if total_duels else 0.0
        label = f"{streak_duels:,} of {total_duels:,} system duels ({share:.1f}%)"
        return entered_duel, label, approximate

    def format_save_status(self) -> str:
        """Return a tiny persistence-health indicator without touching disk."""
        with self.persistence_write_lock:
            pending = bool(self.pending_persistence_sections or self.pending_backup_counts)
        if self.last_persistence_error:
            return (
                '<span class="save-state error" title="'
                + html.escape(self.last_persistence_error, quote=True)
                + '">Save delayed ⚠</span>'
            )
        if pending or self.last_persistence_started_at > self.last_persistence_completed_at:
            return '<span class="save-state pending">Saving…</span>'
        age = humanize_elapsed(time.time() - self.last_persistence_completed_at)
        return f'<span class="save-state saved" title="Last completed save {age} ago">Saved ✓</span>'

    def get_last_error_details(self) -> str:
        return str(self.last_error_details or self.last_persistence_error or self.last_generation_error or "No error has been recorded in this session.")

    def _buffer_match_bucket(self, item: ComparisonItem) -> str:
        reason = str(getattr(item, "matchmaking_reason", "") or "").casefold()
        if "fresh discovery" in reason:
            return "Discovery"
        if any(word in reason for word in ("opening", "recovery", "screening", "qualification", "upside", "stale")):
            return "Follow-up"
        if "boundary" in reason:
            return "Boundary"
        if "elite" in reason:
            return "Verification"
        return "Exploration"

    def format_buffer_health(self) -> str:
        """Describe live buffer composition and repetition without changing matchmaking."""
        with self.state_lock:
            items = ([self.current_comparison] if self.current_comparison else []) + list(self.comparison_queue)
        counts = {name: 0 for name in ("Discovery", "Follow-up", "Boundary", "Verification", "Exploration")}
        artist_counts: Dict[str, int] = {}
        matchup_counts: Dict[str, int] = {}
        for item in items:
            counts[self._buffer_match_bucket(item)] += 1
            for artist in set(list(item.artists_a) + list(item.artists_b)):
                artist_counts[str(artist)] = artist_counts.get(str(artist), 0) + 1
            key = self.matchmaking_state.matchup_key(item.artists_a, item.artists_b)
            matchup_counts[key] = matchup_counts.get(key, 0) + 1
        repeated_artists = sum(1 for value in artist_counts.values() if value > 1)
        repeated_matchups = sum(value - 1 for value in matchup_counts.values() if value > 1)
        diversity = "Good" if repeated_matchups == 0 and repeated_artists <= max(2, len(items) // 10) else "Review"
        chips = "".join(
            f'<span class="buffer-health-chip"><b>{name}</b> {counts[name]}</span>'
            for name in ("Discovery", "Follow-up", "Boundary", "Verification", "Exploration")
        )
        return (
            '<div class="buffer-health-line">'
            f'<span><b>Ready:</b> {len(items)}/{int(self.target_buffer_size)}</span>{chips}'
            f'<span title="Exact pairings repeated inside the ready buffer"><b>Exact repeats:</b> {repeated_matchups}</span>'
            f'<span title="Artists appearing in more than one ready duel"><b>Repeated artists:</b> {repeated_artists}</span>'
            f'<span class="buffer-diversity {diversity.casefold()}"><b>Diversity:</b> {diversity}</span>'
            '</div>'
        )

    def get_artist_filter_count(self, search_text: str, minimum_duels: Any, maximum_duels: Any, minimum_score: Any, maximum_score: Any) -> str:
        """Count matching cached Artist records without rendering thousands of rows."""
        self._ensure_browser_records_cache()
        query = str(search_text or "").strip().casefold()
        def optional_number(value: Any, integer: bool = False):
            raw = str(value or "").strip()
            if not raw:
                return None
            try:
                parsed = float(raw)
                return int(parsed) if integer else parsed
            except (TypeError, ValueError):
                return None
        min_duels = max(0, optional_number(minimum_duels, True) or 0)
        max_duels = optional_number(maximum_duels, True)
        min_score = optional_number(minimum_score)
        max_score = optional_number(maximum_score)
        with self.browser_cache_lock:
            count = sum(
                1 for record in self.artist_browser_records_cache
                if (not query or _boolean_search_matches(query, record.get("search_blob", record)))
                and int(record.get("duels", 0)) >= min_duels
                and (max_duels is None or int(record.get("duels", 0)) <= max_duels)
                and (min_score is None or float(record.get("top_score", 0.0)) >= min_score)
                and (max_score is None or float(record.get("top_score", 0.0)) <= max_score)
            )
        return f"**{count:,} artists match these filters.**"

    def create_manual_backup(self) -> Tuple[str, Optional[str]]:
        """Create an immediate complete backup independent of the automatic cadence."""
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        path = BACKUP_DIR / f"artist_elo_manual_backup_{timestamp}.zip"
        try:
            if not self.legacy_competitive_guard:
                with self.persistence_write_lock:
                    self.pending_persistence_sections.update({
                        "ratings", "history", "buffer", "matchmaking",
                        "pool", "classifications", "top50",
                    })
                self._persist_runtime_state_now()
            candidates = [
                ELO_RATINGS_FILE, COMBINATION_RATINGS_FILE, TOP_SEARCH_RATINGS_FILE,
                COMPARISON_HISTORY_FILE, ACTIVE_POOL_FILE, BUFFER_STATE_FILE,
                MATCHMAKING_STATE_FILE, FAVORITES_FILE, CLASSIFICATION_TAGS_FILE,
                ENTITY_NOTES_FILE, ARTIST_PORTRAITS_FILE, SAVED_PROMPTS_FILE,
                STORAGE_SETTINGS_FILE, TOP50_ENTRY_FILE,
            ]
            with zipfile.ZipFile(path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("backup_manifest.json", json.dumps({
                    "created_at": time.time(), "manual": True,
                    "comparison_count": int(self.elo_system.comparison_count),
                }, indent=2))
                for candidate in candidates:
                    if Path(candidate).exists():
                        archive.write(candidate, arcname=Path(candidate).name)
            return f"Created manual backup: `{path.name}`", str(path)
        except Exception as exc:
            self.last_error_details = f"Manual backup failed: {type(exc).__name__}: {exc}"
            return f"❌ Manual backup failed: {exc}", None

    @staticmethod
    def _sha256_file(path: Path) -> str:
        digest = hashlib.sha256()
        with Path(path).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    def _archive_favorite_duel_images(self) -> Tuple[str, int, int]:
        """Copy, deduplicate, verify, and relink every image/duel favorite."""
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        archive_root = FAVORITE_DUEL_ARCHIVE_DIR / timestamp
        image_root = archive_root / "images"
        image_root.mkdir(parents=True, exist_ok=False)

        references: List[dict] = []
        with self.favorites.lock:
            for key, entry in self.favorites.data.get("image", {}).items():
                metadata = entry.get("metadata", {}) if isinstance(entry, dict) else {}
                source = str(metadata.get("path", "") or key)
                if source:
                    references.append({"kind": "image", "key": str(key), "field": "path", "source": source})
            for key, entry in self.favorites.data.get("duel", {}).items():
                metadata = entry.get("metadata", {}) if isinstance(entry, dict) else {}
                for field_name in ("image_a_path", "image_b_path"):
                    source = str(metadata.get(field_name, "") or "")
                    if source:
                        references.append({"kind": "duel", "key": str(key), "field": field_name, "source": source})

        hash_targets: Dict[str, Path] = {}
        manifest_rows: List[dict] = []
        try:
            for reference in references:
                source = Path(reference["source"])
                if not source.exists() or not source.is_file():
                    raise FileNotFoundError(f"Favorite {reference['kind']} image is missing: {source}")
                source_hash = self._sha256_file(source)
                target = hash_targets.get(source_hash)
                if target is None:
                    suffix = source.suffix.lower() if source.suffix else ".png"
                    target = image_root / f"{source_hash}{suffix}"
                    shutil.copy2(source, target)
                    if target.stat().st_size != source.stat().st_size:
                        raise IOError(f"Favorite archive size verification failed: {source}")
                    if self._sha256_file(target) != source_hash:
                        raise IOError(f"Favorite archive hash verification failed: {source}")
                    hash_targets[source_hash] = target
                row = {
                    **reference,
                    "source": str(source),
                    "archived_path": str(target),
                    "sha256": source_hash,
                    "size_bytes": int(source.stat().st_size),
                }
                manifest_rows.append(row)

            manifest = {
                "version": 1,
                "created_at": time.time(),
                "archive_root": str(archive_root),
                "unique_files": len(hash_targets),
                "favorite_references": len(manifest_rows),
                "entries": manifest_rows,
            }
            atomic_write_json(archive_root / "manifest.json", manifest)
            with (archive_root / "manifest.csv").open("w", encoding="utf-8-sig", newline="") as handle:
                fields = ["kind", "key", "field", "source", "archived_path", "sha256", "size_bytes"]
                writer = csv.DictWriter(handle, fieldnames=fields)
                writer.writeheader()
                writer.writerows(manifest_rows)

            # Relink only after every file and manifest has been verified.
            with self.favorites.lock:
                for row in manifest_rows:
                    entry = self.favorites.data[row["kind"]].get(row["key"])
                    if not isinstance(entry, dict):
                        continue
                    metadata = entry.setdefault("metadata", {})
                    metadata[row["field"]] = row["archived_path"]
                    metadata.setdefault("pre_reset_original_paths", {})[row["field"]] = row["source"]
                    metadata["favorite_archive_manifest"] = str(archive_root / "manifest.json")
                    entry["updated_at"] = time.time()
                self.favorites.version += 1
                atomic_write_json(self.favorites.filepath, self.favorites.data)
            return str(archive_root), len(hash_targets), len(manifest_rows)
        except Exception:
            shutil.rmtree(archive_root, ignore_errors=True)
            raise

    def reset_competitive_data(self, confirmation: str, delete_generated_images: bool) -> Tuple[str, Optional[str]]:
        """Backup first, then reset only ranking/matchmaking data from zero."""
        if str(confirmation or "").strip() != "RESET":
            return "Type **RESET** exactly before using the destructive reset.", None

        was_paused = bool(self.generation_paused)
        self.generation_paused = True
        self.buffer_generation_token += 1
        self.bayesian_refit_generation += 1
        backup_message, backup_path = self.create_manual_backup()
        if not backup_path or not Path(backup_path).exists():
            self.generation_paused = was_paused
            return f"❌ Reset aborted because the mandatory backup failed. {backup_message}", None

        archive_note = "Favorite image archive was not requested."
        try:
            if bool(delete_generated_images):
                archive_root, unique_count, reference_count = self._archive_favorite_duel_images()
                archive_note = (
                    f"Archived and verified {unique_count:,} unique favorite image file(s) "
                    f"covering {reference_count:,} favorite reference(s) in `{archive_root}`."
                )

            with self.state_lock:
                self.current_comparison = None
                self.comparison_queue.clear()
                self.last_undo_state = None
                self.rotation_log.clear()

                self.elo_system = ELOSystem()
                self.combination_elo = CombinationELOSystem()
                self.top_search = TopSearchRatingSystem(refit_interval=500)
                self.history.records = []
                self.matchmaking_state = MatchmakingState()

                # Keep manual categories, erase only retired competitive rotation audit data.
                with self.classifications.lock:
                    self.classifications.rotated_out_counts.clear()
                    self.classifications.rotation_reason_counts.clear()
                    self.classifications.rotation_events.clear()
                    self.classifications.version += 1

                self.top50_tracking = {
                    "version": 3,
                    "tracking_started_duel": 0,
                    "entered_duel": {},
                    "current": [],
                    "baseline_members": [],
                    "last_updated_duel": 0,
                }

                self.artist_manager.elo_system = self.elo_system
                self.artist_manager.active_pool = ActivePool(
                    self.artist_manager.artists,
                    self.elo_system,
                    self.top_search,
                    self.classifications,
                    suppress_persistence=False,
                )
                self.matchmaker = Matchmaker(
                    self.artist_manager,
                    self.elo_system,
                    self.combination_elo,
                    self.top_search,
                    self.matchmaking_state,
                )
                self.matchmaker.scheduler.set_generation_mode(
                    self.storage_settings.get(
                        "matchmaking_mode", MATCHMAKING_MODE_COVERAGE
                    )
                )

                self.legacy_competitive_guard = False
                self.legacy_guard_message = ""
                self.generation_paused = False
                self.last_generation_error = ""
                self.ui_result_msg = "Competitive data reset successfully. Bayesian ranking begins from zero."
                self.ui_details_msg = archive_note

                self.elo_system.save(ELO_RATINGS_FILE)
                self.combination_elo.save(COMBINATION_RATINGS_FILE)
                self.top_search.save(TOP_SEARCH_RATINGS_FILE)
                self.history.save()
                self.matchmaking_state.save(MATCHMAKING_STATE_FILE)
                self.artist_manager.active_pool.save()
                self.classifications.save()
                atomic_write_json(TOP50_ENTRY_FILE, self.top50_tracking)
                self._save_buffer_state()

            if bool(delete_generated_images):
                # The archive lives outside this directory. Delete only after all
                # favorite relinks have been persisted and verified.
                if COMPARISON_IMAGES_DIR.exists():
                    shutil.rmtree(COMPARISON_IMAGES_DIR)
                COMPARISON_IMAGES_DIR.mkdir(parents=True, exist_ok=True)
                THUMBNAIL_DIR.mkdir(parents=True, exist_ok=True)

            with self.browser_cache_lock:
                self.browser_cache_stamp = None
                self.artist_browser_records_cache = []
                self.combination_browser_records_cache = []
            with self.gallery_cache_lock:
                self.gallery_cache_stamp = None
                self.gallery_records_cache = []
            with self.storage_cache_lock:
                self.storage_cache_time = 0.0
            self.start_refill_if_needed()
            return (
                "✅ Competitive state reset from zero. " + archive_note +
                f" Mandatory backup: `{Path(backup_path).name}`.",
                backup_path,
            )
        except Exception as exc:
            self.last_error_details = f"Competitive reset failed: {type(exc).__name__}: {exc}"
            self.generation_paused = True
            return (
                "❌ Reset aborted before competitive deletion completed. "
                f"The safety backup remains available. Error: {exc}",
                backup_path,
            )

    def handle_path_action(self, payload_text: str) -> str:
        """Open/copy local Gallery image paths through the trusted Python backend."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}
        path = Path(str(payload.get("path", "") or "")) if isinstance(payload, dict) else Path()
        action = str(payload.get("action", "") or "").casefold() if isinstance(payload, dict) else ""
        if not path or not path.exists():
            return "❌ That image file is no longer available."
        try:
            if action == "open_file":
                if hasattr(os, "startfile"):
                    os.startfile(str(path))
                else:
                    import subprocess
                    subprocess.Popen(["xdg-open", str(path)])
                return f"Opened `{path.name}`."
            if action == "open_folder":
                if os.name == "nt":
                    import subprocess
                    subprocess.Popen(["explorer", "/select,", str(path)])
                else:
                    import subprocess
                    subprocess.Popen(["xdg-open", str(path.parent)])
                return f"Opened folder for `{path.name}`."
            return str(path)
        except Exception as exc:
            self.last_error_details = f"Path action failed: {type(exc).__name__}: {exc}"
            return f"❌ Could not open the path: {exc}"

    def handle_bulk_artist_action(self, payload_text: str) -> str:
        """Apply one explicit bulk action to checked Artist-table rows."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}
        if not isinstance(payload, dict):
            return "❌ Invalid bulk action."
        artists = [str(value).strip() for value in payload.get("artists", []) if str(value).strip()]
        artists = list(dict.fromkeys(artist for artist in artists if artist in set(self.artist_manager.artists)))
        action = str(payload.get("action", "") or "").casefold()
        if not artists:
            return "Select at least one artist first."
        if action == "favorite":
            for artist in artists:
                self.favorites.set("artist", artist, artist, [], "", {"artist": artist})
            self._invalidate_favorite_dependent_caches()
            return f"★ Favorited {len(artists)} artist(s)."
        if action == "style":
            tag = str(payload.get("tag", "") or "").casefold()
            if tag not in MANUAL_STYLE_TAGS:
                return "Choose a valid manual tag."
            for artist in artists:
                current = set(self.classifications.get_manual_tags("artist", artist))
                current.add(tag)
                self.classifications.set_manual_tags("artist", artist, sorted(current))
            self.classifications.save()
            with self.browser_cache_lock:
                self.browser_cache_stamp = None
            return f"🏷 Applied {MANUAL_STYLE_TAGS[tag]['label']} to {len(artists)} artist(s)."
        return "❌ Unsupported bulk action."

    def _seed_new_list_artist_tags(self) -> None:
        """Seed the removable New List tag for the imported Top-2,000 artists."""
        if not NEW_LIST_ARTISTS_FILE.exists():
            print(
                f"New List tag seed skipped: {NEW_LIST_ARTISTS_FILE.name} was not found."
            )
            return
        try:
            requested = [
                line.strip()
                for line in NEW_LIST_ARTISTS_FILE.read_text(
                    encoding="utf-8", errors="replace"
                ).splitlines()
                if line.strip()
            ]
        except Exception as exc:
            print(f"Warning: Could not read New List artist file: {exc}")
            return
        catalog = set(self.artist_manager.artists)
        matched = [artist for artist in requested if artist in catalog]
        missing = len(requested) - len(matched)
        result = self.classifications.seed_manual_tag_once(
            "artist", matched, "new_list", "top2000-average-score-min50-v1"
        )
        print(
            "New List tag seed: "
            f"{result['added']:,} newly tagged, "
            f"{result['already_seeded']:,} previously processed, "
            f"{missing:,} not present in the active artist catalog."
        )

    def _schedule_persistence(
        self,
        backup_count: Optional[int] = None,
        sections: Optional[Set[str]] = None,
    ):
        """Schedule coalesced persistence without blocking the active UI callback."""
        requested = set(sections or {"ratings", "history", "buffer", "matchmaking", "pool", "classifications", "top50"})
        self.last_persistence_requested_at = time.time()
        with self.persistence_write_lock:
            self.pending_persistence_sections.update(requested)
            if backup_count and backup_count > 0 and backup_count % BACKUP_EVERY_COMPARISONS == 0:
                self.pending_backup_counts.add(int(backup_count))
        self.persistence_event.set()

    def _persistence_worker_loop(self):
        """Persist the newest in-memory state after a short debounce window."""
        while not self.persistence_shutdown.is_set():
            if not self.persistence_event.wait(timeout=1.0):
                continue
            if self.persistence_shutdown.is_set():
                break
            time.sleep(0.35)
            self.persistence_event.clear()
            try:
                self._persist_runtime_state_now()
            except Exception as exc:
                self.last_persistence_error = f"{type(exc).__name__}: {exc}"
                self.last_error_details = self.last_persistence_error
                print(f"Warning: Persistence worker failed: {exc}")

    def _persist_runtime_state_now(self):
        """Snapshot state briefly, then serialize and write without blocking votes."""
        # Only one persistence pass may write files at a time. Importantly, this
        # lock is never touched by _schedule_persistence(), so a vote cannot wait
        # behind a long history/buffer JSON write.
        self.last_persistence_started_at = time.time()
        with self.persistence_io_lock:
            with self.persistence_write_lock:
                sections = set(self.pending_persistence_sections)
                self.pending_persistence_sections.clear()
                backup_counts = sorted(self.pending_backup_counts)
                self.pending_backup_counts.clear()

                # Exit flushes always persist everything, even if only one section was dirty.
                if self.persistence_shutdown.is_set():
                    sections.update({"ratings", "history", "buffer", "matchmaking", "pool", "classifications", "top50"})

            # Take only shallow/primitive snapshots while holding the ranking lock.
            # Historical record dictionaries are append-only after creation, so a
            # shallow list copy is sufficient and avoids a costly deepcopy of the
            # complete history while a user is trying to vote.
            with self.state_lock:
                snapshots: Dict[str, Any] = {}
                if "ratings" in sections:
                    snapshots["elo"] = {
                        "ratings": dict(self.elo_system.ratings),
                        "comparison_count": int(self.elo_system.comparison_count),
                        "artist_comparisons": dict(self.elo_system.artist_comparisons),
                        "ratings_by_size": {
                            size: dict(values)
                            for size, values in self.elo_system.ratings_by_size.items()
                        },
                        "artist_comparisons_by_size": {
                            size: dict(values)
                            for size, values in self.elo_system.artist_comparisons_by_size.items()
                        },
                    }
                    snapshots["combinations"] = {
                        "entries": {
                            key: dict(value)
                            for key, value in self.combination_elo.entries.items()
                        }
                    }
                    snapshots["top_search"] = self.top_search.snapshot()
                if "history" in sections:
                    snapshots["history"] = list(self.history.records)
                if "buffer" in sections:
                    snapshots["buffer"] = {
                        "version": 1,
                        "target_buffer_size": int(self.target_buffer_size),
                        "current_prompt": self.current_prompt,
                        "generation_settings": dict(self.generation_settings),
                        "current_comparison": self.current_comparison.to_dict() if self.current_comparison else None,
                        "queue": [item.to_dict() for item in self.comparison_queue],
                    }
                if "matchmaking" in sections:
                    snapshots["matchmaking"] = {
                        "recent_matchups": list(self.matchmaking_state.recent_matchups[-RECENT_MATCHUP_MEMORY:]),
                        "recent_combinations": list(self.matchmaking_state.recent_combinations[-RECENT_COMBINATION_MEMORY:]),
                        "recent_artists": list(self.matchmaking_state.recent_artists[-RECENT_ARTIST_MEMORY:]),
                        "reason_counts": dict(self.matchmaking_state.reason_counts),
                    }
                if "pool" in sections and self.artist_manager.active_pool is not None:
                    snapshots["pool"] = {
                        "pool": list(self.artist_manager.active_pool.pool),
                        "elite_reservoir": list(self.artist_manager.active_pool.elite_reservoir),
                        "target_pool_size": int(self.artist_manager.active_pool.pool_size),
                        "result_sequence": int(self.artist_manager.active_pool.result_sequence),
                        "fresh_followup_deadlines": dict(
                            self.artist_manager.active_pool.fresh_followup_deadlines
                        ),
                        "model": "top_search_v2",
                    }
                if "classifications" in sections:
                    snapshots["classifications"] = self.classifications.snapshot()
                if "top50" in sections:
                    snapshots["top50"] = deepcopy(self.top50_tracking)

            # No state_lock or scheduling lock is held during hashing, JSON
            # serialization, filesystem replacement, or backup ZIP creation.
            if "elo" in snapshots:
                atomic_write_json(ELO_RATINGS_FILE, snapshots["elo"])
                atomic_write_json(COMBINATION_RATINGS_FILE, snapshots["combinations"])
                atomic_write_json(TOP_SEARCH_RATINGS_FILE, snapshots["top_search"])
            if "history" in snapshots:
                atomic_write_json(COMPARISON_HISTORY_FILE, snapshots["history"])
            if "buffer" in snapshots:
                atomic_write_json(BUFFER_STATE_FILE, snapshots["buffer"])
            if "matchmaking" in snapshots:
                atomic_write_json(MATCHMAKING_STATE_FILE, snapshots["matchmaking"])
            if "pool" in snapshots:
                atomic_write_json(ACTIVE_POOL_FILE, snapshots["pool"])
            if "classifications" in snapshots:
                atomic_write_json(CLASSIFICATION_TAGS_FILE, snapshots["classifications"])
            if "top50" in snapshots:
                atomic_write_json(TOP50_ENTRY_FILE, snapshots["top50"])

        self.last_persistence_completed_at = time.time()
        self.last_persistence_error = ""
        for backup_count in backup_counts:
            self._create_backup_if_due(backup_count)

    def _flush_persistence_on_exit(self):
        """Best-effort synchronous final save when Python exits."""
        try:
            self.persistence_shutdown.set()
            self.persistence_event.set()
            self._persist_runtime_state_now()
        except Exception as exc:
            print(f"Warning: final persistence flush failed: {exc}")

    def _save_buffer_state_locked(self):
        """Atomically persist current and queued duels plus generation settings."""
        data = {
            "version": 1,
            "target_buffer_size": self.target_buffer_size,
            "current_prompt": self.current_prompt,
            "generation_settings": self.generation_settings,
            "current_comparison": self.current_comparison.to_dict() if self.current_comparison else None,
            "queue": [item.to_dict() for item in self.comparison_queue],
        }
        BUFFER_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
        temp_path = BUFFER_STATE_FILE.with_suffix(BUFFER_STATE_FILE.suffix + ".tmp")
        with open(temp_path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        temp_path.replace(BUFFER_STATE_FILE)

    def _save_buffer_state(self):
        with self.state_lock:
            self._save_buffer_state_locked()

    def _load_buffer_state(self):
        """Restore only duels whose two image files still exist."""
        if not BUFFER_STATE_FILE.exists():
            return
        try:
            with open(BUFFER_STATE_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            restored_current = ComparisonItem.from_dict(data.get("current_comparison") or {})
            restored_queue = []
            for raw in data.get("queue", []):
                item = ComparisonItem.from_dict(raw)
                if item is not None:
                    restored_queue.append(item)

            settings = data.get("generation_settings")
            if isinstance(settings, dict):
                merged = dict(self.generation_settings)
                merged.update(settings)
                merged = normalize_generation_settings(merged, DEFAULT_GENERATION_PROFILE_SETTINGS)
                merged["base_prompt"] = self._normalize_base_prompt(
                    merged.get("positive_prompt_text", "")
                )
                negative_text = str(merged.get("negative_prompt_text", "") or "")
                merged["negative_prompt"] = negative_text if negative_text.strip() else None
                merged["rotation_names"] = [
                    name for name in merged.get("rotation_names", []) if name in self.saved_prompts
                ]
                self.generation_settings = merged
            self.current_prompt = str(data.get("current_prompt", self.current_prompt) or self.current_prompt)
            try:
                restored_target = int(data.get("target_buffer_size", self.target_buffer_size))
            except (TypeError, ValueError):
                restored_target = self.target_buffer_size
            self.target_buffer_size = max(MIN_BUFFER_SIZE, min(MAX_BUFFER_SIZE, restored_target))

            self.current_comparison = restored_current
            self.comparison_queue = deque(restored_queue)
            if self.current_comparison is None and self.comparison_queue:
                self.current_comparison = self.comparison_queue.popleft()
            while self._buffered_count_locked() > self.target_buffer_size and self.comparison_queue:
                self.comparison_queue.pop()
            self._save_buffer_state_locked()
            if self.current_comparison or self.comparison_queue:
                print(f"Restored {self._buffered_count_locked()} buffered duel(s) from disk.")
        except Exception as e:
            print(f"Warning: Could not restore buffered duels: {e}")

    def _create_backup_if_due(self, count_override: Optional[int] = None):
        """Create a ZIP backup every configured number of rated duels and keep the newest N."""
        count = int(count_override if count_override is not None else self.elo_system.comparison_count)
        if count <= 0 or count % BACKUP_EVERY_COMPARISONS != 0:
            return
        BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        if list(BACKUP_DIR.glob(f"artist_elo_backup_{count:08d}_*.zip")):
            return

        timestamp = time.strftime("%Y%m%d_%H%M%S")
        backup_path = BACKUP_DIR / f"artist_elo_backup_{count:08d}_{timestamp}.zip"
        files = [
            ELO_RATINGS_FILE,
            COMPARISON_HISTORY_FILE,
            ACTIVE_POOL_FILE,
            COMBINATION_RATINGS_FILE,
            BUFFER_STATE_FILE,
            SAVED_PROMPTS_FILE,
            SAVED_PROMPTS_BACKUP_FILE,
            MATCHMAKING_STATE_FILE,
            FAVORITES_FILE,
            STORAGE_SETTINGS_FILE,
            CLASSIFICATION_TAGS_FILE,
            ENTITY_NOTES_FILE,
            TOP_SEARCH_RATINGS_FILE,
            ARTIST_PORTRAITS_FILE,
        ]
        try:
            with zipfile.ZipFile(backup_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("backup_manifest.json", json.dumps({
                    "created_at": timestamp,
                    "comparison_count": count,
                    "image_directory": str(COMPARISON_IMAGES_DIR),
                    "note": "Generated duel images are not included; cropped artist portraits and all ranking/settings metadata are included.",
                }, indent=2))
                for path in files:
                    path = Path(path)
                    if path.exists() and path.is_file():
                        archive.write(path, arcname=path.name)
                if ARTIST_PORTRAITS_DIR.exists():
                    for portrait_path in ARTIST_PORTRAITS_DIR.glob("*.jpg"):
                        archive.write(portrait_path, arcname=f"artist_portraits/{portrait_path.name}")
            backups = sorted(
                BACKUP_DIR.glob("artist_elo_backup_*.zip"),
                key=lambda path: path.stat().st_mtime,
                reverse=True,
            )
            for old_backup in backups[BACKUP_KEEP_COUNT:]:
                old_backup.unlink(missing_ok=True)
            print(f"Created automatic backup: {backup_path}")
        except Exception as e:
            print(f"Warning: Could not create automatic backup: {e}")

    def get_session(self) -> ApiCredential:
        """Get or create an API session from Windows Credential Manager only."""
        if self.session is None:
            api_key = read_secure_novelai_api_key()
            if not api_key:
                self.api_key_configured = False
                raise ValueError(
                    "NovelAI API key is not configured. Open Storage / Settings on "
                    "this PC at http://127.0.0.1 and save a persistent API token."
                )
            self.api_key_configured = True
            self.session = ApiCredential(api_token=SecretStr(api_key))
        return self.session

    def _normalize_base_prompt(self, custom_prompt: str, use_default_when_empty: bool = True) -> str:
        """Normalize prompt and ensure artist placeholder exists."""
        if custom_prompt and custom_prompt.strip():
            base_prompt = custom_prompt.strip()
        elif use_default_when_empty:
            base_prompt = DEFAULT_PROMPT
        else:
            base_prompt = ""

        base_prompt = remove_artist_tags(base_prompt)
        if "{artist_placeholder}" not in base_prompt:
            if base_prompt.strip():
                base_prompt = insert_artist_tags(base_prompt, "{artist_placeholder}")
            else:
                base_prompt = "{artist_placeholder}"
        return base_prompt

    @staticmethod
    def _clean_saved_prompt_payload(data: Any) -> Tuple[Dict[str, Dict[str, Any]], bool]:
        """Normalize saved profiles and migrate the former prompt-only schema."""
        return clean_profile_payload(data, DEFAULT_GENERATION_PROFILE_SETTINGS)

    def _read_saved_prompts_file(self, path: Path) -> Optional[Tuple[Dict[str, Dict[str, Any]], bool]]:
        """Read one profile file. None means unreadable; an empty dict is valid."""
        if not path.exists():
            return None
        try:
            with open(path, "r", encoding="utf-8") as f:
                return self._clean_saved_prompt_payload(json.load(f))
        except Exception as exc:
            print(f"Warning: Could not read generation profile file {path}: {exc}")
            return None

    def _load_saved_prompts(self) -> Dict[str, Dict[str, Any]]:
        """Load profiles, recovering from backup and migrating old saved prompts."""
        primary = self._read_saved_prompts_file(SAVED_PROMPTS_FILE)
        if primary is not None:
            profiles, migrated = primary
            self._saved_prompts_migrated = bool(migrated)
            return profiles
        backup = self._read_saved_prompts_file(SAVED_PROMPTS_BACKUP_FILE)
        if backup is not None:
            profiles, migrated = backup
            self._saved_prompts_migrated = True
            print(f"Recovered generation profiles from backup: {SAVED_PROMPTS_BACKUP_FILE}")
            return profiles
        return {}

    def _save_saved_prompts(self):
        """Atomically persist versioned generation profiles and a known-good backup."""
        SAVED_PROMPTS_FILE.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "schema_version": PROFILE_SCHEMA_VERSION,
            "profiles": self.saved_prompts,
        }
        temp_path = SAVED_PROMPTS_FILE.with_suffix(SAVED_PROMPTS_FILE.suffix + ".tmp")
        with open(temp_path, "w", encoding="utf-8") as f:
            json.dump(payload, f, indent=2, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        temp_path.replace(SAVED_PROMPTS_FILE)
        try:
            backup_temp = SAVED_PROMPTS_BACKUP_FILE.with_suffix(
                SAVED_PROMPTS_BACKUP_FILE.suffix + ".tmp"
            )
            shutil.copy2(SAVED_PROMPTS_FILE, backup_temp)
            backup_temp.replace(SAVED_PROMPTS_BACKUP_FILE)
        except Exception as exc:
            print(f"Warning: Could not update generation-profile backup: {exc}")
        self._saved_prompts_migrated = False

    def save_prompt_preset(
        self,
        name: str,
        positive: str,
        negative: str,
        ownership: str = OWNERSHIP_PROMPT,
        resolution_preset: str = "portrait",
        width: int = IMG_WIDTH,
        height: int = IMG_HEIGHT,
        steps: int = STEPS,
        sampler: str = DEFAULT_SAMPLER_ID,
        scheduler: str = "default",
        uc_preset: int = 0,
        quality_toggle: bool = True,
        decrisp_mode: bool = False,
        variety_boost: bool = False,
        notes: str = "",
    ) -> str:
        """Create or overwrite a versioned generation profile."""
        clean_name = (name or "").strip()
        if not clean_name:
            return "**Profile name is required.**"
        if not (positive or "").strip() and not (negative or "").strip():
            return "**Nothing to save:** both prompt boxes are empty."
        profile = build_profile(
            ownership=ownership,
            positive=(positive or "").strip(),
            negative=(negative or "").strip(),
            resolution_preset=resolution_preset,
            width=width,
            height=height,
            steps=steps,
            sampler=sampler,
            scheduler=scheduler,
            uc_preset=uc_preset,
            quality_toggle=quality_toggle,
            decrisp_mode=decrisp_mode,
            variety_boost=variety_boost,
            notes=notes,
            defaults=DEFAULT_GENERATION_PROFILE_SETTINGS,
        )
        with self.state_lock:
            self.saved_prompts[clean_name] = profile
            self._save_saved_prompts()
        return f"**Saved generation profile:** {clean_name}"

    def delete_prompt_preset(self, name: str) -> str:
        """Delete a saved generation profile."""
        clean_name = (name or "").strip()
        if not clean_name:
            return "**Select a generation profile to delete.**"
        with self.state_lock:
            if clean_name not in self.saved_prompts:
                return f"**Generation profile not found:** {clean_name}"
            del self.saved_prompts[clean_name]
            self._save_saved_prompts()
            rotation_names = self.generation_settings.get("rotation_names", [])
            self.generation_settings["rotation_names"] = [n for n in rotation_names if n != clean_name]
        return f"**Deleted generation profile:** {clean_name}"

    def get_saved_prompt_names(self) -> List[str]:
        with self.state_lock:
            return sorted(self.saved_prompts.keys(), key=str.casefold)

    def get_generation_profile(self, name: str) -> Optional[dict]:
        with self.state_lock:
            profile = self.saved_prompts.get(str(name or ""))
            return deepcopy(profile) if profile else None

    def load_saved_prompt(
        self,
        preset_name: str,
        positive_prompt: str,
        negative_prompt: str,
        current_settings: Optional[dict] = None,
    ) -> dict:
        """Apply every field owned by one profile and return the resolved editor state."""
        with self.state_lock:
            profile = deepcopy(self.saved_prompts.get(preset_name or "", {}))
        if not profile:
            return {
                "ok": False,
                "message": "**Generation profile not found.**",
                "name": "",
                "positive": positive_prompt,
                "negative": negative_prompt,
            }
        baseline = dict(self.generation_settings)
        if isinstance(current_settings, dict):
            baseline.update(current_settings)
        baseline["positive_prompt_text"] = positive_prompt
        baseline["negative_prompt_text"] = negative_prompt
        resolved = apply_profile(profile, baseline, DEFAULT_GENERATION_PROFILE_SETTINGS)
        normalized_profile, _ = normalize_profile(profile, DEFAULT_GENERATION_PROFILE_SETTINGS)
        return {
            "ok": True,
            "message": f"**Loaded generation profile:** {preset_name}",
            "name": preset_name,
            "positive": resolved["positive_prompt_text"],
            "negative": resolved["negative_prompt_text"],
            "ownership": normalized_profile["ownership"],
            "resolution_preset": resolved["resolution_preset"],
            "width": resolved["width"],
            "height": resolved["height"],
            "steps": resolved["steps"],
            "sampler": resolved["sampler"],
            "scheduler": resolved["scheduler"],
            "uc_preset": resolved["uc_preset"],
            "quality_toggle": resolved["quality_toggle"],
            "decrisp_mode": resolved["decrisp_mode"],
            "variety_boost": resolved["variety_boost"],
            "notes": normalized_profile["notes"],
        }

    def _resolve_rotation_for_duel(self, settings: dict) -> dict:
        """Resolve one profile for a duel, including all fields that profile owns."""
        resolved = normalize_generation_settings(settings, DEFAULT_GENERATION_PROFILE_SETTINGS)
        resolved.update({
            "base_prompt": settings.get("base_prompt", self._normalize_base_prompt("")),
            "negative_prompt": settings.get("negative_prompt"),
            "rotation_preset": None,
        })
        chosen = None
        profile = None
        if resolved.get("rotation_enabled"):
            requested_names = list(resolved.get("rotation_names") or [])
            with self.state_lock:
                available = [name for name in requested_names if name in self.saved_prompts]
                if available:
                    chosen = random.choice(available)
                    profile = deepcopy(self.saved_prompts[chosen])
            if profile:
                resolved = apply_profile(profile, resolved, DEFAULT_GENERATION_PROFILE_SETTINGS)
                resolved["base_prompt"] = self._normalize_base_prompt(
                    resolved.get("positive_prompt_text", ""), use_default_when_empty=False
                )
                resolved["negative_prompt"] = str(resolved.get("negative_prompt_text", "") or "")
                resolved["rotation_preset"] = chosen
        if not profile:
            resolved["base_prompt"] = self._normalize_base_prompt(
                resolved.get("positive_prompt_text", "")
            )
            negative_text = str(resolved.get("negative_prompt_text", "") or "")
            resolved["negative_prompt"] = negative_text if negative_text.strip() else None
        resolved["generation_config"] = snapshot_profile(
            chosen, profile, resolved, DEFAULT_GENERATION_PROFILE_SETTINGS
        )
        return resolved

    def update_generation_settings(
        self,
        custom_prompt: str,
        custom_negative_prompt: str = "",
        quality_toggle: bool = True,
        uc_preset: int = 0,
        target_buffer_size: int = BUFFER_TARGET_SIZE,
        rotation_enabled: bool = False,
        rotation_names: Optional[List[str]] = None,
        resolution_preset: str = "portrait",
        width: int = IMG_WIDTH,
        height: int = IMG_HEIGHT,
        steps: int = STEPS,
        sampler: str = DEFAULT_SAMPLER_ID,
        scheduler: str = "default",
        decrisp_mode: bool = False,
        variety_boost: bool = False,
    ):
        """Update generation settings, avoiding work and disk writes when nothing changed."""
        try:
            new_target = int(target_buffer_size)
        except (TypeError, ValueError):
            new_target = BUFFER_TARGET_SIZE
        new_target = max(MIN_BUFFER_SIZE, min(MAX_BUFFER_SIZE, new_target))

        new_current_prompt = custom_prompt.strip() if custom_prompt and custom_prompt.strip() else DEFAULT_PROMPT
        valid_rotation_names = [
            name for name in (rotation_names or []) if name in self.saved_prompts
        ]
        new_settings = normalize_generation_settings(
            {
                "positive_prompt_text": custom_prompt or "",
                "negative_prompt_text": custom_negative_prompt or "",
                "quality_toggle": quality_toggle,
                "uc_preset": uc_preset,
                "rotation_enabled": bool(rotation_enabled),
                "rotation_names": valid_rotation_names,
                "resolution_preset": resolution_preset,
                "width": width,
                "height": height,
                "steps": steps,
                "sampler": sampler,
                "scheduler": scheduler,
                "decrisp_mode": decrisp_mode,
                "variety_boost": variety_boost,
            },
            DEFAULT_GENERATION_PROFILE_SETTINGS,
        )
        new_settings["base_prompt"] = self._normalize_base_prompt(custom_prompt)
        new_settings["negative_prompt"] = custom_negative_prompt.strip() if custom_negative_prompt and custom_negative_prompt.strip() else None

        # Votes submit the same generation controls on every click.  Avoid
        # waiting for the shared state lock when those values are unchanged;
        # the locked branch below still rechecks before applying real changes.
        if (
            self.current_prompt == new_current_prompt
            and self.target_buffer_size == new_target
            and self.generation_settings == new_settings
        ):
            return False

        changed = False
        with self.state_lock:
            changed = (
                self.current_prompt != new_current_prompt
                or self.target_buffer_size != new_target
                or self.generation_settings != new_settings
            )
            if not changed:
                return False

            self.current_prompt = new_current_prompt
            self.target_buffer_size = new_target
            self.generation_settings = new_settings

            # If target was lowered, discard excess queued duels (never discard the on-screen duel).
            while self._buffered_count_locked() > self.target_buffer_size and self.comparison_queue:
                self.comparison_queue.pop()

        # Persist outside the vote callback's critical path.
        if hasattr(self, "persistence_event"):
            self._schedule_persistence(sections={"buffer"})
        else:
            self._save_buffer_state()
        return True

    def _buffered_count_locked(self) -> int:
        return (1 if self.current_comparison else 0) + len(self.comparison_queue)

    def _advance_to_next_comparison_locked(self):
        """Advance current comparison to the next ready duel if available."""
        if self.comparison_queue:
            self.current_comparison = self.comparison_queue.popleft()
        else:
            self.current_comparison = None

    def _get_current_snapshot(self) -> dict:
        """Read current UI-relevant state under lock."""
        with self.state_lock:
            current = self.current_comparison
            queued = len(self.comparison_queue)
            total_ready = self._buffered_count_locked()
            refill = self.refill_in_progress
            generation_paused = self.generation_paused
            error = self.last_generation_error
            undo_available = self.last_undo_state is not None
            result_msg = self.ui_result_msg
            details_msg = self.ui_details_msg
            target_buffer_size = self.target_buffer_size
            rotation_enabled = bool(self.generation_settings.get("rotation_enabled"))
            rotation_names = list(self.generation_settings.get("rotation_names", []))

            if current:
                image_a = current.image_a_path
                image_b = current.image_b_path
                artists_a = current.artists_a.copy()
                artists_b = current.artists_b.copy()
            else:
                image_a = None
                image_b = None
                artists_a = []
                artists_b = []

        return {
            "image_a": image_a,
            "image_b": image_b,
            "artists_a": artists_a,
            "artists_b": artists_b,
            "queued": queued,
            "total_ready": total_ready,
            "refill": refill,
            "generation_paused": generation_paused,
            "error": error,
            "undo_available": undo_available,
            "result_msg": result_msg,
            "details_msg": details_msg,
            "target_buffer_size": target_buffer_size,
            "rotation_enabled": rotation_enabled,
            "rotation_names": rotation_names,
        }

    def format_status_message(self) -> str:
        """Format a compact, theme-aware Compare status strip."""
        snapshot = self._get_current_snapshot()
        current_ready = bool(snapshot["image_a"] and snapshot["image_b"])
        queued = int(snapshot["queued"])
        total_ready = int(snapshot["total_ready"])
        target_buffer_size = int(snapshot["target_buffer_size"])
        refill = bool(snapshot["refill"])
        generation_paused = bool(snapshot["generation_paused"])
        error = str(snapshot["error"] or "").strip()
        rotation_enabled = bool(snapshot["rotation_enabled"])
        rotation_names = list(snapshot["rotation_names"])

        if generation_paused and refill:
            state_icon, state_text = "◷", "Pausing after current duel"
        elif generation_paused:
            state_icon, state_text = "⏸", "Generation paused"
        elif current_ready:
            state_icon, state_text = "●", "Duel ready"
        elif refill:
            state_icon, state_text = "◌", "Generating next duel"
        else:
            state_icon, state_text = "○", "Waiting for a duel"

        rotation_text = (
            f"Rotation {len(rotation_names)}"
            if rotation_enabled and rotation_names
            else "Rotation needs presets"
            if rotation_enabled
            else "Rotation off"
        )
        html_parts = [
            '<div class="duel-status-bar">',
            f'<span class="duel-status-state">{state_icon} {html.escape(state_text)}</span>',
            f'<span class="duel-status-chip">Buffer <strong>{total_ready}/{target_buffer_size}</strong></span>',
            f'<span class="duel-status-chip">Queued <strong>{queued}</strong></span>',
            f'<span class="duel-status-chip">Refill <strong>{"active" if refill else "idle"}</strong></span>',
            f'<span class="duel-status-chip">{html.escape(rotation_text)}</span>',
            '</div>',
            self.format_buffer_health(),
        ]
        if self.legacy_competitive_guard:
            html_parts.append(
                f'<div class="duel-status-error"><strong>Reset required:</strong> '
                f'{html.escape(self.legacy_guard_message)}</div>'
            )
        if error:
            html_parts.append(
                f'<div class="duel-status-error"><strong>Generation error:</strong> {html.escape(error)}</div>'
            )
        return "".join(html_parts)

    def start_refill_if_needed(self):
        """Start sequential background refill if the rolling buffer is below target."""
        if not self.api_key_configured:
            self.last_generation_error = (
                "NovelAI API key not configured. Open Storage / Settings locally to continue."
            )
            return
        # The refill worker can hold state_lock while selecting/generating. Most
        # vote callbacks only need to learn that it is already alive, so avoid
        # blocking the UI on that lock and re-check safely once acquired.
        thread = self.refill_thread
        if thread is not None and thread.is_alive():
            return
        with self.state_lock:
            total_ready = self._buffered_count_locked()
            thread_alive = self.refill_thread is not None and self.refill_thread.is_alive()
            if self.generation_paused or total_ready >= self.target_buffer_size or thread_alive:
                return

            token = self.buffer_generation_token
            self.refill_in_progress = True
            self.last_generation_error = ""
            self.refill_thread = threading.Thread(
                target=self._refill_worker,
                args=(token,),
                daemon=True,
                name="comparison-refill-worker",
            )
            self.refill_thread.start()

    def _prepare_comparison_pair(
        self,
        base_prompt: str,
    ) -> Tuple[List[str], List[str], str, str, Path, Path, int, str, str, float]:
        """Select a Phase 2 matchup and prepare prompts/paths for the duel."""
        with self.state_lock:
            buffered_items = (
                ([self.current_comparison] if self.current_comparison else [])
                + list(self.comparison_queue)
            )
            reserved_duels = [
                (
                    list(item.artists_a),
                    list(item.artists_b),
                    str(item.matchmaking_reason or ""),
                )
                for item in buffered_items
                if item is not None and item.artists_a and item.artists_b
            ]
            artists_a, artists_b, reason, details, matchmaking_score = self.matchmaker.select_matchup(
                reserved_duels=reserved_duels,
                buffer_target_size=self.target_buffer_size,
            )
            tags_a = self.artist_manager.format_artist_tags(artists_a)
            tags_b = self.artist_manager.format_artist_tags(artists_b)

        prompt_a = insert_artist_tags(base_prompt, tags_a)
        prompt_b = insert_artist_tags(base_prompt, tags_b)
        timestamp = int(time.time() * 1000)
        rand_suffix = random.randint(1000, 9999)
        path_a = COMPARISON_IMAGES_DIR / f"compare_{timestamp}_{rand_suffix}_a.png"
        path_b = COMPARISON_IMAGES_DIR / f"compare_{timestamp}_{rand_suffix}_b.png"
        seed = random.randint(0, MAX_NOVELAI_SEED)
        return (
            artists_a, artists_b, prompt_a, prompt_b, path_a, path_b, seed,
            reason, details, matchmaking_score,
        )

    async def _generate_comparison_item_async(self, session: ApiCredential, settings: dict) -> Optional[ComparisonItem]:
        """Generate a single duel sequentially (A then B), with reliable timing capture."""
        settings = self._resolve_rotation_for_duel(settings)
        base_prompt = settings["base_prompt"]
        negative_prompt = settings["negative_prompt"]
        quality_toggle = settings["quality_toggle"]
        uc_preset = settings["uc_preset"]
        rotation_preset = settings.get("rotation_preset")
        generation_config = deepcopy(settings.get("generation_config", {}))
        width = int(settings.get("width", IMG_WIDTH))
        height = int(settings.get("height", IMG_HEIGHT))
        steps = int(settings.get("steps", STEPS))
        sampler = str(settings.get("sampler", DEFAULT_SAMPLER_ID))
        scheduler = str(settings.get("scheduler", "default"))
        decrisp_mode = bool(settings.get("decrisp_mode", False))
        variety_boost = bool(settings.get("variety_boost", False))

        (
            artists_a, artists_b, prompt_a, prompt_b, path_a, path_b, seed,
            matchmaking_reason, matchmaking_details, matchmaking_score,
        ) = self._prepare_comparison_pair(base_prompt)

        with self.state_lock:
            record_generation_timing = bool(
                self.storage_settings.get("record_generation_timing", False)
            )
        duel_started_epoch = time.time()
        duel_started_perf = time.perf_counter()
        image_timing_samples: List[Tuple[float, float, bool]] = []
        success_a = False
        success_b = False

        def capture_image_timing(started_epoch: float, duration: float, success: bool) -> None:
            image_timing_samples.append((float(started_epoch), float(duration), bool(success)))

        try:
            print(f"Generating image A with artists: {artists_a} | seed: {seed}")
            print(f"Prompt A: {prompt_a[:200]}...")
            success_a = await generate_image(
                session, prompt_a, path_a, negative_prompt, quality_toggle, uc_preset, seed,
                timing_callback=capture_image_timing if record_generation_timing else None,
                width=width, height=height, steps=steps, sampler=sampler,
                scheduler=scheduler, decrisp_mode=decrisp_mode,
                variety_boost=variety_boost,
            )

            print(f"Generating image B with artists: {artists_b} | seed: {seed}")
            print(f"Prompt B: {prompt_b[:200]}...")
            success_b = await generate_image(
                session, prompt_b, path_b, negative_prompt, quality_toggle, uc_preset, seed,
                timing_callback=capture_image_timing if record_generation_timing else None,
                width=width, height=height, steps=steps, sampler=sampler,
                scheduler=scheduler, decrisp_mode=decrisp_mode,
                variety_boost=variety_boost,
            )

            if success_a and success_b:
                with self.state_lock:
                    self.matchmaking_state.record_matchup(artists_a, artists_b, matchmaking_reason)
                duel_payload = {
                    "image_a_path": str(path_a),
                    "image_b_path": str(path_b),
                    "artists_a": artists_a,
                    "artists_b": artists_b,
                    "seed": seed,
                }
                duel_id = hashlib.sha1(
                    json.dumps(duel_payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
                ).hexdigest()[:20]
                return ComparisonItem(
                    image_a_path=str(path_a),
                    image_b_path=str(path_b),
                    artists_a=artists_a,
                    artists_b=artists_b,
                    duel_id=duel_id,
                    seed=seed,
                    rotation_preset=rotation_preset,
                    prompt_a=prompt_a,
                    prompt_b=prompt_b,
                    negative_prompt="" if negative_prompt is None else negative_prompt,
                    quality_toggle=quality_toggle,
                    uc_preset=uc_preset,
                    generation_config=generation_config,
                    matchmaking_reason=matchmaking_reason,
                    matchmaking_details=matchmaking_details,
                    matchmaking_score=matchmaking_score,
                )
            return None
        finally:
            if record_generation_timing:
                try:
                    self.generation_timing_stats.record_batch(
                        image_timing_samples,
                        (
                            duel_started_epoch,
                            time.perf_counter() - duel_started_perf,
                            bool(success_a and success_b),
                        ),
                    )
                except Exception as exc:
                    print(f"Warning: Could not record generation timing statistics: {exc}")

    def _refill_worker(self, token: int):
        """Background worker that sequentially refills the buffer up to target size."""
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        had_error = False
        try:
            try:
                session = self.get_session()
            except Exception as e:
                with self.state_lock:
                    if token == self.buffer_generation_token:
                        self.last_generation_error = str(e)
                return

            while True:
                with self.state_lock:
                    if token != self.buffer_generation_token:
                        break
                    # A pause never interrupts image A/image B halfway through a duel.
                    # This guard is checked only between complete comparison pairs.
                    if self.generation_paused:
                        break
                    total_ready = self._buffered_count_locked()
                    if total_ready >= self.target_buffer_size:
                        break
                    settings = dict(self.generation_settings)

                item = loop.run_until_complete(self._generate_comparison_item_async(session, settings))
                if item is None:
                    had_error = True
                    with self.state_lock:
                        if token == self.buffer_generation_token:
                            self.last_generation_error = "Error generating images. Please try again."
                    break

                with self.state_lock:
                    if token != self.buffer_generation_token:
                        break
                    if self.current_comparison is None:
                        self.current_comparison = item
                    else:
                        self.comparison_queue.append(item)
                    self.last_generation_error = ""
                # Buffer/matchmaking writes are deferred so a simultaneous vote never waits on disk I/O.
                self._schedule_persistence(sections={"buffer", "matchmaking"})

        except Exception as e:
            had_error = True
            print(f"Refill worker error: {e}")
            with self.state_lock:
                if token == self.buffer_generation_token:
                    self.last_generation_error = str(e)
        finally:
            loop.close()
            with self.state_lock:
                if token == self.buffer_generation_token:
                    self.refill_in_progress = False
                    self.refill_thread = None
                    # If something consumed items while we were working, restart as needed
                    needs_more = (
                        not had_error
                        and not self.generation_paused
                        and self._buffered_count_locked() < self.target_buffer_size
                    )
                else:
                    needs_more = False

            if needs_more:
                self.start_refill_if_needed()

    def generation_pause_button_update(self):
        """Return the correct button label after browser refreshes."""
        with self.state_lock:
            paused = self.generation_paused
        return gr.update(
            value="▶ Resume" if paused else "⏸ Pause",
            variant="primary" if paused else "stop",
        )

    def toggle_generation_pause(self) -> Tuple[Any, str]:
        """Pause between complete duels, or resume sequential buffer generation."""
        with self.state_lock:
            self.generation_paused = not self.generation_paused
            paused = self.generation_paused
            worker_active = bool(self.refill_thread and self.refill_thread.is_alive())

        if not paused:
            self.start_refill_if_needed()
            return gr.update(value="⏸ Pause", variant="stop"), self.format_status_message()

        # Do not invalidate the worker token: that would discard a completed in-flight
        # duel. The worker observes the pause only before beginning the next pair.
        label = "▶ Resume"
        status = self.format_status_message()
        if worker_active:
            status += (
                '<div class="duel-status-error"><strong>Pause queued:</strong> '
                'the current A/B pair will finish before generation stops.</div>'
            )
        return gr.update(value=label, variant="primary"), status

    def rebuild_buffer(
        self,
        custom_prompt: str,
        custom_negative_prompt: str = "",
        quality_toggle: bool = True,
        uc_preset: int = 0,
        target_buffer_size: int = BUFFER_TARGET_SIZE,
        rotation_enabled: bool = False,
        rotation_names: Optional[List[str]] = None,
        resolution_preset: str = "portrait",
        width: int = IMG_WIDTH,
        height: int = IMG_HEIGHT,
        steps: int = STEPS,
        sampler: str = DEFAULT_SAMPLER_ID,
        scheduler: str = "default",
        decrisp_mode: bool = False,
        variety_boost: bool = False,
    ):
        """Clear current/queued duels and rebuild rolling buffer with new settings."""
        self.update_generation_settings(
            custom_prompt,
            custom_negative_prompt,
            quality_toggle,
            uc_preset,
            target_buffer_size,
            rotation_enabled,
            rotation_names,
            resolution_preset,
            width,
            height,
            steps,
            sampler,
            scheduler,
            decrisp_mode,
            variety_boost,
        )
        with self.state_lock:
            self.buffer_generation_token += 1  # invalidate old worker outputs
            self.current_comparison = None
            self.comparison_queue.clear()
            self.last_generation_error = ""
            self.ui_result_msg = ""
            self.ui_details_msg = ""
            self._save_buffer_state_locked()
            # Refill the full 45% unseen reserve before generation starts. This
            # prevents a large rebuilt buffer from exhausting a tiny startup
            # reserve and then producing no more fresh screenings until a vote.
            self.artist_manager.synchronize_coverage_reserve(
                max_releases=COVERAGE_STARTUP_RESERVE_ADDITIONS
            )
        self.start_refill_if_needed()

    # -------------------------------------------------------------------------
    # Export / display formatting
    # -------------------------------------------------------------------------

    def export_leaderboard_csv(self) -> str:
        """Export the global Bayesian leaderboard and current scheduling state."""
        with self.state_lock:
            scheduler = self.matchmaker.scheduler
            scheduler.refresh_global_cache(force=True)
            ranked = self.top_search.ranked_artists(0.0, "conservative")
            unseen = [a for a in self.artist_manager.artists if a not in set(ranked)]
            sorted_artists = ranked + unseen
            working_set = set(scheduler.working_pool)
            current_duel = int(self.top_search.comparison_count)
            favorite_artists = {
                str(entry.get("key", ""))
                for entry in self.favorites.entries(["artist"])
            }
            # Convert queue positions to an O(1) audit priority. The live helper
            # intentionally remains qualitative; exporting thousands of artists
            # must not perform repeated list.index scans.
            priority_by_artist: Dict[str, float] = {}
            category_order = (
                "recovery", "boundary", "qualification", "screening", "opening",
                "upside", "stale", "bridge", "elite", "fresh", "exploration",
            )
            for category in category_order:
                for position, artist in enumerate(scheduler._candidate_lists.get(category, [])):
                    score = max(0.0, 10.0 - position / 50.0)
                    priority_by_artist[artist] = max(priority_by_artist.get(artist, 0.0), score)

            headers = [
                "Rank", "Artist", "Official_Score", "Skill_Mu", "Uncertainty_Sigma",
                "Potential_Score", "Top50_Probability", "Stage", "Effective_Evidence",
                "Raw_Duels", "Solo_Duels", "Duo_Duels", "Trio_Duels",
                "Wins", "Losses", "Ties", "Both_Bad", "Bad_Output_Probability",
                "In_Working_Set", "Scheduling_Status", "Scheduling_Priority",
                "Last_Comparison_System_Duel", "System_Duels_Since_Last",
                "Unique_Opponents", "Legacy_Overall_ELO", "Favorite",
                "Manual_Style_Tags", "Private_Note",
            ]
            output = io.StringIO(newline="")
            writer = csv.writer(output, lineterminator="\n")
            writer.writerow(headers)
            for rank, artist in enumerate(sorted_artists, 1):
                entry = self.top_search.get_entry(artist)
                last_seen = int(entry.get("last_comparison_index", 0) or 0)
                note_entry = self.entity_notes.get("artist", artist) or {}
                manual_tags = self.classifications.get_manual_tags("artist", artist)
                writer.writerow([
                    rank,
                    artist,
                    f"{self.top_search.conservative_score(artist):.4f}",
                    f"{self.top_search.get_mu(artist):.4f}",
                    f"{self.top_search.get_sigma(artist):.4f}",
                    f"{self.top_search.potential_score(artist):.4f}",
                    f"{self.top_search.top_k_probability(artist) * 100.0:.4f}",
                    self.top_search.stage(artist),
                    f"{self.top_search.effective_evidence(artist):.4f}",
                    int(entry.get("comparisons", 0) or 0),
                    int(entry.get("solo_comparisons", 0) or 0),
                    int(entry.get("duo_comparisons", 0) or 0),
                    int(entry.get("trio_comparisons", 0) or 0),
                    int(entry.get("wins", 0) or 0),
                    int(entry.get("losses", 0) or 0),
                    int(entry.get("ties", 0) or 0),
                    int(entry.get("both_bad", 0) or 0),
                    f"{self.top_search.bad_probability(artist) * 100.0:.4f}",
                    "TRUE" if artist in working_set else "FALSE",
                    scheduler.artist_status(artist),
                    f"{priority_by_artist.get(artist, 0.0):.4f}",
                    last_seen,
                    max(0, current_duel - last_seen) if last_seen else "",
                    self.matchmaking_state.unique_opponents(artist),
                    f"{self.elo_system.get_rating(artist):.4f}",
                    "TRUE" if artist in favorite_artists else "FALSE",
                    "; ".join(manual_tags),
                    str(note_entry.get("note", "") or ""),
                ])
            return output.getvalue()

    def export_combination_leaderboard_csv(self) -> str:
        """Export exact combinations with legacy rating and learned synergy."""
        lines = [
            "Rank,Artists,Combination_ELO,Synergy_Mu,Synergy_Sigma,Duels,Confidence,"
            "Wins,Losses,Ties,ScoreRate,WeightedWinRate"
        ]
        entries = self.combination_elo.get_top(len(self.combination_elo.entries))
        weighted_stats = self.history.get_combination_stats(self.combination_elo)
        for rank, entry in enumerate(entries, 1):
            comparisons = int(entry.get("comparisons", 0))
            wins = int(entry.get("wins", 0))
            ties = int(entry.get("ties", 0))
            losses = int(entry.get("losses", max(0, comparisons - wins - ties)))
            score_rate = ((wins + ties * 0.5) / comparisons * 100.0) if comparisons else 0.0
            combo_id = self.combination_elo.combination_id(entry.get("artists", []))
            weighted_wr = weighted_stats.get(combo_id, {}).get("weighted_win_rate", 0.0)
            synergy = self.top_search.synergies.get(self.top_search.combo_id(entry.get("artists", [])), {})
            confidence = confidence_info(comparisons)[0]
            artists = " + ".join(entry.get("artists", [])).replace('"', '""')
            lines.append(
                f'{rank},"{artists}",{float(entry.get("rating", DEFAULT_ELO)):.2f},'
                f'{float(synergy.get("mu", 0.0)):.2f},'
                f'{float(synergy.get("sigma", TOP_SKILL_SYNERGY_SIGMA)):.2f},'
                f'{comparisons},{confidence},{wins},{losses},{ties},{score_rate:.2f},{weighted_wr:.2f}'
            )
        return "\n".join(lines)

    def format_recent_history(self, limit: int = 10) -> str:
        """Format recent comparison history for display."""
        with self.state_lock:
            if not self.history.records:
                return "*No comparisons yet.*"
            recent = self.history.records[-limit:][::-1]

        lines = ["*Newest first:*", ""]
        for i, record in enumerate(recent, 1):
            winner = record.get("winner", "?")
            artists_a = record.get("artists_a", [])
            artists_b = record.get("artists_b", [])

            reason = html.escape(str(record.get("matchmaking_reason", "Historical / unknown")))
            generation_summary = html.escape(_generation_config_summary(record.get("generation_config", {})))
            if winner == "TIE":
                side_a = self.render_artist_links(artists_a, "elo-leaderboard-artist-link")
                side_b = self.render_artist_links(artists_b, "elo-leaderboard-artist-link")
                lines.append(f"{i}. <strong>{side_a}</strong> tied {side_b} — <em>{reason}</em> · {generation_summary}")
            elif winner == "INVALID":
                side_a = self.render_artist_links(artists_a, "elo-leaderboard-artist-link")
                side_b = self.render_artist_links(artists_b, "elo-leaderboard-artist-link")
                lines.append(f"{i}. Invalid duel: {side_a} vs {side_b} — <em>{reason}</em> · {generation_summary}")
            else:
                winner_artists = artists_a if winner == "A" else artists_b
                loser_artists = artists_b if winner == "A" else artists_a
                winner_str = self.render_artist_links(winner_artists, "elo-leaderboard-artist-link")
                loser_str = self.render_artist_links(loser_artists, "elo-leaderboard-artist-link")
                lines.append(f"{i}. <strong>{winner_str}</strong> beat {loser_str} — <em>{reason}</em> · {generation_summary}")

        return "\n".join(lines)

    def format_top_artists_display(self, limit: int = 12) -> str:
        """Render the official conservative top-search leaderboard."""
        self._ensure_browser_records_cache()
        with self.browser_cache_lock:
            records = sorted(
                [
                    record for record in self.artist_browser_records_cache
                    if int(record.get("duels", 0)) > 0
                ],
                key=lambda record: record["top_score"],
                reverse=True,
            )[:limit]
        with self.state_lock:
            comparison_count = int(self.top_search.comparison_count)
            rated_count = len(self.top_search.artists)
            pool_size = len(self.artist_manager.active_pool.pool) if self.artist_manager.active_pool else 0
            cutoff = self.top_search.cutoff_score()

        if not records:
            return '<div class="compact-leaderboard-summary">No ratings yet. Start comparing.</div>'

        parts = [
            '<div class="compact-leaderboard">',
            '<div class="compact-leaderboard-header compact-combination-header">'
            '<span>#</span><span>Artist</span><span style="text-align:right">Score</span>'
            '<span style="text-align:right">Top 50</span><span style="text-align:right">Stage</span><span></span>'
            '</div>',
        ]
        for rank, record in enumerate(records, 1):
            artist_text = str(record["artist"])
            artist_attr = html.escape(artist_text, quote=True)
            artist_label = html.escape(artist_text)
            favorite_symbol = "★" if record.get("favorite") else "☆"
            top50_tenure = str(record.get("top50_tenure", "") or "")
            top50_qualifier = (
                "Tracked current Top-50 streak"
                if record.get("top50_approximate")
                else "Current Top-50 streak"
            )
            leaderboard_title = "Open in Artists tab"
            if top50_tenure:
                leaderboard_title += f" · {top50_qualifier}: {top50_tenure}"
            parts.extend([
                '<div class="compact-rank-row">',
                f'<span class="compact-rank-number">{rank}</span>',
                f'<button type="button" class="elo-artist-link elo-leaderboard-artist-link" '
                f'data-artist="{artist_attr}" title="{html.escape(leaderboard_title, quote=True)}">{artist_label}</button>',
                f'<span class="compact-rank-elo">{float(record["top_score"]):.0f}</span>',
                f'<span class="compact-rank-stat">{float(record["top50_probability"])*100:.0f}%</span>',
                f'<span class="compact-rank-stat">{html.escape(str(record["stage"]))}</span>',
                f'<button type="button" class="elo-star-action" data-kind="artist" '
                f'data-key="{artist_attr}" data-label="{artist_attr}" title="Toggle favorite">'
                f'{favorite_symbol}</button>',
                '</div>',
            ])
        parts.append(
            '<div class="compact-leaderboard-summary">'
            f'{comparison_count:,} rated/tied duels · {rated_count:,} evaluated artists · '
            f'{pool_size:,} active · Top-50 cutoff {cutoff:.0f}'
            '</div></div>'
        )
        return "".join(parts)

    def format_pool_activity_display(self) -> str:
        """Explain the temporary working cache and global scheduling health."""
        with self.state_lock:
            stats = self.artist_manager.get_pool_stats()
            scheduler = self.matchmaker.scheduler
            working = list(scheduler.working_pool)
            stage_counts = Counter(self.top_search.stage(a) for a in working)
            status_counts = Counter(scheduler.artist_status(a) for a in working)
            reason_counts = Counter(self.matchmaking_state.reason_counts)
        size = len(working)
        target = int(stats.get("target_size", ACTIVE_POOL_SIZE))
        pool_class = "ok" if size == target else "warning"
        tested_artists = int(stats.get("seen_artists", 0))
        total_artists = int(stats.get("total_artists", 0))
        completed_duels = int(stats.get("completed_duels", self.top_search.comparison_count) or 0)
        coverage = tested_artists / max(1, total_artists)
        parts = [
            f'<div class="pool-cap-banner {pool_class}"><strong>Working set {size}/{target}</strong>'
            + (' · Cache size healthy ✓' if size == target else f' · ⚠ Expected exactly {target}')
            + '</div>',
            '<div class="compact-leaderboard-summary"><strong>This is only a generation cache.</strong> '
            'Artists outside it remain globally ranked and fully eligible for future recall.</div>',
            '<div class="pool-health-grid">',
            f'<div class="pool-health-card"><strong>{coverage*100:.1f}%</strong>Catalog coverage</div>',
            f'<div class="pool-health-card"><strong>{tested_artists:,} / {total_artists:,}</strong>Artists tested</div>',
            f'<div class="pool-health-card"><strong>{completed_duels:,}</strong>Completed duels</div>',
            f'<div class="pool-health-card"><strong>{int(stats.get("unseen_artists", 0)):,}</strong>Untested globally</div>',
            f'<div class="pool-health-card"><strong>{stage_counts.get("Opening",0)}</strong>Opening in cache</div>',
            f'<div class="pool-health-card"><strong>{stage_counts.get("Screening",0)}</strong>Screening in cache</div>',
            f'<div class="pool-health-card"><strong>{stage_counts.get("Qualification",0)}</strong>Qualification in cache</div>',
            f'<div class="pool-health-card"><strong>{stage_counts.get("Established",0)}</strong>Established in cache</div>',
            f'<div class="pool-health-card"><strong>{status_counts.get("High-priority recall",0)}</strong>Recall priority</div>',
            f'<div class="pool-health-card"><strong>{self.top_search.cutoff_score():.0f}</strong>Current mean cutoff</div>',
            '</div>',
            '<div class="compact-leaderboard-summary">Completed duels include A/B wins, ties, and Both bad evaluations; queued, skipped, and Invalid duels are excluded.</div>',
            f'<div class="compact-leaderboard-summary">Fresh discovery contributes {FRESH_DISCOVERY_QUOTA_WEIGHT * 100:.0f}% toward the solo/duo/trio quota; fresh openings remain solo-only.</div>',
        ]
        if reason_counts:
            parts.append('<details class="pool-protection-details"><summary>Completed matchmaking mix</summary><ul class="pool-health-list">')
            for reason, count in reason_counts.most_common():
                parts.append(f'<li>{html.escape(str(reason))}: {int(count):,}</li>')
            parts.append('</ul></details>')
        return "".join(parts)

    def format_top_combinations_display(self, limit: int = 10) -> str:
        """Render a dense exact-combination leaderboard for the Compare sidebar."""
        self._ensure_browser_records_cache()
        with self.browser_cache_lock:
            records = sorted(
                self.combination_browser_records_cache,
                key=lambda record: record["elo"],
                reverse=True,
            )[:limit]

        if not records:
            return '<div class="compact-leaderboard-summary">No combination ratings yet.</div>'

        parts = [
            '<div class="compact-leaderboard">',
            '<div class="compact-leaderboard-header">'
            '<span>#</span><span>Combination</span><span style="text-align:right">ELO</span>'
            '<span style="text-align:right">WR</span><span style="text-align:right">Duels</span><span></span>'
            '</div>',
        ]
        for rank, record in enumerate(records, 1):
            combination_text = str(record["artists"])
            combo_attr = html.escape(combination_text, quote=True)
            combo_label = html.escape(combination_text)
            key_attr = html.escape(str(record.get("combo_id", "")), quote=True)
            favorite_symbol = "★" if record.get("favorite") else "☆"
            parts.extend([
                '<div class="compact-combination-row">',
                f'<span class="compact-rank-number">{rank}</span>',
                f'<button type="button" class="elo-combination-link elo-combination-gallery-link" '
                f'data-combination="{combo_attr}" data-key="{key_attr}" '
                f'title="Open exact duels in Gallery">{combo_label}</button>',
                f'<span class="compact-rank-elo">{float(record["elo"]):.0f}</span>',
                f'<span class="compact-rank-stat">{float(record["weighted_wr"]):.0f}%</span>',
                f'<span class="compact-rank-stat">{int(record["duels"])}</span>',
                f'<button type="button" class="elo-star-action" data-kind="combination" '
                f'data-key="{key_attr}" data-label="{combo_attr}" title="Toggle favorite">'
                f'{favorite_symbol}</button>',
                '</div>',
            ])
        parts.append(
            '<div class="compact-leaderboard-summary">Click a combination to open its exact Gallery duels.</div>'
            '</div>'
        )
        return "".join(parts)

    def _browser_cache_current_stamp(self) -> Tuple[int, int, int, int, int, int]:
        """Return a cheap version stamp for rating/history data."""
        return (
            len(self.history.records),
            int(self.elo_system.comparison_count),
            int(self.top_search.comparison_count),
            len(self.combination_elo.entries),
            int(self.classifications.version),
            int(self.entity_notes.version),
        )

    def _ensure_browser_records_cache(self):
        """Build reusable artist/combination records only when ranking data changes."""
        stamp = self._browser_cache_current_stamp()
        with self.browser_cache_lock:
            if self.browser_cache_stamp == stamp:
                return

            # The history aggregation is the expensive part. Do it once, then reuse
            # the resulting flat records for every search, sort, filter, and page.
            with self.state_lock:
                artist_stats = self.history.get_artist_stats(self.elo_system, self.combination_elo)
                weighted_combo_stats = self.history.get_combination_stats(self.combination_elo)
                artist_names = set(self.elo_system.ratings)
                artist_names.update(self.top_search.artists)
                artist_names.update(artist_stats)
                for size_key in ELOSystem.SIZE_KEYS:
                    artist_names.update(self.elo_system.ratings_by_size.get(size_key, {}))

                overall_ratings = dict(self.elo_system.ratings)
                overall_counts = dict(self.elo_system.artist_comparisons)
                size_ratings = {
                    key: dict(self.elo_system.ratings_by_size.get(key, {}))
                    for key in ELOSystem.SIZE_KEYS
                }
                combo_entries = [deepcopy(entry) for entry in self.combination_elo.entries.values()]

            # Take one snapshot of curation metadata instead of acquiring a lock
            # separately for every one of the ~16,000 possible artist records.
            with self.favorites.lock:
                favorite_artist_keys = set(self.favorites.data.get("artist", {}))
                favorite_combination_keys = set(self.favorites.data.get("combination", {}))
            classification_snapshot = self.classifications.snapshot()
            manual_artist_tags = classification_snapshot.get("manual", {}).get("artist", {})
            manual_combination_tags = classification_snapshot.get("manual", {}).get("combination", {})
            note_snapshot = self.entity_notes.snapshot()
            artist_note_entries = {
                str(key): str(entry.get("note", ""))
                for key, entry in note_snapshot.get("artist", {}).items()
                if isinstance(entry, dict)
            }
            rotated_out_counts = classification_snapshot.get("rotated_out_counts", {})
            rotation_reason_counts = classification_snapshot.get("rotation_reason_counts", {})
            top_cutoff = self.top_search.cutoff_score()
            elite_artists = set(self.top_search.elite_artists())

            artist_records: List[dict] = []
            for artist in artist_names:
                stats = artist_stats.get(artist, {})
                rounds = int(stats.get("rounds", 0))
                wins = int(stats.get("wins", 0))
                ties = int(stats.get("ties", 0))
                losses = max(0, rounds - wins - ties)
                overall_count = int(overall_counts.get(artist, 0))
                top_count = self.top_search.get_comparison_count(artist)
                confidence_label, confidence_factor = confidence_info(top_count)
                top_probability = self.top_search.top_k_probability(artist)
                record = {
                    "artist": artist,
                    "overall_elo": float(overall_ratings.get(artist, DEFAULT_ELO)),
                    "top_mu": self.top_search.get_mu(artist),
                    "top_sigma": self.top_search.get_sigma(artist),
                    "top_score": self.top_search.conservative_score(artist),
                    "potential_score": self.top_search.potential_score(artist),
                    "top50_probability": top_probability,
                    "stage": "Elite" if artist in elite_artists else self.top_search.stage(artist),
                    "duels": rounds,
                    "wins": wins,
                    "losses": losses,
                    "ties": ties,
                    "win_rate": (wins + ties * 0.5) / rounds * 100.0 if rounds else 0.0,
                    "weighted_wr": float(stats.get("weighted_win_rate", 0.0)),
                    "confidence": confidence_label,
                    "confidence_factor": confidence_factor,
                    "favorite": artist in favorite_artist_keys,
                }
                for key in ELOSystem.SIZE_KEYS:
                    category = stats.get(key, {})
                    cat_rounds = int(category.get("rounds", 0))
                    cat_wins = int(category.get("wins", 0))
                    cat_ties = int(category.get("ties", 0))
                    record[f"{key}_elo"] = float(size_ratings[key].get(artist, DEFAULT_ELO))
                    record[f"{key}_duels"] = cat_rounds
                    record[f"{key}_wr"] = (
                        (cat_wins + 0.5 * cat_ties) / cat_rounds * 100.0
                        if cat_rounds else 0.0
                    )
                artist_records.append(record)

            combination_records: List[dict] = []
            for entry in combo_entries:
                artists_list = list(entry.get("artists", []))
                combo_id = self.combination_elo.combination_id(artists_list)
                comparisons = int(entry.get("comparisons", 0))
                wins = int(entry.get("wins", 0))
                ties = int(entry.get("ties", 0))
                losses = int(entry.get("losses", max(0, comparisons - wins - ties)))
                confidence_label, confidence_factor = confidence_info(comparisons)
                synergy = self.top_search.synergies.get(self.top_search.combo_id(artists_list), {})
                combination_records.append({
                    "artists": " + ".join(artists_list),
                    "combo_id": combo_id,
                    "favorite": combo_id in favorite_combination_keys,
                    "size": len(artists_list),
                    "elo": float(entry.get("rating", DEFAULT_ELO)),
                    "synergy_mu": float(synergy.get("mu", 0.0)),
                    "synergy_sigma": float(synergy.get("sigma", TOP_SKILL_SYNERGY_SIGMA)),
                    "duels": comparisons,
                    "wins": wins,
                    "losses": losses,
                    "ties": ties,
                    "win_rate": (wins + ties * 0.5) / comparisons * 100.0 if comparisons else 0.0,
                    "weighted_wr": float(weighted_combo_stats.get(combo_id, {}).get("weighted_win_rate", 0.0)),
                    "confidence": confidence_label,
                    "confidence_factor": confidence_factor,
                })

            # Automatic categories are recomputed from the current ranking. Rank tiers
            # are exclusive to avoid redundant Top 1 + Top 10 + Top 20 clutter.
            for rank, record in enumerate(
                sorted(artist_records, key=lambda item: item["top_score"], reverse=True), 1
            ):
                badges: List[dict] = []
                rank_badge = rank_badge_for_position(rank) if int(record.get("duels", 0)) > 0 else None
                if rank_badge:
                    badges.append(rank_badge)
                if has_great_newcomer_potential(record, "overall_elo"):
                    badges.append({"label": "Great potential", "icon": "⚡", "css": "badge-potential"})
                badges.extend(additional_performance_badges(record))
                reason_counts = rotation_reason_counts.get(record["artist"], {})
                performance_count = int(reason_counts.get("performance", 0))
                discovery_count = int(reason_counts.get("discovery", 0))
                coverage_count = int(reason_counts.get("coverage_release", 0))
                capacity_count = int(reason_counts.get("capacity_trim", 0))
                unknown_count = int(reason_counts.get("legacy_unknown", 0))
                if performance_count:
                    badges.append({"label": f"Performance rotation ({performance_count}×)", "icon": "▼", "css": "badge-rotated"})
                if discovery_count:
                    badges.append({"label": f"Discovery release ({discovery_count}×)", "icon": "↻", "css": "badge-rotated"})
                if coverage_count:
                    badges.append({"label": f"Coverage release ({coverage_count}×)", "icon": "↪", "css": "badge-rotated"})
                if capacity_count:
                    badges.append({"label": f"Capacity trim ({capacity_count}×)", "icon": "⇥", "css": "badge-rotated"})
                if unknown_count:
                    badges.append({"label": f"Historical rotation — reason unknown ({unknown_count}×)", "icon": "?", "css": "badge-rotated"})
                if record["stage"] == "Elite":
                    badges.append({"label": "Elite reservoir", "icon": "♛", "css": "badge-top10"})
                elif self.top_search.is_promising_under_tested(record["artist"], top_cutoff):
                    badges.append({"label": "Verification candidate", "icon": "↥", "css": "badge-potential"})
                manual_tags = list(manual_artist_tags.get(record["artist"], []))
                for tag_id in manual_tags:
                    info = MANUAL_STYLE_TAGS[tag_id]
                    badges.append({"label": info["label"], "icon": info["icon"], "css": info["css"]})
                record["rank"] = rank
                record["manual_tags"] = manual_tags
                entered_duel, top50_tenure, top50_approximate = self._top50_entry_info(record["artist"])
                total_system_duels = len(self.history.records)
                top50_streak_duels = max(0, total_system_duels - entered_duel) if rank <= TOP_TARGET_RANK else 0
                record["top50_entered_duel"] = entered_duel
                record["top50_tenure"] = top50_tenure
                record["top50_streak_duels"] = top50_streak_duels
                record["top50_approximate"] = top50_approximate
                if (
                    rank <= TOP_TARGET_RANK
                    and not top50_approximate
                    and top50_streak_duels <= TOP50_RECENT_BADGE_DUELS
                ):
                    badges.append({
                        "label": f"New Top 50 · {top50_streak_duels:,} duels",
                        "icon": "↗",
                        "css": "badge-top50-new",
                    })
                record["badges"] = badges
                record["badge_html"] = render_category_badges(badges)
                manual_labels = [MANUAL_STYLE_TAGS[tag_id]["label"] for tag_id in manual_tags if tag_id in MANUAL_STYLE_TAGS]
                badge_labels = [str(badge.get("label", "")) for badge in badges]
                record["note"] = artist_note_entries.get(record["artist"], "")
                record["search_blob"] = " ".join(
                    [record["artist"], record["note"], *manual_tags, *manual_labels, *badge_labels]
                ).casefold()

            for rank, record in enumerate(
                sorted(combination_records, key=lambda item: item["elo"], reverse=True), 1
            ):
                badges = []
                rank_badge = rank_badge_for_position(rank)
                if rank_badge:
                    badges.append(rank_badge)
                if has_great_newcomer_potential(record, "elo"):
                    badges.append({"label": "Great potential", "icon": "⚡", "css": "badge-potential"})
                badges.extend(additional_performance_badges(record))
                manual_tags = list(manual_combination_tags.get(record["combo_id"], []))
                for tag_id in manual_tags:
                    info = MANUAL_STYLE_TAGS[tag_id]
                    badges.append({"label": info["label"], "icon": info["icon"], "css": info["css"]})
                record["rank"] = rank
                record["manual_tags"] = manual_tags
                record["badges"] = badges
                record["badge_html"] = render_category_badges(badges)

            self.artist_browser_records_cache = artist_records
            self.combination_browser_records_cache = combination_records
            self.browser_cache_stamp = stamp

    @staticmethod
    def _parse_row_limit(value: Any, available_count: int) -> int:
        if str(value).strip().casefold() == "all":
            return max(0, available_count)
        try:
            return max(1, int(value))
        except (TypeError, ValueError):
            return min(100, max(1, available_count))

    def get_artist_browser_data(
        self,
        sort_by: str = "Top-search score",
        direction: str = "Descending",
        search_text: str = "",
        minimum_duels: Any = 0,
        maximum_duels: Any = None,
        minimum_score: Any = None,
        maximum_score: Any = None,
        row_limit: Any = "50",
        page: int = 1,
    ) -> Tuple[List[List[Any]], str, int]:
        """Return sortable/filterable artist rows from a cached flat index."""
        self._ensure_browser_records_cache()

        def _optional_int(value: Any) -> Optional[int]:
            if value is None:
                return None
            text = str(value).strip()
            if not text:
                return None
            try:
                return int(float(text))
            except (TypeError, ValueError):
                return None

        def _optional_float(value: Any) -> Optional[float]:
            if value is None:
                return None
            text = str(value).strip()
            if not text:
                return None
            try:
                return float(text)
            except (TypeError, ValueError):
                return None

        query = (search_text or "").strip().casefold()
        minimum_duels_value = max(0, _optional_int(minimum_duels) or 0)
        maximum_duels_value = _optional_int(maximum_duels)
        if maximum_duels_value is not None:
            maximum_duels_value = max(0, maximum_duels_value)
        minimum_score_value = _optional_float(minimum_score)
        maximum_score_value = _optional_float(maximum_score)
        with self.browser_cache_lock:
            source_records = list(self.artist_browser_records_cache)
        records = [
            record for record in source_records
            if (not query or _boolean_search_matches(query, record.get("search_blob", record)))
            and record["duels"] >= minimum_duels_value
            and (maximum_duels_value is None or record["duels"] <= maximum_duels_value)
            and (minimum_score_value is None or record["top_score"] >= minimum_score_value)
            and (maximum_score_value is None or record["top_score"] <= maximum_score_value)
        ]

        sort_keys = {
            "Top-search score": lambda r: r["top_score"],
            "Potential score": lambda r: r["potential_score"],
            "Top-50 probability": lambda r: r["top50_probability"],
            "Uncertainty": lambda r: r["top_sigma"],
            "Stage": lambda r: ({"Unseen": 0, "Opening": 1, "Screening": 2, "Qualification": 3, "Established": 4}.get(str(r.get("stage", "")), -1), r["top_score"]),
            "Overall ELO": lambda r: r["overall_elo"],
            "Score rate": lambda r: r["win_rate"],
            "Win rate": lambda r: r["win_rate"],
            "Weighted win rate": lambda r: r["weighted_wr"],
            "Duels fought": lambda r: r["duels"],
            "Wins": lambda r: r["wins"],
            "Confidence": lambda r: (r["confidence_factor"], r["duels"]),
            "Solo ELO": lambda r: r["solo_elo"],
            "Solo win rate": lambda r: r["solo_wr"],
            "Solo duels": lambda r: r["solo_duels"],
            "Duo ELO": lambda r: r["duo_elo"],
            "Duo win rate": lambda r: r["duo_wr"],
            "Duo duels": lambda r: r["duo_duels"],
            "Trio ELO": lambda r: r["trio_elo"],
            "Trio win rate": lambda r: r["trio_wr"],
            "Trio duels": lambda r: r["trio_duels"],
            "Favorites first": lambda r: (r["favorite"], r["top_score"]),
            "Alphabetical": lambda r: r["artist"].casefold(),
        }
        key_function = sort_keys.get(sort_by, sort_keys["Top-search score"])
        reverse = direction != "Ascending"
        records.sort(key=key_function, reverse=reverse)

        total_matching = len(records)
        page_size = self._parse_row_limit(row_limit, max(1, total_matching))
        total_pages = max(1, (total_matching + page_size - 1) // page_size)
        try:
            current_page = int(page or 1)
        except (TypeError, ValueError):
            current_page = 1
        current_page = max(1, min(total_pages, current_page))
        start_index = (current_page - 1) * page_size
        page_records = records[start_index:start_index + page_size]
        rows = []
        for index, record in enumerate(page_records, start_index + 1):
            rows.append([
                index,
                "★" if record["favorite"] else "",
                record.get("badge_html", ""),
                record["artist"],
                round(record["top_score"], 1),
                round(record["potential_score"], 1),
                f"{record['top_mu']:.1f} ± {record['top_sigma']:.1f}",
                round(record["top50_probability"] * 100.0, 1),
                record["stage"],
                round(record["overall_elo"], 1),
                record["duels"],
                f"{record['wins']}–{record['losses']}–{record['ties']}",
                round(record["win_rate"], 1),
                round(record["weighted_wr"], 1),
                record["confidence"],
                f"{record['solo_elo']:.1f} · {record['solo_wr']:.1f}% · {record['solo_duels']}",
                f"{record['duo_elo']:.1f} · {record['duo_wr']:.1f}% · {record['duo_duels']}",
                f"{record['trio_elo']:.1f} · {record['trio_wr']:.1f}% · {record['trio_duels']}",
            ])

        filter_bits = [f"minimum {minimum_duels_value} duels"]
        if maximum_duels_value is not None:
            filter_bits.append(f"maximum {maximum_duels_value} duels")
        if minimum_score_value is not None:
            filter_bits.append(f"minimum top score {minimum_score_value:.1f}")
        if maximum_score_value is not None:
            filter_bits.append(f"maximum top score {maximum_score_value:.1f}")
        summary = (
            f"**Page {current_page} of {total_pages} — showing {len(rows)} of {total_matching} matching artists.**  "
            f"Sorted by **{sort_by}** ({direction.casefold()}); "
            f"{'; '.join(filter_bits)}."
        )
        return rows, summary, current_page

    @staticmethod
    def render_artist_links(artists: Iterable[str], css_class: str = "elo-duel-artist-link") -> str:
        """Render artist names as safe contextual navigation controls."""
        rendered = []
        for artist in artists or []:
            artist_text = str(artist)
            attr = html.escape(artist_text, quote=True)
            label = html.escape(artist_text)
            rendered.append(
                f'<button type="button" class="elo-artist-link {css_class}" '
                f'data-artist="{attr}" title="Open artist">{label}</button>'
            )
        return ", ".join(rendered)

    def render_artist_browser_html(
        self,
        rows: List[List[Any]],
        sort_by: str = "Top-search score",
        direction: str = "Descending",
    ) -> str:
        """Render the Artist table with server-backed clickable sort headers."""
        if not rows:
            return '<div class="artist-html-empty">No matching artists on this page.</div>'
        header_specs = [
            ("#", None),
            ("★", "Favorites first"),
            ("Categories", None),
            ("Artist", "Alphabetical"),
            ("Top score", "Top-search score"),
            ("Potential", "Potential score"),
            ("μ ± σ", "Uncertainty"),
            ("Top-50", "Top-50 probability"),
            ("Stage", "Stage"),
            ("Legacy ELO", "Overall ELO"),
            ("Duels", "Duels fought"),
            ("Record", "Wins"),
            ("Score rate", "Score rate"),
            ("Weighted WR", "Weighted win rate"),
            ("Confidence", "Confidence"),
            ("Solo / Duo / Trio — ELO · WR · duels", None),
        ]
        active_arrow = "▲" if str(direction) == "Ascending" else "▼"
        parts = ['<div class="browser-html-scroll"><table class="browser-html-table artist-html-table"><thead><tr>']
        for label, sort_key in header_specs:
            escaped_label = html.escape(label)
            if sort_key is None:
                parts.append(f"<th>{escaped_label}</th>")
                continue
            escaped_sort = html.escape(sort_key, quote=True)
            is_active = sort_key == sort_by
            aria_sort = (
                "ascending" if is_active and str(direction) == "Ascending"
                else "descending" if is_active
                else "none"
            )
            arrow_html = (
                f'<span class="artist-sort-arrow" aria-hidden="true">{active_arrow}</span>'
                if is_active else ""
            )
            parts.append(
                f'<th data-artist-sort="{escaped_sort}" aria-sort="{aria_sort}" '
                f'title="Sort by {escaped_sort}">{escaped_label}{arrow_html}</th>'
            )
        parts.append("</tr></thead><tbody>")
        for row in rows:
            size_summary = (
                '<div class="size-stats-horizontal">'
                f'<span class="size-stat"><strong>S:</strong> {html.escape(str(row[15]))}</span>'
                f'<span class="size-stat"><strong>D:</strong> {html.escape(str(row[16]))}</span>'
                f'<span class="size-stat"><strong>T:</strong> {html.escape(str(row[17]))}</span>'
                '</div>'
            )
            artist_text = str(row[3])
            artist_attr = html.escape(artist_text, quote=True)
            artist_label = html.escape(artist_text)
            favorite_symbol = "★" if str(row[1]).strip() else "☆"
            portrait_url = self.artist_portraits.get_data_url(artist_text)
            initials = "".join(part[:1] for part in re.split(r"[\s_\-]+", artist_text) if part)[:2].upper() or "?"
            portrait_html = (
                f'<img class="artist-row-portrait" src="{html.escape(portrait_url, quote=True)}" '
                f'alt="" loading="lazy">'
                if portrait_url else
                f'<span class="artist-row-portrait artist-row-portrait-placeholder">{html.escape(initials)}</span>'
            )
            top50_title = ""
            try:
                record_match = next(
                    (item for item in self.artist_browser_records_cache if item.get("artist") == artist_text),
                    None,
                )
                if (
                    record_match
                    and int(record_match.get("rank", TOP_TARGET_RANK + 1)) <= TOP_TARGET_RANK
                ):
                    qualifier = (
                        "Tracked current Top-50 streak"
                        if record_match.get("top50_approximate")
                        else "Current Top-50 streak"
                    )
                    top50_title = f" · {qualifier}: {record_match.get('top50_tenure', '')}"
            except Exception:
                top50_title = ""
            artist_button = (
                f'<button type="button" class="elo-artist-link elo-artist-gallery-link" '
                f'data-artist="{artist_attr}" title="{artist_attr} — open duels in Gallery{html.escape(top50_title, quote=True)}">'
                f'{portrait_html}<span class="artist-row-name">{artist_label}</span></button>'
            )
            favorite_button = (
                f'<button type="button" class="elo-star-action" data-kind="artist" '
                f'data-key="{artist_attr}" data-label="{artist_attr}" '
                f'title="Toggle favorite">{favorite_symbol}</button>'
            )
            cells = [
                html.escape(str(row[0])), favorite_button, row[2], artist_button,
                html.escape(str(row[4])), html.escape(str(row[5])), html.escape(str(row[6])),
                html.escape(f"{row[7]}%"), html.escape(str(row[8])), html.escape(str(row[9])),
                html.escape(str(row[10])), html.escape(str(row[11])), html.escape(f"{row[12]}%"),
                html.escape(f"{row[13]}%"), html.escape(str(row[14])), size_summary,
            ]
            parts.append(f'<tr data-artist="{artist_attr}">')
            for index, value in enumerate(cells):
                if index == 2:
                    parts.append(f'<td class="category-cell">{value}</td>')
                elif index == 15:
                    parts.append(f'<td class="artist-size-cell">{value}</td>')
                else:
                    parts.append(f"<td>{value}</td>")
            parts.append("</tr>")
        parts.append("</tbody></table></div>")
        return "".join(parts)

    def get_artist_browser_view(
        self,
        sort_by: str = "Top-search score",
        direction: str = "Descending",
        search_text: str = "",
        minimum_duels: Any = 0,
        maximum_duels: Any = None,
        minimum_score: Any = None,
        maximum_score: Any = None,
        row_limit: Any = "50",
        page: int = 1,
    ):
        rows, summary, current_page = self.get_artist_browser_data(
            sort_by, direction, search_text, minimum_duels, maximum_duels,
            minimum_score, maximum_score, row_limit, page,
        )
        artist_choices = [str(row[3]) for row in rows]
        return (
            self.render_artist_browser_html(rows, sort_by, direction),
            summary,
            current_page,
            gr.update(choices=artist_choices, value=None),
        )

    def get_combination_browser_data(
        self,
        sort_by: str = "Combination ELO",
        direction: str = "Descending",
        search_text: str = "",
        minimum_duels: int = 0,
        combination_size: str = "All sizes",
        row_limit: Any = "50",
        page: int = 1,
    ) -> Tuple[List[List[Any]], str, int]:
        """Return sortable/filterable exact-combination rows from a cached flat index."""
        self._ensure_browser_records_cache()

        query = (search_text or "").strip().casefold()
        minimum_duels = max(0, int(minimum_duels or 0))
        size_filter = {"Solo only": 1, "Duos only": 2, "Trios only": 3}.get(combination_size)
        note_snapshot = self.entity_notes.snapshot()
        combination_note_entries = note_snapshot.get("combination", {})
        with self.favorites.lock:
            combination_favorite_entries = deepcopy(self.favorites.data.get("combination", {}))
        with self.browser_cache_lock:
            source_records = list(self.combination_browser_records_cache)
        records = [
            record for record in source_records
            if (not query or _boolean_search_matches(query, [record, combination_note_entries.get(str(record.get("combo_id", "")), {}), combination_favorite_entries.get(str(record.get("combo_id", "")), {})]))
            and (size_filter is None or record["size"] == size_filter)
            and record["duels"] >= minimum_duels
        ]

        sort_keys = {
            "Combination ELO": lambda r: r["elo"],
            "Learned synergy": lambda r: r["synergy_mu"],
            "Win rate": lambda r: r["win_rate"],
            "Weighted win rate": lambda r: r["weighted_wr"],
            "Duels fought": lambda r: r["duels"],
            "Wins": lambda r: r["wins"],
            "Confidence": lambda r: (r["confidence_factor"], r["duels"]),
            "Combination size": lambda r: r["size"],
            "Favorites first": lambda r: (r["favorite"], r["elo"]),
            "Alphabetical": lambda r: r["artists"].casefold(),
        }
        key_function = sort_keys.get(sort_by, sort_keys["Combination ELO"])
        reverse = direction != "Ascending"
        records.sort(key=key_function, reverse=reverse)

        total_matching = len(records)
        page_size = self._parse_row_limit(row_limit, max(1, total_matching))
        total_pages = max(1, (total_matching + page_size - 1) // page_size)
        try:
            current_page = int(page or 1)
        except (TypeError, ValueError):
            current_page = 1
        current_page = max(1, min(total_pages, current_page))
        start_index = (current_page - 1) * page_size
        page_records = records[start_index:start_index + page_size]
        rows = []
        for index, record in enumerate(page_records, start_index + 1):
            size_label = {1: "Solo", 2: "Duo", 3: "Trio"}.get(record["size"], str(record["size"]))
            rows.append([
                index,
                "★" if record["favorite"] else "",
                record.get("badge_html", ""),
                record["artists"],
                size_label,
                round(record["elo"], 1),
                f"{record['synergy_mu']:+.1f} ± {record['synergy_sigma']:.1f}",
                record["duels"],
                f"{record['wins']}–{record['losses']}–{record['ties']}",
                round(record["win_rate"], 1),
                round(record["weighted_wr"], 1),
                record["confidence"],
                record["combo_id"],
            ])

        summary = (
            f"**Page {current_page} of {total_pages} — showing {len(rows)} of {total_matching} matching combinations.**  "
            f"Sorted by **{sort_by}** ({direction.casefold()}); minimum {minimum_duels} duels; "
            f"filter: **{combination_size}**."
        )
        return rows, summary, current_page

    @staticmethod
    def render_combination_browser_html(
        rows: List[List[Any]],
        sort_by: str = "Combination ELO",
        direction: str = "Descending",
    ) -> str:
        """Render the Combinations table with server-backed clickable sort headers."""
        if not rows:
            return '<div class="browser-html-empty">No matching combinations on this page.</div>'
        header_specs = [
            ("#", None),
            ("★", "Favorites first"),
            ("Categories", None),
            ("Artists", "Alphabetical"),
            ("Size", "Combination size"),
            ("Combination ELO", "Combination ELO"),
            ("Learned synergy", "Learned synergy"),
            ("Duels", "Duels fought"),
            ("Record", "Wins"),
            ("Score rate", "Win rate"),
            ("Weighted WR", "Weighted win rate"),
            ("Confidence", "Confidence"),
        ]
        active_arrow = "▲" if str(direction) == "Ascending" else "▼"
        parts = ['<div class="browser-html-scroll"><table class="browser-html-table combination-html-table"><thead><tr>']
        for label, sort_key in header_specs:
            escaped_label = html.escape(label)
            if sort_key is None:
                parts.append(f"<th>{escaped_label}</th>")
                continue
            escaped_sort = html.escape(sort_key, quote=True)
            is_active = sort_key == sort_by
            aria_sort = (
                "ascending" if is_active and str(direction) == "Ascending"
                else "descending" if is_active
                else "none"
            )
            arrow_html = (
                f'<span class="combination-sort-arrow" aria-hidden="true">{active_arrow}</span>'
                if is_active else ""
            )
            parts.append(
                f'<th data-combination-sort="{escaped_sort}" aria-sort="{aria_sort}" '
                f'title="Sort by {escaped_sort}">{escaped_label}{arrow_html}</th>'
            )
        parts.append("</tr></thead><tbody>")
        for row in rows:
            combination_text = str(row[3])
            combination_key = str(row[12]) if len(row) > 12 else ""
            combo_attr = html.escape(combination_text, quote=True)
            key_attr = html.escape(combination_key, quote=True)
            favorite_symbol = "★" if str(row[1]).strip() else "☆"
            combination_button = (
                f'<button type="button" class="elo-combination-link elo-combination-gallery-link" '
                f'data-combination="{combo_attr}" data-key="{key_attr}" '
                f'title="Open this exact combination in Gallery">{html.escape(combination_text)}</button>'
            )
            favorite_button = (
                f'<button type="button" class="elo-star-action" data-kind="combination" '
                f'data-key="{key_attr}" data-label="{combo_attr}" title="Toggle favorite">{favorite_symbol}</button>'
            )
            values = [
                html.escape(str(row[0])), favorite_button, row[2], combination_button,
                html.escape(str(row[4])), html.escape(str(row[5])), html.escape(str(row[6])),
                html.escape(str(row[7])), html.escape(str(row[8])), html.escape(f"{row[9]}%"),
                html.escape(f"{row[10]}%"), html.escape(str(row[11])),
            ]
            parts.append(f'<tr data-combination="{combo_attr}" data-key="{key_attr}">')
            for index, value in enumerate(values):
                if index == 2:
                    parts.append(f'<td class="category-cell">{value}</td>')
                else:
                    parts.append(f"<td>{value}</td>")
            parts.append("</tr>")
        parts.append("</tbody></table></div>")
        return "".join(parts)

    def get_combination_browser_view(
        self,
        sort_by: str = "Combination ELO",
        direction: str = "Descending",
        search_text: str = "",
        minimum_duels: int = 0,
        combination_size: str = "All sizes",
        row_limit: Any = "50",
        page: int = 1,
    ):
        rows, summary, current_page = self.get_combination_browser_data(
            sort_by, direction, search_text, minimum_duels, combination_size, row_limit, page,
        )
        choices = [str(row[3]) for row in rows]
        return (
            self.render_combination_browser_html(rows, sort_by, direction),
            summary,
            current_page,
            gr.update(choices=choices, value=None),
        )

    def format_current_duel_type(self) -> str:
        """Describe the matchmaking category of the duel currently on screen."""
        with self.state_lock:
            current = self.current_comparison
            if current is None:
                return "**Duel type:** No duel is currently ready."
            reason = str(current.matchmaking_reason or "Historical / unknown")
            details = str(current.matchmaking_details or "").strip()
            score = float(current.matchmaking_score or 0.0)

        lines = [f"**Duel type:** {reason}"]
        if details:
            lines.append(details)
        if score:
            lines.append(f"*Matchmaking selection score: {score:.2f}*")
        return "  \n".join(lines)

    def build_full_ui_state(self):
        """Build all outputs needed by the main UI."""
        snapshot = self._get_current_snapshot()
        has_current = snapshot["image_a"] is not None and snapshot["image_b"] is not None
        artists_a_text = (
            f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_a"], "elo-duel-artist-link")}'
            if snapshot["artists_a"] else ""
        )
        artists_b_text = (
            f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_b"], "elo-duel-artist-link")}'
            if snapshot["artists_b"] else ""
        )
        favorite_artist_update, favorite_tags, favorite_note, favorite_status = (
            self.get_compare_favorite_editor("Duel — both images", "")
        )
        manual_style_update, manual_style_status = self.get_compare_manual_style_editor(
            "Duel — both images", ""
        )

        return (
            snapshot["image_a"],
            snapshot["image_b"],
            self.format_status_message(),
            self.format_top_artists_display(),
            self.format_pool_activity_display(),
            snapshot["result_msg"],
            snapshot["details_msg"],
            gr.update(interactive=has_current),
            gr.update(interactive=has_current),
            gr.update(interactive=snapshot["undo_available"]),
            artists_a_text,
            artists_b_text,
            self.format_current_duel_type(),
            self.format_recent_history(),
            self.format_top_combinations_display(),
            gr.update(value="Duel — both images"),
            favorite_artist_update,
            favorite_tags,
            favorite_note,
            favorite_status,
            manual_style_update,
            manual_style_status,
        )

    def build_action_ui_state(self, trace: Optional[Any] = None):
        """Build the lightweight Compare outputs used after vote, skip, or undo."""
        snapshot = self._get_current_snapshot()
        if trace:
            trace.mark("ui_snapshot")
        has_current = snapshot["image_a"] is not None and snapshot["image_b"] is not None
        artists_a_text = (
            f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_a"], "elo-duel-artist-link")}'
            if snapshot["artists_a"] else ""
        )
        artists_b_text = (
            f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_b"], "elo-duel-artist-link")}'
            if snapshot["artists_b"] else ""
        )
        if trace:
            trace.mark("ui_artist_links")
        favorite_artist_update, favorite_tags, favorite_note, favorite_status = (
            self.get_compare_favorite_editor("Duel — both images", "")
        )
        if trace:
            trace.mark("ui_favorite_editor")
        manual_style_update, manual_style_status = self.get_compare_manual_style_editor(
            "Duel — both images", ""
        )
        if trace:
            trace.mark("ui_manual_style_editor")
        status_value = self.format_status_message()
        duel_type_value = self.format_current_duel_type()
        if trace:
            trace.mark("ui_status_and_duel_type")
        return (
            snapshot["image_a"],
            snapshot["image_b"],
            status_value,
            snapshot["result_msg"],
            snapshot["details_msg"],
            gr.update(interactive=has_current),
            gr.update(interactive=has_current),
            gr.update(interactive=snapshot["undo_available"]),
            artists_a_text,
            artists_b_text,
            duel_type_value,
            gr.update(value="Duel — both images"),
            favorite_artist_update,
            favorite_tags,
            favorite_note,
            favorite_status,
            manual_style_update,
            manual_style_status,
        )

    def build_poll_ui_state(self):
        """Return only lightweight fields that can change while images generate."""
        snapshot = self._get_current_snapshot()
        has_current = snapshot["image_a"] is not None and snapshot["image_b"] is not None
        artists_a_text = (
            f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_a"], "elo-duel-artist-link")}'
            if snapshot["artists_a"] else ""
        )
        artists_b_text = (
            f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_b"], "elo-duel-artist-link")}'
            if snapshot["artists_b"] else ""
        )
        return (
            snapshot["image_a"],
            snapshot["image_b"],
            self.format_status_message(),
            gr.update(interactive=has_current),
            gr.update(interactive=has_current),
            gr.update(interactive=snapshot["undo_available"]),
            artists_a_text,
            artists_b_text,
            self.format_current_duel_type(),
        )

    # -------------------------------------------------------------------------
    # Actions: pick / skip / undo / poll / export
    # -------------------------------------------------------------------------

    @staticmethod
    def _result_delta_class(value: float) -> str:
        value = float(value or 0.0)
        if value > 0.0001:
            return "positive"
        if value < -0.0001:
            return "negative"
        return ""

    @staticmethod
    def _humanize_stage(value: str) -> str:
        return str(value or "Unrated").replace("_", " ").strip().title()

    def _build_structured_duel_result(
        self,
        selected: ComparisonItem,
        winner: str,
        old_ratings: Dict[str, float],
        top_changes: Dict[str, Any],
        combination_changes: Dict[str, float],
        rotated_out: List[dict],
        rotated_in: List[dict],
    ) -> Tuple[str, str]:
        """Render a compact, card-based result summary for a completed duel."""
        winner = str(winner or "").upper()
        side_a = list(selected.artists_a)
        side_b = list(selected.artists_b)
        side_a_label = " + ".join(side_a)
        side_b_label = " + ".join(side_b)

        if winner == "BOTH_BAD":
            banner = (
                '<div class="duel-outcome-banner bad">'
                '<div class="duel-outcome-icon">✕</div>'
                '<div class="duel-outcome-copy">'
                '<div class="duel-outcome-label">Duel complete</div>'
                '<div class="duel-outcome-title">Both outputs were rejected</div>'
                '<div class="duel-outcome-subtitle">No side was judged better. For compatibility, Legacy ELO and exact-combination ratings record a tie; the Bayesian ranker adds poor-output reliability evidence to every participating artist and does not directly move relative skill μ.</div>'
                '</div></div>'
            )
        elif winner == "TIE":
            banner = (
                '<div class="duel-outcome-banner tie">'
                '<div class="duel-outcome-icon">≈</div>'
                '<div class="duel-outcome-copy">'
                '<div class="duel-outcome-label">Duel complete</div>'
                '<div class="duel-outcome-title">Tie — too close to call</div>'
                '<div class="duel-outcome-subtitle">Both sides gained evaluation evidence; neither side received a win.</div>'
                '</div></div>'
            )
        else:
            winner_label = side_a_label if winner == "A" else side_b_label
            loser_label = side_b_label if winner == "A" else side_a_label
            banner = (
                '<div class="duel-outcome-banner">'
                '<div class="duel-outcome-icon">🏆</div>'
                '<div class="duel-outcome-copy">'
                '<div class="duel-outcome-label">Winner</div>'
                f'<div class="duel-outcome-title">{html.escape(winner_label)}</div>'
                f'<div class="duel-outcome-subtitle">Defeated {html.escape(loser_label)}</div>'
                '</div></div>'
            )

        cutoff = self.top_search.cutoff_score()
        generation_snapshot = deepcopy(selected.generation_config) if isinstance(selected.generation_config, dict) else {}
        profile_name = str(generation_snapshot.get("profile_name", "") or "").strip() or "Manual settings"
        meta_items = [
            ("Seed", f"<code>{int(selected.seed)}</code>"),
            ("Generation profile", html.escape(profile_name)),
            ("Generation", html.escape(_generation_config_summary(generation_snapshot))),
            ("Matchmaking", html.escape(str(selected.matchmaking_reason or "Unspecified"))),
            ("Top-50 cutoff", f"μ {cutoff:.0f}"),
        ]
        meta_html = "".join(
            '<div class="duel-meta-item">'
            f'<span class="duel-meta-label">{label}</span>'
            f'<span class="duel-meta-value">{value}</span>'
            '</div>'
            for label, value in meta_items
        )

        def side_card(side_name: str, artists: List[str]) -> str:
            side_is_winner = winner == side_name
            side_is_bad = winner == "BOTH_BAD"
            side_is_tie = winner == "TIE"
            state_class = "bad" if side_is_bad else ("tie" if side_is_tie else ("winner" if side_is_winner else "loser"))
            badge_text = "Both bad" if side_is_bad else ("Tie" if side_is_tie else ("Winner" if side_is_winner else "Runner-up"))
            combo_label = " + ".join(artists)
            artist_rows: List[str] = []
            for artist in artists:
                top_delta = float(top_changes.get("artist_changes", {}).get(artist, 0.0))
                legacy_old = float(old_ratings.get(artist, self.elo_system.get_rating(artist)))
                legacy_new = float(self.elo_system.get_rating(artist))
                legacy_delta = legacy_new - legacy_old
                mu = self.top_search.get_mu(artist)
                sigma = self.top_search.get_sigma(artist)
                conservative = self.top_search.conservative_score(artist)
                potential = self.top_search.potential_score(artist)
                probability = self.top_search.top_k_probability(artist) * 100.0
                stage = self._humanize_stage(self.top_search.stage(artist))
                top_delta_class = self._result_delta_class(top_delta)
                legacy_delta_class = self._result_delta_class(legacy_delta)
                artist_rows.append(
                    '<div class="duel-artist-result">'
                    '<div class="duel-artist-name">'
                    f'<button type="button" class="elo-artist-link elo-duel-artist-link" '
                    f'data-artist="{html.escape(str(artist), quote=True)}" title="Open artist">'
                    f'{html.escape(str(artist))}</button>'
                    f'<span class="duel-stage-pill">{html.escape(stage)}</span>'
                    '</div>'
                    '<div class="duel-primary-metrics">'
                    '<div class="duel-metric" title="Current estimated artist skill">'
                    '<span class="duel-metric-label">Skill μ</span>'
                    f'<span class="duel-metric-value {top_delta_class}">{mu:.0f} <small>({top_delta:+.1f})</small></span>'
                    '</div>'
                    '<div class="duel-metric" title="Probability this artist exceeds the current qualified Top-50 cutoff">'
                    '<span class="duel-metric-label">Top-50 chance</span>'
                    f'<span class="duel-metric-value">{probability:.1f}%</span>'
                    '</div>'
                    '<div class="duel-metric" title="Skill estimate penalized for uncertainty">'
                    '<span class="duel-metric-label">Conservative</span>'
                    f'<span class="duel-metric-value">{conservative:.0f}</span>'
                    '</div>'
                    '</div>'
                    '<div class="duel-secondary-row">'
                    f'<span><strong>Potential:</strong> {potential:.0f}</span>'
                    f'<span><strong>Uncertainty σ:</strong> {sigma:.0f}</span>'
                    f'<span><strong>Legacy ELO:</strong> {legacy_new:.0f} '
                    f'<span class="{legacy_delta_class}">({legacy_delta:+.1f})</span></span>'
                    '</div>'
                    '</div>'
                )

            combo_id = self.combination_elo.combination_id(artists)
            combo_entry = self.combination_elo.entries.get(combo_id, {})
            synergy = self.top_search.synergies.get(self.top_search.combo_id(artists), {})
            combo_delta = float(combination_changes.get(combo_id, 0.0))
            combo_rating = float(combo_entry.get("rating", DEFAULT_ELO))
            synergy_mu = float(synergy.get("mu", 0.0))
            synergy_sigma = float(synergy.get("sigma", TOP_SKILL_SYNERGY_SIGMA))
            return (
                f'<section class="duel-side-card {state_class}">'
                '<div class="duel-side-header"><div>'
                f'<div class="duel-side-kicker">Image {side_name}</div>'
                f'<div class="duel-side-title">{html.escape(combo_label)}</div>'
                '</div>'
                f'<span class="duel-result-badge {state_class}">{badge_text}</span></div>'
                f'<div class="duel-artist-stack">{"".join(artist_rows)}</div>'
                '<div class="duel-combo-footer">'
                f'<strong>Combination ELO:</strong> {combo_rating:.0f} ({combo_delta:+.1f}) &nbsp;·&nbsp; '
                f'<strong>Learned synergy:</strong> {synergy_mu:+.1f} ± {synergy_sigma:.0f}'
                '</div></section>'
            )

        details = [
            '<div class="duel-results-shell">',
            f'<div class="duel-meta-strip">{meta_html}</div>',
            '<div class="duel-side-grid">',
            side_card("A", side_a),
            side_card("B", side_b),
            '</div>',
        ]
        if selected.matchmaking_details:
            details.append(
                '<div class="duel-matchmaking-details"><strong>Why this matchup:</strong> '
                f'{html.escape(str(selected.matchmaking_details))}</div>'
            )
        if rotated_out or rotated_in:
            details.append('<div class="duel-rotation-panel">')
            if rotated_out:
                items = "".join(
                    '<li>'
                    f'<strong>{html.escape(str(item.get("artist", "")))}</strong> — '
                    f'{html.escape(str(item.get("reason", "Unknown reason")))}; '
                    f'Top-50 chance {float(item.get("top50_probability", 0.0)) * 100:.1f}%, '
                    f'potential {float(item.get("potential_score", 0.0)):.0f}'
                    '</li>'
                    for item in rotated_out
                )
                details.append(
                    '<div class="duel-rotation-card out"><div class="duel-rotation-title">Rotated out</div>'
                    f'<ul class="duel-rotation-list">{items}</ul></div>'
                )
            if rotated_in:
                items = "".join(
                    '<li>'
                    f'<strong>{html.escape(str(item.get("artist", "")))}</strong> — '
                    f'{html.escape(str(item.get("entry_reason", "Unknown reason")))}'
                    '</li>'
                    for item in rotated_in
                )
                details.append(
                    '<div class="duel-rotation-card in"><div class="duel-rotation-title">Rotated in</div>'
                    f'<ul class="duel-rotation-list">{items}</ul></div>'
                )
            details.append('</div>')
        details.append('</div>')
        return banner, "".join(details)

    def _schedule_bayesian_refit_if_due(self) -> None:
        """Fit a detached snapshot, then apply only if competitive state is unchanged."""
        if not self.top_search.is_refit_due():
            return
        if self.bayesian_refit_thread is not None and self.bayesian_refit_thread.is_alive():
            return
        with self.state_lock:
            snapshot = self.top_search.snapshot()
            generation = int(self.bayesian_refit_generation)
            evidence_length = len(snapshot.get("evidence", []))
        def worker() -> None:
            try:
                candidate = TopSearchRatingSystem(
                    artists=deepcopy(snapshot.get("artists", {})),
                    synergies=deepcopy(snapshot.get("synergies", {})),
                    evidence=deepcopy(snapshot.get("evidence", [])),
                    comparison_count=int(snapshot.get("comparison_count", 0) or 0),
                    refit_interval=int(snapshot.get("refit_interval", 500) or 500),
                    _last_refit_evidence=int(snapshot.get("last_refit_evidence", 0) or 0),
                )
                candidate.refit_global(max_iterations=35)
                with self.state_lock:
                    if (
                        generation != self.bayesian_refit_generation
                        or len(self.top_search.evidence) != evidence_length
                        or self.top_search.comparison_count != candidate.comparison_count
                    ):
                        return
                    self.top_search.artists = candidate.artists
                    self.top_search.synergies = candidate.synergies
                    self.top_search._last_refit_evidence = candidate._last_refit_evidence
                    self.top_search._last_refit_error = candidate._last_refit_error
                    self.top_search.invalidate_ranking_cache()
                    self.matchmaker.scheduler.refresh_global_cache(force=True)
                    self._refresh_top50_tracking()
                self._schedule_persistence(sections={"ratings", "top50", "pool"})
            except Exception as exc:
                self.last_error_details = f"Bayesian global refit failed: {type(exc).__name__}: {exc}"
                self.top_search._last_refit_error = str(exc)
            finally:
                self.bayesian_refit_thread = None
                # A vote may have arrived while this detached snapshot was fitting.
                if self.top_search.is_refit_due():
                    self._schedule_bayesian_refit_if_due()
        self.bayesian_refit_thread = threading.Thread(
            target=worker,
            name="bayesian-global-refit",
            daemon=True,
        )
        self.bayesian_refit_thread.start()

    def pick_winner_and_advance(self, winner: str, trace: Optional[Any] = None):
        """Process an A/B/tie result across legacy and top-search rating systems."""
        winner = str(winner or "").upper()
        if winner not in ("A", "B", "TIE", "BOTH_BAD"):
            self.ui_result_msg = "Unsupported result."
            self.ui_details_msg = ""
            if trace:
                trace.mark("unsupported_result")
            return

        lock_wait_started = time.perf_counter()
        with self.state_lock:
            if trace:
                trace.mark(
                    "state_lock_acquired",
                    lock_wait_ms=round((time.perf_counter() - lock_wait_started) * 1000.0, 3),
                )
            if self.current_comparison is None:
                self.ui_result_msg = "No active comparison. Wait for the next duel to finish generating."
                self.ui_details_msg = ""
                if trace:
                    trace.mark("no_active_comparison")
                return

            selected = self.current_comparison
            is_both_bad = winner == "BOTH_BAD"
            stored_winner = "TIE" if is_both_bad else winner
            if winner == "A":
                winners = selected.artists_a
                losers = selected.artists_b
            elif winner == "B":
                winners = selected.artists_b
                losers = selected.artists_a
            else:
                winners = []
                losers = []

            unique_artists = list(dict.fromkeys(selected.artists_a + selected.artists_b))
            old_ratings = {artist: self.elo_system.get_rating(artist) for artist in unique_artists}
            old_comparisons = {
                artist: self.elo_system.get_artist_comparison_count(artist)
                for artist in unique_artists
            }
            old_size_state = self.elo_system.snapshot_size_state(unique_artists)
            old_combination_entries = self.combination_elo.snapshot([
                selected.artists_a,
                selected.artists_b,
            ])
            old_top_search_state = self.top_search.snapshot_entities(
                unique_artists,
                [selected.artists_a, selected.artists_b],
            )
            old_pool_state = (
                self.artist_manager.active_pool.snapshot_runtime_state()
                if self.artist_manager.active_pool is not None
                else {}
            )
            if trace:
                trace.mark("undo_state_snapshots", artists=len(unique_artists))

            result_weight_a = weighted_result_weight(
                self.combination_elo.get_rating(selected.artists_b),
                self.combination_elo.get_comparison_count(selected.artists_b),
            )
            result_weight_b = weighted_result_weight(
                self.combination_elo.get_rating(selected.artists_a),
                self.combination_elo.get_comparison_count(selected.artists_a),
            )
            if trace:
                trace.mark("result_weights")

            if winner in ("TIE", "BOTH_BAD"):
                rating_changes = self.elo_system.update_tie_ratings(
                    selected.artists_a,
                    selected.artists_b,
                )
                combination_changes = self.combination_elo.update_tie_ratings(
                    selected.artists_a,
                    selected.artists_b,
                )
            else:
                rating_changes = self.elo_system.update_ratings(winners, losers)
                combination_changes = self.combination_elo.update_ratings(winners, losers)
            if trace:
                trace.mark("legacy_and_combination_ratings")

            top_changes = self.top_search.update_result(
                selected.artists_a,
                selected.artists_b,
                winner,
            )
            self._refresh_top50_tracking()
            if trace:
                trace.mark("top_search_update")

            rotated_out, rotated_in = self.artist_manager.process_result(
                selected.artists_a,
                selected.artists_b,
            )
            if trace:
                trace.mark(
                    "pool_rotation",
                    rotated_out=len(rotated_out),
                    rotated_in=len(rotated_in),
                )
            rotation_event_ids: List[str] = []
            for removal in rotated_out:
                event_id = self.classifications.mark_rotated_out(
                    str(removal.get("artist", "")),
                    str(removal.get("reason", "legacy_unknown")),
                    removal,
                )
                rotation_event_ids.append(event_id)
                self.rotation_log.insert(0, {"direction": "out", **deepcopy(removal)})
            for entry in rotated_in:
                event_id = self.classifications.mark_rotated_in(
                    str(entry.get("artist", "")),
                    str(entry.get("entry_reason", "unknown")),
                    entry,
                )
                rotation_event_ids.append(event_id)
                self.rotation_log.insert(0, {"direction": "in", **deepcopy(entry)})
            self.rotation_log = self.rotation_log[:30]
            if trace:
                trace.mark("classification_and_rotation_log")

            self.last_undo_state = UndoState(
                winners=winners.copy(),
                losers=losers.copy(),
                old_ratings=old_ratings,
                old_comparisons=old_comparisons,
                old_size_state=old_size_state,
                old_combination_entries=old_combination_entries,
                old_top_search_state=old_top_search_state,
                old_pool_state=old_pool_state,
                rotated_out=[str(item.get("artist", "")) for item in rotated_out],
                rotated_in=[str(item.get("artist", "")) for item in rotated_in],
                rotation_event_ids=rotation_event_ids,
                selected_comparison=selected,
            )
            if trace:
                trace.mark("undo_state_created")

            record = ComparisonRecord(
                timestamp=time.time(),
                artists_a=selected.artists_a,
                artists_b=selected.artists_b,
                winner=stored_winner,
                image_a_path=selected.image_a_path,
                image_b_path=selected.image_b_path,
                duel_id=selected.duel_id,
                seed=selected.seed,
                rotation_preset=selected.rotation_preset,
                prompt_a=selected.prompt_a,
                prompt_b=selected.prompt_b,
                negative_prompt=selected.negative_prompt,
                quality_toggle=selected.quality_toggle,
                uc_preset=selected.uc_preset,
                generation_config=deepcopy(selected.generation_config),
                matchmaking_reason=selected.matchmaking_reason,
                matchmaking_details=selected.matchmaking_details,
                matchmaking_score=selected.matchmaking_score,
                result_weight_a=result_weight_a,
                result_weight_b=result_weight_b,
                legacy_rating_changes=dict(rating_changes.get("overall", {})),
                top_search_rating_changes=dict(top_changes.get("artist_changes", {})),
                combination_rating_changes=dict(combination_changes),
                top_search_expected_a=float(top_changes.get("expected_a", 0.5)),
                both_bad=is_both_bad,
            )
            self.history.add_record(record, save_immediately=False)
            if trace:
                trace.mark("history_append", history_count=len(self.history.records))
            self._refresh_current_duel_favorite_metadata_after_vote(
                selected, stored_winner, len(self.history.records)
            )
            if trace:
                trace.mark("favorite_metadata_refresh")

            self.ui_result_msg, self.ui_details_msg = self._build_structured_duel_result(
                selected,
                winner,
                old_ratings,
                top_changes,
                combination_changes,
                rotated_out,
                rotated_in,
            )
            if trace:
                trace.mark("result_html_build")
            self._advance_to_next_comparison_locked()
            comparison_count = int(self.elo_system.comparison_count)
            if trace:
                trace.mark(
                    "buffer_advance",
                    buffer_ready=self._buffered_count_locked(),
                    queue_length=len(self.comparison_queue),
                )

        if trace:
            trace.mark("state_lock_released")
        self._schedule_bayesian_refit_if_due()
        self._schedule_persistence(comparison_count)
        if trace:
            trace.mark("persistence_scheduled")
        self.start_refill_if_needed()
        if trace:
            trace.mark("refill_requested")

    def mark_invalid_and_advance(self, trace: Optional[Any] = None):
        """Record an unusable duel without adding any rating or rotation evidence."""
        lock_wait_started = time.perf_counter()
        with self.state_lock:
            if trace:
                trace.mark("state_lock_acquired", lock_wait_ms=round((time.perf_counter() - lock_wait_started) * 1000.0, 3))
            if self.current_comparison is None:
                self.ui_result_msg = "No active comparison to mark invalid."
                self.ui_details_msg = ""
                return
            selected = self.current_comparison
            record = ComparisonRecord(
                timestamp=time.time(),
                artists_a=selected.artists_a,
                artists_b=selected.artists_b,
                winner="INVALID",
                image_a_path=selected.image_a_path,
                image_b_path=selected.image_b_path,
                duel_id=selected.duel_id,
                seed=selected.seed,
                rotation_preset=selected.rotation_preset,
                prompt_a=selected.prompt_a,
                prompt_b=selected.prompt_b,
                negative_prompt=selected.negative_prompt,
                quality_toggle=selected.quality_toggle,
                uc_preset=selected.uc_preset,
                generation_config=deepcopy(selected.generation_config),
                matchmaking_reason=selected.matchmaking_reason,
                matchmaking_details=selected.matchmaking_details,
                matchmaking_score=selected.matchmaking_score,
                result_weight_a=0.0,
                result_weight_b=0.0,
            )
            self.history.add_record(record, save_immediately=False)
            if trace:
                trace.mark("history_append", history_count=len(self.history.records))
            self.last_undo_state = None
            self.ui_result_msg = "**Invalid duel recorded.** No ratings, confidence, or rotation decisions were changed."
            self.ui_details_msg = "The images remain in Gallery for auditing, but the duel contributes no ranking evidence."
            self._advance_to_next_comparison_locked()
            if trace:
                trace.mark("buffer_advance", buffer_ready=self._buffered_count_locked(), queue_length=len(self.comparison_queue))
        if trace:
            trace.mark("state_lock_released")
        self._schedule_persistence(sections={"history", "buffer"})
        if trace:
            trace.mark("persistence_scheduled")
        self.start_refill_if_needed()
        if trace:
            trace.mark("refill_requested")

    def skip_current_comparison(self, trace: Optional[Any] = None):
        """Skip current duel, persist the remaining buffer, and advance."""
        lock_wait_started = time.perf_counter()
        with self.state_lock:
            if trace:
                trace.mark("state_lock_acquired", lock_wait_ms=round((time.perf_counter() - lock_wait_started) * 1000.0, 3))
            if self.current_comparison is None:
                self.ui_result_msg = "No active comparison to skip."
                self.ui_details_msg = ""
                return

            self.ui_result_msg = "**Skipped current duel.**"
            self.ui_details_msg = ""
            self._advance_to_next_comparison_locked()
            if trace:
                trace.mark("buffer_advance", buffer_ready=self._buffered_count_locked(), queue_length=len(self.comparison_queue))

        if trace:
            trace.mark("state_lock_released")
        self._schedule_persistence(sections={"buffer"})
        if trace:
            trace.mark("persistence_scheduled")
        self.start_refill_if_needed()
        if trace:
            trace.mark("refill_requested")

    def undo_last_selection(self):
        """Undo the last selection across overall, size and combination ratings."""
        with self.state_lock:
            self.bayesian_refit_generation += 1
            if not self.last_undo_state:
                self.ui_result_msg = "Nothing to undo."
                self.ui_details_msg = ""
                return

            state = self.last_undo_state
            for artist, old_rating in state.old_ratings.items():
                self.elo_system.ratings[artist] = old_rating
            for artist, old_count in state.old_comparisons.items():
                self.elo_system.artist_comparisons[artist] = old_count
            self.elo_system.restore_size_state(state.old_size_state)
            self.combination_elo.restore(state.old_combination_entries)
            self.top_search.restore_entities(state.old_top_search_state)
            self._refresh_top50_tracking()

            self.elo_system.comparison_count = max(0, self.elo_system.comparison_count - 1)

            if state.old_pool_state and self.artist_manager.active_pool is not None:
                self.artist_manager.active_pool.restore_runtime_state(state.old_pool_state, refresh=False)
            else:
                if state.rotated_out:
                    self.artist_manager.restore_artists(state.rotated_out)
                if state.rotated_in:
                    self.artist_manager.remove_artists(state.rotated_in)
            for event_id in reversed(state.rotation_event_ids):
                self.classifications.undo_rotation_event(event_id)

            if self.history.records:
                self.history.records.pop()

            if self.current_comparison is not None:
                self.comparison_queue.appendleft(self.current_comparison)
            if state.selected_comparison is not None:
                self.current_comparison = state.selected_comparison

            self.last_undo_state = None
            self.ui_result_msg = "**Undone!** Pick again."
            self.ui_details_msg = ""

        self._schedule_persistence()
        self.start_refill_if_needed()

    def export_csv_file(self) -> str:
        """Export artist leaderboard as a downloadable CSV file."""
        content = self.export_leaderboard_csv()
        filepath = COMPARISON_IMAGES_DIR / "leaderboard_export.csv"
        filepath.parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, "w", encoding="utf-8-sig", newline="") as f:
            f.write(content)
        return str(filepath)

    def export_combination_csv_file(self) -> str:
        """Export combination leaderboard as a downloadable CSV file."""
        content = self.export_combination_leaderboard_csv()
        filepath = COMPARISON_IMAGES_DIR / "combination_leaderboard_export.csv"
        filepath.parent.mkdir(parents=True, exist_ok=True)
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
        return str(filepath)
