    COMPARE_FAVORITE_TARGETS = (
        "Duel — both images",
        "Image A",
        "Image B",
        "Combination A",
        "Combination B",
        "Individual artist",
    )

    def _ensure_current_duel_id_locked(self, item: ComparisonItem) -> str:
        """Ensure buffered comparisons have a stable ID before they enter history."""
        if item.duel_id:
            return item.duel_id
        payload = {
            "image_a_path": item.image_a_path,
            "image_b_path": item.image_b_path,
            "artists_a": item.artists_a,
            "artists_b": item.artists_b,
            "seed": item.seed,
        }
        item.duel_id = hashlib.sha1(
            json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
        ).hexdigest()[:20]
        self._schedule_persistence(sections={"buffer"})
        return item.duel_id

    def _resolve_compare_favorite_target(
        self, target_label: str, artist_name: str = ""
    ) -> Tuple[Optional[dict], List[str]]:
        """Resolve a Compare-tab target against the duel currently on screen."""
        target_label = str(target_label or "Duel — both images")
        artist_name = str(artist_name or "").strip()
        with self.state_lock:
            item = self.current_comparison
            if item is None:
                return None, []
            duel_id = self._ensure_current_duel_id_locked(item)
            artists_a = list(item.artists_a)
            artists_b = list(item.artists_b)
            artist_choices = list(dict.fromkeys(artists_a + artists_b))
            base_metadata = {
                "duel_id": duel_id,
                "image_a_path": item.image_a_path,
                "image_b_path": item.image_b_path,
                "artists_a": artists_a,
                "artists_b": artists_b,
                "winner": "Unrated / current",
                "seed": item.seed,
                "timestamp": item.created_at,
                "rotation_preset": item.rotation_preset,
                "matchmaking_reason": item.matchmaking_reason,
            }

            if target_label == "Duel — both images":
                target = {
                    "kind": "duel",
                    "key": duel_id,
                    "label": f"Current duel: {' + '.join(artists_a)} vs {' + '.join(artists_b)}",
                    "metadata": base_metadata,
                }
            elif target_label == "Image A":
                target = {
                    "kind": "image",
                    "key": str(Path(item.image_a_path)),
                    "label": f"Image A — {' + '.join(artists_a)}",
                    "metadata": {
                        **base_metadata, "path": item.image_a_path, "side": "A", "artists": artists_a
                    },
                }
            elif target_label == "Image B":
                target = {
                    "kind": "image",
                    "key": str(Path(item.image_b_path)),
                    "label": f"Image B — {' + '.join(artists_b)}",
                    "metadata": {
                        **base_metadata, "path": item.image_b_path, "side": "B", "artists": artists_b
                    },
                }
            elif target_label in ("Combination A", "Combination B"):
                side_artists = artists_a if target_label.endswith("A") else artists_b
                normalized = self.combination_elo.normalize_artists(side_artists)
                combo_id = self.combination_elo.combination_id(normalized)
                target = {
                    "kind": "combination",
                    "key": combo_id,
                    "label": " + ".join(normalized),
                    "metadata": {"artists": normalized},
                }
            elif target_label == "Individual artist":
                if artist_name not in artist_choices:
                    artist_name = artist_choices[0] if artist_choices else ""
                if not artist_name:
                    return None, artist_choices
                target = {
                    "kind": "artist",
                    "key": artist_name,
                    "label": artist_name,
                    "metadata": {"artist": artist_name},
                }
            else:
                return None, artist_choices

        return target, artist_choices

    def get_compare_favorite_editor(
        self, target_label: str = "Duel — both images", artist_name: str = ""
    ) -> Tuple[Any, str, str, str]:
        """Populate the Compare-tab favorite editor for the current duel."""
        target, artist_choices = self._resolve_compare_favorite_target(target_label, artist_name)
        show_artist = str(target_label) == "Individual artist"
        selected_artist = str(artist_name or "").strip()
        if show_artist and selected_artist not in artist_choices:
            selected_artist = artist_choices[0] if artist_choices else None
        artist_update = gr.update(
            choices=artist_choices,
            value=selected_artist if show_artist else None,
            visible=show_artist,
        )
        if target is None:
            status = (
                "No duel is ready yet." if not artist_choices
                else "Select a valid favorite target."
            )
            return artist_update, "", "", status
        tags, note, status = self.get_favorite_fields(target["kind"], target["key"])
        return artist_update, tags, note, status

    def save_compare_favorite(
        self, target_label: str, artist_name: str, tags: Any, note: str
    ) -> str:
        target, _ = self._resolve_compare_favorite_target(target_label, artist_name)
        if target is None:
            return "No current duel or valid favorite target is available."
        return self.save_favorite_entry(
            target["kind"], target["key"], target["label"], tags, note, target.get("metadata", {})
        )

    def remove_compare_favorite(self, target_label: str, artist_name: str) -> str:
        target, _ = self._resolve_compare_favorite_target(target_label, artist_name)
        if target is None:
            return "No current duel or valid favorite target is available."
        return self.remove_favorite_entry(target["kind"], target["key"])

    def get_compare_manual_style_editor(self, target_label: str, artist_name: str):
        """Load manual tags for an artist/combination in the current duel."""
        target, _ = self._resolve_compare_favorite_target(target_label, artist_name)
        if target is None:
            return gr.update(value=[], interactive=False), "No current duel or valid target is available."
        if target["kind"] not in ("artist", "combination"):
            return (
                gr.update(value=[], interactive=False),
                "Manual tags apply only to an individual artist or an exact combination.",
            )
        labels = self.get_manual_style_labels(target["kind"], target["key"])
        return gr.update(value=labels, interactive=True), f"Editing manual tags for **{target['label']}**."

    def save_compare_manual_style_tags(
        self, target_label: str, artist_name: str, selected_labels: Any
    ) -> str:
        target, _ = self._resolve_compare_favorite_target(target_label, artist_name)
        if target is None:
            return "No current duel or valid target is available."
        if target["kind"] not in ("artist", "combination"):
            return "Choose **Individual artist**, **Combination A**, or **Combination B** first."
        return self.save_manual_style_tags(target["kind"], target["key"], selected_labels)

    def _refresh_current_duel_favorite_metadata_after_vote(
        self, item: ComparisonItem, winner: str, history_number: int
    ) -> None:
        """Add the final winner/history number to favorites created before voting."""
        duel_id = item.duel_id
        base_metadata = {
            "duel_id": duel_id,
            "history_number": history_number,
            "image_a_path": item.image_a_path,
            "image_b_path": item.image_b_path,
            "artists_a": list(item.artists_a),
            "artists_b": list(item.artists_b),
            "winner": winner,
            "seed": item.seed,
            "timestamp": item.created_at,
            "rotation_preset": item.rotation_preset,
            "matchmaking_reason": item.matchmaking_reason,
        }
        refresh_targets = [
            (
                "duel", duel_id,
                f"Duel #{history_number}: {' + '.join(item.artists_a)} vs {' + '.join(item.artists_b)}",
                base_metadata,
            ),
            (
                "image", str(Path(item.image_a_path)),
                f"Image A — {' + '.join(item.artists_a)}",
                {**base_metadata, "path": item.image_a_path, "side": "A", "artists": list(item.artists_a)},
            ),
            (
                "image", str(Path(item.image_b_path)),
                f"Image B — {' + '.join(item.artists_b)}",
                {**base_metadata, "path": item.image_b_path, "side": "B", "artists": list(item.artists_b)},
            ),
        ]
        for kind, key, label, metadata in refresh_targets:
            existing = self.favorites.get(kind, key)
            if existing:
                self.favorites.set(
                    kind, key, label, existing.get("tags", []), existing.get("note", ""), metadata
                )
        self._invalidate_favorite_dependent_caches()

    def _invalidate_favorite_dependent_caches(self) -> None:
        # Favorite changes do not alter any rating statistics. Update only the
        # lightweight bookmark flags instead of rebuilding history aggregations.
        with self.browser_cache_lock:
            for record in self.artist_browser_records_cache:
                record["favorite"] = self.favorites.is_favorite("artist", record["artist"])
            for record in self.combination_browser_records_cache:
                record["favorite"] = self.favorites.is_favorite("combination", record["combo_id"])
        with self.gallery_cache_lock:
            self.gallery_cache_stamp = None

    @staticmethod
    def _favorite_kind_label(kind: str) -> str:
        return {
            "artist": "Artist",
            "combination": "Combination",
            "image": "Image",
            "duel": "Duel",
        }.get(kind, kind.title())

    def get_favorite_fields(self, kind: str, key: str) -> Tuple[str, str, str]:
        entry = self.favorites.get(kind, key) if kind and key else None
        if not entry:
            return "", "", "Not currently favorited."
        tags = ", ".join(entry.get("tags", []))
        note = str(entry.get("note", ""))
        return tags, note, f"★ Saved {self._favorite_kind_label(kind).casefold()} favorite."

    def save_favorite_entry(
        self,
        kind: str,
        key: str,
        label: str,
        tags: Any,
        note: str,
        metadata: Optional[dict] = None,
    ) -> str:
        if not kind or not key:
            return "Select an item first."
        try:
            entry = self.favorites.set(kind, key, label, tags, note, metadata)
            self._invalidate_favorite_dependent_caches()
            return (
                f"★ Saved {self._favorite_kind_label(kind).casefold()} favorite "
                f"with {len(entry.get('tags', []))} tag(s)."
            )
        except Exception as e:
            return f"Could not save favorite: {e}"

    def remove_favorite_entry(self, kind: str, key: str) -> str:
        if not kind or not key:
            return "Select an item first."
        removed = self.favorites.remove(kind, key)
        self._invalidate_favorite_dependent_caches()
        return "Favorite removed." if removed else "That item was not favorited."

    def select_artist_for_favorite(self, artist: str) -> Tuple[str, str, str, str]:
        artist = str(artist or "").strip()
        if not artist:
            return "", "", "", "Select an artist row first."
        tags, note, status = self.get_favorite_fields("artist", artist)
        return artist, tags, note, status

    def save_artist_favorite(self, artist: str, tags: Any, note: str) -> str:
        artist = str(artist or "").strip()
        return self.save_favorite_entry(
            "artist", artist, artist, tags, note, {"artist": artist}
        )

    def remove_artist_favorite(self, artist: str) -> str:
        return self.remove_favorite_entry("artist", str(artist or "").strip())

    def select_combination_for_favorite(self, combination_text: str) -> Tuple[str, str, str, str, str]:
        artists = [part.strip() for part in str(combination_text or "").split("+") if part.strip()]
        if not artists:
            return "", "", "", "", "Select a combination row first."
        normalized = self.combination_elo.normalize_artists(artists)
        combo_id = self.combination_elo.combination_id(normalized)
        label = " + ".join(normalized)
        tags, note, status = self.get_favorite_fields("combination", combo_id)
        return label, combo_id, tags, note, status

    def save_combination_favorite(self, combination_text: str, combination_key: str, tags: Any, note: str) -> str:
        artists = [part.strip() for part in str(combination_text or "").split("+") if part.strip()]
        normalized = self.combination_elo.normalize_artists(artists)
        combo_id = combination_key or (self.combination_elo.combination_id(normalized) if normalized else "")
        label = " + ".join(normalized)
        return self.save_favorite_entry(
            "combination", combo_id, label, tags, note, {"artists": normalized}
        )

    def remove_combination_favorite(self, combination_key: str) -> str:
        return self.remove_favorite_entry("combination", combination_key)

    def get_manual_style_labels(self, kind: str, key: str) -> List[str]:
        return [
            MANUAL_STYLE_TAGS[tag_id]["label"]
            for tag_id in self.classifications.get_manual_tags(kind, key)
            if tag_id in MANUAL_STYLE_TAGS
        ]

    def save_manual_style_tags(self, kind: str, key: str, selected_labels: Any) -> str:
        key = str(key or "").strip()
        if not key:
            return "Select an item first."
        saved = self.classifications.set_manual_tags(kind, key, selected_labels)
        self.browser_cache_stamp = None
        labels = [MANUAL_STYLE_TAGS[tag_id]["label"] for tag_id in saved]
        if labels:
            return "Saved manual tags: " + ", ".join(labels)
        return "Manual tags cleared."

    def save_artist_manual_tags(self, artist: str, selected_labels: Any) -> str:
        return self.save_manual_style_tags("artist", str(artist or "").strip(), selected_labels)

    def save_combination_manual_tags(self, combination_key: str, selected_labels: Any) -> str:
        return self.save_manual_style_tags("combination", str(combination_key or "").strip(), selected_labels)

    def _ensure_gallery_records_cache(self) -> None:
        """Build the Gallery index once per history/favorites revision.

        This is deliberately single-flight: Gradio can fire several initial filter
        events at once, and concurrent full-history scans previously made Gallery
        appear to refresh forever. The index performs metadata-only availability
        checks and never creates thousands of thumbnails while listing duels.
        """
        stamp = (len(self.history.records), self.favorites.version)
        with self.gallery_cache_condition:
            if self.gallery_cache_stamp == stamp:
                return
            while self.gallery_cache_building_stamp is not None:
                self.gallery_cache_condition.wait(timeout=2.0)
                if self.gallery_cache_stamp == stamp:
                    return
            self.gallery_cache_building_stamp = stamp

        try:
            with self.state_lock:
                history_copy = [dict(record) for record in self.history.records]
            records: List[dict] = []
            for history_index, record in enumerate(history_copy):
                artists_a = list(record.get("artists_a", []))
                artists_b = list(record.get("artists_b", []))
                timestamp = float(record.get("timestamp", 0.0) or 0.0)
                duel_id = stable_duel_id(record)
                image_a = str(record.get("image_a_path", ""))
                image_b = str(record.get("image_b_path", ""))
                originals_available = Path(image_a).is_file() and Path(image_b).is_file()
                images_available = bool(
                    gallery_record_preview_exists(record, "A")
                    and gallery_record_preview_exists(record, "B")
                )
                preset = str(record.get("rotation_preset", "") or "")
                reason = str(record.get("matchmaking_reason", "Historical / unknown") or "Historical / unknown")
                winner = str(record.get("winner", "?") or "?")
                both_bad = bool(record.get("both_bad", False))
                search_blob = " ".join(
                    artists_a + artists_b + [preset, reason, winner, duel_id]
                ).casefold()
                records.append({
                    "history_number": history_index + 1,
                    "history_index": history_index,
                    "duel_id": duel_id,
                    "timestamp": timestamp,
                    "date": time.strftime("%Y-%m-%d %H:%M", time.localtime(timestamp)) if timestamp else "Unknown",
                    "winner": winner,
                    "both_bad": both_bad,
                    "artists_a": artists_a,
                    "artists_b": artists_b,
                    "reason": reason,
                    "preset": preset,
                    "seed": int(record.get("seed", 0) or 0),
                    "images_available": images_available,
                    "originals_available": originals_available,
                    "favorite": self.favorites.is_favorite("duel", duel_id),
                    "search_blob": search_blob,
                })
            records.reverse()
        except Exception:
            with self.gallery_cache_condition:
                self.gallery_cache_building_stamp = None
                self.gallery_cache_condition.notify_all()
            raise

        with self.gallery_cache_condition:
            self.gallery_records_cache = records
            self.gallery_cache_stamp = stamp
            self.gallery_cache_building_stamp = None
            self.gallery_cache_condition.notify_all()

    def get_gallery_preset_choices(self) -> List[str]:
        """Return preset names seen in history or saved locally, without loading images."""
        with self.state_lock:
            history_presets = {
                str(record.get("rotation_preset", "") or "").strip()
                for record in self.history.records
                if str(record.get("rotation_preset", "") or "").strip()
            }
            saved_presets = set(self.saved_prompts.keys())
        names = sorted(history_presets | saved_presets, key=str.casefold)
        return ["All presets", "(No preset)"] + names

    @staticmethod
    def _normalize_gallery_artist_terms(value: Any) -> List[str]:
        """Normalize the custom multiselect value into unique artist-name tokens."""
        if value is None:
            raw_values: List[Any] = []
        elif isinstance(value, (list, tuple, set)):
            raw_values = list(value)
        else:
            raw_values = re.split(r"[,\n]+", str(value))

        normalized: List[str] = []
        seen = set()
        for raw in raw_values:
            # Also accept a pasted comma-separated value inside one custom chip.
            pieces = re.split(r"[,\n]+", str(raw))
            for piece in pieces:
                clean = piece.strip()
                folded = clean.casefold()
                if clean and folded not in seen:
                    seen.add(folded)
                    normalized.append(clean)
        return normalized

    @classmethod
    def _parse_gallery_artist_query(
        cls, value: Any
    ) -> Tuple[List[str], List[str], bool, str]:
        """Split normal artist chips or one ``VS`` separator into two sides."""
        tokens = cls._normalize_gallery_artist_terms(value)
        versus_indexes = [
            index for index, token in enumerate(tokens)
            if str(token).strip().casefold() == "vs"
        ]
        if not versus_indexes:
            return tokens, [], False, ""
        if len(versus_indexes) > 1:
            return [], [], True, "Use only one **VS** token in a Gallery matchup search."
        versus_index = versus_indexes[0]
        left = tokens[:versus_index]
        right = tokens[versus_index + 1:]
        if not left or not right:
            return [], [], True, "Place at least one artist on both sides of the **VS** token."
        return left, right, True, ""

    @staticmethod
    def _gallery_side_matches_artists(
        side_artists: List[str], selected_artists: List[str], exact_combination: bool
    ) -> bool:
        """Return whether one image side contains the requested artist set."""
        if not selected_artists:
            return True
        side_set = {str(artist).strip().casefold() for artist in side_artists if str(artist).strip()}
        selected_set = {str(artist).strip().casefold() for artist in selected_artists if str(artist).strip()}
        if exact_combination:
            return side_set == selected_set
        return selected_set.issubset(side_set)

    @staticmethod
    def _gallery_match_css(reason: str) -> str:
        value = str(reason or "").casefold()
        if "elite" in value:
            return "gallery-match-elite"
        if "gatekeeper" in value:
            return "gallery-match-gatekeeper"
        if "contender" in value:
            return "gallery-match-contender"
        if "retest" in value or "verification" in value:
            return "gallery-match-retest"
        if "screen" in value:
            return "gallery-match-screening"
        return ""

    @classmethod
    def _render_gallery_browser_html(cls, rows: List[List[Any]]) -> str:
        """Render an accessible, proportioned Gallery table independent of Gradio's Dataframe DOM."""
        if not rows:
            return '<div class="gallery-empty">No duels match the current filters.</div>'

        header_cells = "".join(
            f'<th scope="col">{html.escape(label)}</th>'
            for label in GALLERY_BROWSER_HEADERS
        )
        body_rows: List[str] = []
        for row in rows:
            padded = list(row) + [""] * max(0, len(GALLERY_BROWSER_HEADERS) - len(row))
            history_number, favorite, date_text, winner_text, matched_side, artists_a, artists_b, reason, preset, seed, images = padded[:11]
            outcome = str(winner_text or "").strip().upper()
            if outcome == "BOTH BAD":
                outcome_class = "bad"
                side_a_class = side_b_class = "gallery-side-bad"
                winner_label = "Both bad"
            elif outcome == "A":
                outcome_class = "winner"
                side_a_class, side_b_class = "gallery-side-winner", "gallery-side-loser"
                winner_label = "A"
            elif outcome == "B":
                outcome_class = "winner"
                side_a_class, side_b_class = "gallery-side-loser", "gallery-side-winner"
                winner_label = "B"
            elif outcome == "TIE":
                outcome_class = "tie"
                side_a_class = side_b_class = "gallery-side-tie"
                winner_label = "Tie"
            else:
                outcome_class = "invalid"
                side_a_class = side_b_class = "gallery-side-invalid"
                winner_label = "Invalid" if outcome == "INVALID" else str(winner_text or "—")

            match_class = cls._gallery_match_css(str(reason))
            values = [
                history_number, favorite, date_text, winner_label, matched_side,
                artists_a, artists_b, reason, preset or "—", seed, images,
            ]
            classes = [
                "gallery-center", "gallery-center gallery-star", "", f"gallery-center gallery-winner-cell {outcome_class}",
                "gallery-center", side_a_class, side_b_class,
                f"gallery-match-type {match_class}", "", "gallery-center", "gallery-center",
            ]
            cells = "".join(
                f'<td class="{classes[index]}" title="{html.escape(str(value), quote=True)}">{html.escape(str(value))}</td>'
                for index, value in enumerate(values)
            )
            body_rows.append(
                f'<tr tabindex="0" role="button" aria-label="Open duel {int(history_number)}" '
                f'data-history="{int(history_number)}">{cells}</tr>'
            )

        return (
            '<table class="gallery-duel-list" aria-label="Historical duels">'
            '<colgroup>'
            '<col style="width:5%"><col style="width:3%"><col style="width:10%"><col style="width:6%">'
            '<col style="width:6%"><col style="width:18%"><col style="width:18%"><col style="width:13%">'
            '<col style="width:11%"><col style="width:6%"><col style="width:4%">'
            '</colgroup>'
            f'<thead><tr>{header_cells}</tr></thead>'
            f'<tbody>{"".join(body_rows)}</tbody></table>'
        )

    def get_gallery_browser_data(
        self,
        artist_terms: Any = None,
        exact_combination: bool = False,
        preset_filter: str = "All presets",
        other_search: str = "",
        favorite_only: bool = False,
        searched_artist_lost_only: bool = False,
        winner_filter: str = "All winners",
        image_filter: str = "All records",
        size_filter: Any = None,
        row_limit: Any = "50",
        page: int = 1,
    ) -> Tuple[str, str, int]:
        self._ensure_gallery_records_cache()
        _gallery_boolean_artist_query = str(artist_terms or "").strip()
        _gallery_boolean_artist_mode = _looks_like_boolean_search(_gallery_boolean_artist_query)
        if _gallery_boolean_artist_mode:
            artist_terms = None
        left_artists, right_artists, versus_mode, artist_query_error = (
            self._parse_gallery_artist_query(artist_terms)
        )
        selected_artists = left_artists if not versus_mode else left_artists + right_artists
        text_query = str(other_search or "").strip().casefold()
        chosen_preset = str(preset_filter or "All presets").strip()

        if artist_query_error:
            return self._render_gallery_browser_html([]), f"**{artist_query_error}**", 1

        with self.gallery_cache_lock:
            records = list(self.gallery_records_cache)

        # Boolean artist query searches the complete Gallery record, including
        # artist names and every other value already indexed for this duel.
        if _gallery_boolean_artist_mode:
            records = [
                record for record in records
                if _boolean_search_matches(_gallery_boolean_artist_query, record)
            ]

        def side_matches(side: List[str], required: List[str]) -> bool:
            return self._gallery_side_matches_artists(side, required, bool(exact_combination))

        def versus_orientation(record: dict) -> str:
            artists_a = record.get("artists_a", [])
            artists_b = record.get("artists_b", [])
            if side_matches(artists_a, left_artists) and side_matches(artists_b, right_artists):
                return "A"
            if side_matches(artists_b, left_artists) and side_matches(artists_a, right_artists):
                return "B"
            return ""

        if versus_mode:
            records = [record for record in records if versus_orientation(record)]
        elif left_artists:
            records = [
                record for record in records
                if side_matches(record.get("artists_a", []), left_artists)
                or side_matches(record.get("artists_b", []), left_artists)
            ]

        if chosen_preset == "(No preset)":
            records = [record for record in records if not str(record.get("preset", "") or "").strip()]
        elif chosen_preset and chosen_preset != "All presets":
            preset_key = chosen_preset.casefold()
            records = [
                record for record in records
                if str(record.get("preset", "") or "").strip().casefold() == preset_key
            ]

        if text_query:
            records = [record for record in records if _boolean_search_matches(text_query, record.get("search_blob", record))]

        if searched_artist_lost_only:
            if not selected_artists:
                return (
                    self._render_gallery_browser_html([]),
                    "**Add at least one artist chip before using the lost-match filter.**",
                    1,
                )

            if versus_mode:
                def selected_side_lost(record: dict) -> bool:
                    orientation = versus_orientation(record)
                    winner = str(record.get("winner", "") or "").upper()
                    return (orientation == "A" and winner == "B") or (orientation == "B" and winner == "A")
            else:
                def selected_side_lost(record: dict) -> bool:
                    winner = str(record.get("winner", "") or "")
                    if winner == "A":
                        winning_artists = record.get("artists_a", [])
                        losing_artists = record.get("artists_b", [])
                    elif winner == "B":
                        winning_artists = record.get("artists_b", [])
                        losing_artists = record.get("artists_a", [])
                    else:
                        return False
                    return (
                        side_matches(losing_artists, left_artists)
                        and not side_matches(winning_artists, left_artists)
                    )

            records = [record for record in records if selected_side_lost(record)]

        if favorite_only:
            records = [record for record in records if record["favorite"]]

        if winner_filter in (
            "Selected artists won", "Selected artists lost",
            "Selected artists tied", "Both bad",
        ):
            if not selected_artists:
                return (
                    self._render_gallery_browser_html([]),
                    "**Add at least one artist before using a selected-side result filter.**",
                    1,
                )

            def selected_relative_result(record: dict) -> bool:
                outcome = "BOTH_BAD" if record.get("both_bad", False) else str(record.get("winner", "") or "").upper()
                if winner_filter == "Both bad":
                    return outcome == "BOTH_BAD"
                if winner_filter == "Selected artists tied":
                    return outcome == "TIE"
                if outcome not in ("A", "B"):
                    return False
                if versus_mode:
                    selected_side = versus_orientation(record)
                else:
                    a_match = side_matches(record.get("artists_a", []), left_artists)
                    b_match = side_matches(record.get("artists_b", []), left_artists)
                    selected_side = "A" if a_match and not b_match else "B" if b_match and not a_match else ""
                if not selected_side:
                    return False
                won = selected_side == outcome
                return won if winner_filter == "Selected artists won" else not won

            records = [record for record in records if selected_relative_result(record)]
        if winner_filter in ("Winner A", "Winner B"):
            wanted = winner_filter[-1]
            records = [record for record in records if record["winner"] == wanted]
        elif winner_filter == "Tie":
            records = [record for record in records if record["winner"] == "TIE"]
        elif winner_filter == "Invalid":
            records = [record for record in records if record["winner"] == "INVALID"]
        if image_filter == "Images available":
            records = [record for record in records if record["images_available"]]
        elif image_filter == "Missing images":
            records = [record for record in records if not record["images_available"]]

        size_values = size_filter if isinstance(size_filter, (list, tuple, set)) else [size_filter]
        size_lookup = {"solo": 1, "duo": 2, "trio": 3}
        selected_sizes = {
            size_lookup[str(value or "").strip().casefold()]
            for value in size_values
            if str(value or "").strip().casefold() in size_lookup
        }
        if selected_sizes:
            def matches_selected_sizes(record: dict) -> bool:
                side_sizes = {
                    len(list(record.get("artists_a", []) or [])),
                    len(list(record.get("artists_b", []) or [])),
                } - {0}
                # Normal history is 1v1, 2v2, or 3v3. For an unusual mixed-size
                # historical duel, every represented side size must be selected.
                return bool(side_sizes) and side_sizes.issubset(selected_sizes)

            records = [record for record in records if matches_selected_sizes(record)]

        total_matching = len(records)
        page_size = self._parse_row_limit(row_limit, max(1, total_matching))
        total_pages = max(1, (total_matching + page_size - 1) // page_size)
        try:
            current_page = max(1, min(total_pages, int(page or 1)))
        except (TypeError, ValueError):
            current_page = 1
        start = (current_page - 1) * page_size
        page_records = records[start:start + page_size]

        rows: List[List[Any]] = []
        for record in page_records:
            if versus_mode:
                orientation = versus_orientation(record)
                matched_side = "A vs B" if orientation == "A" else "B vs A" if orientation == "B" else ""
            else:
                matched_sides: List[str] = []
                if left_artists:
                    if side_matches(record.get("artists_a", []), left_artists):
                        matched_sides.append("A")
                    if side_matches(record.get("artists_b", []), left_artists):
                        matched_sides.append("B")
                matched_side = "+".join(matched_sides)
            rows.append([
                record["history_number"],
                "★" if record["favorite"] else "",
                record["date"],
                "BOTH BAD" if record.get("both_bad", False) else record["winner"],
                matched_side,
                " + ".join(record["artists_a"]),
                " + ".join(record["artists_b"]),
                record["reason"],
                record["preset"],
                record["seed"],
                "Ready" if record["images_available"] else "Missing",
            ])

        notes: List[str] = []
        match_word = "exactly" if exact_combination else "as part of each image side"
        if versus_mode:
            left_wins = right_wins = ties = both_bad_count = invalid_count = 0
            for record in records:
                orientation = versus_orientation(record)
                outcome = "BOTH_BAD" if record.get("both_bad", False) else str(record.get("winner", "") or "").upper()
                if outcome == "BOTH_BAD":
                    both_bad_count += 1
                elif outcome == "TIE":
                    ties += 1
                elif outcome == "INVALID":
                    invalid_count += 1
                elif (orientation == "A" and outcome == "A") or (orientation == "B" and outcome == "B"):
                    left_wins += 1
                elif outcome in ("A", "B"):
                    right_wins += 1
            notes.append(
                f"Versus filter: **{' + '.join(left_artists)} VS {' + '.join(right_artists)}** "
                f"({match_word}, either A/B orientation)."
            )
            notes.append(
                f"**Head-to-head:** {len(records)} matches · left won {left_wins} · right won {right_wins} · "
                f"{ties} ties · {both_bad_count} Both bad"
                + (f" · {invalid_count} invalid" if invalid_count else "")
                + "."
            )
        elif left_artists:
            notes.append(
                f"Artist filter: **{' + '.join(left_artists)}** "
                f"({'exactly' if exact_combination else 'together on the same image side'})."
            )
        if chosen_preset == "(No preset)":
            notes.append("Preset filter: **No rotation preset**.")
        elif chosen_preset and chosen_preset != "All presets":
            notes.append(f"Preset filter: **{chosen_preset}**.")
        if searched_artist_lost_only:
            if versus_mode:
                notes.append("Only duels where the artists left of VS lost to the artists right of VS are displayed.")
            else:
                notes.append(
                    "The selected artist set was only on the losing side in every displayed duel; "
                    "appearances on both sides are treated as neutral and excluded."
                )
        if winner_filter != "All winners":
            notes.append(f"Result filter: **{winner_filter}**.")
        if selected_sizes:
            readable_sizes = [label for label, value in (("Solo", 1), ("Duo", 2), ("Trio", 3)) if value in selected_sizes]
            notes.append(f"Duel sizes: **{', '.join(readable_sizes)}**.")

        summary = (
            f"**Page {current_page} of {total_pages} — showing {len(rows)} of {total_matching} matching duels.**  "
            "Click a row to open its duel viewer, or use Up/Down and Enter."
        )
        if notes:
            summary += "  " + " ".join(notes)
        return self._render_gallery_browser_html(rows), summary, current_page

    def _backfill_history_rating_changes_if_needed(self) -> int:
        """Replay history into temporary models and persist per-duel rating deltas.

        Older history records predate the Gallery duel viewer and therefore do not
        contain the exact legacy ELO, uncertainty-model, or combination changes
        produced by each duel. This one-time replay adds those values without
        mutating the live rating systems or active pool.
        """
        required_fields = (
            "legacy_rating_changes",
            "top_search_rating_changes",
            "combination_rating_changes",
            "top_search_expected_a",
        )
        needs_backfill = any(
            str(record.get("winner", "") or "").upper() in ("A", "B", "TIE")
            and not all(field_name in record for field_name in required_fields)
            for record in self.history.records
        )
        if not needs_backfill:
            return 0

        temp_elo = ELOSystem()
        temp_combination = CombinationELOSystem()
        temp_top_search = TopSearchRatingSystem()
        rebuilt: List[dict] = []
        rated_count = 0

        for original in self.history.records:
            record = deepcopy(original)
            artists_a = list(record.get("artists_a", []))
            artists_b = list(record.get("artists_b", []))
            winner = str(record.get("winner", "") or "").upper()
            if not artists_a or not artists_b or winner not in ("A", "B", "TIE"):
                record["legacy_rating_changes"] = {}
                record["top_search_rating_changes"] = {}
                record["combination_rating_changes"] = {}
                record["top_search_expected_a"] = 0.5
                rebuilt.append(record)
                continue

            if winner == "TIE":
                legacy_changes = temp_elo.update_tie_ratings(artists_a, artists_b)
                combination_changes = temp_combination.update_tie_ratings(artists_a, artists_b)
            else:
                winners = artists_a if winner == "A" else artists_b
                losers = artists_b if winner == "A" else artists_a
                legacy_changes = temp_elo.update_ratings(winners, losers)
                combination_changes = temp_combination.update_ratings(winners, losers)
            top_outcome = "BOTH_BAD" if bool(record.get("both_bad", False)) else winner
            top_changes = temp_top_search.update_result(artists_a, artists_b, top_outcome)

            record["legacy_rating_changes"] = {
                str(key): float(value)
                for key, value in legacy_changes.get("overall", {}).items()
            }
            record["top_search_rating_changes"] = {
                str(key): float(value)
                for key, value in top_changes.get("artist_changes", {}).items()
            }
            record["combination_rating_changes"] = {
                str(key): float(value)
                for key, value in combination_changes.items()
            }
            record["top_search_expected_a"] = float(top_changes.get("expected_a", 0.5))
            rebuilt.append(record)
            rated_count += 1

        self.history.records = rebuilt
        atomic_write_json(self.history.filepath, self.history.records)
        return rated_count

    def _rebuild_all_ratings_from_history_locked(self) -> int:
        """Replay valid history chronologically into the existing rating objects.

        The objects are reset in place because ActivePool and Matchmaker keep
        references to them. Weighted-win-rate opponent weights are recomputed at
        the rating state that existed immediately before each historical duel.
        """
        self.elo_system.ratings.clear()
        self.elo_system.comparison_count = 0
        self.elo_system.artist_comparisons.clear()
        self.elo_system.ratings_by_size = {key: {} for key in ELOSystem.SIZE_KEYS}
        self.elo_system.artist_comparisons_by_size = {
            key: {} for key in ELOSystem.SIZE_KEYS
        }
        self.combination_elo.entries.clear()
        self.top_search.artists.clear()
        self.top_search.synergies.clear()
        self.top_search.comparison_count = 0
        self.top_search.invalidate_ranking_cache()

        replayed = 0
        rebuilt_records: List[dict] = []
        for original_record in self.history.records:
            # Copy-on-write keeps any shallow snapshot already owned by the
            # persistence worker immutable while this correction is replayed.
            record = deepcopy(original_record)
            artists_a = list(record.get("artists_a", []))
            artists_b = list(record.get("artists_b", []))
            winner = str(record.get("winner", "") or "").upper()
            if not artists_a or not artists_b or winner not in ("A", "B", "TIE"):
                record["result_weight_a"] = 0.0
                record["result_weight_b"] = 0.0
                record["legacy_rating_changes"] = {}
                record["top_search_rating_changes"] = {}
                record["combination_rating_changes"] = {}
                record["top_search_expected_a"] = 0.5
                rebuilt_records.append(record)
                continue

            # These weights describe the opponent faced by each side and are
            # independent of which side won. Calculate before applying the duel.
            record["result_weight_a"] = weighted_result_weight(
                self.combination_elo.get_rating(artists_b),
                self.combination_elo.get_comparison_count(artists_b),
            )
            record["result_weight_b"] = weighted_result_weight(
                self.combination_elo.get_rating(artists_a),
                self.combination_elo.get_comparison_count(artists_a),
            )

            if winner == "TIE":
                legacy_changes = self.elo_system.update_tie_ratings(artists_a, artists_b)
                combination_changes = self.combination_elo.update_tie_ratings(artists_a, artists_b)
            else:
                winners = artists_a if winner == "A" else artists_b
                losers = artists_b if winner == "A" else artists_a
                legacy_changes = self.elo_system.update_ratings(winners, losers)
                combination_changes = self.combination_elo.update_ratings(winners, losers)
            top_outcome = "BOTH_BAD" if bool(record.get("both_bad", False)) else winner
            top_changes = self.top_search.update_result(artists_a, artists_b, top_outcome)
            record["legacy_rating_changes"] = {
                str(key): float(value)
                for key, value in legacy_changes.get("overall", {}).items()
            }
            record["top_search_rating_changes"] = {
                str(key): float(value)
                for key, value in top_changes.get("artist_changes", {}).items()
            }
            record["combination_rating_changes"] = {
                str(key): float(value)
                for key, value in combination_changes.items()
            }
            record["top_search_expected_a"] = float(top_changes.get("expected_a", 0.5))
            replayed += 1
            rebuilt_records.append(record)
        self.history.records = rebuilt_records
        return replayed

    def _update_corrected_duel_favorite_metadata(
        self,
        duel_id: str,
        history_number: int,
        winner: str,
        corrected_at: float,
    ) -> None:
        """Keep favorite duel/image metadata aligned with a corrected result."""
        changed = False
        snapshot = None
        with self.favorites.lock:
            for kind in ("duel", "image"):
                for entry in self.favorites.data.get(kind, {}).values():
                    metadata = entry.get("metadata", {})
                    same_duel = str(metadata.get("duel_id", "")) == str(duel_id)
                    try:
                        same_history = int(metadata.get("history_number", 0) or 0) == int(history_number)
                    except (TypeError, ValueError):
                        same_history = False
                    if not (same_duel or same_history):
                        continue
                    metadata["winner"] = winner
                    metadata["history_number"] = int(history_number)
                    metadata["corrected_at"] = float(corrected_at)
                    entry["metadata"] = metadata
                    entry["updated_at"] = time.time()
                    changed = True
            if changed:
                self.favorites.version += 1
                snapshot = deepcopy(self.favorites.data)
        if snapshot is not None:
            atomic_write_json(self.favorites.filepath, snapshot)
            self._invalidate_favorite_dependent_caches()

    def correct_historical_duel_result(
        self,
        history_number: Any,
        corrected_winner: str,
        confirmed: bool,
    ) -> str:
        """Change one stored outcome and rebuild all dependent rating statistics."""
        if not confirmed:
            return "Check the confirmation box before applying a historical correction."
        corrected_outcome = str(corrected_winner or "").upper().strip()
        if corrected_outcome not in ("A", "B", "TIE", "BOTH_BAD", "INVALID"):
            return (
                "Choose **Image A won**, **Image B won**, **Tie / too close**, "
                "**Both bad**, or **Invalid duel**."
            )
        try:
            index = int(history_number) - 1
        except (TypeError, ValueError):
            return "Load a valid historical duel first."

        with self.state_lock:
            if index < 0 or index >= len(self.history.records):
                return "That historical duel no longer exists. Refresh the gallery."
            original_record = self.history.records[index]
            previous_winner = str(original_record.get("winner", "") or "").upper()
            previous_outcome = (
                "BOTH_BAD" if bool(original_record.get("both_bad", False)) else previous_winner
            )
            if previous_outcome == corrected_outcome:
                readable = {
                    "A": "Image A won",
                    "B": "Image B won",
                    "TIE": "Tie / too close",
                    "BOTH_BAD": "Both bad",
                    "INVALID": "Invalid duel",
                }.get(corrected_outcome, corrected_outcome)
                return f"Duel #{index + 1} already records **{readable}**."

            corrected_at = time.time()
            record = deepcopy(original_record)
            corrections = record.setdefault("result_corrections", [])
            if not isinstance(corrections, list):
                corrections = []
                record["result_corrections"] = corrections
            corrections.append({
                "timestamp": corrected_at,
                "previous_winner": previous_outcome,
                "new_winner": corrected_outcome,
            })
            record["winner"] = "TIE" if corrected_outcome == "BOTH_BAD" else corrected_outcome
            record["both_bad"] = corrected_outcome == "BOTH_BAD"
            record["corrected_at"] = corrected_at
            record["previous_winner"] = previous_outcome
            duel_id = stable_duel_id(record)
            self.history.records[index] = record

            replayed = self._rebuild_all_ratings_from_history_locked()
            self._refresh_top50_tracking()
            # A normal Undo snapshot depends on the exact pre-vote rating state and
            # is no longer safe after a full chronological replay.
            self.last_undo_state = None
            self.ui_result_msg = (
                f"**Historical duel #{index + 1} corrected:** "
                f"{previous_outcome or '?'} → {corrected_outcome}."
            )
            self.ui_details_msg = (
                f"Replayed {replayed:,} valid historical duels to rebuild legacy artist, "
                "solo/duo/trio, exact-combination, and uncertainty-aware top-search ratings."
            )

        with self.browser_cache_lock:
            self.browser_cache_stamp = None
        with self.gallery_cache_lock:
            self.gallery_cache_stamp = None
        self._update_corrected_duel_favorite_metadata(
            duel_id, index + 1, corrected_outcome, corrected_at
        )
        self._schedule_persistence(sections={"ratings", "history", "top50"})
        return (
            f"Updated duel #{index + 1}: **{previous_outcome or '?'}** → "
            f"**{corrected_outcome}**. Replayed {replayed:,} rated duels. "
            "Historical active-pool rotations were left unchanged."
        )

    def _history_record_by_number(self, history_number: Any) -> Optional[dict]:
        try:
            index = int(history_number) - 1
        except (TypeError, ValueError):
            return None
        with self.state_lock:
            if index < 0 or index >= len(self.history.records):
                return None
            return dict(self.history.records[index])

    def _gallery_target_map(self, record: dict, history_number: int) -> Dict[str, dict]:
        artists_a = list(record.get("artists_a", []))
        artists_b = list(record.get("artists_b", []))
        duel_id = stable_duel_id(record)
        image_a = str(record.get("image_a_path", ""))
        image_b = str(record.get("image_b_path", ""))
        base_duel_metadata = {
            "duel_id": duel_id,
            "history_number": history_number,
            "image_a_path": image_a,
            "image_b_path": image_b,
            "artists_a": artists_a,
            "artists_b": artists_b,
            "winner": record.get("winner", "?"),
            "seed": record.get("seed", 0),
            "timestamp": record.get("timestamp", 0),
        }
        target_map: Dict[str, dict] = {
            "Duel — both images": {
                "kind": "duel", "key": duel_id,
                "label": f"Duel #{history_number}: {' + '.join(artists_a)} vs {' + '.join(artists_b)}",
                "metadata": base_duel_metadata,
            },
            "Image A": {
                "kind": "image", "key": str(Path(image_a)),
                "label": f"Image A — {' + '.join(artists_a)}",
                "metadata": {**base_duel_metadata, "path": image_a, "side": "A", "artists": artists_a},
            },
            "Image B": {
                "kind": "image", "key": str(Path(image_b)),
                "label": f"Image B — {' + '.join(artists_b)}",
                "metadata": {**base_duel_metadata, "path": image_b, "side": "B", "artists": artists_b},
            },
        }
        for side, artists in (("A", artists_a), ("B", artists_b)):
            normalized = self.combination_elo.normalize_artists(artists)
            combo_id = self.combination_elo.combination_id(normalized)
            target_map[f"Combination {side} — {' + '.join(normalized)}"] = {
                "kind": "combination", "key": combo_id,
                "label": " + ".join(normalized), "metadata": {"artists": normalized},
            }
        for artist in dict.fromkeys(artists_a + artists_b):
            target_map[f"Artist — {artist}"] = {
                "kind": "artist", "key": artist, "label": artist, "metadata": {"artist": artist},
            }
        return target_map

    def load_gallery_duel(
        self,
        history_number: Any,
        full_resolution: bool = False,
    ) -> tuple:
        record = self._history_record_by_number(history_number)
        if record is None:
            return (
                None, None, "Select a valid duel.", "", "", "",
                gr.update(choices=[], value=None), {}, "", "", "",
                gr.update(value=[], interactive=False),
                "Load a duel and choose an artist or combination.", 0,
                gr.update(value=None, interactive=False),
                gr.update(value=False),
                "Load a duel before correcting its result.",
            )
        history_number = int(history_number)
        artists_a = list(record.get("artists_a", []))
        artists_b = list(record.get("artists_b", []))
        image_a_path = str(record.get("image_a_path", ""))
        image_b_path = str(record.get("image_b_path", ""))
        preview_a = gallery_record_preview(record, "A", bool(full_resolution))
        preview_b = gallery_record_preview(record, "B", bool(full_resolution))
        winner = str(record.get("winner", "?"))
        timestamp = float(record.get("timestamp", 0.0) or 0.0)
        date_text = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(timestamp)) if timestamp else "Unknown"
        details = [
            f"## Duel #{history_number}",
            f"**Date:** {date_text}  ",
            f"**Winner:** Image {winner}  ",
            f"**Image A artists:** {self.render_artist_links(artists_a, 'elo-gallery-artist-link')}  ",
            f"**Image B artists:** {self.render_artist_links(artists_b, 'elo-gallery-artist-link')}  ",
            f"**Seed:** `{int(record.get('seed', 0) or 0)}`  ",
            f"**Matchmaking:** {record.get('matchmaking_reason', 'Historical / unknown')}  ",
        ]
        if record.get("matchmaking_details"):
            details.append(f"**Match details:** {record.get('matchmaking_details')}  ")
        generation_config = record.get("generation_config", {})
        if isinstance(generation_config, dict) and generation_config:
            details.append(f"**Generation snapshot:** {_generation_config_summary(generation_config)}  ")
            ownership = str(generation_config.get("ownership", "manual") or "manual")
            details.append(f"**Profile ownership:** {OWNERSHIP_LABELS.get(ownership, ownership.replace('_', ' ').title())}  ")
        elif record.get("rotation_preset"):
            details.append(f"**Generation profile:** {record.get('rotation_preset')}  ")
        corrections = record.get("result_corrections", [])
        if isinstance(corrections, list) and corrections:
            latest = corrections[-1] if isinstance(corrections[-1], dict) else {}
            corrected_timestamp = float(latest.get("timestamp", record.get("corrected_at", 0.0)) or 0.0)
            corrected_text = (
                time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(corrected_timestamp))
                if corrected_timestamp else "Unknown"
            )
            details.append(
                f"**Result corrections:** {len(corrections)} · latest {corrected_text} "
                f"({latest.get('previous_winner', '?')} → {latest.get('new_winner', winner)})  "
            )
        retention_status = gallery_record_retention_status(record)
        details.append(f"**Image retention:** {retention_status}  ")
        if full_resolution and (not preview_a or not preview_b):
            details.append("\n**Full-resolution view is unavailable for one or both sides. Disable full-resolution preview to use retained thumbnails.**")
        target_map = self._gallery_target_map(record, history_number)
        default_target = "Duel — both images"
        default_data = target_map[default_target]
        tags, note, favorite_status = self.get_favorite_fields(default_data["kind"], default_data["key"])
        manual_update, manual_status = self.get_gallery_manual_style_editor(default_target, target_map)
        return (
            preview_a,
            preview_b,
            "\n".join(details),
            str(record.get("prompt_a", "") or ""),
            str(record.get("prompt_b", "") or ""),
            str(record.get("negative_prompt", "") or ""),
            gr.update(choices=list(target_map), value=default_target),
            target_map,
            tags,
            note,
            favorite_status,
            manual_update,
            manual_status,
            history_number,
            gr.update(value=winner if winner in ("A", "B", "TIE") else None, interactive=True),
            gr.update(value=False),
            (
                "Stored result: **Both outputs were rejected.** No relative winner; Legacy ELO and exact-combination ratings store a tie, while the Bayesian ranker stores poor-output reliability evidence without directly moving skill μ."
                if bool(record.get("both_bad", False))
                else "Stored result: **Tie / too close to call.**"
                if winner == "TIE"
                else "Stored result: **Invalid duel — no rating evidence.**"
                if winner == "INVALID"
                else f"Stored result: **Image {winner}** won."
            ),
        )

    def load_gallery_duel_modal(
        self,
        history_number: Any,
        full_resolution: bool = False,
        request_id: str = "",
    ) -> Tuple[Optional[str], Optional[str], str, int]:
        """Return one historical duel for the browser modal viewer."""
        record = self._history_record_by_number(history_number)
        if record is None:
            return None, None, json.dumps({
                "request_id": str(request_id or ""),
                "ok": False,
                "error": "That historical duel is no longer available.",
            }), 0

        history_number = int(history_number)
        artists_a = list(record.get("artists_a", []))
        artists_b = list(record.get("artists_b", []))
        image_a_path = str(record.get("image_a_path", ""))
        image_b_path = str(record.get("image_b_path", ""))
        preview_a = gallery_record_preview(record, "A", bool(full_resolution))
        preview_b = gallery_record_preview(record, "B", bool(full_resolution))
        winner = str(record.get("winner", "?") or "?").upper()
        both_bad = bool(record.get("both_bad", False))
        timestamp = float(record.get("timestamp", 0.0) or 0.0)
        date_text = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(timestamp)) if timestamp else "Unknown"

        legacy_changes = {
            str(key): float(value)
            for key, value in dict(record.get("legacy_rating_changes", {}) or {}).items()
        }
        top_changes = {
            str(key): float(value)
            for key, value in dict(record.get("top_search_rating_changes", {}) or {}).items()
        }
        combination_changes = {
            str(key): float(value)
            for key, value in dict(record.get("combination_rating_changes", {}) or {}).items()
        }
        combo_id_a = self.combination_elo.combination_id(artists_a) if artists_a else ""
        combo_id_b = self.combination_elo.combination_id(artists_b) if artists_b else ""

        def side_status(side: str) -> str:
            if both_bad:
                return "bad"
            if winner == "TIE":
                return "tie"
            if winner == "INVALID":
                return "invalid"
            if winner == side:
                return "winner"
            if winner in ("A", "B"):
                return "loser"
            return "unknown"

        def artist_change_rows(artists: List[str]) -> List[dict]:
            return [
                {
                    "artist": str(artist),
                    "top_search": float(top_changes.get(str(artist), 0.0)),
                    "legacy_elo": float(legacy_changes.get(str(artist), 0.0)),
                }
                for artist in artists
            ]

        response = {
            "request_id": str(request_id or ""),
            "ok": True,
            "history_number": history_number,
            "duel_id": stable_duel_id(record),
            "date": date_text,
            "winner": "Both bad" if both_bad else winner,
            "outcome": "BOTH_BAD" if both_bad else winner,
            "both_bad": both_bad,
            "seed": int(record.get("seed", 0) or 0),
            "match_type": str(record.get("matchmaking_reason", "Historical / unknown") or "Historical / unknown"),
            "match_details": str(record.get("matchmaking_details", "") or ""),
            "preset": str(record.get("rotation_preset", "") or ""),
            "generation_config": deepcopy(record.get("generation_config", {}))
                if isinstance(record.get("generation_config", {}), dict) else {},
            "generation_summary": _generation_config_summary(record.get("generation_config", {})),
            "prompt_a": str(record.get("prompt_a", "") or ""),
            "prompt_b": str(record.get("prompt_b", "") or ""),
            "negative_prompt": str(record.get("negative_prompt", "") or ""),
            "image_a_path": image_a_path,
            "image_b_path": image_b_path,
            "image_retention_status": gallery_record_retention_status(record),
            "image_a_original_retained": Path(image_a_path).is_file(),
            "image_b_original_retained": Path(image_b_path).is_file(),
            "expected_a": float(record.get("top_search_expected_a", 0.5) or 0.5),
            "image_a_available": bool(preview_a),
            "image_b_available": bool(preview_b),
            "correction_count": len(record.get("result_corrections", []))
                if isinstance(record.get("result_corrections", []), list) else 0,
            "corrected_at": float(record.get("corrected_at", 0.0) or 0.0),
            "side_a": {
                "label": "Image A",
                "status": side_status("A"),
                "artists": artists_a,
                "artist_changes": artist_change_rows(artists_a),
                "combination_change": float(combination_changes.get(combo_id_a, 0.0)),
            },
            "side_b": {
                "label": "Image B",
                "status": side_status("B"),
                "artists": artists_b,
                "artist_changes": artist_change_rows(artists_b),
                "combination_change": float(combination_changes.get(combo_id_b, 0.0)),
            },
        }
        return preview_a, preview_b, json.dumps(response, ensure_ascii=False), history_number

    def get_gallery_target_fields(self, target_label: str, target_map: dict) -> Tuple[str, str, str]:
        target = (target_map or {}).get(target_label)
        if not target:
            return "", "", "Select a favorite target."
        return self.get_favorite_fields(target["kind"], target["key"])

    def save_gallery_target_favorite(self, target_label: str, target_map: dict, tags: Any, note: str) -> str:
        target = (target_map or {}).get(target_label)
        if not target:
            return "Select a favorite target."
        return self.save_favorite_entry(
            target["kind"], target["key"], target["label"], tags, note, target.get("metadata", {})
        )

    def remove_gallery_target_favorite(self, target_label: str, target_map: dict) -> str:
        target = (target_map or {}).get(target_label)
        if not target:
            return "Select a favorite target."
        return self.remove_favorite_entry(target["kind"], target["key"])

    def get_gallery_manual_style_editor(self, target_label: str, target_map: dict):
        """Load manual tags for a selected historical artist/combination."""
        target = (target_map or {}).get(target_label)
        if not target:
            return gr.update(value=[], interactive=False), "Load a duel and choose an artist or combination."
        if target["kind"] not in ("artist", "combination"):
            return (
                gr.update(value=[], interactive=False),
                "Manual tags apply only to an individual artist or an exact combination.",
            )
        labels = self.get_manual_style_labels(target["kind"], target["key"])
        return gr.update(value=labels, interactive=True), f"Editing manual tags for **{target['label']}**."

    def save_gallery_manual_style_tags(
        self, target_label: str, target_map: dict, selected_labels: Any
    ) -> str:
        target = (target_map or {}).get(target_label)
        if not target:
            return "Load a duel and choose an artist or combination."
        if target["kind"] not in ("artist", "combination"):
            return "Choose an **Artist** or **Combination** target first."
        return self.save_manual_style_tags(target["kind"], target["key"], selected_labels)

    def _resolve_context_target(self, payload: dict, gallery_history_number: Any = 0) -> Optional[dict]:
        """Resolve a compact browser context-menu request to a favorite/tag target."""
        source = str(payload.get("source", "")).strip().casefold()
        target_label = str(payload.get("target", "")).strip()

        if source == "compare":
            target, _choices = self._resolve_compare_favorite_target(
                target_label or "Duel — both images",
                str(payload.get("artist", "") or ""),
            )
            return target

        if source == "gallery":
            record = self._history_record_by_number(gallery_history_number)
            if record is None:
                return None
            target_map = self._gallery_target_map(record, int(gallery_history_number))
            requested = target_label or "Duel — both images"
            direct = target_map.get(requested)
            if direct is not None:
                return direct
            # Historical combination labels include the artists (for example
            # "Combination A — artist one + artist two"), while image context
            # menus intentionally use the compact "Combination A" label.
            prefix = requested + " —"
            for label, target in target_map.items():
                if label.startswith(prefix):
                    return target
            return None

        if source == "artist":
            artist = str(payload.get("key") or payload.get("artist") or "").strip()
            if not artist:
                return None
            return {
                "kind": "artist",
                "key": artist,
                "label": artist,
                "metadata": {"artist": artist},
            }

        if source == "combination":
            key = str(payload.get("key", "") or "").strip()
            label = str(payload.get("label") or payload.get("combination") or "").strip()
            artists = [str(value).strip() for value in payload.get("artists", []) if str(value).strip()]
            if not artists and label:
                artists = [part.strip() for part in label.split(" + ") if part.strip()]
            if not key and artists:
                key = self.combination_elo.combination_id(artists)
            if not key:
                return None
            return {
                "kind": "combination",
                "key": key,
                "label": label or " + ".join(artists) or key,
                "metadata": {"artists": artists},
            }
        return None

    @staticmethod
    def _portrait_preview_data_url(image_path: str, max_side: int = 512) -> str:
        if PILImage is None:
            return ""
        path = Path(str(image_path or ""))
        if not path.exists() or not path.is_file():
            return ""
        try:
            with PILImage.open(path) as image:
                image = image.convert("RGB")
                image.thumbnail((max_side, max_side), PILImage.Resampling.LANCZOS)
                buffer = io.BytesIO()
                image.save(buffer, format="JPEG", quality=72, optimize=True)
            return "data:image/jpeg;base64," + base64.b64encode(buffer.getvalue()).decode("ascii")
        except Exception:
            return ""

    def handle_context_state_request(
        self,
        payload_text: str,
        gallery_history_number: Any = 0,
    ) -> str:
        """Return active favorite/manual-style state for a contextual target."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}
        request_id = str(payload.get("request_id", "")) if isinstance(payload, dict) else ""
        response = {
            "request_id": request_id,
            "ok": False,
            "error": "",
            "is_favorite": False,
            "manual_tags": [],
        }
        if not isinstance(payload, dict):
            response["error"] = "Invalid context-state request."
            return json.dumps(response)
        target = self._resolve_context_target(payload, gallery_history_number)
        if not target:
            response["error"] = "The selected item is no longer available."
            return json.dumps(response)
        kind = str(target.get("kind", ""))
        key = str(target.get("key", ""))
        response.update({
            "ok": True,
            "kind": kind,
            "key": key,
            "label": str(target.get("label", key)),
            "is_favorite": self.favorites.is_favorite(kind, key),
            "manual_tags": self.classifications.get_manual_tags(kind, key)
                if kind in ("artist", "combination") else [],
        })
        return json.dumps(response)

    def handle_portrait_request(self, payload_text: str) -> str:
        """Return recent solo Gallery images that can represent one artist."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}
        request_id = str(payload.get("request_id", "")) if isinstance(payload, dict) else ""
        artist = str(payload.get("artist", "")).strip() if isinstance(payload, dict) else ""
        response = {
            "request_id": request_id,
            "ok": False,
            "artist": artist,
            "error": "",
            "candidates": [],
            "has_portrait": bool(self.artist_portraits.get(artist)) if artist else False,
        }
        if not artist or artist not in set(self.artist_manager.artists):
            response["error"] = "That artist is not in the artist database."
            return json.dumps(response)

        candidates: List[dict] = []
        seen_paths: Set[str] = set()
        for history_number in range(len(self.history.records), 0, -1):
            record = self.history.records[history_number - 1]
            for side in ("A", "B"):
                artists = [str(value) for value in record.get(f"artists_{side.lower()}", [])]
                if len(artists) != 1 or artists[0].casefold() != artist.casefold():
                    continue
                path = str(record.get(f"image_{side.lower()}_path", "") or "")
                if not path or path in seen_paths or not Path(path).exists():
                    continue
                preview = self._portrait_preview_data_url(path)
                if not preview:
                    continue
                seen_paths.add(path)
                candidates.append({
                    "source_path": path,
                    "preview": preview,
                    "history_number": history_number,
                    "side": side,
                    "winner": str(record.get("winner", "") or ""),
                    "date": time.strftime(
                        "%Y-%m-%d",
                        time.localtime(float(record.get("timestamp", 0.0) or 0.0)),
                    ) if record.get("timestamp") else "Unknown",
                })
                if len(candidates) >= 18:
                    break
            if len(candidates) >= 18:
                break
        response["ok"] = True
        response["candidates"] = candidates
        if not candidates:
            response["error"] = "No available solo Gallery images were found for this artist."
        return json.dumps(response)

    def handle_portrait_save(self, payload_text: str) -> str:
        """Save or remove an artist's cropped representative image."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            return "❌ Could not understand that portrait update."
        if not isinstance(payload, dict):
            return "❌ Invalid portrait update."
        artist = str(payload.get("artist", "")).strip()
        if not artist:
            return "❌ No artist was selected."
        action = str(payload.get("action", "save")).strip().casefold()
        if action == "remove":
            removed = self.artist_portraits.remove(artist)
            return (
                f"🖼 Removed the portrait for **{artist}**."
                if removed else f"ℹ **{artist}** did not have a saved portrait."
            )
        try:
            self.artist_portraits.set_crop(
                artist=artist,
                source_path=str(payload.get("source_path", "")),
                crop_x=float(payload.get("crop_x", 0.0) or 0.0),
                crop_y=float(payload.get("crop_y", 0.0) or 0.0),
                crop_size=float(payload.get("crop_size", 1.0) or 1.0),
                history_number=int(payload.get("history_number", 0) or 0),
            )
            return f"🖼 Saved the representative portrait for **{artist}**."
        except Exception as exc:
            return f"❌ Could not save the portrait for **{artist}**: {exc}"

    def handle_context_action(self, payload_text: str, gallery_history_number: Any = 0) -> str:
        """Apply a favorite or manual-style action requested from the contextual UI."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            return "⚠ Could not understand that contextual action."
        if not isinstance(payload, dict):
            return "⚠ Invalid contextual action."

        action = str(payload.get("action", "")).strip().casefold()
        target = self._resolve_context_target(payload, gallery_history_number)
        if not target:
            return "⚠ The selected item is no longer available."

        kind = str(target["kind"])
        key = str(target["key"])
        label = str(target.get("label", key))
        metadata = dict(target.get("metadata", {}))
        # Keep Compare blind: contextual image/duel/combination actions must not reveal
        # hidden artist tags before the user votes or explicitly enables artist display.
        display_label = (
            str(payload.get("target") or "current item")
            if str(payload.get("source", "")).casefold() == "compare" and kind != "artist"
            else label
        )

        if action == "toggle_favorite":
            if self.favorites.is_favorite(kind, key):
                self.remove_favorite_entry(kind, key)
                return f"☆ Removed **{display_label}** from Favorites."
            self.save_favorite_entry(kind, key, label, [], "", metadata)
            return f"★ Added **{display_label}** to Favorites."

        if action == "toggle_style":
            if kind not in ("artist", "combination"):
                return "⚠ Manual tags apply only to artists and exact combinations."
            tag_id = str(payload.get("tag", "")).strip().casefold()
            info = MANUAL_STYLE_TAGS.get(tag_id)
            if not info:
                return "⚠ Unknown manual tag."
            current_labels = self.get_manual_style_labels(kind, key)
            label_name = info["label"]
            if label_name in current_labels:
                current_labels = [value for value in current_labels if value != label_name]
                verb = "Removed"
            else:
                current_labels.append(label_name)
                verb = "Added"
            self.save_manual_style_tags(kind, key, current_labels)
            return f"{info['icon']} {verb} **{label_name}** for **{display_label}**."

        return "⚠ Unsupported contextual action."

    def handle_favorite_request(
        self,
        payload_text: str,
        gallery_history_number: Any = 0,
        compare_artists_visible: bool = False,
    ) -> str:
        """Load one favorite entry for the contextual browser editor."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}

        response = {
            "request_id": payload.get("request_id", ""),
            "ok": False,
            "error": "",
            "kind": "",
            "key": "",
            "label": "",
            "save_label": "",
            "metadata": {},
            "tags": "",
            "note": "",
            "is_favorite": False,
            "source": str(payload.get("source", "")),
            "target": str(payload.get("target", "")),
        }
        if not isinstance(payload, dict):
            response["error"] = "Invalid favorite request."
            return json.dumps(response)

        target = self._resolve_context_target(payload, gallery_history_number)
        if not target:
            response["error"] = "The selected item is no longer available."
            return json.dumps(response)

        source = str(payload.get("source", "")).casefold()
        kind = str(target["kind"])
        key = str(target["key"])
        storage_label = str(target.get("label", key))
        metadata = dict(target.get("metadata", {}))
        display_label = storage_label
        if source == "compare" and kind != "artist" and not compare_artists_visible:
            display_label = str(payload.get("target") or self._favorite_kind_label(kind))

        entry = self.favorites.get(kind, key) or {}
        response.update({
            "ok": True,
            "kind": kind,
            "key": key,
            "label": display_label,
            "save_label": storage_label,
            "metadata": metadata,
            "tags": ", ".join(entry.get("tags", [])),
            "note": str(entry.get("note", "")),
            "is_favorite": bool(entry),
        })
        return json.dumps(response)

    def handle_favorite_save(self, payload_text: str) -> str:
        """Save or remove one contextual favorite entry with tags and note."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            return "❌ Could not understand that favorite update."
        if not isinstance(payload, dict):
            return "❌ Invalid favorite update."

        kind = str(payload.get("kind", "")).strip()
        key = str(payload.get("key", "")).strip()
        label = str(payload.get("save_label") or payload.get("label") or key).strip()
        metadata = payload.get("metadata", {})
        if not isinstance(metadata, dict):
            metadata = {}
        display_label = str(payload.get("label") or label or key)
        if not kind or not key:
            return "❌ The favorite target is no longer valid."

        action = str(payload.get("action", "save")).strip().casefold()
        if action == "delete":
            removed = self.favorites.remove(kind, key)
            self._invalidate_favorite_dependent_caches()
            return (
                f"☆ Removed **{display_label}** from Favorites."
                if removed else f"ℹ **{display_label}** was not currently favorited."
            )

        tags = payload.get("tags", "")
        note = str(payload.get("note", ""))
        try:
            entry = self.favorites.set(kind, key, label or key, tags, note, metadata)
            self._invalidate_favorite_dependent_caches()
            return (
                f"★ Saved **{display_label}** as a favorite "
                f"with {len(entry.get('tags', []))} tag(s)."
            )
        except Exception as exc:
            return f"❌ Could not save **{display_label}**: {exc}"

    def handle_note_request(
        self,
        payload_text: str,
        gallery_history_number: Any = 0,
        compare_artists_visible: bool = False,
    ) -> str:
        """Load one artist/combination note for the contextual browser editor."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}
        request_id = str(payload.get("request_id", "")) if isinstance(payload, dict) else ""
        response = {"ok": False, "request_id": request_id}
        if not isinstance(payload, dict):
            response["error"] = "Invalid note request."
            return json.dumps(response, ensure_ascii=False)

        target = self._resolve_context_target(payload, gallery_history_number)
        if not target:
            response["error"] = "The selected artist or combination is no longer available."
            return json.dumps(response, ensure_ascii=False)
        kind = str(target.get("kind", ""))
        if kind not in ("artist", "combination"):
            response["error"] = "Notes are available only for artists and exact combinations."
            return json.dumps(response, ensure_ascii=False)

        source = str(payload.get("source", "")).strip().casefold()
        if source == "compare" and kind == "combination" and not bool(compare_artists_visible):
            response["error"] = (
                "Reveal artist tags before consulting a combination note so blind voting remains unbiased."
            )
            return json.dumps(response, ensure_ascii=False)

        key = str(target.get("key", ""))
        label = str(target.get("label", key) or key)
        metadata = dict(target.get("metadata", {}))
        entry = self.entity_notes.get(kind, key) or {}
        response.update({
            "ok": True,
            "kind": kind,
            "key": key,
            "label": label,
            "note": str(entry.get("note", "")),
            "metadata": metadata,
        })
        return json.dumps(response, ensure_ascii=False)

    def handle_note_save(self, payload_text: str) -> str:
        """Save or clear one contextual artist/combination note."""
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            return "❌ Could not understand that note update."
        if not isinstance(payload, dict):
            return "❌ Invalid note update."

        kind = str(payload.get("kind", "")).strip().casefold()
        key = str(payload.get("key", "")).strip()
        label = str(payload.get("label", key) or key).strip()
        metadata = payload.get("metadata", {})
        metadata = dict(metadata) if isinstance(metadata, dict) else {}
        action = str(payload.get("action", "save")).strip().casefold()
        if kind not in ("artist", "combination") or not key:
            return "❌ The note target is no longer valid."

        if action == "delete":
            removed = self.entity_notes.remove(kind, key)
            return (
                f"🗑 Removed the note for **{label}**."
                if removed else f"ℹ **{label}** did not have a saved note."
            )

        note = str(payload.get("note", ""))
        saved = self.entity_notes.set(kind, key, label, note, metadata)
        if saved is None:
            return f"🗑 Cleared the note for **{label}**."
        return f"📝 Saved the note for **{label}**."

    def get_favorites_browser_data(
        self,
        kind_filter: str = "All types",
        search_text: str = "",
        tag_filter: str = "",
        row_limit: Any = "50",
        page: int = 1,
    ) -> Tuple[List[List[Any]], str, int]:
        kind_map = {
            "Artists": "artist", "Combinations": "combination",
            "Images": "image", "Duels": "duel",
        }
        chosen_kind = kind_map.get(kind_filter)
        entries = self.favorites.entries([chosen_kind] if chosen_kind else None)
        query = str(search_text or "").strip().casefold()
        tag_query = str(tag_filter or "").strip().casefold()
        filtered = []
        for entry in entries:
            tags = list(entry.get("tags", []))
            blob = " ".join([
                str(entry.get("label", "")), str(entry.get("note", "")),
                " ".join(tags), str(entry.get("key", "")),
            ]).casefold()
            if query and not _boolean_search_matches(query, [entry, blob]):
                continue
            if tag_query and not _boolean_search_matches(tag_query, tags):
                continue
            filtered.append(entry)
        filtered.sort(key=lambda item: float(item.get("updated_at", 0.0)), reverse=True)
        total = len(filtered)
        page_size = self._parse_row_limit(row_limit, max(1, total))
        total_pages = max(1, (total + page_size - 1) // page_size)
        try:
            current_page = max(1, min(total_pages, int(page or 1)))
        except (TypeError, ValueError):
            current_page = 1
        start = (current_page - 1) * page_size
        page_entries = filtered[start:start + page_size]
        rows = []
        for index, entry in enumerate(page_entries, start + 1):
            added = float(entry.get("created_at", 0.0) or 0.0)
            rows.append([
                index,
                self._favorite_kind_label(entry["kind"]),
                entry.get("label", entry.get("key", "")),
                ", ".join(entry.get("tags", [])),
                str(entry.get("note", ""))[:180],
                time.strftime("%Y-%m-%d %H:%M", time.localtime(added)) if added else "Unknown",
                entry.get("key", ""),
            ])
        summary = f"**Page {current_page} of {total_pages} — showing {len(rows)} of {total} favorites.**"
        return rows, summary, current_page

    def load_favorite_for_editing(
        self,
        kind_label: str,
        key: str,
        full_resolution: bool = False,
    ) -> Tuple[str, str, str, str, str, Any, Any]:
        reverse_kind = {
            "Artist": "artist", "Combination": "combination", "Image": "image", "Duel": "duel"
        }
        kind = reverse_kind.get(str(kind_label), str(kind_label).casefold())
        entry = self.favorites.get(kind, key)
        if not entry:
            return "", "", "", "Favorite not found.", "", None, None
        metadata = entry.get("metadata", {})
        tags = ", ".join(entry.get("tags", []))
        note = str(entry.get("note", ""))
        details = [
            f"## {self._favorite_kind_label(kind)} favorite",
            f"**Name:** {entry.get('label', key)}  ",
            f"**Key:** `{key}`  ",
        ]
        preview_a = None
        preview_b = None
        if kind == "image":
            path = str(metadata.get("path", key))
            preview_a = gallery_thumbnail_path(path, full_resolution)
            details.append(f"**Image path:** `{path}`  ")
        elif kind == "duel":
            preview_a = gallery_thumbnail_path(str(metadata.get("image_a_path", "")), full_resolution)
            preview_b = gallery_thumbnail_path(str(metadata.get("image_b_path", "")), full_resolution)
            details.append(f"**History duel:** {metadata.get('history_number', 'Unknown')}  ")
            details.append(f"**Winner:** {metadata.get('winner', '?')}  ")
        elif kind == "combination":
            details.append(f"**Artists:** {', '.join(metadata.get('artists', []))}  ")
        return kind, key, tags, note, "\n".join(details), preview_a, preview_b

    def update_favorite_from_editor(self, kind: str, key: str, tags: Any, note: str) -> str:
        entry = self.favorites.get(kind, key)
        if not entry:
            return "Favorite not found."
        return self.save_favorite_entry(
            kind, key, entry.get("label", key), tags, note, entry.get("metadata", {})
        )

