    def handle_appearance_theme_action(self, payload_text: Any) -> Tuple[str, str, str]:
        try:
            payload = json.loads(str(payload_text or "{}"))
        except Exception:
            payload = {}
        action = str(payload.get("action", "select")).strip().lower()
        if action == "reload":
            reload_theme_configuration_from_config()
            self.storage_settings["appearance_theme"] = normalize_theme_name(
                self.storage_settings.get("appearance_theme")
            )
        else:
            name = normalize_theme_name(payload.get("name"))
            self.storage_settings["appearance_theme"] = name
            if name == "Custom":
                base_mode = str(payload.get("mode", UI_CUSTOM_THEME_MODE)).strip().lower()
                if base_mode not in {"light", "dark"}:
                    base_mode = UI_CUSTOM_THEME_MODE
                self.storage_settings["custom_theme_mode"] = base_mode
                for key, fallback in NORMALIZED_CUSTOM_THEME_DEFAULTS.items():
                    self.storage_settings[f"custom_theme_{key}"] = normalize_hex_color(
                        payload.get(key),
                        self.storage_settings.get(f"custom_theme_{key}", fallback),
                    )
        save_storage_settings(self.storage_settings)
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
            self.storage_cache_markdown = ""
        return (
            self.appearance_theme_payload(),
            self.appearance_theme_catalog_payload(),
            self.get_storage_dashboard(force=True),
        )

    def appearance_theme_status(self, saved: bool = False) -> str:
        payload = theme_payload_from_settings(self.storage_settings)
        name = str(payload.get("name", "System"))
        prefix = "**Appearance saved.** " if saved else ""
        if payload.get("mode") == "system":
            return prefix + "**System** follows the browser or operating-system light/dark preference."
        if payload.get("is_custom"):
            return prefix + (
                f"**Custom ({str(payload.get('mode', 'dark')).title()} base)** · "
                f"accent `{payload['accent']}` · background `{payload['background']}` · "
                f"panel `{payload['panel']}` · text `{payload['text']}`."
            )
        return prefix + f"**{html.escape(name)}** preset is active."

    def reload_appearance_theme_configuration(self) -> Tuple[Any, str, str, str, str]:
        success, message = reload_theme_configuration_from_config()
        current = normalize_theme_name(self.storage_settings.get("appearance_theme"))
        self.storage_settings["appearance_theme"] = current
        for key, fallback in NORMALIZED_CUSTOM_THEME_DEFAULTS.items():
            self.storage_settings[f"custom_theme_{key}"] = normalize_hex_color(
                self.storage_settings.get(f"custom_theme_{key}"), fallback
            )
        save_storage_settings(self.storage_settings)
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
            self.storage_cache_markdown = ""
        prefix = "**Theme configuration reloaded.** " if success else "**Theme reload failed.** "
        status = prefix + message
        return (
            gr.update(choices=list(UI_THEME_CHOICES), value=current),
            theme_config_source_markdown(),
            status,
            self.appearance_theme_payload(),
            self.get_storage_dashboard(force=True),
        )

    def save_appearance_theme(
        self,
        theme_name: Any,
        accent: Any,
        background: Any,
        panel: Any,
        text_color: Any,
        custom_mode: Any = None,
    ) -> Tuple[str, str, str]:
        normalized_name = normalize_theme_name(theme_name)
        self.storage_settings["appearance_theme"] = normalized_name
        if normalized_name == "Custom":
            base_mode = str(custom_mode or self.storage_settings.get("custom_theme_mode", UI_CUSTOM_THEME_MODE)).strip().lower()
            self.storage_settings["custom_theme_mode"] = base_mode if base_mode in {"light", "dark"} else UI_CUSTOM_THEME_MODE
        submitted = {
            "accent": accent,
            "background": background,
            "panel": panel,
            "text": text_color,
        }
        for key, fallback in NORMALIZED_CUSTOM_THEME_DEFAULTS.items():
            self.storage_settings[f"custom_theme_{key}"] = normalize_hex_color(
                submitted.get(key),
                self.storage_settings.get(f"custom_theme_{key}", fallback),
            )
        save_storage_settings(self.storage_settings)
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
            self.storage_cache_markdown = ""
        return (
            self.appearance_theme_status(saved=True),
            self.appearance_theme_payload(),
            self.get_storage_dashboard(force=True),
        )

    # -------------------------------------------------------------------------
    # Shareable Edition Phase 4: full-resolution retention and recovery
    # SHAREABLE_EDITION_STORAGE_RETENTION_V211
    # -------------------------------------------------------------------------

    def _retention_special_protected_paths(self) -> Set[str]:
        """Return originals that managed cleanup may never touch."""
        protected: Set[str] = set()
        with self.state_lock:
            items = ([self.current_comparison] if self.current_comparison else []) + list(self.comparison_queue)
            for item in items:
                if item is None:
                    continue
                protected.add(str(Path(item.image_a_path)))
                protected.add(str(Path(item.image_b_path)))

            # Undo/Redo can bring a recently rated duel back to the voting surface.
            for stack_name in ("qol_undo_stack", "qol_redo_stack"):
                for entry in list(getattr(self, stack_name, []) or []):
                    selected = getattr(getattr(entry, "before", None), "selected_comparison", None)
                    if selected is not None:
                        protected.add(str(Path(selected.image_a_path)))
                        protected.add(str(Path(selected.image_b_path)))
            selected = getattr(getattr(self, "last_undo_state", None), "selected_comparison", None)
            if selected is not None:
                protected.add(str(Path(selected.image_a_path)))
                protected.add(str(Path(selected.image_b_path)))

            # Future-proof explicit protection flags without changing old records.
            for record in self.history.records:
                if bool(record.get("retention_protected", False)):
                    for field_name in ("image_a_path", "image_b_path"):
                        value = str(record.get(field_name, "") or "")
                        if value:
                            protected.add(str(Path(value)))
                for side in ("a", "b"):
                    if bool(record.get(f"image_{side}_protected", False)):
                        value = str(record.get(f"image_{side}_path", "") or "")
                        if value:
                            protected.add(str(Path(value)))
        protected.update(self.favorites.referenced_image_paths())
        return protected

    def _retention_history_snapshot(self) -> List[dict]:
        with self.state_lock:
            return [deepcopy(record) for record in self.history.records]

    def retention_policy_status(self, saved: bool = False) -> str:
        settings = normalize_retention_settings(self.storage_settings)
        quarantine = self.retention_manager.quarantine_summary()
        prefix = "**Retention settings saved.**  \n" if saved else ""
        if settings["image_retention_policy"] == "keep_all":
            policy_line = "**Keep all originals** is active. Dry runs are safe, but managed cleanup selects nothing."
        else:
            cap = float(settings["retention_max_storage_gb"])
            cap_text = f"{cap:g} GB target" if cap > 0 else "no storage-size target"
            policy_line = (
                f"**Managed cleanup** keeps the latest **{int(settings['retention_keep_latest_duels']):,} duels**, "
                f"normally keeps originals for **{float(settings['retention_keep_days']):g} days**, and uses **{cap_text}**."
            )
        auto_line = (
            f"Automatic background cleanup: **ON**, checked every "
            f"{float(settings['retention_auto_interval_hours']):g} hour(s)."
            if settings["retention_auto_cleanup"]
            else "Automatic background cleanup: **OFF**."
        )
        recovery_line = (
            f"Recovery quarantine: **{quarantine['count']:,} files — {readable_size(quarantine['bytes'])}**. "
            f"New cleanup items remain recoverable for **{float(settings['retention_quarantine_days']):g} day(s)**."
        )
        return prefix + policy_line + "  \n" + auto_line + "  \n" + recovery_line

    def save_retention_policy(
        self,
        policy: Any,
        keep_latest: Any,
        keep_days: Any,
        max_storage_gb: Any,
        keep_thumbnails: Any,
        quarantine_days: Any,
        auto_cleanup: Any,
        auto_interval_hours: Any,
    ) -> Tuple[str, str]:
        updated = dict(self.storage_settings)
        updated.update({
            "image_retention_policy": str(policy or "keep_all"),
            "retention_keep_latest_duels": keep_latest,
            "retention_keep_days": keep_days,
            "retention_max_storage_gb": max_storage_gb,
            "retention_keep_thumbnails": bool(keep_thumbnails),
            "retention_quarantine_days": quarantine_days,
            "retention_auto_cleanup": bool(auto_cleanup),
            "retention_auto_interval_hours": auto_interval_hours,
        })
        self.storage_settings = normalize_retention_settings(updated)
        save_storage_settings(self.storage_settings)
        self.last_retention_plan = None
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
            self.storage_cache_markdown = ""
        return self.retention_policy_status(saved=True), self.get_storage_dashboard(force=True)

    def _retention_plan_report(self, plan: RetentionPlan) -> Tuple[str, str]:
        settings = plan.policy
        quarantine_days = float(settings.get("retention_quarantine_days", 0.0) or 0.0)
        policy_name = "Managed cleanup" if settings.get("image_retention_policy") == "managed_cleanup" else "Keep all originals"
        cap = float(settings.get("retention_max_storage_gb", 0.0) or 0.0)
        cap_text = f"{cap:g} GB" if cap > 0 else "disabled"
        lines = [
            "### Retention cleanup dry run",
            f"**Plan:** `{plan.plan_id}`  ",
            f"**Settings used:** {policy_name} · keep latest {int(settings.get('retention_keep_latest_duels', 0) or 0):,} duels · keep for {float(settings.get('retention_keep_days', 0.0) or 0.0):g} days · storage target {cap_text}  ",
            f"**Full-resolution originals scanned:** {plan.original_file_count:,} — {readable_size(plan.original_bytes)}  ",
            f"**Hard-protected originals:** {plan.protected_file_count:,} — {readable_size(plan.protected_bytes)}  ",
            f"**Selected originals:** {len(plan.selected):,} — {readable_size(plan.selected_bytes)}  ",
            f"**Projected comparison-image originals after cleanup:** {readable_size(plan.projected_original_bytes)}  ",
        ]
        if quarantine_days > 0 and plan.selected:
            lines.append(
                f"Selected originals will first move to a **{quarantine_days:g}-day recovery quarantine**. "
                "The comparison-image folder shrinks immediately, but physical disk space is reclaimed only when recovery files expire or are purged.  "
            )
        elif plan.selected:
            lines.append("Recovery is disabled, so selected originals would be deleted immediately.  ")
        if bool(settings.get("retention_keep_thumbnails", True)):
            lines.append("A gallery thumbnail is created before each original is moved or deleted whenever possible.  ")
        else:
            lines.append("Thumbnail retention is disabled; cleaned history may show metadata without an image preview.  ")
        if plan.max_storage_bytes > 0:
            lines.append(f"**Configured size target:** {readable_size(plan.max_storage_bytes)}  ")
        if plan.cap_unreachable_bytes > 0:
            lines.append(
                f"⚠️ The target remains over by approximately **{readable_size(plan.cap_unreachable_bytes)}** because protected/latest originals are never selected.  "
            )
        for note in plan.notes:
            lines.append(f"- {note}")
        path_lines = [
            f"#{item.history_number} {item.side} | {readable_size(item.size_bytes)} | {item.reason} | {item.original_path}"
            for item in plan.selected[:300]
        ]
        return "\n".join(lines), "\n".join(path_lines)

    def preview_retention_cleanup(
        self,
        policy: Any,
        keep_latest: Any,
        keep_days: Any,
        max_storage_gb: Any,
        keep_thumbnails: Any,
        quarantine_days: Any,
        auto_cleanup: Any,
        auto_interval_hours: Any,
    ) -> Tuple[str, str, Any, str, str]:
        """Save and preview the values currently visible in the retention editor."""
        if not self.retention_cleanup_lock.acquire(blocking=False):
            return (
                "A retention operation is already running.",
                "",
                gr.update(value=False),
                self.retention_policy_status(),
                self.get_storage_dashboard(),
            )
        try:
            status, dashboard = self.save_retention_policy(
                policy,
                keep_latest,
                keep_days,
                max_storage_gb,
                keep_thumbnails,
                quarantine_days,
                auto_cleanup,
                auto_interval_hours,
            )
            plan = self.retention_manager.build_plan(
                self._retention_history_snapshot(),
                self._retention_special_protected_paths(),
                self.storage_settings,
            )
            self.last_retention_plan = plan
            report, paths = self._retention_plan_report(plan)
            return report, paths, gr.update(value=False), status, dashboard
        finally:
            self.retention_cleanup_lock.release()

    def _apply_retention_actions_to_history(self, actions: Sequence[RetentionAction]) -> int:
        changed = 0
        if not actions:
            return changed
        with self.state_lock:
            for action in actions:
                index = int(action.history_number or 0) - 1
                if index < 0 or index >= len(self.history.records):
                    continue
                record = self.history.records[index]
                side = "b" if str(action.side).upper() == "B" else "a"
                # A history rebuild can synthesize a different legacy duel ID even when
                # the original record is still at the same position. Match the exact
                # side/path instead so a cleanup can never annotate a replacement duel.
                expected_path = str(record.get(f"image_{side}_path", "") or "").strip()
                try:
                    expected_key = os.path.normcase(os.path.abspath(expected_path)) if expected_path else ""
                    action_key = os.path.normcase(os.path.abspath(str(action.original_path or "")))
                except Exception:
                    expected_key = expected_path
                    action_key = str(action.original_path or "")
                if not expected_key or expected_key != action_key:
                    continue
                if action.status in {"quarantined", "removed"}:
                    record[f"image_{side}_retained"] = False
                    record[f"image_{side}_retention_status"] = action.status
                    record[f"image_{side}_removed_at"] = float(action.acted_at or time.time())
                    record[f"image_{side}_removed_size_bytes"] = int(action.size_bytes or 0)
                    if action.thumbnail_path:
                        record[f"image_{side}_thumbnail_path"] = str(action.thumbnail_path)
                    if action.quarantine_path:
                        record[f"image_{side}_quarantine_path"] = str(action.quarantine_path)
                    else:
                        record.pop(f"image_{side}_quarantine_path", None)
                    changed += 1
                elif action.status == "restored":
                    record[f"image_{side}_retained"] = True
                    record[f"image_{side}_retention_status"] = "restored"
                    record[f"image_{side}_restored_at"] = float(action.acted_at or time.time())
                    record.pop(f"image_{side}_quarantine_path", None)
                    changed += 1
                elif action.status == "purged":
                    record[f"image_{side}_retained"] = False
                    record[f"image_{side}_retention_status"] = "removed"
                    record[f"image_{side}_purged_at"] = float(action.acted_at or time.time())
                    record.pop(f"image_{side}_quarantine_path", None)
                    changed += 1
        if changed:
            with self.gallery_cache_lock:
                self.gallery_cache_stamp = None
            with self.storage_cache_lock:
                self.storage_cache_time = 0.0
                self.storage_cache_markdown = ""
            self._schedule_persistence(sections={"history"})
        return changed

    def _execute_retention_plan(self, plan: RetentionPlan) -> RetentionResult:
        result = self.retention_manager.execute_plan(
            plan,
            self._retention_special_protected_paths,
            lambda path: gallery_thumbnail_path(path, False),
        )
        self._apply_retention_actions_to_history(result.actions)
        return result

    def apply_retention_cleanup(self, confirmed: Any) -> Tuple[str, str, str, Any]:
        if not bool(confirmed):
            return (
                "Enable the confirmation checkbox after reviewing the dry run.",
                self.get_storage_dashboard(),
                "",
                gr.update(value=False),
            )
        plan = self.last_retention_plan
        if plan is None:
            return "Run a dry run first.", self.get_storage_dashboard(), "", gr.update(value=False)
        if time.time() - float(plan.created_at or 0.0) > 15 * 60:
            self.last_retention_plan = None
            return "The dry run is older than 15 minutes. Run it again.", self.get_storage_dashboard(), "", gr.update(value=False)
        if not self.retention_cleanup_lock.acquire(blocking=False):
            return "A retention operation is already running.", self.get_storage_dashboard(), "", gr.update(value=False)
        try:
            result = self._execute_retention_plan(plan)
            self.last_retention_plan = None
            quarantine_note = (
                f"Moved {result.moved_count:,} originals into recovery quarantine."
                if result.moved_count else ""
            )
            delete_note = (
                f"Deleted {result.deleted_count:,} originals immediately."
                if result.deleted_count else ""
            )
            message = (
                f"### Retention cleanup complete\n"
                f"{quarantine_note} {delete_note}  \n"
                f"**Original comparison-folder space released:** {readable_size(result.original_bytes_released)}  \n"
                f"**Physical disk space reclaimed now:** {readable_size(result.disk_bytes_reclaimed_now)}  \n"
                f"Skipped: {result.skipped_count:,} · Failed: {result.failed_count:,}."
            )
            return message, self.get_storage_dashboard(force=True), "", gr.update(value=False)
        finally:
            self.retention_cleanup_lock.release()

    def restore_latest_retention_cleanup(self) -> Tuple[str, str, Any]:
        if not self.retention_cleanup_lock.acquire(blocking=False):
            return "A retention operation is already running.", self.get_storage_dashboard(), gr.update(value=False)
        try:
            restored = self.retention_manager.restore_latest_cleanup()
            self._apply_retention_actions_to_history(restored)
            if restored:
                total = sum(int(item.size_bytes or 0) for item in restored)
                message = f"Restored **{len(restored):,} originals** from the latest cleanup ({readable_size(total)})."
            else:
                message = "No recoverable cleanup run is available."
            return message, self.get_storage_dashboard(force=True), gr.update(value=False)
        finally:
            self.retention_cleanup_lock.release()

    def purge_expired_retention_quarantine(self, confirmed: Any) -> Tuple[str, str, Any]:
        if not bool(confirmed):
            return "Enable the confirmation checkbox before permanently purging expired recovery files.", self.get_storage_dashboard(), gr.update(value=False)
        if not self.retention_cleanup_lock.acquire(blocking=False):
            return "A retention operation is already running.", self.get_storage_dashboard(), gr.update(value=False)
        try:
            purged = self.retention_manager.purge_expired()
            self._apply_retention_actions_to_history(purged)
            total = sum(int(item.size_bytes or 0) for item in purged)
            message = (
                f"Permanently purged **{len(purged):,} expired recovery files** and reclaimed approximately **{readable_size(total)}**."
                if purged else "No recovery files have expired yet."
            )
            return message, self.get_storage_dashboard(force=True), gr.update(value=False)
        finally:
            self.retention_cleanup_lock.release()

    def _run_automatic_retention_once(self) -> None:
        settings = normalize_retention_settings(self.storage_settings)
        now = time.time()
        if not settings.get("retention_auto_cleanup", False):
            return
        if settings.get("image_retention_policy") != "managed_cleanup":
            return
        interval = float(settings.get("retention_auto_interval_hours", 24.0)) * 3600.0
        last_run = float(settings.get("retention_last_auto_run", 0.0) or 0.0)
        if now - last_run < interval:
            return
        if not self.retention_cleanup_lock.acquire(blocking=False):
            return
        try:
            plan = self.retention_manager.build_plan(
                self._retention_history_snapshot(),
                self._retention_special_protected_paths(),
                settings,
                now=now,
            )
            if plan.selected:
                self._execute_retention_plan(plan)
            purged = self.retention_manager.purge_expired(now=now)
            self._apply_retention_actions_to_history(purged)
            self.storage_settings["retention_last_auto_run"] = now
            save_storage_settings(self.storage_settings)
            with self.storage_cache_lock:
                self.storage_cache_time = 0.0
                self.storage_cache_markdown = ""
        finally:
            self.retention_cleanup_lock.release()

    def _retention_worker_loop(self) -> None:
        # The worker is deliberately independent of voting and generation callbacks.
        while not self.retention_worker_stop.wait(60.0):
            try:
                self._run_automatic_retention_once()
            except Exception as exc:
                self.last_error_details = f"Retention worker: {type(exc).__name__}: {exc}"

    def _stop_retention_worker(self) -> None:
        try:
            self.retention_worker_stop.set()
        except Exception:
            pass

    def save_storage_policy(self, cleanup_every: Any, cleanup_oldest: Any, orphan_age_days: Any) -> str:
        every, oldest = configure_gradio_cleanup(cleanup_every, cleanup_oldest)
        try:
            orphan_days = max(0.0, min(3650.0, float(orphan_age_days)))
        except (TypeError, ValueError):
            orphan_days = 2.0
        self.storage_settings.update({
            "cleanup_every_images": every,
            "cleanup_oldest_entries": oldest,
            "orphan_min_age_days": orphan_days,
        })
        save_storage_settings(self.storage_settings)
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
        return f"Settings saved. Cleanup runs every {every} images and removes {oldest} old entries."

    def manual_temp_cleanup(self, delete_count: Any) -> Tuple[str, str]:
        try:
            delete_count = max(1, min(5000, int(delete_count)))
        except (TypeError, ValueError):
            delete_count = int(self.storage_settings.get("cleanup_oldest_entries", 25))
        deleted, bytes_freed = cleanup_old_gradio_temp_entries(delete_count)
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
        return (
            f"Deleted {deleted} app-specific Gradio cache entries and freed approximately {readable_size(bytes_freed)}.",
            self.get_storage_dashboard(force=True),
        )

    def _protected_image_paths(self) -> Set[str]:
        protected: Set[str] = set()
        with self.state_lock:
            for record in self.history.records:
                for field_name in ("image_a_path", "image_b_path"):
                    path = str(record.get(field_name, ""))
                    if path:
                        protected.add(str(Path(path)))
            items = ([self.current_comparison] if self.current_comparison else []) + list(self.comparison_queue)
            for item in items:
                if item:
                    protected.add(str(Path(item.image_a_path)))
                    protected.add(str(Path(item.image_b_path)))
        protected.update(self.favorites.referenced_image_paths())
        return protected

    def scan_orphan_images(self, minimum_age_days: Any = 2) -> Tuple[str, str]:
        try:
            minimum_age_days = max(0.0, float(minimum_age_days))
        except (TypeError, ValueError):
            minimum_age_days = 2.0
        cutoff = time.time() - minimum_age_days * 86400.0
        protected = self._protected_image_paths()
        candidates: List[str] = []
        total_bytes = 0
        if COMPARISON_IMAGES_DIR.exists():
            for path in COMPARISON_IMAGES_DIR.glob("compare_*_[ab].png"):
                try:
                    normalized = str(path)
                    if normalized in protected or path.stat().st_mtime > cutoff:
                        continue
                    candidates.append(normalized)
                    total_bytes += path.stat().st_size
                except (OSError, PermissionError):
                    continue
        self.last_orphan_scan = candidates
        report = (
            f"Found **{len(candidates)} unreferenced comparison images** older than {minimum_age_days:g} day(s), "
            f"using approximately **{readable_size(total_bytes)}**. These are commonly images from skipped or "
            "discarded buffered duels. Rated history, active buffer, and favorite images/duels are protected."
        )
        return report, "\n".join(candidates[:200])

    def delete_scanned_orphans(self, confirmed: bool) -> Tuple[str, str, str]:
        if not confirmed:
            return "Enable the confirmation checkbox before deleting.", self.get_storage_dashboard(), ""
        deleted = 0
        freed = 0
        # Re-check protection at deletion time in case a duel was rated or favorited
        # after the scan completed.
        protected_now = self._protected_image_paths()
        for raw_path in list(self.last_orphan_scan):
            path = Path(raw_path)
            try:
                if str(path) in protected_now:
                    continue
                if path.exists() and path.is_file():
                    size = path.stat().st_size
                    path.unlink()
                    deleted += 1
                    freed += size
            except (OSError, PermissionError):
                continue
        self.last_orphan_scan = []
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
        return (
            f"Deleted {deleted} unreferenced images and freed approximately {readable_size(freed)}.",
            self.get_storage_dashboard(force=True),
            "",
        )

    def clear_gallery_thumbnails(self) -> Tuple[str, str]:
        count, total_bytes = self._scan_directory(THUMBNAIL_DIR)
        try:
            if THUMBNAIL_DIR.exists():
                shutil.rmtree(THUMBNAIL_DIR)
            THUMBNAIL_DIR.mkdir(parents=True, exist_ok=True)
            message = f"Cleared {count} gallery thumbnails and freed approximately {readable_size(total_bytes)}."
        except Exception as e:
            message = f"Could not clear thumbnails: {e}"
        with self.storage_cache_lock:
            self.storage_cache_time = 0.0
        return message, self.get_storage_dashboard(force=True)


