    def secure_credential_status_markdown(self) -> str:
        status = credential_status()
        configured = "Configured" if status.configured else "Not configured"
        availability = "Available" if status.available else "Unavailable"
        return (
            f"**NovelAI API key:** `{configured}`  \n"
            f"**Secure storage:** `{status.backend}` — {availability}  \n"
            "The token is never displayed, written to ranker JSON, copied into diagnostics, "
            "included in backups, sent to the Android app, or stored by the browser."
        )

    def first_run_setup_markdown(self) -> str:
        artist_count = len(getattr(self.artist_manager, "artists", []) or [])
        try:
            free_bytes = shutil.disk_usage(DATA_ROOT).free
            free_text = readable_size(free_bytes)
            disk_ok = free_bytes >= 2 * 1024 * 1024 * 1024
        except Exception:
            free_text = "Unknown"
            disk_ok = False
        backup_count = len(list(BACKUP_DIR.glob("*.zip"))) if BACKUP_DIR.exists() else 0
        apk_ready = ANDROID_APK_PATH.exists()
        paired_count = len([device for device in PHONE_PAIRING.list_devices() if not device.get("revoked")])
        complete = bool(self.storage_settings.get("first_run_complete", False))
        policy = str(self.storage_settings.get("image_retention_policy", "keep_all"))
        lan_urls = discover_lan_urls(SERVER_PORT)
        lan_text = lan_urls[0] if lan_urls else "Use this PC's local IPv4 address"
        check = lambda value: "✅" if value else "⚠️"
        self.api_key_configured = novelai_key_is_configured()
        return (
            f"### Setup checklist\n"
            f"**Setup state:** `{'Complete' if complete else 'Needs attention'}`  \n"
            f"{check(self.api_key_configured)} API key: `{'Configured' if self.api_key_configured else 'Not configured'}`  \n"
            f"{check(artist_count > 0)} Artist list: `{artist_count:,} artists`  \n"
            f"{check(disk_ok)} Free space at data location: `{free_text}`  \n"
            f"✅ Data mode: `{DATA_LAYOUT.active_layout.mode}` — `{DATA_LAYOUT.active_layout.root}`  \n"
            f"✅ Ranker port: `{SERVER_PORT}` is active  \n"
            f"{check(apk_ready)} Android package: `{'Ready' if apk_ready else 'Not installed'}`  \n"
            f"{check(paired_count > 0)} Paired phones: `{paired_count}`  \n"
            f"{check(backup_count > 0)} Backups found: `{backup_count}`  \n"
            f"✅ Image-retention choice: `{policy}`  \n"
            f"**LAN address:** `{lan_text}`  \n"
            "Create or revoke phone access under **Storage / Settings → Phone pairing and LAN security**."
        )

    def complete_first_run_setup(self, retention_policy: str) -> Tuple[str, str, Optional[str]]:
        self.api_key_configured = novelai_key_is_configured()
        if not self.api_key_configured:
            return self.first_run_setup_markdown(), "Configure the NovelAI API key first.", None
        if not self.artist_manager.artists:
            return self.first_run_setup_markdown(), f"Artist list is missing: {ARTIST_TAGS_FILE}", None
        normalized_policy = str(retention_policy or "keep_all").strip().casefold()
        if normalized_policy not in {"keep_all", "managed_cleanup"}:
            normalized_policy = "keep_all"
        self.storage_settings["image_retention_policy"] = normalized_policy
        self.storage_settings["first_run_complete"] = True
        save_storage_settings(self.storage_settings)
        backup_message, backup_path = self.create_manual_backup()
        self.last_generation_error = ""
        self.start_refill_if_needed()
        return (
            self.first_run_setup_markdown(),
            "Setup marked complete. " + backup_message,
            backup_path,
        )

