            # Phase 7 backup, transfer, recovery, and update callbacks.
            def on_transfer_export(mode, label):
                try:
                    report, path = self.transfer_recovery.create_export(mode, label)
                    return report, gr.update(value=str(path), visible=True)
                except Exception as exc:
                    return f"❌ Export failed: {type(exc).__name__}: {exc}", gr.update(value=None, visible=False)

            def on_transfer_import_preview(upload):
                try:
                    report, plan = self.transfer_recovery.preview_import(upload)
                    return report, plan, False
                except Exception as exc:
                    return f"❌ Import preview failed: {type(exc).__name__}: {exc}", "", False

            def on_transfer_import_apply(plan, strategy, confirmed):
                return self.transfer_recovery.apply_import(plan, strategy, confirmed), False

            def on_recovery_create(label, include_images):
                try:
                    path = self.transfer_recovery.create_restore_point(
                        str(label or "manual"), include_program=True, include_images=bool(include_images)
                    )
                    return (
                        f"✅ Restore point created: `{path.name}`",
                        gr.update(value=str(path), visible=True),
                        gr.update(choices=[row["name"] for row in self.transfer_recovery.list_restore_points()], value=path.name),
                        self.transfer_recovery.restore_points_markdown(),
                    )
                except Exception as exc:
                    return (
                        f"❌ Restore point failed: {type(exc).__name__}: {exc}",
                        gr.update(value=None, visible=False),
                        gr.update(),
                        self.transfer_recovery.restore_points_markdown(),
                    )

            def on_recovery_refresh():
                rows = self.transfer_recovery.list_restore_points()
                return gr.update(choices=[row["name"] for row in rows], value=None), self.transfer_recovery.restore_points_markdown()

            def on_recovery_integrity():
                report, _details = self.transfer_recovery.validate_integrity()
                return report

            def on_recovery_restore(selected, confirmed):
                return self.transfer_recovery.restore_selected(selected, confirmed), False

            def on_update_feed_check(url):
                with self.state_lock:
                    self.storage_settings["update_feed_url"] = str(url or "").strip()
                    save_storage_settings(self.storage_settings)
                return self.transfer_recovery.check_release_feed(url)

            def on_update_preview(upload):
                try:
                    report, plan = self.transfer_recovery.preview_update(upload)
                    return report, plan, False
                except Exception as exc:
                    return f"❌ Update preview failed: {type(exc).__name__}: {exc}", "", False

            def on_update_schedule(plan, confirmed):
                return self.transfer_recovery.schedule_update(plan, confirmed), False

            def _selected_table_row(table_data, evt):
                if evt is None or evt.index is None:
                    return None
                try:
                    row_index = evt.index[0] if isinstance(evt.index, (tuple, list)) else int(evt.index)
                    if hasattr(table_data, "iloc"):
                        return list(table_data.iloc[row_index])
                    return list(table_data[row_index])
                except Exception:
                    return None

            def update_settings_from_inputs(
                prompt, negative_prompt, quality_tags, uc_preset,
                buffer_size, rotation_on, rotation_names,
                resolution_preset, width, height, steps, sampler, scheduler,
                decrisp_mode, variety_boost,
            ):
                self.update_generation_settings(
                    prompt, negative_prompt, quality_tags, uc_preset,
                    buffer_size, rotation_on, rotation_names,
                    resolution_preset, width, height, steps, sampler, scheduler,
                    decrisp_mode, variety_boost,
                )

            def on_load(*_generation_values):
                # Browser refreshes must not let static dropdown values overwrite
                # the authoritative settings already persisted by the server.
                self.start_refill_if_needed()
                return self.build_full_ui_state()

            def on_load_prompt_presets():
                """Refresh every profile dropdown from live server state after page load."""
                names = self.get_saved_prompt_names()
                with self.state_lock:
                    rotation_names = [
                        name for name in self.generation_settings.get("rotation_names", [])
                        if name in self.saved_prompts
                    ]
                gallery_choices = self.get_gallery_preset_choices()
                return (
                    gr.update(choices=names, value=None),
                    gr.update(choices=names, value=rotation_names),
                    gr.update(choices=gallery_choices, value="All presets"),
                )

            def on_rebuild(*generation_values):
                self.rebuild_buffer(*generation_values)
                return self.build_full_ui_state()

            def _run_duel_action(action):
                # Generation controls persist through their own change handlers.
                # Never serialize them into a vote request: a malformed editor value
                # must not be able to block A/B/Tie/Both-bad/Invalid/Skip.
                trace = _current_duel_trace()
                if trace:
                    trace.mark("generation_settings_already_persisted")
                action(trace)
                if trace:
                    trace.mark("duel_state_updated")
                result = self.build_action_ui_state(trace)
                if trace:
                    trace.mark("action_ui_complete")
                return result

            def on_pick_a():
                return _run_duel_action(
                    lambda trace: self.pick_winner_and_advance("A", trace),
                )

            def on_pick_b():
                return _run_duel_action(
                    lambda trace: self.pick_winner_and_advance("B", trace),
                )

            def on_tie():
                return _run_duel_action(
                    lambda trace: self.pick_winner_and_advance("TIE", trace),
                )

            def on_both_bad():
                return _run_duel_action(
                    lambda trace: self.pick_winner_and_advance("BOTH_BAD", trace),
                )

            def on_invalid():
                return _run_duel_action(
                    lambda trace: self.mark_invalid_and_advance(trace),
                )

            def on_skip():
                return _run_duel_action(
                    lambda trace: self.skip_current_comparison(trace),
                )

