            def on_artist_qol_action(payload_text, sort_by, direction, search_text,
                                     minimum_duels, maximum_duels,
                                     minimum_score, maximum_score, row_limit):
                """Apply Artist-tab presets and table-header sorting server-side.

                This deliberately avoids trying to mutate Gradio Dropdown internals from
                JavaScript. The browser sends one small action payload and Gradio returns
                authoritative component values together with the refreshed table.
                """
                try:
                    payload = json.loads(str(payload_text or "{}"))
                except Exception:
                    payload = {}
                if not isinstance(payload, dict):
                    payload = {}

                sort_by = str(sort_by or "Top-search score")
                direction = str(direction or "Descending")
                minimum_duels = str(minimum_duels if minimum_duels is not None else "0")
                maximum_duels = str(maximum_duels if maximum_duels is not None else "")
                minimum_score = str(minimum_score if minimum_score is not None else "")
                maximum_score = str(maximum_score if maximum_score is not None else "")

                action = str(payload.get("action", "")).strip().casefold()
                if action == "preset":
                    preset = str(payload.get("preset", "")).strip().casefold()
                    cutoff = float(self.top_search.cutoff_score())
                    preset_values = {
                        "untested": ("0", "0", "", ""),
                        "provisional": ("1", "5", "", ""),
                        "established": ("6", "24", "", ""),
                        "battle": ("25", "", "", ""),
                        "below": ("0", "", "", f"{max(0.0, cutoff - 0.1):.1f}"),
                        "near": ("0", "", f"{max(0.0, cutoff - 100.0):.1f}", f"{max(0.0, cutoff - 0.1):.1f}"),
                        "top50": ("0", "", f"{cutoff:.1f}", ""),
                    }
                    values = preset_values.get(preset)
                    if values is not None:
                        minimum_duels, maximum_duels, minimum_score, maximum_score = values
                elif action == "sort":
                    requested_sort = str(payload.get("sort", "")).strip()
                    valid_sorts = {
                        "Top-search score", "Potential score", "Top-50 probability", "Uncertainty", "Stage",
                        "Overall ELO", "Score rate", "Weighted win rate", "Duels fought", "Wins",
                        "Confidence", "Solo ELO", "Solo win rate", "Solo duels", "Duo ELO",
                        "Duo win rate", "Duo duels", "Trio ELO", "Trio win rate", "Trio duels",
                        "Favorites first", "Alphabetical",
                    }
                    if requested_sort in valid_sorts:
                        if requested_sort == sort_by:
                            direction = "Ascending" if direction == "Descending" else "Descending"
                        else:
                            sort_by = requested_sort
                            direction = "Descending"

                view = self.get_artist_browser_view(
                    sort_by, direction, search_text,
                    minimum_duels, maximum_duels, minimum_score, maximum_score,
                    row_limit, 1,
                )
                count = self.get_artist_filter_count(
                    search_text, minimum_duels, maximum_duels, minimum_score, maximum_score
                )
                return (
                    sort_by, direction,
                    minimum_duels, maximum_duels, minimum_score, maximum_score,
                    1, view[0], view[1], view[3], count,
                )

            def on_combination_qol_action(
                payload_text, sort_by, direction, search_text, minimum_duels,
                combination_size, row_limit,
            ):
                """Apply Combinations-table header sorting through authoritative Gradio state."""
                try:
                    payload = json.loads(str(payload_text or "{}"))
                except Exception:
                    payload = {}
                if not isinstance(payload, dict):
                    payload = {}

                sort_by = str(sort_by or "Combination ELO")
                direction = str(direction or "Descending")
                if str(payload.get("action", "")).strip().casefold() == "sort":
                    requested_sort = str(payload.get("sort", "")).strip()
                    valid_sorts = {
                        "Combination ELO", "Learned synergy", "Win rate",
                        "Weighted win rate", "Duels fought", "Wins", "Confidence",
                        "Combination size", "Favorites first", "Alphabetical",
                    }
                    if requested_sort in valid_sorts:
                        if requested_sort == sort_by:
                            direction = "Ascending" if direction == "Descending" else "Descending"
                        else:
                            sort_by = requested_sort
                            direction = "Descending"

                view = self.get_combination_browser_view(
                    sort_by, direction, search_text, minimum_duels,
                    combination_size, row_limit, 1,
                )
                return sort_by, direction, 1, view[0], view[1], view[3]

