            def on_credential_save(api_key, request: gr.Request):
                try:
                    require_local_request(request)
                    save_secure_novelai_api_key(api_key)
                    self.session = None
                    self.api_key_configured = True
                    self.last_generation_error = ""
                    self.start_refill_if_needed()
                    message = "API key saved securely in Windows Credential Manager."
                except Exception as exc:
                    message = f"Could not save API key: {exc}"
                    self.api_key_configured = novelai_key_is_configured()
                return (
                    self.secure_credential_status_markdown(),
                    message,
                    gr.update(value=""),
                    self.first_run_setup_markdown(),
                )

            def on_credential_test(api_key, request: gr.Request):
                try:
                    require_local_request(request)
                    success, message = test_secure_novelai_api_key(api_key)
                    prefix = "✅ " if success else "⚠️ "
                    return prefix + message
                except Exception as exc:
                    return f"Could not test API key: {exc}"

            def on_credential_remove(confirmed, request: gr.Request):
                try:
                    require_local_request(request)
                    if not bool(confirmed):
                        return (
                            self.secure_credential_status_markdown(),
                            "Tick the confirmation box before removing the key.",
                            gr.update(value=""),
                            False,
                            self.first_run_setup_markdown(),
                        )
                    removed = delete_api_key()
                    with self.state_lock:
                        self.session = None
                        self.api_key_configured = False
                        self.buffer_generation_token += 1
                        self.last_generation_error = "NovelAI API key not configured."
                    message = (
                        "API key removed from Windows Credential Manager."
                        if removed else "No stored API key was found."
                    )
                except Exception as exc:
                    message = f"Could not remove API key: {exc}"
                    self.api_key_configured = novelai_key_is_configured()
                return (
                    self.secure_credential_status_markdown(),
                    message,
                    gr.update(value=""),
                    False,
                    self.first_run_setup_markdown(),
                )

            def on_first_run_refresh():
                self.api_key_configured = novelai_key_is_configured()
                return self.first_run_setup_markdown()

