            def on_context_refresh_views(
                payload_text,
                *view_values,
            ):
                """Refresh only the views affected by one contextual action.

                The previous implementation chained Artists, Combinations, Compare rankings,
                and Gallery refreshes after every menu click. Besides doing unnecessary work,
                those sequential callbacks made a tiny favorite/tag action feel sluggish.
                """
                artist_count = len(artist_browser_inputs)
                combination_count = len(combination_browser_inputs)
                gallery_count = len(gallery_browser_inputs)
                artist_values = view_values[:artist_count]
                combination_values = view_values[
                    artist_count:artist_count + combination_count
                ]
                gallery_values = view_values[
                    artist_count + combination_count:
                    artist_count + combination_count + gallery_count
                ]

                try:
                    payload = json.loads(str(payload_text or "{}"))
                except Exception:
                    payload = {}
                if not isinstance(payload, dict):
                    payload = {}

                source = str(payload.get("source", "")).strip().casefold()
                action = str(payload.get("action", "")).strip().casefold()
                target = str(payload.get("target", "")).strip().casefold()

                affects_artist = source == "artist"
                affects_combination = (
                    source == "combination"
                    or target.startswith("combination a")
                    or target.startswith("combination b")
                )
                affects_rankings = affects_artist or affects_combination
                affects_gallery = source == "gallery" and action in ("toggle_favorite", "save", "delete")

                artist_outputs_local = [gr.update(), gr.update(), gr.update(), gr.update()]
                combination_outputs_local = [gr.update(), gr.update(), gr.update(), gr.update()]
                compare_outputs_local = [gr.update(), gr.update(), gr.update(), gr.update()]
                gallery_outputs_local = [gr.update(), gr.update(), gr.update()]

                if affects_artist:
                    artist_outputs_local = list(on_refresh_artists(*artist_values))
                if affects_combination:
                    combination_outputs_local = list(on_refresh_combinations(*combination_values))
                if affects_rankings:
                    compare_outputs_local = list(on_refresh_compare_rankings())
                if affects_gallery:
                    gallery_outputs_local = list(on_refresh_gallery(*gallery_values))

                return (
                    *artist_outputs_local,
                    *combination_outputs_local,
                    *compare_outputs_local,
                    *gallery_outputs_local,
                )

            def on_context_navigation(payload_text, artist_sort_by, artist_sort_direction,
                                      artist_minimum_duels, artist_maximum_duels,
                                      artist_minimum_score, artist_maximum_score,
                                      artist_rows_per_page, gallery_size_filter_value, gallery_rows_per_page):
                """Navigate between ranking and Gallery views from contextual artist/combo links."""
                try:
                    payload = json.loads(str(payload_text or "{}"))
                except Exception:
                    payload = {}
                if not isinstance(payload, dict):
                    payload = {}
                destination = str(payload.get("destination", "")).strip().casefold()

                # Defaults preserve unrelated tab state.
                artist_outputs = [gr.update(), gr.update(), gr.update(), gr.update(), gr.update()]
                gallery_filter_outputs = [
                    gr.update(), gr.update(), gr.update(), gr.update(),
                    gr.update(), gr.update(), gr.update(), gr.update(),
                ]
                gallery_list_outputs_local = [gr.update(), gr.update(), gr.update()]

                if destination == "artists":
                    artist = str(payload.get("artist", "") or "").strip()
                    if not artist:
                        return (
                            gr.update(), *artist_outputs,
                            *gallery_filter_outputs, *gallery_list_outputs_local,
                        )
                    artist_view = self.get_artist_browser_view(
                        artist_sort_by, artist_sort_direction, artist,
                        artist_minimum_duels, artist_maximum_duels,
                        artist_minimum_score, artist_maximum_score,
                        artist_rows_per_page, 1,
                    )
                    artist_outputs = [
                        artist,
                        1,
                        artist_view[0],
                        artist_view[1],
                        artist_view[3],
                    ]
                    return (
                        gr.update(selected="artists"), *artist_outputs,
                        *gallery_filter_outputs, *gallery_list_outputs_local,
                    )

                if destination == "gallery":
                    artist = str(payload.get("artist", "") or "").strip()
                    combination = str(payload.get("combination", "") or "").strip()
                    raw_artists = payload.get("terms", payload.get("artists", []))
                    terms = (
                        [str(value).strip() for value in raw_artists if str(value).strip()]
                        if isinstance(raw_artists, list)
                        else []
                    )
                    exact = bool(payload.get("exact", False))
                    requested_winner = str(payload.get("winner_filter", "All winners") or "All winners")
                    requested_lost_only = bool(payload.get("lost_only", False))
                    if artist:
                        terms = [artist]
                        exact = False
                    elif combination and not terms:
                        terms = [part.strip() for part in combination.split(" + ") if part.strip()]
                        exact = True
                    if not terms:
                        return (
                            gr.update(), *artist_outputs,
                            *gallery_filter_outputs, *gallery_list_outputs_local,
                        )
                    gallery_view = self.get_gallery_browser_data(
                        terms, exact, "All presets", "", False, requested_lost_only,
                        requested_winner, "All records", gallery_size_filter_value, gallery_rows_per_page, 1,
                    )
                    gallery_filter_outputs = [
                        gr.update(value=", ".join(terms)),
                        gr.update(value=exact),
                        gr.update(value="All presets"),
                        gr.update(value=""),
                        gr.update(value=False),
                        gr.update(value=requested_lost_only),
                        gr.update(value=requested_winner),
                        gr.update(value="All records"),
                    ]
                    gallery_list_outputs_local = [gallery_view[0], gallery_view[1], gallery_view[2]]
                    return (
                        gr.update(selected="gallery"), *artist_outputs,
                        *gallery_filter_outputs, *gallery_list_outputs_local,
                    )

                return (
                    gr.update(), *artist_outputs,
                    *gallery_filter_outputs, *gallery_list_outputs_local,
                )

