# QOL_PERFORMANCE_BUNDLE_V1
# Persistent duel-preview acceleration, optimistic client prefetching, bounded
# multi-step Undo/Redo, session analytics, quick duel tools, and UI recovery.
import queue as _qol_queue

QOL_PREVIEW_DIR = DATA_LAYOUT.path("qol_preview_dir")
QOL_BAD_IMAGE_REPORTS_FILE = DATA_LAYOUT.path("bad_image_reports_file")
QOL_RUNTIME_STATE_FILE = DATA_LAYOUT.path("qol_runtime_state_file")
