QOL_ACTIVE_BREAK_SECONDS = 300.0
QOL_PREFETCH_DEPTH = 2


@dataclass
class QOLVoteHistoryEntry:
    """A bounded exact before/after snapshot for one rated duel."""
    result: str
    before: UndoState
    before_top50_tracking: dict
    after_ratings: Dict[str, float]
    after_comparisons: Dict[str, int]
    after_size_state: dict
    after_combination_entries: dict
    after_top_search_state: dict
    after_evidence_tail: List[dict]
    after_pool_state: dict
    after_top50_tracking: dict
    after_classification_events: List[dict]
    after_record: dict
    after_elo_comparison_count: int
    result_msg: str
    details_msg: str
    created_at: float = field(default_factory=time.time)


def _qol_atomic_json(path: Path, value: Any) -> None:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(path)


def _qol_restore_rotation_event(store: ClassificationStore, event: dict) -> None:
    """Restore one previously removed rotation event without changing its ID."""
    if not isinstance(event, dict):
        return
    event_id = str(event.get("event_id", "") or "")
    if not event_id:
        return
    with store.lock:
        if any(str(existing.get("event_id", "")) == event_id for existing in store.rotation_events):
            return
        restored = deepcopy(event)
        store.rotation_events.append(restored)
        store.rotation_events = store.rotation_events[-20000:]
        if restored.get("direction") == "out":
            artist = str(restored.get("artist", ""))
            reason = str(restored.get("reason", "legacy_unknown"))
            if reason not in store.ROTATION_REASONS:
                reason = "legacy_unknown"
            bucket = store.rotation_reason_counts.setdefault(
                artist, {key: 0 for key in store.ROTATION_REASONS}
            )
            for key in store.ROTATION_REASONS:
                bucket.setdefault(key, 0)
            bucket[reason] = int(bucket.get(reason, 0) or 0) + 1
            store._recalculate_totals_locked()
        store.version += 1


def _qol_result_label(result: str) -> str:
    return {
        "A": "Picked A",
        "B": "Picked B",
        "TIE": "Tie",
        "BOTH_BAD": "Both bad",
        "INVALID": "Invalid",
        "SKIP": "Skipped",
        "UNDO": "Undo",
        "REDO": "Redo",
    }.get(str(result or "").upper(), str(result or "Action"))


_ArtistELORanker_original_init = ArtistELORanker.__init__
_ArtistELORanker_original_snapshot = ArtistELORanker._get_current_snapshot
_ArtistELORanker_original_advance = ArtistELORanker._advance_to_next_comparison_locked
_ArtistELORanker_original_pick = ArtistELORanker.pick_winner_and_advance
_ArtistELORanker_original_invalid = ArtistELORanker.mark_invalid_and_advance
_ArtistELORanker_original_skip = ArtistELORanker.skip_current_comparison
_ArtistELORanker_original_rebuild = ArtistELORanker.rebuild_buffer
_ArtistELORanker_original_favorite_refresh = ArtistELORanker._refresh_current_duel_favorite_metadata_after_vote


def _qol_init(self: ArtistELORanker) -> None:
    _ArtistELORanker_original_init(self)

    self.qol_preview_queue: "_qol_queue.Queue[str]" = _qol_queue.Queue()
    self.qol_preview_pending: Set[str] = set()
    self.qol_preview_ready: Set[str] = set()
    self.qol_preview_lock = threading.RLock()
    self.qol_preview_fingerprint_cache: Dict[str, Tuple[str, Optional[str]]] = {}
    self.qol_preview_thread = threading.Thread(
        target=self._qol_preview_worker,
        name="artist-elo-duel-preview-worker",
        daemon=True,
    )
    self.qol_preview_thread.start()

    self.qol_maintenance_queue: "_qol_queue.Queue[Tuple[str, Any, tuple, dict]]" = _qol_queue.Queue()
    self.qol_maintenance_thread = threading.Thread(
        target=self._qol_maintenance_worker,
        name="artist-elo-post-vote-maintenance",
        daemon=True,
    )
    self.qol_maintenance_thread.start()

    self.qol_undo_stack: Deque[QOLVoteHistoryEntry] = deque(maxlen=QOL_HISTORY_LIMIT)
    self.qol_redo_stack: Deque[QOLVoteHistoryEntry] = deque(maxlen=QOL_HISTORY_LIMIT)
    self.qol_recent_actions: Deque[dict] = deque(maxlen=QOL_RECENT_ACTION_LIMIT)
    self.qol_session = {
        "started_at": 0.0,
        "last_decision_at": 0.0,
        "active_seconds": 0.0,
        "counts": {key: 0 for key in ("A", "B", "TIE", "BOTH_BAD", "INVALID", "SKIP", "UNDO", "REDO")},
        "coverage_samples": [],
        "break_seconds": QOL_ACTIVE_BREAK_SECONDS,
    }
    self._qol_load_runtime_state()
    self._qol_enqueue_ready_previews()


def _qol_runtime_snapshot(self: ArtistELORanker) -> dict:
    return {
        "version": 1,
        "saved_at": time.time(),
        "session": deepcopy(self.qol_session),
        "recent_actions": list(self.qol_recent_actions),
        "undo_available": len(self.qol_undo_stack),
        "redo_available": len(self.qol_redo_stack),
        "current_duel_id": str(getattr(self.current_comparison, "duel_id", "") or ""),
    }


def _qol_load_runtime_state(self: ArtistELORanker) -> None:
    if not QOL_RUNTIME_STATE_FILE.exists():
        return
    try:
        raw = json.loads(QOL_RUNTIME_STATE_FILE.read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            return
        saved_at = float(raw.get("saved_at", 0.0) or 0.0)
        # Continue a recently interrupted session, but start fresh after a long gap.
        if saved_at and time.time() - saved_at <= 12 * 3600:
            loaded_session = raw.get("session", {})
            if isinstance(loaded_session, dict):
                self.qol_session.update(loaded_session)
                counts = self.qol_session.setdefault("counts", {})
                for key in ("A", "B", "TIE", "BOTH_BAD", "INVALID", "SKIP", "UNDO", "REDO"):
                    counts[key] = max(0, int(counts.get(key, 0) or 0))
                samples = self.qol_session.get("coverage_samples", [])
                self.qol_session["coverage_samples"] = [
                    [int(item[0]), float(item[1])]
                    for item in list(samples)[-250:]
                    if isinstance(item, (list, tuple)) and len(item) >= 2
                ]
            recent = raw.get("recent_actions", [])
            if isinstance(recent, list):
                self.qol_recent_actions.extend(dict(item) for item in recent[-QOL_RECENT_ACTION_LIMIT:] if isinstance(item, dict))
    except Exception as exc:
        self.last_error_details = f"Could not restore QOL runtime state: {type(exc).__name__}: {exc}"


def _qol_save_runtime_state(self: ArtistELORanker) -> None:
    try:
        _qol_atomic_json(QOL_RUNTIME_STATE_FILE, self._qol_runtime_snapshot())
    except Exception as exc:
        self.last_error_details = f"Could not save QOL runtime state: {type(exc).__name__}: {exc}"


def _qol_enqueue_maintenance(self: ArtistELORanker, name: str, func: Any, *args: Any, **kwargs: Any) -> None:
    try:
        self.qol_maintenance_queue.put_nowait((str(name), func, tuple(args), dict(kwargs)))
    except Exception as exc:
        self.last_error_details = f"Could not queue {name}: {type(exc).__name__}: {exc}"


def _qol_maintenance_worker(self: ArtistELORanker) -> None:
    while True:
        try:
            name, func, args, kwargs = self.qol_maintenance_queue.get()
        except Exception:
            time.sleep(0.1)
            continue
        try:
            func(*args, **kwargs)
        except Exception as exc:
            self.last_error_details = f"Background {name} failed: {type(exc).__name__}: {exc}"
        finally:
            try:
                self.qol_maintenance_queue.task_done()
            except Exception:
                pass


def _qol_preview_fingerprint(self: ArtistELORanker, raw_path: str) -> Tuple[Path, Optional[Path]]:
    path = Path(str(raw_path or ""))
    cache_key = str(path)
    with self.qol_preview_lock:
        cached = self.qol_preview_fingerprint_cache.get(cache_key)
    if cached is not None:
        source_text, target_text = cached
        return Path(source_text), Path(target_text) if target_text else None
    if not path.exists() or not path.is_file() or PILImage is None:
        return path, None
    try:
        stat = path.stat()
        digest = hashlib.sha1(
            f"{path.resolve()}|{stat.st_mtime_ns}|{stat.st_size}|{QOL_PREVIEW_MAX_EDGE}|{QOL_PREVIEW_QUALITY}".encode("utf-8")
        ).hexdigest()[:28]
        QOL_PREVIEW_DIR.mkdir(parents=True, exist_ok=True)
        target = QOL_PREVIEW_DIR / f"duel_preview_{digest}.webp"
        with self.qol_preview_lock:
            self.qol_preview_fingerprint_cache[cache_key] = (str(path), str(target))
            if len(self.qol_preview_fingerprint_cache) > 4096:
                self.qol_preview_fingerprint_cache.pop(next(iter(self.qol_preview_fingerprint_cache)), None)
        return path, target
    except Exception:
        return path, None


def _qol_enqueue_preview(self: ArtistELORanker, raw_path: str) -> None:
    """Queue preview work without touching the filesystem on the vote thread."""
    key = str(raw_path or "").strip()
    if not key:
        return
    with self.qol_preview_lock:
        if key in self.qol_preview_ready or key in self.qol_preview_pending:
            return
        self.qol_preview_pending.add(key)
    try:
        self.qol_preview_queue.put_nowait(key)
    except Exception:
        with self.qol_preview_lock:
            self.qol_preview_pending.discard(key)


def _qol_preview_worker(self: ArtistELORanker) -> None:
    while True:
        raw_path = self.qol_preview_queue.get()
        temporary = None
        try:
            source, target = self._qol_preview_fingerprint(raw_path)
            if target is None or not source.exists():
                continue
            if target.exists():
                with self.qol_preview_lock:
                    self.qol_preview_ready.add(str(raw_path))
                continue
            temporary = target.with_suffix(target.suffix + ".tmp")
            with PILImage.open(source) as image:
                image = image.convert("RGB")
                image.thumbnail((QOL_PREVIEW_MAX_EDGE, QOL_PREVIEW_MAX_EDGE), PILImage.Resampling.LANCZOS)
                image.save(temporary, "WEBP", quality=QOL_PREVIEW_QUALITY, method=4)
            temporary.replace(target)
            with self.qol_preview_lock:
                self.qol_preview_ready.add(str(raw_path))
        except Exception as exc:
            self.last_error_details = f"Duel preview generation failed: {type(exc).__name__}: {exc}"
            try:
                if temporary is not None and temporary.exists():
                    temporary.unlink()
            except Exception:
                pass
        finally:
            with self.qol_preview_lock:
                self.qol_preview_pending.discard(str(raw_path))
            try:
                self.qol_preview_queue.task_done()
            except Exception:
                pass


def _qol_display_path(self: ArtistELORanker, raw_path: str) -> Optional[str]:
    if not raw_path:
        return None
    source, target = self._qol_preview_fingerprint(raw_path)
    if target is not None and target.exists():
        return str(target)
    self._qol_enqueue_preview(str(source))
    return str(source) if source.exists() else None


def _qol_enqueue_ready_previews(self: ArtistELORanker) -> None:
    with self.state_lock:
        items = ([self.current_comparison] if self.current_comparison else []) + list(self.comparison_queue)[:8]
    for item in items:
        if not item:
            continue
        self._qol_enqueue_preview(item.image_a_path)
        self._qol_enqueue_preview(item.image_b_path)


def _qol_prefetch_paths(self: ArtistELORanker) -> Tuple[Optional[str], Optional[str], Optional[str], Optional[str]]:
    with self.state_lock:
        items = list(self.comparison_queue)[:QOL_PREFETCH_DEPTH]
    paths: List[Optional[str]] = []
    for index in range(QOL_PREFETCH_DEPTH):
        item = items[index] if index < len(items) else None
        if item is None:
            paths.extend([None, None])
        else:
            paths.extend([
                self._qol_display_path(item.image_a_path),
                self._qol_display_path(item.image_b_path),
            ])
    return tuple(paths[:4])  # type: ignore[return-value]


def _qol_get_current_snapshot(self: ArtistELORanker) -> dict:
    snapshot = _ArtistELORanker_original_snapshot(self)
    if snapshot.get("image_a"):
        snapshot["original_image_a"] = snapshot["image_a"]
        snapshot["image_a"] = self._qol_display_path(snapshot["image_a"])
    if snapshot.get("image_b"):
        snapshot["original_image_b"] = snapshot["image_b"]
        snapshot["image_b"] = self._qol_display_path(snapshot["image_b"])
    return snapshot


def _qol_advance(self: ArtistELORanker) -> None:
    _ArtistELORanker_original_advance(self)
    # Queueing is nonblocking and lets the worker prepare the new current duel
    # and its two successors while the user judges the visible duel.
    current = self.current_comparison
    queued = list(self.comparison_queue)[:4]
    for item in ([current] if current else []) + queued:
        if item:
            self._qol_enqueue_preview(item.image_a_path)
            self._qol_enqueue_preview(item.image_b_path)


def _qol_deferred_favorite_refresh(
    self: ArtistELORanker, item: ComparisonItem, winner: str, history_number: int
) -> None:
    self._qol_enqueue_maintenance(
        "favorite metadata refresh",
        _ArtistELORanker_original_favorite_refresh,
        self,
        deepcopy(item),
        str(winner),
        int(history_number),
    )


def _qol_classification_events(self: ArtistELORanker, event_ids: Iterable[str]) -> List[dict]:
    ids = {str(value) for value in event_ids if str(value)}
    if not ids:
        return []
    with self.classifications.lock:
        by_id = {
            str(event.get("event_id", "")): deepcopy(event)
            for event in self.classifications.rotation_events
            if str(event.get("event_id", "")) in ids
        }
    return [by_id[event_id] for event_id in event_ids if event_id in by_id]


def _qol_record_recent(self: ArtistELORanker, action: str, item: Optional[ComparisonItem], note: str = "") -> None:
    self.qol_recent_actions.appendleft({
        "timestamp": time.time(),
        "action": str(action).upper(),
        "artists_a": list(getattr(item, "artists_a", []) or []),
        "artists_b": list(getattr(item, "artists_b", []) or []),
        "duel_id": str(getattr(item, "duel_id", "") or ""),
        "note": str(note or ""),
    })


def _qol_session_decision(
    self: ArtistELORanker,
    result: str,
    coverage_before: Optional[float] = None,
    coverage_after: Optional[float] = None,
    reverse: bool = False,
) -> None:
    now = time.time()
    session = self.qol_session
    counts = session.setdefault("counts", {})
    result = str(result or "").upper()
    for key in ("A", "B", "TIE", "BOTH_BAD", "INVALID", "SKIP", "UNDO", "REDO"):
        counts.setdefault(key, 0)
    if reverse:
        if result in counts:
            counts[result] = max(0, int(counts.get(result, 0) or 0) - 1)
    else:
        last = float(session.get("last_decision_at", 0.0) or 0.0)
        break_seconds = float(session.get("break_seconds", QOL_ACTIVE_BREAK_SECONDS) or QOL_ACTIVE_BREAK_SECONDS)
        if not float(session.get("started_at", 0.0) or 0.0):
            session["started_at"] = now
        if last > 0:
            gap = max(0.0, now - last)
            if gap <= break_seconds:
                session["active_seconds"] = float(session.get("active_seconds", 0.0) or 0.0) + gap
        session["last_decision_at"] = now
        if result in counts:
            counts[result] = int(counts.get(result, 0) or 0) + 1

    if coverage_after is not None:
        rated_count = sum(int(counts.get(key, 0) or 0) for key in ("A", "B", "TIE", "BOTH_BAD", "INVALID", "SKIP"))
        samples = list(session.get("coverage_samples", []) or [])
        samples.append([rated_count, float(coverage_after)])
        session["coverage_samples"] = samples[-250:]
    self._qol_enqueue_maintenance("QOL runtime save", self._qol_save_runtime_state)


def _qol_capture_after_state(
    self: ArtistELORanker,
    result: str,
    selected: ComparisonItem,
    before: UndoState,
    before_top50_tracking: dict,
) -> QOLVoteHistoryEntry:
    unique_artists = list(dict.fromkeys(selected.artists_a + selected.artists_b))
    after_ratings = {artist: self.elo_system.get_rating(artist) for artist in unique_artists}
    after_comparisons = {
        artist: self.elo_system.get_artist_comparison_count(artist)
        for artist in unique_artists
    }
    after_size_state = self.elo_system.snapshot_size_state(unique_artists)
    after_combination_entries = self.combination_elo.snapshot([
        selected.artists_a, selected.artists_b,
    ])
    after_top_search_state = self.top_search.snapshot_entities(
        unique_artists, [selected.artists_a, selected.artists_b]
    )
    after_pool_state = (
        self.artist_manager.active_pool.snapshot_runtime_state()
        if self.artist_manager.active_pool is not None else {}
    )
    before_evidence_length = int(before.old_top_search_state.get("evidence_length", len(self.top_search.evidence)) or 0)
    return QOLVoteHistoryEntry(
        result=str(result).upper(),
        before=before,
        before_top50_tracking=deepcopy(before_top50_tracking),
        after_ratings=after_ratings,
        after_comparisons=after_comparisons,
        after_size_state=after_size_state,
        after_combination_entries=after_combination_entries,
        after_top_search_state=after_top_search_state,
        after_evidence_tail=deepcopy(self.top_search.evidence[before_evidence_length:]),
        after_pool_state=after_pool_state,
        after_top50_tracking=deepcopy(self.top50_tracking),
        after_classification_events=self._qol_classification_events(before.rotation_event_ids),
        after_record=deepcopy(self.history.records[-1]) if self.history.records else {},
        after_elo_comparison_count=int(self.elo_system.comparison_count),
        result_msg=str(self.ui_result_msg or ""),
        details_msg=str(self.ui_details_msg or ""),
    )


def _qol_pick(self: ArtistELORanker, winner: str, trace: Optional[Any] = None) -> None:
    with self.state_lock:
        selected = self.current_comparison
        coverage_before = self.matchmaker.scheduler.coverage_ratio()
        before_top50_tracking = deepcopy(self.top50_tracking)
    _ArtistELORanker_original_pick(self, winner, trace)
    if selected is None or self.last_undo_state is None:
        return
    try:
        entry = self._qol_capture_after_state(str(winner), selected, self.last_undo_state, before_top50_tracking)
        self.qol_undo_stack.append(entry)
        self.qol_redo_stack.clear()
        self.last_undo_state = self.qol_undo_stack[-1].before
        coverage_after = self.matchmaker.scheduler.coverage_ratio()
        self._qol_session_decision(str(winner), coverage_before, coverage_after)
        self._qol_record_recent(str(winner), selected)
        self._qol_enqueue_maintenance("QOL runtime save", self._qol_save_runtime_state)
    except Exception as exc:
        self.last_error_details = f"Could not capture multi-step vote state: {type(exc).__name__}: {exc}"


def _qol_invalid(self: ArtistELORanker, trace: Optional[Any] = None) -> None:
    with self.state_lock:
        selected = self.current_comparison
        coverage_before = self.matchmaker.scheduler.coverage_ratio()
    _ArtistELORanker_original_invalid(self, trace)
    if selected is not None:
        self.qol_undo_stack.clear()
        self.qol_redo_stack.clear()
        self.last_undo_state = None
        self._qol_session_decision("INVALID", coverage_before, self.matchmaker.scheduler.coverage_ratio())
        self._qol_record_recent("INVALID", selected, "Undo history reset")


def _qol_skip(self: ArtistELORanker, trace: Optional[Any] = None) -> None:
    with self.state_lock:
        selected = self.current_comparison
        coverage_before = self.matchmaker.scheduler.coverage_ratio()
    _ArtistELORanker_original_skip(self, trace)
    if selected is not None:
        self.qol_undo_stack.clear()
        self.qol_redo_stack.clear()
        self.last_undo_state = None
        self._qol_session_decision("SKIP", coverage_before, self.matchmaker.scheduler.coverage_ratio())
        self._qol_record_recent("SKIP", selected, "Undo history reset")


def _qol_rebuild(self: ArtistELORanker, *args: Any, **kwargs: Any):
    result = _ArtistELORanker_original_rebuild(self, *args, **kwargs)
    self.qol_undo_stack.clear()
    self.qol_redo_stack.clear()
    self.last_undo_state = None
    self._qol_record_recent("SKIP", None, "Buffer rebuilt; Undo/Redo history reset")
    self._qol_enqueue_ready_previews()
    return result


def _qol_invalidate_views(self: ArtistELORanker) -> None:
    with self.browser_cache_lock:
        self.browser_cache_stamp = None
    with self.gallery_cache_lock:
        self.gallery_cache_stamp = None
    with self.storage_cache_lock:
        self.storage_cache_time = 0.0


def _qol_undo(self: ArtistELORanker) -> None:
    with self.state_lock:
        self.bayesian_refit_generation += 1
        if not self.qol_undo_stack:
            self.last_undo_state = None
            self.ui_result_msg = "Nothing to undo."
            self.ui_details_msg = ""
            return
        entry = self.qol_undo_stack.pop()
        state = entry.before
        for artist, old_rating in state.old_ratings.items():
            self.elo_system.ratings[artist] = old_rating
        for artist, old_count in state.old_comparisons.items():
            self.elo_system.artist_comparisons[artist] = old_count
        self.elo_system.restore_size_state(state.old_size_state)
        self.combination_elo.restore(state.old_combination_entries)
        self.top_search.restore_entities(state.old_top_search_state)
        self.top50_tracking = deepcopy(entry.before_top50_tracking)
        self.elo_system.comparison_count = max(0, int(entry.after_elo_comparison_count) - 1)

        if state.old_pool_state and self.artist_manager.active_pool is not None:
            self.artist_manager.active_pool.restore_runtime_state(state.old_pool_state, refresh=False)
        else:
            if state.rotated_out:
                self.artist_manager.restore_artists(state.rotated_out)
            if state.rotated_in:
                self.artist_manager.remove_artists(state.rotated_in)
        for event_id in reversed(state.rotation_event_ids):
            self.classifications.undo_rotation_event(event_id)

        if self.history.records:
            expected_id = str(entry.after_record.get("duel_id", "") or "")
            actual_id = str(self.history.records[-1].get("duel_id", "") or "")
            if not expected_id or expected_id == actual_id:
                self.history.records.pop()

        if self.current_comparison is not None:
            self.comparison_queue.appendleft(self.current_comparison)
        if state.selected_comparison is not None:
            self.current_comparison = state.selected_comparison

        self.qol_redo_stack.append(entry)
        self.last_undo_state = self.qol_undo_stack[-1].before if self.qol_undo_stack else None
        self.ui_result_msg = f"**Undone ({len(self.qol_undo_stack)} earlier vote(s) remain undoable).** Pick again or use Redo."
        self.ui_details_msg = ""
        self._qol_enqueue_ready_previews()

    self._qol_session_decision(entry.result, reverse=True)
    self._qol_session_decision("UNDO")
    self._qol_record_recent("UNDO", state.selected_comparison, _qol_result_label(entry.result))
    self._qol_invalidate_views()
    self._schedule_persistence()
    self.start_refill_if_needed()


def _qol_redo(self: ArtistELORanker) -> None:
    with self.state_lock:
        self.bayesian_refit_generation += 1
        if not self.qol_redo_stack:
            self.ui_result_msg = "Nothing to redo."
            self.ui_details_msg = ""
            return
        entry = self.qol_redo_stack.pop()
        selected = entry.before.selected_comparison
        current_id = str(getattr(self.current_comparison, "duel_id", "") or "")
        expected_id = str(getattr(selected, "duel_id", "") or "")
        if selected is None or (current_id and expected_id and current_id != expected_id):
            self.qol_redo_stack.append(entry)
            self.ui_result_msg = "Redo is unavailable because the current duel no longer matches the undone vote."
            self.ui_details_msg = ""
            return

        for artist, value in entry.after_ratings.items():
            self.elo_system.ratings[artist] = value
        for artist, value in entry.after_comparisons.items():
            self.elo_system.artist_comparisons[artist] = value
        self.elo_system.restore_size_state(entry.after_size_state)
        self.combination_elo.restore(entry.after_combination_entries)
        self.top_search.restore_entities(entry.after_top_search_state)
        target_evidence_length = int(entry.after_top_search_state.get("evidence_length", len(self.top_search.evidence)) or 0)
        if len(self.top_search.evidence) < target_evidence_length:
            needed = target_evidence_length - len(self.top_search.evidence)
            self.top_search.evidence.extend(deepcopy(entry.after_evidence_tail[:needed]))
            self.top_search.invalidate_ranking_cache()
        self.elo_system.comparison_count = int(entry.after_elo_comparison_count)
        if entry.after_pool_state and self.artist_manager.active_pool is not None:
            self.artist_manager.active_pool.restore_runtime_state(entry.after_pool_state, refresh=False)
        for event in entry.after_classification_events:
            _qol_restore_rotation_event(self.classifications, event)
        self.top50_tracking = deepcopy(entry.after_top50_tracking)
        if entry.after_record:
            self.history.records.append(deepcopy(entry.after_record))

        self.current_comparison = selected
        self._advance_to_next_comparison_locked()
        self.ui_result_msg = entry.result_msg
        self.ui_details_msg = entry.details_msg
        self.qol_undo_stack.append(entry)
        self.last_undo_state = self.qol_undo_stack[-1].before

    self._qol_session_decision(entry.result, coverage_after=self.matchmaker.scheduler.coverage_ratio())
    self._qol_session_decision("REDO")
    self._qol_record_recent("REDO", selected, _qol_result_label(entry.result))
    self._qol_invalidate_views()
    self._schedule_persistence()
    self.start_refill_if_needed()


def _qol_fast_action_ui_state(self: ArtistELORanker, trace: Optional[Any] = None):
    """Return only current-duel essentials; refresh editors on demand in the tools panel."""
    snapshot = self._get_current_snapshot()
    if trace:
        trace.mark("ui_snapshot")
    has_current = snapshot["image_a"] is not None and snapshot["image_b"] is not None
    artists_a_text = (
        f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_a"], "elo-duel-artist-link")}'
        if snapshot["artists_a"] else ""
    )
    artists_b_text = (
        f'<strong>Artists:</strong> {self.render_artist_links(snapshot["artists_b"], "elo-duel-artist-link")}'
        if snapshot["artists_b"] else ""
    )
    if trace:
        trace.mark("ui_artist_links")
    return (
        snapshot["image_a"], snapshot["image_b"], self.format_status_message(),
        snapshot["result_msg"], snapshot["details_msg"],
        gr.update(interactive=has_current), gr.update(interactive=has_current),
        gr.update(interactive=bool(self.qol_undo_stack)),
        artists_a_text, artists_b_text, self.format_current_duel_type(),
        gr.update(), gr.update(), gr.update(), gr.update(), gr.update(), gr.update(), gr.update(),
        *self._qol_prefetch_paths(),
        gr.update(interactive=bool(self.qol_redo_stack)),
        self.qol_session_dashboard_html(),
        self.qol_action_history_html(),
        self.qol_transition_token(),
    )


