def _qol_active_seconds(self: ArtistELORanker) -> float:
    session = self.qol_session
    active = float(session.get("active_seconds", 0.0) or 0.0)
    last = float(session.get("last_decision_at", 0.0) or 0.0)
    if last > 0:
        active += min(
            max(0.0, time.time() - last),
            float(session.get("break_seconds", QOL_ACTIVE_BREAK_SECONDS) or QOL_ACTIVE_BREAK_SECONDS),
        )
    return active


def _qol_format_duration(seconds: float) -> str:
    seconds = max(0, int(seconds or 0))
    hours, remainder = divmod(seconds, 3600)
    minutes, secs = divmod(remainder, 60)
    if hours:
        return f"{hours}h {minutes:02d}m"
    if minutes:
        return f"{minutes}m {secs:02d}s"
    return f"{secs}s"


def _qol_eta_label(duels: Optional[int], dph: float) -> str:
    if duels is None:
        return "—"
    if duels <= 0:
        return "Reached"
    if dph <= 0.1:
        return f"~{duels:,} duels"
    hours = duels / dph
    return f"~{duels:,} duels / {_qol_format_duration(hours * 3600)}"


def _qol_session_dashboard_html(self: ArtistELORanker) -> str:
    counts = self.qol_session.setdefault("counts", {})
    decision_count = sum(int(counts.get(key, 0) or 0) for key in ("A", "B", "TIE", "BOTH_BAD", "INVALID", "SKIP"))
    active_seconds = self._qol_active_seconds()
    dph = decision_count / max(active_seconds / 3600.0, 1e-9) if decision_count else 0.0
    a_count = int(counts.get("A", 0) or 0)
    b_count = int(counts.get("B", 0) or 0)
    side_total = a_count + b_count
    a_share = (a_count / side_total * 100.0) if side_total else 50.0
    bias_warning = ""
    if side_total >= 20 and (a_share >= 65.0 or a_share <= 35.0):
        favored = "A / left" if a_share > 50.0 else "B / right"
        bias_warning = f'<span class="qol-bias-warning">Possible {html.escape(favored)} bias</span>'

    coverage = float(self.matchmaker.scheduler.coverage_ratio())
    samples = list(self.qol_session.get("coverage_samples", []) or [])[-200:]
    gain_per_duel = 0.0
    if len(samples) >= 2:
        first_n, first_c = int(samples[0][0]), float(samples[0][1])
        last_n, last_c = int(samples[-1][0]), float(samples[-1][1])
        if last_n > first_n:
            gain_per_duel = max(0.0, (last_c - first_c) / (last_n - first_n))
    eta_items = []
    for target in (0.80, 0.90, 0.95, 0.99):
        if coverage >= target:
            duels = 0
        elif gain_per_duel > 1e-9:
            duels = int(math.ceil((target - coverage) / gain_per_duel))
        else:
            duels = None
        eta_items.append(
            f'<span><b>{int(target*100)}%</b> {_qol_eta_label(duels, dph)}</span>'
        )
    return (
        '<div class="qol-session-dashboard">'
        f'<div class="qol-session-card"><span>Active session</span><strong>{_qol_format_duration(active_seconds)}</strong></div>'
        f'<div class="qol-session-card"><span>Decisions</span><strong>{decision_count:,}</strong></div>'
        f'<div class="qol-session-card"><span>Active pace</span><strong>{dph:.1f}/hour</strong></div>'
        f'<div class="qol-session-card"><span>A / B choices</span><strong>{a_count} / {b_count}</strong>{bias_warning}</div>'
        f'<div class="qol-session-card"><span>Coverage</span><strong>{coverage*100:.2f}%</strong></div>'
        '<div class="qol-session-eta"><span class="qol-session-eta-label">Coverage ETA</span>'
        + ''.join(eta_items) + '</div></div>'
    )


def _qol_action_history_html(self: ArtistELORanker) -> str:
    rows: List[str] = []
    for action in list(self.qol_recent_actions)[:12]:
        timestamp = float(action.get("timestamp", 0.0) or 0.0)
        age = humanize_elapsed(max(0.0, time.time() - timestamp))
        side_a = " + ".join(action.get("artists_a", []) or []) or "—"
        side_b = " + ".join(action.get("artists_b", []) or []) or "—"
        note = str(action.get("note", "") or "")
        rows.append(
            '<tr>'
            f'<td>{html.escape(_qol_result_label(str(action.get("action", ""))))}</td>'
            f'<td>{html.escape(side_a)}</td><td>{html.escape(side_b)}</td>'
            f'<td>{html.escape(note)}</td><td>{html.escape(age)} ago</td>'
            '</tr>'
        )
    if not rows:
        return '<div class="qol-history-empty">No duel actions in this session yet.</div>'
    return (
        '<div class="qol-action-history-summary">'
        f'<span><b>{len(self.qol_undo_stack)}</b> undoable</span>'
        f'<span><b>{len(self.qol_redo_stack)}</b> redoable</span>'
        '</div><div class="qol-action-history-table-wrap"><table class="qol-action-history-table">'
        '<thead><tr><th>Action</th><th>Side A</th><th>Side B</th><th>Detail</th><th>When</th></tr></thead><tbody>'
        + ''.join(rows) + '</tbody></table></div>'
    )


def _qol_transition_token(self: ArtistELORanker) -> str:
    with self.state_lock:
        duel_id = str(getattr(self.current_comparison, "duel_id", "") or "")
        history_count = len(self.history.records)
    return f"{history_count}:{duel_id}:{len(self.qol_undo_stack)}:{len(self.qol_redo_stack)}"


def _qol_note_target_choices(self: ArtistELORanker) -> List[Tuple[str, str]]:
    with self.state_lock:
        item = self.current_comparison
        if item is None:
            return []
        choices: List[Tuple[str, str]] = []
        for side, artists in (("A", item.artists_a), ("B", item.artists_b)):
            normalized = self.combination_elo.normalize_artists(artists)
            choices.append((f"Combination {side}: {' + '.join(normalized)}", f"combination|{self.combination_elo.combination_id(normalized)}|{' + '.join(normalized)}"))
            for index, artist in enumerate(artists, start=1):
                choices.append((f"Artist {side}{index}: {artist}", f"artist|{artist}|{artist}"))
        return choices


def _qol_load_note(self: ArtistELORanker, target_value: str = ""):
    choices = self._qol_note_target_choices()
    values = [value for _, value in choices]
    selected = str(target_value or "")
    if selected not in values:
        selected = values[0] if values else None
    if not selected:
        return gr.update(choices=choices, value=None), "", "No duel is currently ready."
    parts = str(selected).split("|", 2)
    kind, key, label = parts if len(parts) == 3 else ("", "", "")
    entry = self.entity_notes.get(kind, key) if kind in ("artist", "combination") else None
    return gr.update(choices=choices, value=selected), str((entry or {}).get("note", "")), f"Editing note for **{label or key}**."


def _qol_save_note(self: ArtistELORanker, target_value: str, note: str) -> str:
    parts = str(target_value or "").split("|", 2)
    if len(parts) != 3:
        return "No valid note target is selected."
    kind, key, label = parts
    if kind not in ("artist", "combination") or not key:
        return "No valid note target is selected."
    saved = self.entity_notes.set(kind, key, label, str(note or ""), {})
    self._qol_invalidate_views()
    return f"Saved note for **{label}**." if saved else f"Cleared note for **{label}**."


def _qol_report_bad_image(self: ArtistELORanker, side: str, reason: str, details: str) -> str:
    side = str(side or "").upper()
    if side not in ("A", "B", "BOTH"):
        return "Choose Image A, Image B, or Both."
    with self.state_lock:
        item = self.current_comparison
        if item is None:
            return "No current duel is available to report."
        report = {
            "timestamp": time.time(),
            "duel_id": item.duel_id,
            "side": side,
            "reason": str(reason or "Other"),
            "details": str(details or "").strip(),
            "image_a_path": item.image_a_path,
            "image_b_path": item.image_b_path,
            "artists_a": list(item.artists_a),
            "artists_b": list(item.artists_b),
            "seed": item.seed,
            "matchmaking_reason": item.matchmaking_reason,
        }
    def save_report() -> None:
        existing: List[dict] = []
        if QOL_BAD_IMAGE_REPORTS_FILE.exists():
            try:
                loaded = json.loads(QOL_BAD_IMAGE_REPORTS_FILE.read_text(encoding="utf-8"))
                if isinstance(loaded, list):
                    existing = [dict(value) for value in loaded if isinstance(value, dict)]
            except Exception:
                existing = []
        existing.append(report)
        _qol_atomic_json(QOL_BAD_IMAGE_REPORTS_FILE, existing[-5000:])
    self._qol_enqueue_maintenance("bad-image report", save_report)
    return f"Recorded a bad-image report for **{side}**. This does not change ratings."


