DEDICATED_NAV_BRIDGE_HEAD = r"""
<script>
(() => {
  const install = () => {
    let raw = null;
    try { raw = localStorage.getItem('artistEloDedicatedNavigation'); } catch (_) {}
    if (!raw) return;
    const payloadRoot = document.getElementById('navigation-payload');
    const submitRoot = document.getElementById('navigation-submit');
    const input = payloadRoot?.querySelector('textarea,input');
    const button = submitRoot?.querySelector('button') || submitRoot;
    if (!input || !button) { setTimeout(install, 180); return; }
    try {
      const payload = JSON.parse(raw);
      const setter = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(input), 'value')?.set;
      if (setter) setter.call(input, JSON.stringify(payload)); else input.value = JSON.stringify(payload);
      input.dispatchEvent(new Event('input', {bubbles:true}));
      input.dispatchEvent(new Event('change', {bubbles:true}));
      localStorage.removeItem('artistEloDedicatedNavigation');
      setTimeout(() => button.click(), 80);
    } catch (error) {
      console.error('[Dedicated duel navigation bridge]', error);
      localStorage.removeItem('artistEloDedicatedNavigation');
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', install, {once:true}); else install();
})();
</script>
"""


def _dedicated_duel_preview_items(ranker, limit: int = 3):
    with ranker.state_lock:
        items = []
        if getattr(ranker, "current_comparison", None) is not None:
            items.append(ranker.current_comparison)
        items.extend(list(getattr(ranker, "comparison_queue", []))[:max(0, limit - len(items))])
        for item in items:
            try:
                ranker._ensure_current_duel_id_locked(item)
            except Exception:
                if not getattr(item, "duel_id", ""):
                    item.duel_id = hashlib.sha1(
                        f"{item.image_a_path}|{item.image_b_path}|{time.time()}".encode("utf-8")
                    ).hexdigest()[:20]
    return items[:limit]


def _dedicated_duel_find_item(ranker, duel_id: str):
    duel_id = str(duel_id or "").strip()
    if not duel_id:
        return None
    with ranker.state_lock:
        items = []
        if getattr(ranker, "current_comparison", None) is not None:
            items.append(ranker.current_comparison)
        items.extend(list(getattr(ranker, "comparison_queue", []))[:10])
        for item in items:
            try:
                current_id = ranker._ensure_current_duel_id_locked(item)
            except Exception:
                current_id = getattr(item, "duel_id", "")
            if str(current_id) == duel_id:
                return item
    return None


def _dedicated_combo_key(ranker, artists: List[str]) -> str:
    try:
        normalized = ranker.combination_elo.normalize_artists(list(artists or []))
        return ranker.combination_elo.combination_id(normalized)
    except Exception:
        return " + ".join(sorted(str(a) for a in artists or []))


def _dedicated_duel_to_payload(ranker, item):
    if item is None:
        return None
    duel_id = str(getattr(item, "duel_id", "") or "")
    if not duel_id:
        try:
            with ranker.state_lock:
                duel_id = ranker._ensure_current_duel_id_locked(item)
        except Exception:
            duel_id = hashlib.sha1(
                f"{item.image_a_path}|{item.image_b_path}".encode("utf-8")
            ).hexdigest()[:20]
            try:
                item.duel_id = duel_id
            except Exception:
                pass
    artists_a = list(getattr(item, "artists_a", []) or [])
    artists_b = list(getattr(item, "artists_b", []) or [])
    stamp = int(getattr(item, "created_at", 0.0) or time.time())
    return {
        "duel_id": duel_id,
        "image_a_url": f"/api/duel/image/{duel_id}/A?ts={stamp}",
        "image_b_url": f"/api/duel/image/{duel_id}/B?ts={stamp}",
        "artists_a": artists_a,
        "artists_b": artists_b,
        "matchmaking_reason": str(
            getattr(item, "matchmaking_reason", "Historical / unknown") or "Historical / unknown"
        ),
        "matchmaking_details": str(getattr(item, "matchmaking_details", "") or ""),
        "seed": int(getattr(item, "seed", 0) or 0),
        "combination_a_key": _dedicated_combo_key(ranker, artists_a),
        "combination_b_key": _dedicated_combo_key(ranker, artists_b),
    }


def _dedicated_result_artist(ranker, artist: str, record: dict) -> dict:
    skill_delta = float((record.get("top_search_rating_changes", {}) or {}).get(artist, 0.0) or 0.0)
    legacy_delta = float((record.get("legacy_rating_changes", {}) or {}).get(artist, 0.0) or 0.0)
    try:
        mu = float(ranker.top_search.get_mu(artist))
        top50_probability = float(ranker.top_search.top_k_probability(artist) * 100.0)
    except Exception:
        mu = float(ranker.elo_system.get_rating(artist))
        top50_probability = 0.0
    return {
        "name": str(artist),
        "skill_delta": skill_delta,
        "legacy_delta": legacy_delta,
        "mu": mu,
        "top50_probability": top50_probability,
    }


def _dedicated_build_result(ranker, record: Optional[dict], action: str = "") -> Optional[dict]:
    action = str(action or "").upper()
    if action == "UNDO":
        return {"title": "Last vote undone", "subtitle": "The previous duel and ratings were restored.", "sides": []}
    if action == "SKIP":
        return {"title": "Duel skipped", "subtitle": "No rating evidence was recorded.", "sides": []}
    if not isinstance(record, dict):
        return None
    artists_a = list(record.get("artists_a", []) or [])
    artists_b = list(record.get("artists_b", []) or [])
    both_bad = bool(record.get("both_bad", False))
    winner = str(record.get("winner", "TIE") or "TIE").upper()
    if both_bad:
        title = "Both images rejected"
        subtitle = "Poor-output evidence was recorded without selecting a relative winner."
        label_a = label_b = "Both bad"
    elif winner == "TIE":
        title = "Tie — too close to call"
        subtitle = "Both sides received evidence; neither side received a win."
        label_a = label_b = "Tie"
    else:
        winning_artists = artists_a if winner == "A" else artists_b
        losing_artists = artists_b if winner == "A" else artists_a
        title = f"Winner: {' + '.join(winning_artists)}"
        subtitle = f"Defeated {' + '.join(losing_artists)}"
        label_a = "Winner" if winner == "A" else "Lost"
        label_b = "Winner" if winner == "B" else "Lost"
    expected_a = float(record.get("top_search_expected_a", 0.5) or 0.5)
    expected_a = max(0.0, min(1.0, expected_a))
    return {
        "title": title,
        "subtitle": subtitle,
        "expected_a_pct": expected_a * 100.0,
        "expected_b_pct": (1.0 - expected_a) * 100.0,
        "sides": [
            {
                "side": "A",
                "label": label_a,
                "artists": [_dedicated_result_artist(ranker, artist, record) for artist in artists_a],
            },
            {
                "side": "B",
                "label": label_b,
                "artists": [_dedicated_result_artist(ranker, artist, record) for artist in artists_b],
            },
        ],
        "duel_type": str(record.get("matchmaking_reason", "") or ""),
    }


def _dedicated_coverage_metrics(ranker) -> dict:
    """Authoritative coverage/evidence progress for the dedicated duel page.

    Coverage counts come from the same Bayesian Top Search system used by the
    scheduler and ranking tables, not from the legacy ELO compatibility counts.
    """
    try:
        global_duels = int(getattr(ranker.top_search, "comparison_count", 0) or 0)
    except Exception:
        try:
            global_duels = len(getattr(ranker.history, "records", []) or [])
        except Exception:
            global_duels = 0

    cache = getattr(ranker, "_dedicated_coverage_cache_v5", None)
    if isinstance(cache, dict) and int(cache.get("global_duels", -1)) == global_duels:
        return deepcopy(cache.get("payload", {}))

    with ranker.state_lock:
        manager = getattr(ranker, "artist_manager", None)
        catalog = list(getattr(manager, "artists", []) or [])
        if not catalog:
            active_pool = getattr(manager, "active_pool", None)
            catalog = list(getattr(active_pool, "all_artists", []) or [])
        if not catalog:
            catalog = list(getattr(getattr(ranker, "top_search", None), "artists", {}).keys())
        catalog = list(dict.fromkeys(str(artist) for artist in catalog if str(artist)))
        records = list(getattr(ranker.history, "records", []) or [])
        scheduler = getattr(getattr(ranker, "matchmaker", None), "scheduler", None)
        mode = str(getattr(scheduler, "generation_mode", "coverage") or "coverage")
        try:
            taper = float(scheduler.selection_taper_progress()) if scheduler is not None else 0.0
        except Exception:
            taper = 0.0

    def count_for(artist: str) -> int:
        try:
            return int(ranker.top_search.get_comparison_count(artist) or 0)
        except Exception:
            try:
                return int(getattr(ranker.elo_system, "artist_comparisons", {}).get(artist, 0) or 0)
            except Exception:
                return 0

    counts = {artist: count_for(artist) for artist in catalog}
    total = len(catalog)
    level_thresholds = (1, 2, 3, 5)
    level_counts = {threshold: sum(1 for value in counts.values() if value >= threshold) for threshold in level_thresholds}
    seen = level_counts[1]
    two_plus = level_counts[2]
    one_match = sum(1 for value in counts.values() if value == 1)
    unseen = max(0, total - seen)

    # Select the next meaningful evidence stage rather than declaring the whole
    # ranking project complete as soon as every artist has merely appeared once.
    active_threshold = 5
    for threshold in level_thresholds:
        if level_counts[threshold] < total:
            active_threshold = threshold
            break
    active_count = level_counts[active_threshold]
    active_fraction = float(active_count) / float(total or 1)
    stage_labels = {
        1: "first-appearance coverage",
        2: "2+ match coverage",
        3: "3+ match evidence",
        5: "5+ match evidence",
    }
    active_goal_label = stage_labels[active_threshold]
    all_configured_complete = bool(total and level_counts[5] >= total)

    # Reconstruct the comparison counts at the beginning of a recent history
    # window, then count how many artists crossed each evidence threshold.
    window = min(500, len(records))
    recent_records = records[-window:] if window else []
    involved = set()
    for record in recent_records:
        involved.update(str(a) for a in list(record.get("artists_a", []) or []) + list(record.get("artists_b", []) or []))
    rolling = {artist: int(counts.get(artist, 0) or 0) for artist in involved}
    for record in reversed(recent_records):
        participants = set(str(a) for a in list(record.get("artists_a", []) or []) + list(record.get("artists_b", []) or []))
        for artist in participants:
            rolling[artist] = max(0, int(rolling.get(artist, 0) or 0) - 1)

    crossings = {threshold: 0 for threshold in level_thresholds}
    participant_events = 0
    for record in recent_records:
        participants = set(str(a) for a in list(record.get("artists_a", []) or []) + list(record.get("artists_b", []) or []))
        participant_events += len(participants)
        for artist in participants:
            before = int(rolling.get(artist, 0) or 0)
            after = before + 1
            for threshold in level_thresholds:
                if before < threshold <= after:
                    crossings[threshold] += 1
            rolling[artist] = after

    rates = {
        threshold: (float(crossings[threshold]) / float(window) if window else 0.0)
        for threshold in level_thresholds
    }
    active_rate = rates.get(active_threshold, 0.0)

    targets = (("80", .80), ("90", .90), ("95", .95), ("99", .99), ("100", 1.0))
    active_etas = {}
    next_target_label = ""
    next_eta = 0 if all_configured_complete else None
    for label, target in targets:
        target_count = int(math.ceil(total * target))
        remaining = max(0, target_count - active_count)
        eta = 0 if remaining <= 0 else (int(math.ceil(remaining / active_rate)) if active_rate > 0 else None)
        active_etas[label] = eta
        if not all_configured_complete and not next_target_label and target > active_fraction + 1e-12:
            next_target_label = f"{label}% at {active_threshold}+"
            next_eta = eta
    if not all_configured_complete and not next_target_label:
        next_target_label = f"100% at {active_threshold}+"
        next_eta = active_etas.get("100")

    discovery_fraction = float(seen) / float(total or 1)
    followup_fraction = float(two_plus) / float(total or 1)
    payload = {
        "global_duels": global_duels,
        "total": total,
        "seen": seen,
        "unseen": unseen,
        "one_match": one_match,
        "two_plus": two_plus,
        "fraction": discovery_fraction,
        "discovery_fraction": discovery_fraction,
        "followup_fraction": followup_fraction,
        "coverage_levels": {str(threshold): level_counts[threshold] for threshold in level_thresholds},
        "coverage_fractions": {
            str(threshold): float(level_counts[threshold]) / float(total or 1)
            for threshold in level_thresholds
        },
        "mode": mode,
        "mode_label": "Manual Selection" if mode == "selection" else "Coverage / automatic taper",
        "taper_percent": max(0.0, min(100.0, taper * 100.0)),
        "active_stage": f"match_{active_threshold}",
        "active_threshold": active_threshold,
        "active_goal_label": active_goal_label,
        "active_target_label": next_target_label,
        "active_eta_duels": next_eta,
        "active_etas": active_etas,
        "configured_complete": all_configured_complete,
        "recent": {
            "window_duels": window,
            "participant_events": participant_events,
            "crossings": {str(threshold): crossings[threshold] for threshold in level_thresholds},
            "rates_per_100": {str(threshold): rates[threshold] * 100.0 for threshold in level_thresholds},
            "active_crossings": crossings.get(active_threshold, 0),
            "active_per_100": active_rate * 100.0,
            # Backward-compatible keys used by older dedicated-page builds.
            "first_appearances": crossings[1],
            "second_appearances": crossings[2],
            "first_per_100": rates[1] * 100.0,
            "second_per_100": rates[2] * 100.0,
        },
    }
    ranker._dedicated_coverage_cache_v5 = {"global_duels": global_duels, "payload": deepcopy(payload)}
    return payload

def _dedicated_buffer_metrics(ranker) -> dict:
    try:
        snapshot = ranker._get_current_snapshot()
        return {
            "total_ready": int(snapshot.get("total_ready", 0) or 0),
            "queued": int(snapshot.get("queued", 0) or 0),
            "target": int(snapshot.get("target_buffer_size", 0) or 0),
            "refill": bool(snapshot.get("refill", False)),
            "paused": bool(snapshot.get("generation_paused", False)),
            "error": str(snapshot.get("error", "") or ""),
        }
    except Exception:
        return {"total_ready": 0, "queued": 0, "target": 0, "refill": False, "paused": False, "error": ""}


def _dedicated_duel_state_payload(ranker):
    items = _dedicated_duel_preview_items(ranker, limit=3)
    current = _dedicated_duel_to_payload(ranker, items[0]) if items else None
    queued = [_dedicated_duel_to_payload(ranker, item) for item in items[1:]] if len(items) > 1 else []
    coverage = _dedicated_coverage_metrics(ranker)
    if current is not None:
        current["global_duels"] = coverage.get("global_duels", 0)
        current["coverage_fraction"] = coverage.get("fraction", 0.0)
    return {
        "current": current,
        "queue": queued,
        "last_result": deepcopy(getattr(ranker, "_dedicated_last_result", None)),
        "global_duels": coverage.get("global_duels", 0),
        "coverage_fraction": coverage.get("fraction", 0.0),
        "coverage": coverage,
        "buffer": _dedicated_buffer_metrics(ranker),
    }



def _dedicated_generation_payload(ranker) -> dict:
    with ranker.state_lock:
        settings = normalize_generation_settings(
            dict(getattr(ranker, "generation_settings", {}) or {}),
            DEFAULT_GENERATION_PROFILE_SETTINGS,
        )
        profiles = deepcopy(getattr(ranker, "saved_prompts", {}) or {})
        payload = {
            "schema_version": PROFILE_SCHEMA_VERSION,
            "settings": {
                "positive_prompt_text": str(settings.get("positive_prompt_text", "") or ""),
                "negative_prompt_text": str(settings.get("negative_prompt_text", "") or ""),
                "quality_toggle": bool(settings.get("quality_toggle", True)),
                "uc_preset": int(settings.get("uc_preset", 0) or 0),
                "resolution_preset": str(settings.get("resolution_preset", "portrait")),
                "width": int(settings.get("width", IMG_WIDTH)),
                "height": int(settings.get("height", IMG_HEIGHT)),
                "steps": int(settings.get("steps", STEPS)),
                "sampler": str(settings.get("sampler", DEFAULT_SAMPLER_ID)),
                "scheduler": str(settings.get("scheduler", "default")),
                "decrisp_mode": bool(settings.get("decrisp_mode", False)),
                "variety_boost": bool(settings.get("variety_boost", False)),
                "target_buffer_size": int(getattr(ranker, "target_buffer_size", BUFFER_TARGET_SIZE) or BUFFER_TARGET_SIZE),
                "generation_paused": bool(getattr(ranker, "generation_paused", False)),
                "rotation_enabled": bool(settings.get("rotation_enabled", False)),
                "rotation_names": [name for name in list(settings.get("rotation_names", []) or []) if name in profiles],
            },
            "profiles": profiles,
            # Compatibility alias for pre-Phase-3 Android/web clients.
            "presets": profiles,
            "profile_ownership_choices": [
                {"label": label, "value": value} for label, value in OWNERSHIP_CHOICES
            ],
            "resolution_presets": [
                {"label": label, "value": value, **deepcopy(RESOLUTION_PRESETS[value])}
                for label, value in RESOLUTION_CHOICES
            ],
            "sampler_choices": [
                {"label": label, "value": value} for label, value in SAMPLER_CHOICES
            ],
            "scheduler_choices": [
                {"label": label, "value": value} for label, value in SCHEDULER_CHOICES
            ],
            "buffer_min": MIN_BUFFER_SIZE,
            "buffer_max": MAX_BUFFER_SIZE,
        }
    return payload


def _dedicated_plain_message(value: Any) -> str:
    return re.sub(r"[*_`]", "", str(value or "")).strip()


def _dedicated_favorite_target(ranker, label: str):
    try:
        target, _choices = ranker._resolve_compare_favorite_target(str(label or "Duel — both images"), "")
        return target
    except Exception:
        return None



