# DEDICATED_GALLERY_SIZE_KEYBOARD_REPAIR_V174
def _dedicated_artist_ladder_payload(
    ranker,
    q: str = "",
    sort: str = "top",
    stage: str = "",
    favorites: bool = False,
    offset: int = 0,
    limit: int = 30,
) -> dict:
    ranker._ensure_browser_records_cache()
    query = str(q or "").strip().casefold()
    stage_filter = str(stage or "").strip().casefold()
    with ranker.browser_cache_lock:
        records = list(ranker.artist_browser_records_cache)
    if query:
        records = [record for record in records if _boolean_search_matches(query, record.get("search_blob", record))]
    if stage_filter:
        records = [record for record in records if str(record.get("stage", "")).casefold() == stage_filter]
    if bool(favorites):
        records = [record for record in records if bool(record.get("favorite", False))]
    sort_key = str(sort or "top").strip().casefold()
    sorters = {
        "top": (lambda record: float(record.get("top_score", 0.0) or 0.0), True, "Top-search score"),
        "potential": (lambda record: float(record.get("potential_score", 0.0) or 0.0), True, "Potential"),
        "top50": (lambda record: float(record.get("top50_probability", 0.0) or 0.0), True, "Top-50 probability"),
        "uncertainty": (lambda record: float(record.get("top_sigma", 0.0) or 0.0), True, "Uncertainty"),
        "duels": (lambda record: int(record.get("duels", 0) or 0), True, "Duels fought"),
        "alphabetical": (lambda record: str(record.get("artist", "")).casefold(), False, "Alphabetical"),
    }
    key_fn, reverse, sort_label = sorters.get(sort_key, sorters["top"])
    records.sort(key=key_fn, reverse=reverse)
    total = len(records)
    offset = max(0, int(offset or 0))
    limit = max(1, min(100, int(limit or 30)))
    page = records[offset:offset + limit]
    items = []
    for record in page:
        badges = []
        for badge in list(record.get("badges", []) or [])[:8]:
            if not isinstance(badge, dict):
                continue
            badges.append({"label": str(badge.get("label", "") or ""), "icon": str(badge.get("icon", "") or "")})
        items.append({
            "rank": int(record.get("rank", 0) or 0),
            "artist": str(record.get("artist", "") or ""),
            "favorite": bool(record.get("favorite", False)),
            "top_score": float(record.get("top_score", 0.0) or 0.0),
            "potential_score": float(record.get("potential_score", 0.0) or 0.0),
            "top_mu": float(record.get("top_mu", 0.0) or 0.0),
            "top_sigma": float(record.get("top_sigma", 0.0) or 0.0),
            "top50_probability": float(record.get("top50_probability", 0.0) or 0.0),
            "stage": str(record.get("stage", "Unknown") or "Unknown"),
            "duels": int(record.get("duels", 0) or 0),
            "wins": int(record.get("wins", 0) or 0),
            "losses": int(record.get("losses", 0) or 0),
            "ties": int(record.get("ties", 0) or 0),
            "win_rate": float(record.get("win_rate", 0.0) or 0.0),
            "weighted_wr": float(record.get("weighted_wr", 0.0) or 0.0),
            "confidence": str(record.get("confidence", "") or ""),
            "manual_tags": list(record.get("manual_tags", []) or []),
            "badges": badges,
        })
    return {
        "items": items,
        "total": total,
        "offset": offset,
        "limit": limit,
        "has_more": offset + len(items) < total,
        "sort": sort_key,
        "sort_label": sort_label,
    }


# DEDICATED_MOBILE_GALLERY_V17
def _dedicated_gallery_side_matches(ranker, side: List[str], required: List[str], exact: bool) -> bool:
    return ranker._gallery_side_matches_artists(side, required, bool(exact))


def _dedicated_gallery_list_payload(
    ranker,
    q: str = "",
    artist: str = "",
    exact: bool = False,
    preset: str = "",
    favorite: bool = False,
    lost: bool = False,
    outcome: str = "all",
    images: str = "all",
    sizes: str = "",
    offset: int = 0,
    limit: int = 18,
) -> dict:
    ranker._ensure_gallery_records_cache()
    with ranker.gallery_cache_lock:
        records = [dict(record) for record in ranker.gallery_records_cache]
    available_presets = sorted(
        {str(record.get("preset", "") or "") for record in records if str(record.get("preset", "") or "")},
        key=str.casefold,
    )
    query = str(q or "").strip().casefold()
    artist_query = str(artist or "").strip()
    left, right, versus, error = ranker._parse_gallery_artist_query(artist_query)
    if error:
        raise ValueError(error)

    def side_matches(side: List[str], required: List[str]) -> bool:
        return _dedicated_gallery_side_matches(ranker, side, required, bool(exact))

    def orientation(record: dict) -> str:
        if not versus:
            return ""
        if side_matches(record.get("artists_a", []), left) and side_matches(record.get("artists_b", []), right):
            return "A"
        if side_matches(record.get("artists_b", []), left) and side_matches(record.get("artists_a", []), right):
            return "B"
        return ""

    if artist_query:
        if versus:
            records = [record for record in records if orientation(record)]
        elif left:
            records = [
                record for record in records
                if side_matches(record.get("artists_a", []), left)
                or side_matches(record.get("artists_b", []), left)
            ]
    if query:
        records = [record for record in records if _boolean_search_matches(query, record.get("search_blob", record))]
    selected_preset = str(preset or "").strip()
    if selected_preset:
        records = [record for record in records if str(record.get("preset", "") or "") == selected_preset]
    if favorite:
        records = [record for record in records if bool(record.get("favorite", False))]
    if lost:
        selected = left + right if versus else left
        if not selected:
            raise ValueError("Choose an artist or matchup before using the lost-only filter.")
        def selected_lost(record: dict) -> bool:
            winner = str(record.get("winner", "") or "").upper()
            if bool(record.get("both_bad", False)) or winner not in ("A", "B"):
                return False
            if versus:
                selected_side = orientation(record)
            else:
                a = side_matches(record.get("artists_a", []), left)
                b = side_matches(record.get("artists_b", []), left)
                selected_side = "A" if a and not b else "B" if b and not a else ""
            return bool(selected_side) and selected_side != winner
        records = [record for record in records if selected_lost(record)]
    wanted = str(outcome or "all").strip().upper()
    outcome_map = {"A": "A", "B": "B", "TIE": "TIE", "INVALID": "INVALID", "BOTH_BAD": "BOTH_BAD"}
    if wanted in outcome_map:
        def record_outcome(record: dict) -> str:
            return "BOTH_BAD" if bool(record.get("both_bad", False)) else str(record.get("winner", "") or "").upper()
        records = [record for record in records if record_outcome(record) == outcome_map[wanted]]
    image_mode = str(images or "all").strip().lower()
    if image_mode == "available":
        records = [record for record in records if bool(record.get("images_available", False))]
    elif image_mode == "missing":
        records = [record for record in records if not bool(record.get("images_available", False))]

    selected_sizes = {
        int(value) for value in re.split(r"[,;\s]+", str(sizes or "").strip())
        if value.isdigit() and int(value) in (1, 2, 3)
    }
    if selected_sizes:
        def mobile_record_size_match(record: dict) -> bool:
            side_sizes = {
                len(list(record.get("artists_a", []) or [])),
                len(list(record.get("artists_b", []) or [])),
            } - {0}
            return bool(side_sizes) and side_sizes.issubset(selected_sizes)

        records = [record for record in records if mobile_record_size_match(record)]
    try:
        offset = max(0, int(offset or 0))
    except (TypeError, ValueError):
        offset = 0
    try:
        limit = max(6, min(48, int(limit or 18)))
    except (TypeError, ValueError):
        limit = 18
    total = len(records)
    page = records[offset:offset + limit]
    items = []
    for record in page:
        history_number = int(record.get("history_number", 0) or 0)
        result = "BOTH_BAD" if bool(record.get("both_bad", False)) else str(record.get("winner", "?") or "?").upper()
        history_record = ranker._history_record_by_number(history_number) or {}
        image_a_available = bool(gallery_record_preview(history_record, "A", False))
        image_b_available = bool(gallery_record_preview(history_record, "B", False))
        image_a_original_retained = Path(str(history_record.get("image_a_path", "") or "")).is_file()
        image_b_original_retained = Path(str(history_record.get("image_b_path", "") or "")).is_file()
        size_a = len(list(record.get("artists_a", []) or []))
        size_b = len(list(record.get("artists_b", []) or []))
        size_names = {1: "Solo", 2: "Duo", 3: "Trio"}
        size_label = (
            size_names.get(size_a, f"{size_a} artists")
            if size_a == size_b
            else f"{size_names.get(size_a, size_a)} vs {size_names.get(size_b, size_b)}"
        )
        items.append({
            "history_number": history_number,
            "date": str(record.get("date", "Unknown")),
            "timestamp": float(record.get("timestamp", 0.0) or 0.0),
            "outcome": result,
            "favorite": bool(record.get("favorite", False)),
            "artists_a": list(record.get("artists_a", []) or []),
            "artists_b": list(record.get("artists_b", []) or []),
            "size_a": size_a,
            "size_b": size_b,
            "size_label": size_label,
            "match_type": str(record.get("reason", "Historical / unknown") or "Historical / unknown"),
            "preset": str(record.get("preset", "") or ""),
            "seed": int(record.get("seed", 0) or 0),
            "image_a_available": image_a_available,
            "image_b_available": image_b_available,
            "image_a_original_retained": image_a_original_retained,
            "image_b_original_retained": image_b_original_retained,
            "image_a_url": f"/api/duel/gallery/image/{history_number}/A",
            "image_b_url": f"/api/duel/gallery/image/{history_number}/B",
        })
    next_offset = min(total, offset + len(items))
    return {
        "items": items,
        "total": total,
        "offset": offset,
        "next_offset": next_offset,
        "has_more": next_offset < total,
        "presets": available_presets,
    }


def _dedicated_gallery_detail_payload(ranker, history_number: Any) -> dict:
    record = ranker._history_record_by_number(history_number)
    if record is None:
        raise KeyError("That historical duel no longer exists.")
    history_number = int(history_number)
    _preview_a, _preview_b, raw_json, _selected = ranker.load_gallery_duel_modal(history_number, False, "mobile-gallery")
    payload = json.loads(raw_json)
    if not payload.get("ok"):
        raise KeyError(payload.get("error", "That historical duel could not be loaded."))
    payload.pop("image_a_path", None)
    payload.pop("image_b_path", None)
    payload["image_a_url"] = f"/api/duel/gallery/image/{history_number}/A"
    payload["image_b_url"] = f"/api/duel/gallery/image/{history_number}/B"
    targets = []
    for label, target in ranker._gallery_target_map(record, history_number).items():
        tags, note, _status = ranker.get_favorite_fields(target["kind"], target["key"])
        targets.append({
            "label": label,
            "kind": target["kind"],
            "is_favorite": bool(ranker.favorites.get(target["kind"], target["key"])),
            "tags": tags,
            "note": note,
        })
    payload["targets"] = targets
    return payload


