    @server.post("/api/duel/action")
    async def dedicated_duel_action(request: Request):
        payload = await request.json()
        action = str(payload.get("action", "")).strip().upper()
        duel_id = str(payload.get("duel_id", "")).strip()
        try:
            current_items = _dedicated_duel_preview_items(ranker, limit=1)
            current_item = current_items[0] if current_items else None
            current_id = str(getattr(current_item, "duel_id", "") or "") if current_item else ""
            history_before = len(getattr(ranker.history, "records", []))
            if action == "UNDO":
                ranker.undo_last_selection()
                ranker._dedicated_last_result = _dedicated_build_result(ranker, None, "UNDO")
            elif action == "SKIP":
                if current_id and duel_id and current_id != duel_id:
                    raise HTTPException(status_code=409, detail="The duel changed before Skip was submitted.")
                ranker.skip_current_comparison(None)
                ranker._dedicated_last_result = _dedicated_build_result(ranker, None, "SKIP")
            elif action in {"A", "B", "TIE", "BOTH_BAD"}:
                if not current_id or not duel_id or current_id != duel_id:
                    raise HTTPException(status_code=409, detail="The duel changed before the vote was submitted.")
                ranker.pick_winner_and_advance(action, None)
                records = getattr(ranker.history, "records", [])
                record = records[-1] if len(records) > history_before else None
                ranker._dedicated_last_result = _dedicated_build_result(ranker, record, action)
            else:
                raise HTTPException(status_code=400, detail="Unsupported action.")
            ranker.start_refill_if_needed()
            return JSONResponse({"ok": True, "state": _dedicated_duel_state_payload(ranker)})
        except HTTPException:
            raise
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"{type(exc).__name__}: {exc}")

