    @server.post("/api/duel/generation/settings")
    async def dedicated_generation_settings(request: Request):
        payload = await request.json()
        positive = str(payload.get("positive_prompt", "") or "")
        negative = str(payload.get("negative_prompt", "") or "")
        quality = bool(payload.get("quality_toggle", True))
        try:
            uc_preset = int(payload.get("uc_preset", 0))
        except (TypeError, ValueError):
            uc_preset = 0
        if uc_preset not in {-1, 0, 1, 2, 3}:
            raise HTTPException(status_code=400, detail="Unsupported auto-negative preset.")
        try:
            target = int(payload.get("target_buffer_size", BUFFER_TARGET_SIZE))
        except (TypeError, ValueError):
            target = BUFFER_TARGET_SIZE
        rotation_names = payload.get("rotation_names", [])
        if not isinstance(rotation_names, list):
            rotation_names = []
        changed = ranker.update_generation_settings(
            positive,
            negative,
            quality,
            uc_preset,
            target,
            bool(payload.get("rotation_enabled", False)),
            [str(name) for name in rotation_names],
            str(payload.get("resolution_preset", "portrait") or "portrait"),
            payload.get("width", IMG_WIDTH),
            payload.get("height", IMG_HEIGHT),
            payload.get("steps", STEPS),
            str(payload.get("sampler", DEFAULT_SAMPLER_ID) or DEFAULT_SAMPLER_ID),
            str(payload.get("scheduler", "default") or "default"),
            bool(payload.get("decrisp_mode", False)),
            bool(payload.get("variety_boost", False)),
        )
        requested_paused = bool(payload.get("generation_paused", False))
        with ranker.state_lock:
            pause_changed = bool(ranker.generation_paused) != requested_paused
            ranker.generation_paused = requested_paused
        if pause_changed:
            ranker._schedule_persistence(sections={"buffer"}) if hasattr(ranker, "_schedule_persistence") else ranker._save_buffer_state()
        if not requested_paused:
            ranker.start_refill_if_needed()
        return JSONResponse({
            "ok": True,
            "message": "Generation settings applied." if changed or pause_changed else "Generation settings were already current.",
            "state": _dedicated_generation_payload(ranker),
        })

