    @server.post("/api/diagnostics/browser-events")
    async def diagnostics_browser_events(request: Request):
        if not GLOBAL_DUEL_DIAGNOSTICS.enabled:
            return JSONResponse({"ok": True, "ignored": True})
        payload = await request.json()
        events = payload.get("events", []) if isinstance(payload, dict) else []
        if not isinstance(events, list):
            raise HTTPException(status_code=400, detail="events must be a list")
        accepted = 0
        for event in events[:100]:
            if not isinstance(event, dict):
                continue
            GLOBAL_DUEL_DIAGNOSTICS.write("browser_input_timeline", event, browser=True)
            accepted += 1
        return JSONResponse({"ok": True, "accepted": accepted})

    # Phase 8 public launcher/tray controller API. Every mutating action is
    # restricted to the local PC; paired LAN clients cannot pause or stop the server.
    def _require_public_local(request: Request) -> None:
        if not is_local_request(request):
            raise HTTPException(status_code=403, detail="This launcher action is available only on the ranker PC.")

    @server.get("/api/public/health")
    async def public_launcher_health():
        return JSONResponse({
            "ok": True,
            "application": "NovelAI Artist Ranker",
            "version": SHAREABLE_EDITION_VERSION,
            "port": int(SERVER_PORT),
        }, headers={"Cache-Control": "no-store"})

    @server.get("/api/public/status")
    async def public_launcher_status(request: Request):
        _require_public_local(request)
        with ranker.state_lock:
            current = getattr(ranker, "current_comparison", None)
            queued = len(getattr(ranker, "comparison_queue", []))
            paused = bool(getattr(ranker, "generation_paused", False))
            generated = int(getattr(ranker, "generated_count", 0) or 0)
            target = int(getattr(ranker, "target_buffer_size", BUFFER_TARGET_SIZE) or BUFFER_TARGET_SIZE)
            completed = int(getattr(ranker.elo_system, "comparison_count", 0) or 0)
        return JSONResponse({
            "ok": True,
            "version": SHAREABLE_EDITION_VERSION,
            "generation_paused": paused,
            "buffer_ready": queued + int(current is not None),
            "buffer_target": target,
            "generated_images": generated,
            "completed_duels": completed,
            "data_mode": DATA_LAYOUT.active_layout.mode,
            "data_root": str(DATA_LAYOUT.active_layout.root),
            "api_key_configured": bool(novelai_key_is_configured()),
        }, headers={"Cache-Control": "no-store"})

    @server.post("/api/public/generation/toggle")
    async def public_launcher_toggle_generation(request: Request):
        _require_public_local(request)
        # Reuse the same pause/resume path as the Gradio button so an in-flight
        # pair is allowed to finish and no worker token is accidentally invalidated.
        ranker.toggle_generation_pause()
        with ranker.state_lock:
            paused = bool(ranker.generation_paused)
        return JSONResponse({"ok": True, "generation_paused": paused})

    @server.post("/api/public/diagnostics/export")
    async def public_launcher_export_diagnostics(request: Request):
        _require_public_local(request)
        destination = GLOBAL_DUEL_DIAGNOSTICS.export_bundle(ranker)
        return JSONResponse({"ok": True, "path": str(destination)})

    @server.post("/api/public/shutdown")
    async def public_launcher_shutdown(request: Request):
        _require_public_local(request)
        # Return the response before asking the main process to stop. SIGINT lets
        # Uvicorn and the ranker's registered atexit persistence handlers exit cleanly.
        threading.Timer(0.45, lambda: os.kill(os.getpid(), signal.SIGINT)).start()
        return JSONResponse({"ok": True, "message": "Artist Ranker is shutting down safely."})

    server = gr.mount_gradio_app(
        server,
        gradio_app,
        path="/ranker",
        server_name=LAN_SERVER_HOST,
        server_port=SERVER_PORT,
        theme=gr.themes.Soft(),
        css=PHASE3_CSS + str(globals().get("QOL_ACCELERATOR_CSS", "")) + DEDICATED_RANKER_MOUNT_SAFETY_CSS + SECURE_SETUP_CSS + PHONE_PAIRING_CSS + FULL_RANKER_V5_CSS + FULL_RANKER_GUIDANCE_CSS,
        head=(
            CONTEXT_UI_HEAD + GALLERY_DUEL_UI_HEAD + SOUND_UI_HEAD
            + GALLERY_ARTIST_PICKER_HEAD + APPEARANCE_THEME_HEAD + POLISH_UI_HEAD
            + ARTIST_CONTROLS_HEAD + QOL_UI_HEAD + BOOLEAN_PAGINATION_HEAD
            + DIAGNOSTICS_HEAD + GENERATION_ANALYTICS_HEAD + SECURE_SETUP_HEAD + PHONE_PAIRING_HEAD
            + str(globals().get("QOL_ACCELERATOR_HEAD", "")) + DEDICATED_NAV_BRIDGE_HEAD + FULL_RANKER_V5_HEAD + FULL_RANKER_GUIDANCE_HEAD
        ),
        allowed_paths=[str(COMPARISON_IMAGES_DIR)],
    )
    PHONE_PAIRING_MDNS.start()
    atexit.register(PHONE_PAIRING_MDNS.stop)
    if os.environ.get("ARTIST_RANKER_NO_AUTO_BROWSER", "").strip() != "1":
        threading.Timer(1.0, lambda: webbrowser.open(f"http://127.0.0.1:{SERVER_PORT}/ranker/")).start()
    uvicorn.run(server, host=LAN_SERVER_HOST, port=SERVER_PORT, log_level="info")

