def discover_lan_urls(port: int) -> List[str]:
    """Return likely same-network URLs without making an external web request."""
    addresses: Set[str] = set()
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            address = str(info[4][0] or "").strip()
            if address and not address.startswith("127.") and not address.startswith("169.254."):
                addresses.add(address)
    except OSError:
        pass

    # A UDP socket can reveal the preferred LAN interface without sending data.
    try:
        probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        probe.settimeout(0.2)
        probe.connect(("192.0.2.1", 9))
        address = str(probe.getsockname()[0] or "").strip()
        probe.close()
        if address and not address.startswith("127.") and not address.startswith("169.254."):
            addresses.add(address)
    except OSError:
        pass

    return [f"http://{address}:{int(port)}" for address in sorted(addresses)]


def main():
    """Main entry point."""
    # LAPSEBAS_MDNS_START
    # Publish a stable local-network name for phones even when DHCP changes the IP.
    _lapsebas_mdns = start_lan_hostname_advertiser(
        hostname=socket.gethostname(),
        port=int(SERVER_PORT),
    )
    # LAPSEBAS_MDNS_END
    print("Starting Artist ELO Ranker...")
    print(f"Data layout mode: {DATA_LAYOUT.active_layout.mode}")
    print(f"Active data root: {DATA_LAYOUT.active_layout.root}")
    print(
        f"Data schemas: layout={DATA_LAYOUT_SCHEMA_VERSION}, "
        f"data={DATA_SCHEMA_VERSION}, config={CONFIG_SCHEMA_VERSION}"
    )
    if DATA_LAYOUT.last_startup_message:
        print(DATA_LAYOUT.last_startup_message)
    if _PHASE7_BOOTSTRAP_MESSAGE:
        print(_PHASE7_BOOTSTRAP_MESSAGE)
    print(f"Artist tags file: {ARTIST_TAGS_FILE}")
    print(f"ELO ratings file: {ELO_RATINGS_FILE}")
    print(f"Comparison images dir: {COMPARISON_IMAGES_DIR}")
    print(f"Buffer state file: {BUFFER_STATE_FILE}")
    print(f"Combination ratings file: {COMBINATION_RATINGS_FILE}")
    print(f"Top-search ratings file: {TOP_SEARCH_RATINGS_FILE}")
    print(f"Automatic backups: {BACKUP_DIR}")
    print(f"Classification tags: {CLASSIFICATION_TAGS_FILE}")
    print(f"Entity notes: {ENTITY_NOTES_FILE}")
    print(f"Artist portraits: {ARTIST_PORTRAITS_FILE}")
    print(f"Server bind host: {LAN_SERVER_HOST}:{SERVER_PORT}")
    print(f"NovelAI API key: {'Configured' if novelai_key_is_configured() else 'Not configured'}")
    lan_urls = discover_lan_urls(SERVER_PORT)
    if lan_urls:
        print("Phone / LAN access URLs:")
        for url in lan_urls:
            print(f"  {url}")
        print("Open one of these URLs on a phone connected to the same Wi-Fi/LAN.")
        print("Dedicated duel page: add /duel to the same address.")
    else:
        print("Phone / LAN URL could not be detected automatically; use this PC's local IPv4 address with the configured port.")

    # Serve permanent comparison images directly from D: instead of copying
    # every newly displayed buffered image into Gradio's temp cache. This removes
    # a variable file-copy delay from the winner-click response path.
    COMPARISON_IMAGES_DIR.mkdir(parents=True, exist_ok=True)
    gr.set_static_paths([COMPARISON_IMAGES_DIR])

    ranker = ArtistELORanker()
    app = ranker.create_ui()

    launch_with_dedicated_duel_page(ranker, app)
if __name__ == "__main__":
    main()
